-- بيانات مقرر كيمياء 2-2 (المقرر 3، قيد الإعداد) — الجزء 3 من 4. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem22-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C2-L2-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في المنحنى الآتي لتوزيع طاقة الجسيمات، ماذا تمثل المنطقة المظللة تحت كل منحنى يمين الخط المتقطع؟', null, '[{"src":"qimg/chem22/c2-l2b-dist-t1t2.svg","alt":"منحنيا توزيع طاقة الجسيمات: المحور الأفقي طاقة التصادم، والمحور الرأسي عدد الجسيمات. المنحنى T₁ (أزرق) قمته عالية وضيقة عند طاقة منخفضة، والمنحنى T₂ (أحمر) قمته أخفض وأعرض وتقع عند طاقة أعلى، ومكتوب أعلى الشكل T₂ > T₁. خط رأسي متقطع يمثل طاقة التنشيط، والمنطقة تحت كل منحنى يمين هذا الخط مظللة: المنطقة تحت المنحنى T₂ (وردية) أكبر بكثير من المنطقة تحت المنحنى T₁ (زرقاء)."}]'::jsonb, '["عدد التصادمات التي طاقتها تساوي طاقة التنشيط أو تزيد عليها","عدد التصادمات التي طاقتها أقل من طاقة التنشيط","العدد الكلي لجسيمات العينة عند درجة الحرارة تلك","متوسط الطاقة الحركية لجسيمات العينة"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 60 — الشكل 2-10 طاقة الجسيم ودرجة حرارته'),
('mcq', 2, 'يمثل الشكل الآتي توزيع طاقة الجسيمات لعينتين من الغاز نفسه عند درجتي حرارة مختلفتين. أيّ المنحنيين يمثل درجة الحرارة الأعلى، ولماذا؟', null, '[{"src":"qimg/chem22/c2-l2b-dist-ab.svg","alt":"منحنيا توزيع طاقة الجسيمات لعينتين من الغاز نفسه عند درجتي حرارة مختلفتين: المحور الأفقي طاقة التصادم، والمحور الرأسي عدد الجسيمات. المنحنى (أ) (أخضر) قمته عالية وضيقة عند طاقة منخفضة، والمنحنى (ب) (برتقالي) قمته أخفض وأعرض وتقع عند طاقة أعلى. خط رأسي متقطع عنوانه Ea، والمنطقة يمين الخط تحت المنحنى (ب) أكبر بكثير من المنطقة تحت المنحنى (أ)."}]'::jsonb, '["(أ)؛ لأن قمته أعلى من قمة (ب)","(أ)؛ لأن عدد جسيماته الكلي أكبر","(ب)؛ لأن قمته أخفض ومنزاحة نحو طاقة أعلى","لا يمكن التمييز؛ لأن طاقة التنشيط واحدة"]'::jsonb, 'تحليل', 'تحليل شكل', 'متوسط', 'الكتاب ص 60 — الشكل 2-10 طاقة الجسيم ودرجة حرارته'),
('mcq', 3, 'في الشكل الآتي، تقع قمة المنحنى (ب) عند طاقة أعلى من قمة المنحنى (أ). علام يدل انزياح القمة نحو اليمين؟', null, '[{"src":"qimg/chem22/c2-l2b-dist-ab.svg","alt":"منحنيا توزيع طاقة الجسيمات لعينتين من الغاز نفسه عند درجتي حرارة مختلفتين: المحور الأفقي طاقة التصادم، والمحور الرأسي عدد الجسيمات. المنحنى (أ) (أخضر) قمته عالية وضيقة عند طاقة منخفضة، والمنحنى (ب) (برتقالي) قمته أخفض وأعرض وتقع عند طاقة أعلى. خط رأسي متقطع عنوانه Ea، والمنطقة يمين الخط تحت المنحنى (ب) أكبر بكثير من المنطقة تحت المنحنى (أ)."}]'::jsonb, '["زيادة طاقة التنشيط للتفاعل","زيادة متوسط الطاقة الحركية للجسيمات","زيادة العدد الكلي للجسيمات في العينة","نقص سرعة التفاعل في العينة"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 60 — الشكل 2-10 طاقة الجسيم ودرجة حرارته'),
('mcq', 4, 'في المنحنى الآتي لتوزيع طاقة جسيمات العينة نفسها عند T₁ وT₂، تكون المساحة الكلية تحت المنحنى T₁ مساوية للمساحة الكلية تحت المنحنى T₂ مع أن شكليهما مختلفان. بم يُفسَّر تساوي المساحتين؟', null, '[{"src":"qimg/chem22/c2-l2b-dist-t1t2.svg","alt":"منحنيا توزيع طاقة الجسيمات: المحور الأفقي طاقة التصادم، والمحور الرأسي عدد الجسيمات. المنحنى T₁ (أزرق) قمته عالية وضيقة عند طاقة منخفضة، والمنحنى T₂ (أحمر) قمته أخفض وأعرض وتقع عند طاقة أعلى، ومكتوب أعلى الشكل T₂ > T₁. خط رأسي متقطع يمثل طاقة التنشيط، والمنطقة تحت كل منحنى يمين هذا الخط مظللة: المنطقة تحت المنحنى T₂ (وردية) أكبر بكثير من المنطقة تحت المنحنى T₁ (زرقاء)."}]'::jsonb, '["تساوي طاقة التنشيط للتفاعل عند درجتي الحرارة","تساوي متوسط الطاقة الحركية للجسيمات عند الدرجتين","تساوي عدد الجسيمات ذات الطاقة الكافية عند الدرجتين","تساوي العدد الكلي لجسيمات العينة عند الدرجتين"]'::jsonb, 'تحليل', 'تحليل شكل', 'متوسط', 'الكتاب ص 60 — الشكل 2-10 طاقة الجسيم ودرجة حرارته'),
('mcq', 5, 'يمثل المنحنى الآتي توزيع طاقة الجسيمات عند درجة حرارة واحدة T، وعليه طاقتا التنشيط لتفاعلين X وY يحدثان عند هذه الدرجة. أيّ التفاعلين أسرع، ولماذا؟', null, '[{"src":"qimg/chem22/c2-l2b-dist-xy.svg","alt":"منحنى توزيع طاقة جسيمات واحد عند درجة حرارة T: المحور الأفقي طاقة التصادم، والمحور الرأسي عدد الجسيمات. يرتفع المنحنى إلى قمة ثم ينخفض تدريجيًا. خطان رأسيان متقطعان: الأول Ea(X) قريب من القمة على يمينها حيث المنحنى ما زال مرتفعًا، والثاني Ea(Y) بعيد إلى اليمين حيث المنحنى قريب من المحور الأفقي."}]'::jsonb, '["Y؛ لأن طاقة تنشيطه الأعلى تجعل تصادماته أقوى","X؛ لأن عدد الجسيمات التي تتجاوز طاقة تنشيطه أكبر","X؛ لأن عدد جسيماته الكلي أكبر من جسيمات Y","السرعتان متساويتان؛ لأن درجة الحرارة واحدة"]'::jsonb, 'تحليل', 'تحليل شكل', 'صعب', 'الكتاب ص 60 — الشكل 2-10، وص 62 — طاقة التنشيط عقبة يجب تخطيها'),
('mcq', 6, 'إذا خُفّضت درجة حرارة غاز من T₂ إلى T₁، فكيف يتغير منحنى توزيع طاقة جسيماته؟', null, null, '["تعلو قمته وتنزاح نحو طاقة أقل ويصغر الجزء الواقع بعد Ea","تنخفض قمته وتنزاح نحو طاقة أعلى ويكبر الجزء الواقع بعد Ea","يبقى المنحنى كما هو وينزاح خط Ea نحو طاقة أعلى","يبقى شكل المنحنى كما هو ويقل عدد الجسيمات الكلي"]'::jsonb, 'تطبيق', 'توقع', 'متوسط', 'الكتاب ص 60 — الشكل 2-10 طاقة الجسيم ودرجة حرارته'),
('mcq', 7, 'في المنحنى الآتي، عند أيّ درجة حرارة يكون عدد الجسيمات ذات الطاقة المنخفضة (قرب يسار المحور الأفقي) أكبر؟', null, '[{"src":"qimg/chem22/c2-l2b-dist-t1t2.svg","alt":"منحنيا توزيع طاقة الجسيمات: المحور الأفقي طاقة التصادم، والمحور الرأسي عدد الجسيمات. المنحنى T₁ (أزرق) قمته عالية وضيقة عند طاقة منخفضة، والمنحنى T₂ (أحمر) قمته أخفض وأعرض وتقع عند طاقة أعلى، ومكتوب أعلى الشكل T₂ > T₁. خط رأسي متقطع يمثل طاقة التنشيط، والمنطقة تحت كل منحنى يمين هذا الخط مظللة: المنطقة تحت المنحنى T₂ (وردية) أكبر بكثير من المنطقة تحت المنحنى T₁ (زرقاء)."}]'::jsonb, '["عند T₂؛ لأن متوسط طاقة جسيماته أكبر","العدد متساوٍ؛ لأن المنحنيين يبدآن من الصفر","عند T₁؛ لأن منحناه أعلى في منطقة الطاقة المنخفضة","عند T₂؛ لأن المساحة الكلية تحت منحناه أكبر"]'::jsonb, 'فهم', 'قراءة شكل', 'سهل', 'الكتاب ص 60 — الشكل 2-10 طاقة الجسيم ودرجة حرارته'),
('essay', 1, 'يمثل المنحنى الآتي توزيع طاقة جسيمات خليط متفاعل عند درجتي الحرارة T₁ وT₂. ميّز بين المنطقتين المظللتين، ثم فسّر بالاعتماد عليهما أيّ درجتي الحرارة يكون عندها التفاعل أسرع، مبينًا علاقة ذلك بعدد الاصطدامات التي تحدث في وحدة الزمن والتي لها طاقة أكبر من أو تساوي طاقة التنشيط.', null, '[{"src":"qimg/chem22/c2-l2b-dist-t1t2.svg","alt":"منحنيا توزيع طاقة الجسيمات: المحور الأفقي طاقة التصادم، والمحور الرأسي عدد الجسيمات. المنحنى T₁ (أزرق) قمته عالية وضيقة عند طاقة منخفضة، والمنحنى T₂ (أحمر) قمته أخفض وأعرض وتقع عند طاقة أعلى، ومكتوب أعلى الشكل T₂ > T₁. خط رأسي متقطع يمثل طاقة التنشيط، والمنطقة تحت كل منحنى يمين هذا الخط مظللة: المنطقة تحت المنحنى T₂ (وردية) أكبر بكثير من المنطقة تحت المنحنى T₁ (زرقاء)."}]'::jsonb, null, 'تحليل', 'تحليل شكل', 'صعب', 'الكتاب ص 71 — س55 (الشكل 2-15)'),
('essay', 2, 'يمثل الشكل الآتي توزيع طاقة جسيمات عينتين من الغاز نفسه عند درجتي حرارة مختلفتين. (أ) حدّد المنحنى الذي يمثل درجة الحرارة الأعلى، واذكر دليلين من المنحنيين. (ب) اذكر شيئًا لم يتغير بين العينتين، وعلّل.', null, '[{"src":"qimg/chem22/c2-l2b-dist-ab.svg","alt":"منحنيا توزيع طاقة الجسيمات لعينتين من الغاز نفسه عند درجتي حرارة مختلفتين: المحور الأفقي طاقة التصادم، والمحور الرأسي عدد الجسيمات. المنحنى (أ) (أخضر) قمته عالية وضيقة عند طاقة منخفضة، والمنحنى (ب) (برتقالي) قمته أخفض وأعرض وتقع عند طاقة أعلى. خط رأسي متقطع عنوانه Ea، والمنطقة يمين الخط تحت المنحنى (ب) أكبر بكثير من المنطقة تحت المنحنى (أ)."}]'::jsonb, null, 'تحليل', 'تحليل شكل', 'متوسط', 'الكتاب ص 60 — الشكل 2-10 طاقة الجسيم ودرجة حرارته'),
('essay', 3, 'يمثل المنحنى الآتي توزيع طاقة الجسيمات عند درجة الحرارة T، وعليه طاقتا التنشيط لتفاعلين X وY. قال طالب: «التفاعل Y أسرع؛ لأن طاقة تنشيطه أعلى فتصادماته أقوى». (أ) قوّم قول الطالب مستعينًا بالمنحنى. (ب) توقع كيف يتغير الجزء من المنحنى الواقع بعد كل من Ea(X) وEa(Y) إذا رُفعت درجة الحرارة.', null, '[{"src":"qimg/chem22/c2-l2b-dist-xy.svg","alt":"منحنى توزيع طاقة جسيمات واحد عند درجة حرارة T: المحور الأفقي طاقة التصادم، والمحور الرأسي عدد الجسيمات. يرتفع المنحنى إلى قمة ثم ينخفض تدريجيًا. خطان رأسيان متقطعان: الأول Ea(X) قريب من القمة على يمينها حيث المنحنى ما زال مرتفعًا، والثاني Ea(Y) بعيد إلى اليمين حيث المنحنى قريب من المحور الأفقي."}]'::jsonb, null, 'تقويم', 'تقويم قول', 'صعب', 'الكتاب ص 60 — الشكل 2-10، وص 62 — طاقة التنشيط')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C2-L2-O11') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الخط المتقطع يمثل طاقة التنشيط Ea، والمنطقة المظللة تحت المنحنى يمينه تمثل عدد الاصطدامات التي لها طاقة مساوية لطاقة التنشيط أو أكبر منها، أي التصادمات القادرة على إحداث التفاعل.', '["","التصادمات الأقل طاقة من طاقة التنشيط تقع يسار الخط المتقطع لا يمينه.","العدد الكلي يمثله المنحنى كله (المساحة تحته كلها)، لا الجزء المظلل فقط.","متوسط الطاقة يرتبط بموضع المنحنى على المحور الأفقي، وليس مساحة الذيل المظلل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.153Z"}'::jsonb),
('mcq', 2, 2, 'عند درجة الحرارة الأعلى يزداد متوسط الطاقة الحركية، فينزاح المنحنى نحو الطاقة الأعلى وتنخفض قمته ويتسع، ويكبر الجزء الواقع يمين Ea. وهذه صفات المنحنى (ب).', '["القمة الأعلى والأضيق تدل على أن جسيمات أكثر تتجمع عند طاقة منخفضة، وهذا يميز درجة الحرارة الأقل.","العينتان من الغاز نفسه، والفرق في توزيع طاقة الجسيمات لا في عددها الكلي.","","طاقة التنشيط واحدة للتفاعل، لكن هيئة المنحنى تميز درجة الحرارة الأعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-06T22:20:31.153Z"}'::jsonb),
('mcq', 3, 1, 'المحور الأفقي يمثل طاقة التصادم، وانزياح قمة المنحنى (ب) نحو الطاقة الأعلى يعني أن جسيماته تمتلك في المتوسط طاقة حركية أكبر؛ أي أن العينة (ب) عند درجة حرارة أعلى.', '["خط طاقة التنشيط واحد للمنحنيين؛ فانزياح القمة لا يغير طاقة التنشيط.","","المحور الأفقي يمثل الطاقة، فالانزياح عليه يتعلق بطاقة الجسيمات لا بعددها.","انزياح المنحنى نحو الطاقة الأعلى يزيد عدد التصادمات ذات الطاقة الكافية، فتزداد السرعة لا تنقص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-06T22:20:31.154Z"}'::jsonb),
('mcq', 4, 3, 'المحور الرأسي يمثل عدد الجسيمات، فالمساحة الكلية تحت المنحنى تمثل العدد الكلي لجسيمات العينة. والعينة نفسها عند الدرجتين، فعدد جسيماتها لم يتغير، وإنما تغير توزيع طاقاتها: عند T₂ تنخفض القمة ويتسع المنحنى نحو الطاقة الأعلى.', '["طاقة التنشيط واحدة فعلًا، لكنها موضع الخط المتقطع على محور الطاقة، ولا تحدد المساحة الكلية تحت المنحنى.","متوسط الطاقة الحركية أكبر عند T₂، ولذلك انزاح منحناه نحو الطاقة الأعلى؛ فهو غير متساوٍ.","عدد الجسيمات ذات الطاقة الكافية (المنطقة المظللة) أكبر عند T₂، فهو غير متساوٍ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.154Z"}'::jsonb),
('mcq', 5, 1, 'الجزء من المنحنى الواقع يمين Ea(X) كبير لأنها قريبة من القمة، أما الواقع يمين Ea(Y) فصغير جدًا. فعدد التصادمات التي تمتلك طاقة تساوي طاقة التنشيط أو تزيد عليها أكبر في التفاعل X، فهو الأسرع.', '["طاقة التنشيط الأعلى عقبة أكبر؛ فقليل من الجسيمات يمتلك طاقة تتجاوزها، فيكون Y أبطأ.","","المنحنى واحد للتفاعلين، فلا يدل على اختلاف عدد الجسيمات؛ الفرق في طاقة التنشيط.","ثبات درجة الحرارة لا يعني تساوي السرعة؛ فالجزء من المنحنى الذي يتجاوز Ea مختلف للتفاعلين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.154Z"}'::jsonb),
('mcq', 6, 0, 'عند خفض درجة الحرارة يقل متوسط الطاقة الحركية، فتتجمع جسيمات أكثر عند طاقات منخفضة: تعلو القمة وتضيق وتنزاح يسارًا، ويصغر عدد الجسيمات التي تتجاوز طاقة التنشيط.', '["","هذا ما يحدث عند رفع درجة الحرارة لا خفضها.","طاقة التنشيط لا تتغير بتغير درجة الحرارة، والمنحنى نفسه هو الذي يتغير.","خفض درجة الحرارة لا يغير عدد الجسيمات، وإنما يغير توزيع طاقاتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.154Z"}'::jsonb),
('mcq', 7, 2, 'في منطقة الطاقة المنخفضة يقع منحنى T₁ فوق منحنى T₂، فعدد الجسيمات ذات الطاقة المنخفضة أكبر عند درجة الحرارة الأقل T₁، وهذا يتفق مع أن متوسط الطاقة الحركية عندها أقل.', '["كون متوسط الطاقة أكبر عند T₂ يعني أن جسيمات أقل بقيت في منطقة الطاقة المنخفضة، لا أكثر.","بدء المنحنيين من الصفر لا يعني تطابقهما؛ فمنحنى T₁ أعلى بوضوح في منطقة الطاقة المنخفضة.","","المساحة الكلية تحت المنحنيين متساوية لأن العينة نفسها، ومنحنى T₂ أخفض في منطقة الطاقة المنخفضة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.154Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المنطقة المظللة تحت كل منحنى يمين خط طاقة التنشيط تمثل عدد الاصطدامات التي طاقتها تساوي طاقة التنشيط أو أكبر منها عند تلك الدرجة. والمنطقة تحت المنحنى T₂ أكبر كثيرًا من المنطقة تحت المنحنى T₁؛ فعدد الاصطدامات عالية الطاقة في وحدة الزمن عند T₂ أكبر كثيرًا منه عند T₁. وبما أن هذه الاصطدامات هي التي تنتج عنها تفاعلات، يكون التفاعل أسرع عند T₂. وطاقة التنشيط واحدة عند الدرجتين، فالسبب هو زيادة الطاقة الحركية عند T₂.', '["المنطقة المظللة = تصادمات طاقتها ≥ طاقة التنشيط","منطقة T₂ أكبر من منطقة T₁","الاصطدامات ذات الطاقة الكافية تنتج التفاعل فالسرعة أكبر عند T₂","طاقة التنشيط لم تتغير"]'::jsonb, '[]'::jsonb, '[{"element":"معنى المنطقة المظللة","marks":1},{"element":"المقارنة بين المنطقتين","marks":1},{"element":"استنتاج التفاعل الأسرع مع التعليل","marks":1},{"element":"ثبات طاقة التنشيط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يفسر معنى المنطقتين ويقارن بينهما ويستنتج الأسرع معللًا ويبين ثبات طاقة التنشيط"},{"level":"2–3 درجات","description":"يقارن ويستنتج دون تفسير كاف لمعنى المنطقة أو دون ذكر ثبات طاقة التنشيط"},{"level":"1 درجة","description":"يذكر أن التفاعل أسرع عند T₂ دون تعليل من المنحنى"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ القمة الأعلى (T₁) دليلًا على سرعة أكبر","القول إن طاقة التنشيط أقل عند T₂","تفسير المنطقة المظللة بالعدد الكلي للجسيمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-06T22:20:31.155Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المنحنى (ب) يمثل درجة الحرارة الأعلى. الدليل الأول: قمته أخفض وأعرض ومنزاحة نحو طاقة أعلى، أي أن متوسط الطاقة الحركية لجسيماته أكبر. الدليل الثاني: الجزء تحت المنحنى (ب) يمين Ea أكبر كثيرًا، أي أن عدد الجسيمات التي طاقتها تساوي طاقة التنشيط أو تزيد عليها أكبر. (ب) لم تتغير طاقة التنشيط Ea (خط واحد للمنحنيين)؛ لأنها خاصية للتفاعل لا تعتمد على درجة الحرارة. ولم يتغير كذلك العدد الكلي للجسيمات لأنهما عينتان من الغاز نفسه.', '["المنحنى (ب) هو الأعلى حرارة","دليل: القمة أخفض ومنزاحة نحو طاقة أعلى","دليل: الجزء يمين Ea أكبر","Ea لم تتغير مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المنحنى","marks":1},{"element":"الدليل الأول","marks":1},{"element":"الدليل الثاني","marks":1},{"element":"ما لم يتغير مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحدد المنحنى ويذكر دليلين صحيحين ويذكر ما لم يتغير معللًا"},{"level":"2–3 درجات","description":"يحدد المنحنى بدليل واحد، أو يغفل ما لم يتغير"},{"level":"1 درجة","description":"يحدد المنحنى دون دليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار المنحنى ذي القمة الأعلى","القول إن طاقة التنشيط تختلف بين العينتين","تفسير الانزياح بزيادة عدد الجسيمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-06T22:20:31.155Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) قول الطالب خطأ. طاقة التنشيط أقل طاقة يجب أن تمتلكها الجسيمات المتصادمة ليحدث التفاعل، فهي عقبة وليست قوة للتصادم. ويبين المنحنى أن الجزء من المنحنى يمين Ea(Y) صغير جدًا، أي أن قليلًا من التصادمات يمتلك طاقة كافية، أما الجزء يمين Ea(X) فكبير؛ فالتفاعل X أسرع. (ب) عند رفع درجة الحرارة ينزاح المنحنى نحو طاقة أعلى وتنخفض قمته، فيكبر الجزء الواقع بعد كل من Ea(X) وEa(Y)، فتزداد سرعة التفاعلين، ولا تتغير طاقتا التنشيط نفسهما.', '["الحكم بخطأ القول","طاقة التنشيط عقبة: الأعلى يعني تصادمات فعالة أقل","X أسرع لأن الجزء يمين Ea(X) أكبر","رفع الحرارة يكبر الجزأين ولا يغير طاقتي التنشيط"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم مع التعليل بمعنى طاقة التنشيط","marks":1},{"element":"الاستدلال بالمنحنى وتحديد الأسرع","marks":1},{"element":"توقع تغير المنحنى برفع الحرارة","marks":1},{"element":"ثبات طاقتي التنشيط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحكم بخطأ القول ويعلل بمعنى طاقة التنشيط ويستدل بالمنحنى ويتوقع أثر رفع الحرارة صحيحًا"},{"level":"2–3 درجات","description":"يحكم صحيحًا مع نقص في الاستدلال بالمنحنى أو في التوقع"},{"level":"1 درجة","description":"يحكم بخطأ القول دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ طاقة التنشيط الأعلى ميزة تسرع التفاعل","توقع أن رفع الحرارة يخفض طاقة التنشيط","توقع أن رفع الحرارة يفيد X فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.155Z"}'::jsonb)
