('mcq', 6, 'عند المقارنة بين منحنيي مخطط الطاقة لتفاعل واحد بمحفز ودون محفز، أيّ الخصائص الآتية تختلف بين المنحنيين؟', null, null, '["مستوى طاقة المواد المتفاعلة","مستوى طاقة المواد الناتجة","الفرق بين طاقتي المتفاعلات والنواتج","ارتفاع قمة المنحنى (طاقة المعقد المنشط)"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 62 — الشكل 2-11 طاقة التفاعل المحفز وغير المحفز'),
('mcq', 7, 'اعتمادًا على المخطط الآتي، ما طاقة المعقد المنشط في المسار (2)؟', null, '[{"src":"qimg/chem22/c2-l2b-cat-12.svg","alt":"مخطط الطاقة مع سير التفاعل لتفاعل واحد بمسارين، والمحور الرأسي الطاقة بوحدة kJ مدرج من 0 إلى 250. المتفاعلات عند 100 kJ والنواتج عند 40 kJ. المسار (1) (أخضر) قمته عند 250 kJ، والمسار (2) (برتقالي) قمته عند 170 kJ، ويبدأ المساران من مستوى المتفاعلات نفسه وينتهيان عند مستوى النواتج نفسه."}]'::jsonb, '["70 kJ","250 kJ","170 kJ","130 kJ"]'::jsonb, 'تطبيق', 'قراءة شكل', 'سهل', 'الكتاب ص 62 — الشكل 2-11 طاقة التفاعل المحفز وغير المحفز'),
('essay', 1, 'اعتمادًا على المخطط الآتي لتفاعل محفز وغير محفز: (أ) احسب طاقة التنشيط لكل من المسارين. (ب) احسب ΔH لكل من المسارين. (ج) ماذا تستنتج عن أثر المحفز؟', null, '[{"src":"qimg/chem22/c2-l2b-cat-exo.svg","alt":"مخطط الطاقة مع سير التفاعل، والمحور الرأسي الطاقة بوحدة kJ مدرج من 0 إلى 250. المتفاعلات عند 100 kJ والنواتج عند 40 kJ. مساران: المسار غير المحفز (أحمر) قمته عند 250 kJ، والمسار المحفز (أزرق) قمته عند 170 kJ، ويبدأ المساران من مستوى المتفاعلات نفسه وينتهيان عند مستوى النواتج نفسه."}]'::jsonb, null, 'تحليل', 'تحليل شكل', 'متوسط', 'الكتاب ص 62 — الشكل 2-11 طاقة التفاعل المحفز وغير المحفز'),
('essay', 2, 'يمثل المخطط الآتي تفاعلًا ماصًّا للطاقة بمحفز ودون محفز. قال طالب: «المحفز جعل التفاعل أقل امتصاصًا للطاقة؛ لأن قمة منحناه أخفض». قوّم هذا القول مستعينًا بقيم من المخطط.', null, '[{"src":"qimg/chem22/c2-l2b-cat-endo.svg","alt":"مخطط الطاقة مع سير التفاعل، والمحور الرأسي الطاقة بوحدة kJ مدرج من 0 إلى 250. المتفاعلات عند 50 kJ والنواتج عند 120 kJ. مساران: المسار غير المحفز (أحمر) قمته عند 230 kJ، والمسار المحفز (أزرق) قمته عند 160 kJ، ويبدأ المساران من مستوى المتفاعلات نفسه وينتهيان عند مستوى النواتج نفسه."}]'::jsonb, null, 'تقويم', 'تقويم قول', 'صعب', 'الكتاب ص 62 — الشكل 2-11 طاقة التفاعل المحفز وغير المحفز'),
('essay', 3, 'تفاعل طارد للطاقة: طاقة متفاعلاته 80 kJ وطاقة نواتجه 20 kJ، وطاقة تنشيطه 120 kJ دون محفز و50 kJ بوجود محفز. (أ) احسب طاقة المعقد المنشط في كل من المسارين، وΔH للتفاعل. (ب) صف ما يجب أن يظهر في مخطط الطاقة الذي يمثل المسارين معًا. (ج) فسّر بتشبيه الحصان والحاجز لماذا يكون المسار المحفز أسرع.', null, null, null, 'تحليل', 'تصميم مخطط', 'صعب', 'الكتاب ص 62 — الشكلان 2-11 و2-12، وص 73 — س65')
