insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C2-L2-O13'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أُضيف محفز مناسب إلى تفاعل كيميائي مع بقاء كميات المتفاعلات ودرجة الحرارة كما هي. أيّ مما يأتي يبقى كما كان دون تغيير؟', null, null, '["سرعة التفاعل الكيميائي","طاقة التنشيط للتفاعل","كمية النواتج عند اكتمال التفاعل","الزمن اللازم لاكتمال التفاعل"]'::jsonb, 'تذكر', 'تذكر مفهوم', 'سهل', 'الكتاب ص 61 — المحفزات والمثبطات، وص 62 — الخلاصة'),
('mcq', 2, 'بعد انتهاء تحلل محلول H₂O₂ بوجود MnO₂، فُصل MnO₂ وجُفف، ثم أُضيف إلى عينة جديدة مماثلة من محلول H₂O₂. ماذا تتوقع أن يحدث؟', null, null, '["لا يؤثر في العينة الجديدة؛ لأنه استُهلك في التحلل الأول","يزيد حجم O₂ الناتج من العينة الجديدة إلى الضعف","يُسرّع تحللها بدرجة أقل؛ لأن جزءًا منه تحول إلى O₂","يُسرّع تحللها كما فعل في العينة الأولى"]'::jsonb, 'فهم', 'توقع', 'متوسط', 'الكتاب ص 61 — المحفزات والمثبطات، وص 70 — س43'),
('mcq', 3, 'عينتان متماثلتان من محلول H₂O₂، أُضيف إلى إحداهما قليل من MnO₂ وتُركت الأخرى دون إضافة. كيف يقارن حجم O₂ الكلي الناتج من العينتين عند اكتمال التحلل؟', null, null, '["متساوٍ، لكنه يتكون في زمن أقصر بوجود المحفز","ضعف الحجم في العينة التي فيها MnO₂","أقل في العينة التي فيها MnO₂ لأنه يستهلك بعض O₂","أكبر في العينة التي فيها MnO₂ بمقدار كتلة المحفز"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 61 — المحفزات والمثبطات'),
('mcq', 4, 'يتحلل H₂O₂ إلى ماء وأكسجين بوجود MnO₂ محفزًا. أيّ المعادلات الآتية تعبر عن التفاعل الكيميائي تعبيرًا صحيحًا؟', null, null, '["2H₂O₂(aq) + MnO₂(s) → 2H₂O(l) + O₂(g)","2H₂O₂(aq) → 2H₂O(l) + O₂(g)","2H₂O₂(aq) → 2H₂O(l) + O₂(g) + MnO₂(s)","H₂O₂(aq) → H₂O(l) + O₂(g)"]'::jsonb, 'تطبيق', 'كتابة معادلة', 'متوسط', 'الكتاب ص 61 — المحفزات والمثبطات'),
('mcq', 5, 'يُسرّع إنزيم في الخلية تحويل كمية كبيرة جدًا من مادة ما، مع أن كمية الإنزيم الموجودة صغيرة. ما تفسير ذلك؟', null, null, '["كل جزيء إنزيم يتفاعل مرة واحدة ثم يُستهلك","الإنزيم يزيد كمية النواتج على حساب كتلته","الإنزيم يُكتب ضمن المتفاعلات فيلزم بكميات كبيرة","الإنزيم محفز لا يُستهلك، فيعمل مرة بعد أخرى"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 61 — المحفزات والمثبطات'),
('mcq', 6, 'تستعمل المصانع المحفزات على نطاق واسع لتقليل تكلفة الإنتاج. ما السبب الصحيح لذلك؟', null, null, '["تزيد كمية الناتج النهائية من كمية المتفاعلات نفسها","تسرّع الإنتاج في الزمن نفسه ويُعاد استعمالها لأنها لا تُستهلك","تُستهلك بدل المواد المتفاعلة الغالية الثمن","تتحول إلى نواتج إضافية تُباع مع المنتج"]'::jsonb, 'تحليل', 'تمييز', 'صعب', 'الكتاب ص 61 — المحفزات (استعمالها في الصناعات)'),
('mcq', 7, 'يبين الجدول الآتي نتائج تجربتين لتحلل كميتين متساويتين من محلول H₂O₂، إحداهما بوجود MnO₂. ما الاستنتاج الذي تدعمه البيانات؟', '{"headers":["التجربة","كتلة MnO₂ قبل التفاعل","كتلة MnO₂ بعد التفاعل","حجم O₂ الكلي الناتج","زمن اكتمال التفاعل"],"rows":[["(1) دون محفز","—","—","48 mL","10 h تقريبًا"],["(2) بوجود MnO₂","0.50 g","0.50 g","48 mL","40 s"]]}'::jsonb, null, '["زاد MnO₂ السرعة ولم يُستهلك ولم يزد كمية O₂","زاد MnO₂ كمية O₂ الناتجة وسرعة تكونه","استُهلك MnO₂ في التفاعل فزادت السرعة","لا يحدث التحلل إطلاقًا دون MnO₂"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 61 — المحفزات والمثبطات'),
('essay', 1, 'يبين الجدول الآتي حجم غاز O₂ المتجمع مع الزمن من عينتين متماثلتين من محلول H₂O₂، أُضيف إلى إحداهما 0.50 g من MnO₂. (أ) في أيّ العينتين يكون التحلل أسرع؟ استدل بقيم من الجدول. (ب) فسّر توقف حجم O₂ عند 48 mL في العينة التي فيها MnO₂، وتوقع الحجم النهائي للعينة الأخرى بعد زمن طويل. (ج) فسّر كيف تكفي كتلة صغيرة من MnO₂ لتحليل العينة كلها.', '{"headers":["الزمن (s)","حجم O₂ بوجود 0.50 g من MnO₂","حجم O₂ دون محفز"],"rows":[["0","0 mL","0 mL"],["20","30 mL","1 mL"],["40","45 mL","2 mL"],["60","48 mL","3 mL"],["120","48 mL","6 mL"],["600","48 mL","25 mL"]]}'::jsonb, null, null, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 61 — المحفزات والمثبطات، وص 70 — س43'),
('essay', 2, 'قال طالب: «إذا أضفنا كمية أكبر من MnO₂ إلى محلول H₂O₂ فسنحصل في النهاية على كمية أكبر من الأكسجين». (أ) قوّم هذا القول. (ب) صف تجربة بسيطة تثبت بها أن MnO₂ لا يُستهلك في التفاعل ولا يزيد كمية الأكسجين الناتجة.', null, null, null, 'تقويم', 'تقويم قول وتصميم تجربة', 'صعب', 'الكتاب ص 61 — المحفزات والمثبطات'),
('essay', 3, 'قارن بين المحفز والمادة المتفاعلة في تفاعل كيميائي من حيث: (أ) الاستهلاك في التفاعل. (ب) ظهورهما في المعادلة الكيميائية. (ج) أثر زيادة كمية كل منهما في كمية النواتج النهائية.', null, null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 61 — المحفزات والمثبطات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
