('mcq', 6, 'عندما تنخفض درجة حرارة الجسم يرتجف الشخص (القشعريرة). كيف تساعد القشعريرة على رفع درجة حرارة الجسم؟', null, null, '["تقلصات عضلية سريعة ناتجة عن تفاعلات تطلق طاقة حرارية","تقلل التفاعلات الكيميائية فتحفظ طاقة الجسم","توسع الأوعية الدموية القريبة من سطح الجلد","تزيد التعرق فتنتقل الحرارة إلى داخل الجسم"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'سهل', 'الكتاب ص 67 — الكيمياء والصحة: سرعة التفاعل ودرجة حرارة الجسم (انخفاض درجة حرارة الجسم)'),
('mcq', 7, 'في يوم شديد الحرارة يتعرق الجسم وتتوسع الأوعية الدموية القريبة من سطح الجلد. ما أهمية هذه الاستجابة لعمل الإنزيمات؟', null, null, '["ترفع حرارة الجسم لتسريع التفاعلات الإنزيمية","تزيد فقد الحرارة فتبقى الحرارة قرب 37°C حيث الإنزيمات أكفأ","تخفض حرارة الجسم إلى أقل من 30°C لإبطاء التفاعلات","تزيد إنتاج ATP لتعويض الطاقة المفقودة بالتعرق"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 67 — الكيمياء والصحة: سرعة التفاعل ودرجة حرارة الجسم (ارتفاع درجة حرارة الجسم)'),
('essay', 1, 'يمثل المنحنى الآتي سرعة تفاعل يحفزه إنزيم في جسم الإنسان عند درجات حرارة مختلفة. (أ) صف شكل المنحنى. (ب) فسّر الجزء الصاعد منه. (ج) فسّر الجزء الهابط منه. (د) ماذا تستنتج عن درجة الحرارة المثلى لعمل الإنزيم؟', null, '[{"src":"qimg/chem22/c2-l2b-enzyme.svg","alt":"منحنى سرعة تفاعل يحفزه إنزيم (المحور الرأسي) مع درجة الحرارة بوحدة °C من 0 إلى 60 (المحور الأفقي). ترتفع السرعة تدريجيًا من 0 °C حتى تبلغ أعلى قيمة عند 37 °C تقريبًا (خط متقطع)، ثم تنخفض بسرعة بعد 40 °C حتى تقترب من الصفر عند 60 °C."}]'::jsonb, null, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 67 — الكيمياء والصحة: سرعة التفاعل ودرجة حرارة الجسم (الشكل 1)'),
('essay', 2, 'وضّح كيف ينظم الجسم درجة حرارته ليحافظ على سرعة التفاعلات الحيوية، مبينًا: (أ) الجزء المسؤول عن التنظيم وطريقة عمله. (ب) استجابتين عند انخفاض درجة حرارة الجسم. (ج) استجابتين عند ارتفاعها.', null, null, null, 'فهم', 'شرح', 'متوسط', 'الكتاب ص 67 — الكيمياء والصحة: سرعة التفاعل ودرجة حرارة الجسم'),
('essay', 3, 'يصاب شخص بارتفاع شديد في درجة حرارة جسمه يصل إلى 42°C لمدة طويلة. حلل أثر ذلك في سرعة التفاعلات الحيوية في جسمه، مفرقًا بين أثر الحرارة في الطاقة الحركية للجسيمات وأثرها في الإنزيمات، ثم بيّن أيّ الأثرين هو الغالب.', null, null, null, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 67 — الكيمياء والصحة: سرعة التفاعل ودرجة حرارة الجسم')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
