select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'قانون السرعة يساوي ثابت السرعة مضروبًا في تركيز المادة المتفاعلة مرفوعًا إلى رتبتها؛ والرتبة 3، فيكون R = k[A]³.', '["الأس في قانون السرعة هو الرتبة المحددة تجريبيًّا (3)، وليس المعامل a في المعادلة الموزونة.","الرتبة تظهر أسًّا لتركيز المادة المتفاعلة، لا عاملًا يُضرب في ثابت السرعة.","","قانون السرعة يُكتب بدلالة تراكيز المواد المتفاعلة (A)، وB مادة ناتجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-06T22:20:31.163Z"}'::jsonb),
('mcq', 2, 0, 'رتبة O₂ تساوي 1، والرتبة الكلية 3، فرتبة NO = 3 − 1 = 2؛ لذا قانون السرعة R = k[NO]²[O₂].', '["","جعل رتبة O₂ ثانية، والمعطى أنها أولى؛ فتكون رتبة NO هي 3 − 1 = 2.","مجموع الأسس هنا 4، والرتبة الكلية المعطاة 3.","قانون السرعة يُكتب بدلالة تراكيز المواد المتفاعلة لا المادة الناتجة NO₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.163Z"}'::jsonb),
('mcq', 3, 3, 'تركيز NO يُرفع إلى الأس 2 وتركيز H₂ إلى الأس 1، فقانون السرعة R = k[NO]²[H₂]، والرتبة الكلية 3.', '["أخذ الأسين من معاملات المعادلة الموزونة (2 و2)، والرتبة في H₂ أولى؛ فالرتب تحدد تجريبيًّا.","عكس الرتبتين: الرتبة الثانية لـ NO لا لـ H₂.","استعمل تراكيز النواتج، وقانون السرعة يُكتب بدلالة تراكيز المتفاعلات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.163Z"}'::jsonb),
('mcq', 4, 1, 'العلاقة خط مستقيم يمر بنقطة الأصل؛ فمضاعفة [H₂O₂] من 1.0 إلى 2.0 mol/L تضاعف السرعة من 2.0 × 10⁻⁶ إلى 4.0 × 10⁻⁶ mol/L·s، فالتفاعل من الرتبة الأولى وقانونه R = k[H₂O₂].', '["لو كانت الرتبة الثانية لتضاعفت السرعة أربع مرات عند مضاعفة التركيز، لكنها في المنحنى تتضاعف مرتين فقط (من 1.0 × 10⁻⁶ إلى 2.0 × 10⁻⁶ عند مضاعفة التركيز من 0.5 إلى 1.0 mol/L).","","هذا قانون تفاعل لا تتغير سرعته بتغير التركيز (رتبة صفرية)، والمنحنى يبين أن السرعة تزداد بزيادة التركيز.","H₂O وO₂ ناتجا التحلل، وقانون السرعة يُكتب بدلالة تركيز المادة المتفاعلة H₂O₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-06T22:20:31.164Z"}'::jsonb),
('mcq', 5, 2, 'الرتب تعبر عن تأثير التركيز في السرعة ولا تساوي المعاملات إلا إذا حدث التفاعل في خطوة واحدة، وهذا غير محتمل غالبًا؛ لذلك يحدد قانون السرعة تجريبيًّا.', '["معاملات المعادلة الموزونة ثابتة لا تتغير بتغير درجة الحرارة.","المعادلة الموزونة فيها معاملات للمتفاعلات والنواتج معًا.","","قانون السرعة يربط السرعة بتراكيز المواد المتفاعلة مرفوعة لرتبها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.164Z"}'::jsonb),
('mcq', 6, 1, 'الرتبة الثانية تعني رفع [A] إلى الأس 2، فيكون R = k[A]²؛ ولذلك يتقوس المنحنى (ع) إلى أعلى، إذ تتضاعف السرعة أربع مرات عند مضاعفة التركيز.', '["هذا قانون تفاعل من الرتبة الأولى، وهو ما يمثله المستقيم (ص).","","الرتبة تُكتب أسًّا للتركيز، لا عاملًا يضرب في k.","الأس 3 يعني أن التفاعل من الرتبة الثالثة للمادة A، والمعطى أنه من الرتبة الثانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-06T22:20:31.164Z"}'::jsonb),
('mcq', 7, 3, 'الرتبة الكلية مجموع الرتب: 1 + n = 3، فـ n = 2، ويكون القانون R = k[A][B]².', '["مجموع الأسس هنا 4، والرتبة الكلية 3، فرتبة B = 3 − 1 = 2.","جعل رتبة A ثالثة، والمعطى أنها أولى.","مجموع الأسس هنا 2، أي رتبة كلية ثانية لا ثالثة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-06T22:20:31.164Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) R = k[A]²[B].
(ب) الرتبة الكلية = 2 + 1 = 3، أي أن التفاعل من الرتبة الثالثة.
(ج) أخطأ الطالب لأنه جعل الأسين معاملي المعادلة a وb، والأسس في قانون السرعة هي رتب المواد المتفاعلة التي تحدد تجريبيًّا، ولا تساوي المعاملات بالضرورة.', '["R = k[A]²[B]","الرتبة الكلية 3 (مجموع الأسس)","الأسس رتب تحدد تجريبيًّا لا معاملات المعادلة"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة قانون السرعة صحيحًا","marks":2},{"element":"حساب الرتبة الكلية","marks":1},{"element":"بيان خطأ الطالب مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"قانون صحيح ورتبة كلية صحيحة وتعليل كامل لخطأ الطالب"},{"level":"3–4 درجات","description":"قانون صحيح مع نقص في الرتبة الكلية أو التعليل"},{"level":"1–2 درجة","description":"جزء واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة R = k[A]²[B]² أو تبديل الرتبتين","عدّ الرتبة الكلية 2 بدل 3","القول إن الأسس تساوي المعاملات دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-06T22:20:31.164Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الرتبة الأولى: R = k[A]، والرتبة الثانية: R = k[A]². في الرتبة الأولى تتناسب السرعة طرديًّا مع [A]، فإذا تضاعف التركيز مرتين تضاعفت السرعة مرتين (2¹ = 2). وفي الرتبة الثانية تتناسب السرعة مع مربع التركيز، فإذا تضاعف التركيز مرتين تضاعفت السرعة أربع مرات (2² = 4).', '["R = k[A] للرتبة الأولى","R = k[A]² للرتبة الثانية","مضاعفة التركيز تضاعف السرعة مرتين في الأولى","وأربع مرات في الثانية"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة الرتبة الأولى","marks":1},{"element":"معادلة الرتبة الثانية","marks":1},{"element":"أثر المضاعفة في الرتبة الأولى","marks":1},{"element":"أثر المضاعفة في الرتبة الثانية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلتان صحيحتان وأثر المضاعفة صحيح في الحالتين"},{"level":"2–3 درجات","description":"المعادلتان صحيحتان مع خطأ أو نقص في توضيح الأثر"},{"level":"1 درجة","description":"معادلة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة R = 2k[A] للرتبة الثانية","القول إن السرعة تتضاعف مرتين في الحالتين","الخلط بين الرتبة ومعامل A في المعادلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.165Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) R = k[A]¹[B]²[D]⁰، وبما أن أي عدد مرفوع إلى الأس صفر يساوي 1 فإن [D]⁰ = 1، فيصبح القانون R = k[A][B]².
(ب) الرتبة الكلية = 1 + 2 + 0 = 3.
(ج) يغيب [D] لأن رتبته صفر، أي أن تغيير تركيزه لا يغير السرعة الابتدائية. ولا يعني ذلك أن D لا تشترك في التفاعل؛ فهي مادة متفاعلة في المعادلة وتُستهلك، لكن تركيزها لا يؤثر في سرعة التفاعل.', '["R = k[A][B]²[D]⁰","[D]⁰ = 1 فيصبح R = k[A][B]²","الرتبة الكلية 3","الرتبة الصفرية: تغيير [D] لا يغير السرعة","D تبقى مادة متفاعلة"]'::jsonb, '["كتابة كل تركيز مرفوعًا إلى رتبته: R = k[A]¹[B]²[D]⁰","تبسيط [D]⁰ = 1: R = k[A][B]²","جمع الرتب: 1 + 2 + 0 = 3"]'::jsonb, '[{"element":"القانون بالأسس","marks":1},{"element":"التبسيط","marks":1},{"element":"الرتبة الكلية","marks":1},{"element":"تفسير غياب [D]","marks":1},{"element":"بيان أن D تبقى مادة متفاعلة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"القانون والتبسيط والرتبة صحيحة مع تفسير كامل"},{"level":"3–4 درجات","description":"القانون صحيح مع نقص في التفسير أو الرتبة"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إدخال [D] بالأس 1","جعل الرتبة الكلية 2 بإهمال B أو 4 بعدّ D","القول إن D ليست مادة متفاعلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-06T22:20:31.165Z"}'::jsonb)
