('mcq', 6, 'لتحديد رتبة التفاعل بالنسبة للمادة B من بيانات الجدول الآتي، أي محاولتين تقارن بينهما؟', '{"headers":["المحاولة","[A] الابتدائي (M)","[B] الابتدائي (M)","السرعة الابتدائية (mol/L·s)"],"rows":[["1","0.100","0.100","2.00 × 10⁻³"],["2","0.200","0.100","4.00 × 10⁻³"],["3","0.200","0.200","16.00 × 10⁻³"]]}'::jsonb, null, '["المحاولتان 1 و2؛ لأن السرعة تضاعفت فيهما مرتين","المحاولتان 1 و3؛ لأن الفرق بين سرعتيهما هو الأكبر","أي محاولتين؛ لأن k ثابت في جميع المحاولات","المحاولتان 2 و3؛ لأن [A] ثابت فيهما ويتغير [B] وحده"]'::jsonb, 'فهم', 'إجراء مقارنة السرعات', 'سهل', 'الكتاب ص 65 — مقارنة السرعات الابتدائية'),
('mcq', 7, 'في المنحنى الآتي تمثل المنحنيات (س) و(ص) و(ع) العلاقة بين السرعة الابتدائية وتركيز المادة المتفاعلة A في ثلاثة تفاعلات. أي منحنى يمثل تفاعلًا من الرتبة الأولى بالنسبة للمادة A؟', null, '[{"src":"qimg/chem22/c2-l3-three-curves.svg","alt":"منحنى بياني محوره الأفقي تركيز المادة المتفاعلة [A] بوحدة mol/L، ومحوره الرأسي السرعة الابتدائية R، بلا أرقام على المحورين. فيه ثلاثة منحنيات: (س) خط أفقي ثابت الارتفاع لا تتغير فيه السرعة مهما تغير التركيز؛ (ص) خط مستقيم يبدأ من نقطة الأصل وتزداد فيه السرعة بانتظام مع التركيز؛ (ع) منحنى يبدأ من نقطة الأصل ويتقوس إلى أعلى، فتزداد فيه السرعة ببطء عند التراكيز المنخفضة ثم بسرعة متزايدة عند التراكيز العالية."}]'::jsonb, '["المنحنى (ص)","المنحنى (س)","المنحنى (ع)","المنحنيان (ص) و(ع) معًا"]'::jsonb, 'فهم', 'تحديد الرتبة من منحنى', 'سهل', 'الكتاب ص 64 — الشكل 14-2 العلاقة المباشرة بين التركيز والسرعة'),
('essay', 1, 'يبين الجدول الآتي بيانات السرعات الابتدائية للتفاعل aA + bB → نواتج. حدد بطريقة مقارنة السرعات الابتدائية رتبة التفاعل بالنسبة لكل من A وB، ثم اكتب قانون السرعة، وحدد الرتبة الكلية.', '{"headers":["المحاولة","[A] الابتدائي (M)","[B] الابتدائي (M)","السرعة الابتدائية (mol/L·s)"],"rows":[["1","0.100","0.100","2.00 × 10⁻³"],["2","0.200","0.100","4.00 × 10⁻³"],["3","0.200","0.200","16.00 × 10⁻³"]]}'::jsonb, null, null, 'تحليل', 'تحديد قانون السرعة من بيانات', 'متوسط', 'الكتاب ص 65 — الجدول 2-2'),
('essay', 2, 'تبين البيانات الآتية السرعات الابتدائية لتفاعل افتراضي aA + bB → نواتج عند درجة حرارة ثابتة. حدد رتبة التفاعل لكل مادة متفاعلة، واكتب قانون السرعة، وحدد الرتبة الكلية، موضحًا خطوات المقارنة.', '{"headers":["المحاولة","[A] الابتدائي (M)","[B] الابتدائي (M)","السرعة الابتدائية (mol/L·s)"],"rows":[["1","0.020","0.010","1.2 × 10⁻⁴"],["2","0.040","0.010","4.8 × 10⁻⁴"],["3","0.020","0.030","3.6 × 10⁻⁴"]]}'::jsonb, null, null, 'تحليل', 'تحديد الرتب من بيانات', 'صعب', 'الكتاب ص 65 — تحديد رتبة التفاعل'),
