('mcq', 4, 'ما المقصود برتبة التفاعل بالنسبة لمادة متفاعلة؟', null, null, '["الأس الذي يرفع إليه تركيز المادة في قانون السرعة","معامل المادة في المعادلة الكيميائية الموزونة","عدد خطوات التفاعل التي تشترك فيها المادة","النسبة بين سرعة التفاعل وتركيز المادة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'متوسط', 'الكتاب ص 64 — رتبة التفاعل'),
