('mcq', 4, 0, 'رتبة التفاعل بالنسبة لمادة هي الرقم العلوي (الأس) الذي يُرفع إليه تركيزها في قانون السرعة، وتصف تأثير التغير في تركيزها في سرعة التفاعل.', '["","الرتبة تحدد تجريبيًّا ولا تساوي المعامل بالضرورة.","الرتبة لا تعني عدد الخطوات؛ هي أس التركيز في قانون السرعة.","هذه النسبة في الرتبة الأولى تساوي k، لا الرتبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-06T22:20:31.170Z"}'::jsonb),
('mcq', 5, 3, 'يحدد قانون سرعة التفاعل تجريبيًّا باستعمال طريقة مقارنة السرعات الابتدائية عند تراكيز مختلفة.', '["المعاملات لا تساوي الرتب بالضرورة، لذلك لا يُستنتج القانون منها.","ΔH تبين هل التفاعل طارد أم ماص للحرارة، ولا تحدد قانون السرعة.","الكتل المولية لا علاقة لها بتحديد الرتب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-06T22:20:31.170Z"}'::jsonb),
('mcq', 6, 1, 'في القانون العام R = k[A]ᵐ[B]ⁿ يمثل [A] و[B] تراكيز المواد المتفاعلة، ويمثل m وn رتبتي التفاعل بالنسبة للمادتين A وB، ويتم تحديدهما تجريبيًّا.', '["m وn يحددان تجريبيًّا، ولا يساويان المعاملين a وb بالضرورة.","","التركيزان هما [A] و[B]، أما m وn فأسّاهما.","للتفاعل ثابت سرعة واحد k، وm وn ليسا ثوابت سرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-06T22:20:31.170Z"}'::jsonb),
('mcq', 7, 2, 'من القانون R = k[H₂O₂] تكون النسبة R ÷ [H₂O₂] ثابتة وتساوي k، وهذه النسبة هي ميل المستقيم؛ فالميل يمثل ثابت سرعة التفاعل k.', '["الرتبة (1) تظهر في كون العلاقة خطًّا مستقيمًا، لا في قيمة الميل.","متوسط السرعة تغير التركيز في وحدة الزمن، والميل هنا نسبة السرعة إلى التركيز.","","التركيز يقرأ على المحور الأفقي، والميل نسبة R إلى [H₂O₂]."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-06T22:20:31.171Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قانون سرعة التفاعل: العلاقة الرياضية بين سرعة التفاعل الكيميائي وتركيز المواد المتفاعلة عند درجة حرارة محددة.
ثابت سرعة التفاعل k: قيمة عددية ثابتة تربط سرعة التفاعل بتركيز المواد المتفاعلة عند درجة حرارة معينة.
قانون سرعة التفاعل A → B: R = k[A]، حيث R سرعة التفاعل، وk ثابت سرعة التفاعل، و[A] تركيز المادة المتفاعلة A.', '["تعريف قانون سرعة التفاعل","تعريف ثابت سرعة التفاعل","R = k[A]","دلالة الرموز R وk و[A]"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف قانون السرعة","marks":1},{"element":"تعريف ثابت السرعة","marks":1},{"element":"كتابة القانون","marks":1},{"element":"تحديد دلالة الرموز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريفان والقانون ودلالة الرموز صحيحة"},{"level":"2–3 درجات","description":"تعريف واحد صحيح مع القانون"},{"level":"1 درجة","description":"كتابة القانون فقط أو تعريف واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال شرط درجة الحرارة المحددة","الخلط بين قانون السرعة ومتوسط السرعة","كتابة R = k[B] بتركيز الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.171Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ثابت سرعة التفاعل k يربط القيمة العددية لسرعة التفاعل بتراكيز المواد المتفاعلة عند درجة حرارة معينة؛ فهو العامل الذي يحول حاصل ضرب التراكيز المرفوعة لرتبها إلى قيمة السرعة (R = k[A]). وقيمته محددة لكل تفاعل، ولا تتغير بتغير التركيز. والقيمة الكبيرة لـ k تعني أن المادة المتفاعلة تتفاعل بسرعة، فيكون التفاعل سريعًا عند التراكيز نفسها.', '["k يربط السرعة بتراكيز المتفاعلات عند درجة حرارة معينة","قيمته محددة لكل تفاعل","القيمة الكبيرة لـ k تعني تفاعلًا سريعًا"]'::jsonb, '[]'::jsonb, '[{"element":"وظيفة k في القانون","marks":2},{"element":"ثبات قيمته لكل تفاعل عند درجة حرارة معينة","marks":1},{"element":"دلالة القيمة الكبيرة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"شرح كامل للوظيفة والدلالة"},{"level":"2–3 درجات","description":"شرح الوظيفة مع نقص في الدلالة أو العكس"},{"level":"1 درجة","description":"عبارة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن k يساوي السرعة نفسها","القول إن القيمة الكبيرة لـ k تعني تفاعلًا بطيئًا","إغفال ارتباط k بدرجة حرارة معينة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-06T22:20:31.171Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) متوسط سرعة التفاعل يربط التغير في تركيز المادة المتفاعلة أو الناتجة بالتغير في الزمن، أما قانون السرعة فيربط سرعة التفاعل بتراكيز المواد المتفاعلة عند درجة حرارة محددة.
(ب) متوسط السرعة = التغير في التركيز ÷ Δt، أما قانون السرعة فصورته R = k[A]ᵐ[B]ⁿ.
سبب الفائدة: قانون السرعة يمكّن من حساب السرعة عند أي تراكيز وتوقع أثر تغيير تركيز أي مادة متفاعلة في السرعة، أما متوسط السرعة فيصف فترة زمنية محددة فقط.', '["متوسط السرعة يربط تغير التركيز بالزمن","قانون السرعة يربط السرعة بتراكيز المتفاعلات","التعبيران الرياضيان","سبب مقبول لفائدة قانون السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في (أ)","marks":2},{"element":"المقارنة في (ب)","marks":2},{"element":"اقتراح سبب مقبول","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة في الجانبين وسبب مقبول"},{"level":"3–4 درجات","description":"مقارنة صحيحة في جانب واحد مع سبب"},{"level":"1–2 درجة","description":"عبارة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّهما مفهومًا واحدًا","كتابة متوسط السرعة بدلالة k","إغفال اعتماد قانون السرعة على تراكيز المتفاعلات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.171Z"}'::jsonb)
