('essay', 3, null::int, null, null, 'العبارة غير دقيقة؛ فثابت سرعة التفاعل k ثابت للتفاعل عند درجة حرارة معينة فقط، ولا يتغير مع تغير التركيز، لكنه يتغير مع تغير درجة الحرارة. فلا يكون k ثابتًا إذا تغيرت درجة حرارة التفاعل. وتدل قيمة k على مدى سرعة التفاعل: القيمة الكبيرة لـ k تعني أن المادة المتفاعلة تتفاعل بسرعة، والقيمة الصغيرة تعني تفاعلًا بطيئًا عند التراكيز نفسها.', '["الحكم بأن العبارة غير دقيقة","k ثابت عند درجة حرارة معينة ولا يتغير مع التركيز","k لا يكون ثابتًا عند تغير درجة الحرارة","القيمة الكبيرة لـ k تعني تفاعلًا سريعًا"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على العبارة","marks":1},{"element":"تحديد شرط ثبات k","marks":1},{"element":"متى لا يكون k ثابتًا","marks":1},{"element":"دلالة قيمة k","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع توضيح كامل لشرط الثبات ودلالة k"},{"level":"2–3 درجات","description":"حكم صحيح مع نقص في أحد العناصر"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","القول إن k يتغير مع التركيز","القول إن k الكبيرة تعني تفاعلًا بطيئًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-06T22:20:31.173Z"}'::jsonb)
