from (values
('mcq', 1, 3, 'في الرتبة الأولى R = k[A] تتناسب السرعة طرديًّا مع التركيز مرفوعًا إلى الأس 1؛ فزيادة التركيز ثلاث مرات تزيد السرعة 3¹ = 3 مرات.', '["هذا يحدث في تفاعل من الرتبة الثانية (3² = 9).","هذا يحدث في تفاعل من الرتبة الصفرية، والتفاعل هنا من الرتبة الأولى.","السرعة تتناسب طرديًّا مع التركيز في الرتبة الأولى، فلا تنخفض بزيادته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-06T22:20:31.174Z"}'::jsonb),
('mcq', 2, 0, 'R = k[A]²، فإذا أصبح [A] نصف قيمته تصبح السرعة (½)² = ¼ من قيمتها، أي تنخفض إلى الربع.', '["","هذا يحدث في الرتبة الأولى؛ أما في الرتبة الثانية فالسرعة تتغير بمربع نسبة تغير التركيز.","خفض التركيز يخفض السرعة ولا يزيدها.","استعمل (½)² بالعكس؛ فخفض التركيز يخفض السرعة إلى ربعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-06T22:20:31.174Z"}'::jsonb),
('mcq', 3, 2, 'التفاعل من الرتبة الأولى (مستقيم يمر بالأصل)؛ فعند 1.5 mol/L تكون السرعة 3.0 × 10⁻⁶، ومضاعفة التركيز إلى 3.0 mol/L تضاعف السرعة إلى 6.0 × 10⁻⁶ mol/L·s.', '["عامل التفاعل كأنه من الرتبة الثانية؛ والمستقيم يبين أنه من الرتبة الأولى.","هذه السرعة عند 1.5 mol/L لا عند 3.0 mol/L.","","هذه قيمة k العددية (أو السرعة عند 1.0 mol/L)، لا السرعة عند 3.0 mol/L."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-06T22:20:31.174Z"}'::jsonb),
('mcq', 4, 1, 'السرعة الجديدة = k(2[NO])²(2[H₂]) = 2² × 2 × k[NO]²[H₂] = 8R؛ أي أن السرعة تزداد ثماني مرات.', '["احتسب أثر مضاعفة [NO] فقط (2² = 4) وأهمل مضاعفة [H₂].","","جمع الأثرين (4 + 2) بدل ضربهما (4 × 2).","عامل H₂ كأنه من الرتبة الثانية أيضًا (2² × 2² = 16)، ورتبته أولى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-06T22:20:31.175Z"}'::jsonb),
('mcq', 5, 3, 'تضاعف السرعة أربع مرات عند مضاعفة التركيز يعني الرتبة الثانية R = k[A]² (2² = 4)، ومنحناها يبدأ من الأصل ويتقوس إلى أعلى، وهو المنحنى (ع).', '["المستقيم (ص) يمثل الرتبة الأولى، فمضاعفة التركيز تضاعف السرعة مرتين فقط.","في (س) لا تتغير السرعة بتغير التركيز (رتبة صفرية).","في (ص) تتضاعف السرعة مرتين لا أربع مرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-06T22:20:31.175Z"}'::jsonb),
('mcq', 6, 2, '[A]⁰ = 1 مهما كانت قيمة [A]؛ فمضاعفة [A] تجعل السرعة 2⁰ × R = R، أي أنها لا تتغير.', '["رتبة A صفر، و2⁰ = 1، فلا تتغير السرعة.","الأس صفر لا يعني تناسبًا عكسيًّا؛ فأي عدد مرفوع للأس صفر يساوي 1.","","الأس صفر يجعل [A]⁰ = 1 لا صفرًا، فتبقى السرعة k[B]."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-06T22:20:31.175Z"}'::jsonb),
('mcq', 7, 0, 'السرعة الجديدة = k(½[A])(2[B])² = ½ × 4 × k[A][B]² = 2R؛ أي أن السرعة تتضاعف مرتين.', '["","عدّ أثر B مضاعفة مرتين فقط (رتبة أولى)، فتعادل الأثران؛ لكن رتبة B ثانية.","احتسب أثر B فقط (2² = 4) وأهمل انخفاض [A] إلى النصف.","احتسب أثر A فقط وأهمل الزيادة الناتجة عن مضاعفة [B]."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.175Z"}'::jsonb),
('essay', 1, null::int, null, null, 'بما أن التفاعل من الرتبة الثانية للمادة A فإن R ∝ [A]².
