(ب) R = k[CH₃N₂CH₃] = 2.08 × 10⁻⁴ × 0.048 = 1.0 × 10⁻⁵ mol/L·s.', '["k = R ÷ [CH₃N₂CH₃]","k = 2.1 × 10⁻⁴ s⁻¹","R = 1.0 × 10⁻⁵ mol/L·s عند 0.048 M"]'::jsonb, '["k = 2.5 × 10⁻⁶ ÷ 0.012 = 2.08 × 10⁻⁴ ≈ 2.1 × 10⁻⁴ s⁻¹","R = 2.08 × 10⁻⁴ × 0.048 = 1.0 × 10⁻⁵ mol/L·s"]'::jsonb, '[{"element":"كتابة قانون السرعة وجعل k موضوعه","marks":1},{"element":"قيمة k","marks":1},{"element":"وحدة k","marks":1},{"element":"حساب السرعة عند 0.048 M","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب k ووحدته والسرعة صحيحة"},{"level":"2–3 درجات","description":"k صحيح مع خطأ في الوحدة أو السرعة"},{"level":"1 درجة","description":"كتابة القانون فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب السرعة في التركيز بدل القسمة","كتابة وحدة k بوحدة mol/L·s","معاملة التفاعل كأنه من الرتبة الثانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-06T22:20:31.179Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) k = R ÷ [CH₃CHO]² = 2.70 × 10⁻¹¹ ÷ (2.00 × 10⁻³)² = 2.70 × 10⁻¹¹ ÷ 4.00 × 10⁻⁶ = 6.75 × 10⁻⁶ L/mol·s (والمحاولة 2 تعطي 10.8 × 10⁻¹¹ ÷ (4.00 × 10⁻³)² = 6.75 × 10⁻⁶ أيضًا).
(ب) R₃ = k[CH₃CHO]² = 6.75 × 10⁻⁶ × (8.00 × 10⁻³)² = 6.75 × 10⁻⁶ × 6.40 × 10⁻⁵ = 4.32 × 10⁻¹⁰ mol/L·s.', '["k = R ÷ [CH₃CHO]²","k = 6.75 × 10⁻⁶ L/mol·s","R₃ = 4.32 × 10⁻¹⁰ mol/L·s"]'::jsonb, '["(2.00 × 10⁻³)² = 4.00 × 10⁻⁶","k = 2.70 × 10⁻¹¹ ÷ 4.00 × 10⁻⁶ = 6.75 × 10⁻⁶ L/mol·s","(8.00 × 10⁻³)² = 6.40 × 10⁻⁵","R₃ = 6.75 × 10⁻⁶ × 6.40 × 10⁻⁵ = 4.32 × 10⁻¹⁰ mol/L·s"]'::jsonb, '[{"element":"قيمة k","marks":2},{"element":"وحدة k","marks":1},{"element":"حساب R₃","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"k ووحدته وR₃ صحيحة مع الخطوات"},{"level":"3–4 درجات","description":"k صحيح مع خطأ في الوحدة أو في R₃"},{"level":"1–2 درجة","description":"خطوة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال تربيع التركيز","وحدة k: s⁻¹ بدل L/mol·s","مضاعفة سرعة المحاولة 2 مرتين فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-06T22:20:31.180Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المحاولتان 1 و2: تضاعف [A] و[B] ثابت، فتضاعفت السرعة (8.0 × 10⁻⁴ ÷ 4.0 × 10⁻⁴ = 2) ← m = 1. المحاولتان 1 و3: تضاعف [B] و[A] ثابت، فزادت السرعة أربع مرات (1.6 × 10⁻³ ÷ 4.0 × 10⁻⁴ = 4) ← n = 2. إذن R = k[A][B]².
(ب) k = R ÷ ([A][B]²) = 4.0 × 10⁻⁴ ÷ (0.10 × 0.10²) = 0.40 L²/mol²·s.
(ج) R = 0.40 × 0.30 × (0.30)² = 1.1 × 10⁻² mol/L·s.', '["m = 1","n = 2","R = k[A][B]²","k = 0.40 L²/mol²·s","R = 1.1 × 10⁻² mol/L·s"]'::jsonb, '["نسبة السرعة (2 إلى 1) = 2 ← m = 1","نسبة السرعة (3 إلى 1) = 4 ← n = 2","k = 4.0 × 10⁻⁴ ÷ (0.10 × 0.010) = 0.40 L²/mol²·s","R = 0.40 × 0.30 × 0.090 = 0.0108 ≈ 1.1 × 10⁻² mol/L·s"]'::jsonb, '[{"element":"تحديد قانون السرعة","marks":2},{"element":"قيمة k ووحدته","marks":2},{"element":"حساب السرعة الجديدة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"القانون وk ووحدته والسرعة صحيحة"},{"level":"3–5 درجات","description":"القانون صحيح مع خطأ في k أو السرعة"},{"level":"1–2 درجة","description":"تحديد رتبة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال تربيع [B]","وحدة k: L/mol·s بدل L²/mol²·s","التقريب الخاطئ للأرقام المعنوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-06T22:20:31.180Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C2-L3-O07') and x.type = v.type and x.number = v.number
