insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالتفاعل العكسي؟', null, null, '["التفاعل الذي تتحول فيه المتفاعلات كلها إلى نواتج ثم يتوقف","التفاعل الكيميائي الذي يحدث في الاتجاهين الأمامي والعكسي","التفاعل الذي يحدث في اتجاه واحد فقط من النواتج إلى المتفاعلات","التفاعل الذي تتساوى فيه تراكيز المتفاعلات وتراكيز النواتج"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 79 — التفاعلات العكسية والاتزان الكيميائي'),
('mcq', 2, 'أيّ مما يأتي يُستعمل في المعادلة الكيميائية للدلالة على أن التفاعل عكسي؟', null, null, '["السهم المفرد → المتجه نحو النواتج","السهم المفرد ← المتجه نحو المتفاعلات","كتابة الحالة الفيزيائية (g) بعد كل صيغة","السهم المزدوج ⇌ بين المتفاعلات والنواتج"]'::jsonb, 'تذكر', 'تذكر رمز', 'سهل', 'الكتاب ص 79 — التفاعلات العكسية والاتزان الكيميائي'),
('mcq', 3, 'في التفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g)، ماذا يحدث في التفاعل العكسي؟', null, null, '["تتحلل الأمونيا لتكوّن غازي النيتروجين والهيدروجين","يتحد النيتروجين والهيدروجين لتكوين الأمونيا","يتوقف التفاعل الأمامي توقفًا تامًّا","يتحول غاز النيتروجين إلى غاز الهيدروجين"]'::jsonb, 'تذكر', 'تحديد اتجاه التفاعل', 'سهل', 'الكتاب ص 79 — التفاعلات العكسية والاتزان الكيميائي'),
('mcq', 4, 'في التفاعل العكسي الآتي: 2NO(g) + O₂(g) ⇌ 2NO₂(g)، ما المادة (أو المواد) المتفاعلة في التفاعل العكسي؟', null, null, '["NO وO₂","NO فقط","NO₂ فقط","NO وO₂ وNO₂"]'::jsonb, 'فهم', 'تحديد متفاعلات التفاعل العكسي', 'متوسط', 'الكتاب ص 79 — التفاعلات العكسية والاتزان الكيميائي'),
('mcq', 5, 'يمثل المنحنى الآتي تغير تراكيز المواد مع الزمن لتفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) بدأ بالنيتروجين والهيدروجين فقط في وعاء مغلق. ما الدليل من المنحنى على أن التفاعل عكسي ولم يكتمل؟', null, '[{"src":"qimg/chem22/c3-l1a-conc-nh3.svg","alt":"منحنيات تغير التركيز (mol/L) مع الزمن لتفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) في وعاء مغلق بدأ بالنيتروجين والهيدروجين فقط، دون قيم عددية على المحورين. منحنى [H₂] يبدأ من أعلى قيمة ويتناقص، ومنحنى [N₂] يبدأ من قيمة أقل ويتناقص، ومنحنى [NH₃] يبدأ من الصفر ويتزايد، ويتقاطع منحنيا [N₂] و[NH₃] قبل t₂. يقل ميل المنحنيات الثلاثة تدريجيًّا حتى الزمن t₂، ثم تصبح خطوطًا أفقية من t₂ حتى t₃ ونهاية الرسم. في الجزء الأفقي يكون [H₂] الأعلى، ثم [NH₃]، ثم [N₂] أقل منه بقليل، ولا يصل أي منها إلى الصفر. على المحور الأفقي ثلاثة أزمنة مُعلَّمة بخطوط رأسية متقطعة: t₁ (والمنحنيات ما زالت تتغير)، وt₂ (بداية ثبات المنحنيات)، وt₃ (بعد الثبات)."}]'::jsonb, '["تناقص [N₂] و[H₂] في بداية التفاعل","تزايد [NH₃] من الصفر حتى الزمن t₂","تقاطع منحنيي [N₂] و[NH₃] قبل t₂","ثبات [N₂] و[H₂] عند قيم أكبر من الصفر"]'::jsonb, 'فهم', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 79 — الشكل 3-2 تراكيز المتفاعلات والنواتج مقابل الزمن'),
('mcq', 6, 'يصف العلماء التفاعل بأنه مكتمل عندما:', null, null, '["تتحول المتفاعلات كاملة إلى نواتج","تتساوى سرعتا التفاعلين الأمامي والعكسي","تثبت تراكيز المتفاعلات والنواتج","يُكتب التفاعل بسهم مزدوج ⇌"]'::jsonb, 'تذكر', 'تمييز مفهوم', 'متوسط', 'الكتاب ص 79 — التفاعلات العكسية والاتزان الكيميائي'),
('mcq', 7, 'يمثل المنحنيان (س) و(ص) في الشكل الآتي تغير سرعتي التفاعلين الأمامي والعكسي مع الزمن لتفاعل عكسي بدأ بالمتفاعلات فقط. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/chem22/c3-l1a-rates-xy.svg","alt":"منحنيان غير مسميين، (س) و(ص)، لتغير سرعة التفاعل مع الزمن لتفاعل عكسي بدأ بالمتفاعلات فقط في وعاء مغلق، دون قيم عددية. المنحنى (ص) يبدأ من قيمة عالية ويتناقص تدريجيًّا، والمنحنى (س) يبدأ من الصفر ويتزايد تدريجيًّا. يلتقي المنحنيان عند الزمن t₂ المُعلَّم بخط متقطع، ويستمران بعده خطًّا أفقيًّا واحدًا فوق الصفر حتى نهاية الرسم."}]'::jsonb, '["(ص) يمثل سرعة التفاعل العكسي؛ لأن سرعته تكون أكبر ما يمكن في بداية التفاعل","(س) يمثل سرعة التفاعل الأمامي؛ لأن سرعته تزداد بتكوّن المزيد من النواتج","(س) يمثل سرعة التفاعل العكسي؛ لأنه لا يبدأ إلا بعد تكوّن النواتج ثم تزداد سرعته بزيادة تركيزها","المنحنيان يمثلان التفاعل الأمامي؛ لأن التفاعل العكسي يبدأ بعد الزمن t₂"]'::jsonb, 'فهم', 'تفسير رسم بياني', 'صعب', 'الكتاب ص 80 — سير تفاعل تكوين الأمونيا وتعريف الاتزان الكيميائي'),
('essay', 1, 'عرّف التفاعل العكسي، ثم اكتب معادلة التفاعل الأمامي ومعادلة التفاعل العكسي لتكوين الأمونيا NH₃ من غازي النيتروجين والهيدروجين، ثم ادمجهما في معادلة واحدة، مبيّنًا الرمز الذي يدل على أن التفاعل عكسي.', null, null, null, 'فهم', 'تعريف وكتابة معادلات', 'متوسط', 'الكتاب ص 79 — التفاعلات العكسية والاتزان الكيميائي'),
('essay', 2, 'يحدث الاتزان I₂(s) ⇌ I₂(g) في دورق مغلق عند درجة حرارة ثابتة. صف ما يحدث في كل من التفاعل الأمامي والتفاعل العكسي، واذكر اسم التفاعل الأمامي، ثم فسّر لماذا تظهر جزيئات اليود المشع I-131 في الحالتين الصلبة والغازية في دورق اليود غير المشع بعد وصل دورقين متزنين أحدهما بالآخر مدة من الزمن.', null, null, null, 'فهم', 'وصف وتفسير', 'صعب', 'الكتاب ص 82 — المبنيان المتصلان وتسامي اليود'),
('essay', 3, 'يمثل المنحنى الآتي تغير التراكيز مع الزمن لتفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) بدأ بالنيتروجين والهيدروجين فقط. (أ) فسّر لماذا يقل ميل منحنيي [N₂] و[H₂] تدريجيًّا بين بداية التفاعل والزمن t₂. (ب) فسّر لماذا لا يصل [N₂] ولا [H₂] إلى الصفر. (ج) ماذا تستنتج عن نوع هذا التفاعل؟', null, '[{"src":"qimg/chem22/c3-l1a-conc-nh3.svg","alt":"منحنيات تغير التركيز (mol/L) مع الزمن لتفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) في وعاء مغلق بدأ بالنيتروجين والهيدروجين فقط، دون قيم عددية على المحورين. منحنى [H₂] يبدأ من أعلى قيمة ويتناقص، ومنحنى [N₂] يبدأ من قيمة أقل ويتناقص، ومنحنى [NH₃] يبدأ من الصفر ويتزايد، ويتقاطع منحنيا [N₂] و[NH₃] قبل t₂. يقل ميل المنحنيات الثلاثة تدريجيًّا حتى الزمن t₂، ثم تصبح خطوطًا أفقية من t₂ حتى t₃ ونهاية الرسم. في الجزء الأفقي يكون [H₂] الأعلى، ثم [NH₃]، ثم [N₂] أقل منه بقليل، ولا يصل أي منها إلى الصفر. على المحور الأفقي ثلاثة أزمنة مُعلَّمة بخطوط رأسية متقطعة: t₁ (والمنحنيات ما زالت تتغير)، وt₂ (بداية ثبات المنحنيات)، وt₃ (بعد الثبات)."}]'::jsonb, null, 'تحليل', 'تفسير رسم بياني', 'صعب', 'الكتاب ص 79–80 — الشكل 3-2 وسير تفاعل تكوين الأمونيا')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'التفاعل العكسي هو التفاعل الكيميائي الذي يحدث في الاتجاهين الأمامي والعكسي؛ فتتحول المتفاعلات إلى نواتج، وتتحول النواتج مرة أخرى إلى متفاعلات.', '["هذا وصف التفاعل المكتمل؛ أما التفاعل العكسي فتتحول فيه النواتج أيضًا إلى متفاعلات.","","التفاعل العكسي يحدث في الاتجاهين معًا، لا في اتجاه واحد.","تساوي التراكيز ليس تعريفًا للتفاعل العكسي، ولا يتحقق عادة حتى عند الاتزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-06T22:20:31.180Z"}'::jsonb),
('mcq', 2, 3, 'يدمج الكيميائيون معادلتي التفاعلين الأمامي والعكسي في معادلة واحدة يُستعمل فيها السهم المزدوج ⇌ ليشير إلى حدوث التفاعل في الاتجاهين.', '["السهم المفرد → يدل على التفاعل الأمامي وحده.","السهم ← يدل على التفاعل العكسي وحده، لا على الاتجاهين معًا.","رمز الحالة الفيزيائية لا يدل على اتجاه التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-06T22:20:31.180Z"}'::jsonb),
('mcq', 3, 0, 'في التفاعل العكسي تكون الأمونيا هي المادة المتفاعلة، فتتحلل لتكوّن غازي الهيدروجين والنيتروجين: N₂(g) + 3H₂(g) ← 2NH₃(g).', '["","هذا هو التفاعل الأمامي، لا العكسي.","التفاعل العكسي لا يوقف التفاعل الأمامي؛ فالتفاعلان يحدثان معًا.","لا تتحول مادة متفاعلة إلى أخرى؛ ففي التفاعل العكسي تتحلل الأمونيا (الناتج) إلى المتفاعلات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.181Z"}'::jsonb),
('mcq', 4, 2, 'تكون متفاعلات التفاعل الأمامي في الجهة اليسرى من الأسهم، ومتفاعلات التفاعل العكسي في الجهة اليمنى؛ لذا فالمادة المتفاعلة في التفاعل العكسي هي NO₂ فقط، ويتحلل إلى NO وO₂.', '["NO وO₂ هما متفاعلا التفاعل الأمامي، ويقعان في الجهة اليسرى من الأسهم.","NO ناتج من نواتج التفاعل العكسي، وليس متفاعلًا فيه.","","متفاعلات التفاعل العكسي هي المواد في الجهة اليمنى فقط، وهي NO₂ وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.181Z"}'::jsonb),
('mcq', 5, 3, 'لو كان التفاعل مكتملًا لاستُهلكت المتفاعلات حتى يصل تركيز أحدها إلى الصفر. أما في المنحنى فيثبت [N₂] و[H₂] عند قيم أكبر من الصفر، أي إن المتفاعلات لم تتحول كاملة إلى نواتج؛ لأن الأمونيا المتكونة تتحلل أيضًا في التفاعل العكسي.', '["التناقص في البداية يحدث في أي تفاعل يستهلك متفاعلاته، مكتملًا كان أم غير مكتمل.","تكوّن الناتج يحدث في كل تفاعل، ولا يدل وحده على أن التفاعل عكسي.","التقاطع يعني تساوي تركيزين لحظة واحدة، ولا علاقة له باكتمال التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.181Z"}'::jsonb),
('mcq', 6, 0, 'يوصف التفاعل بأنه مكتمل عندما تتحول المتفاعلات كاملة إلى نواتج، إلا أن معظم التفاعلات لا تكتمل، بل تظهر وكأنها توقفت لأنها عكسية.', '["","هذا وصف حالة الاتزان في التفاعل العكسي، لا التفاعل المكتمل.","ثبات التراكيز مع بقاء المتفاعلات يدل على الاتزان، لا على اكتمال التفاعل.","السهم المزدوج يدل على أن التفاعل عكسي، أي غير مكتمل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-06T22:20:31.181Z"}'::jsonb),
('mcq', 7, 2, 'بما أن التفاعل بدأ بالمتفاعلات فقط، فسرعة التفاعل العكسي صفر في البداية، ثم يحدث ببطء بمجرد تكوّن النواتج، وتزداد سرعته مع زيادة تركيزها؛ وهذا هو المنحنى (س). أما (ص) فيمثل التفاعل الأمامي الذي تتناقص سرعته بنقص تراكيز المتفاعلات.', '["في البداية لا توجد نواتج، فسرعة التفاعل العكسي صفر؛ و(ص) يمثل التفاعل الأمامي.","سرعة التفاعل الأمامي تتناقص بنقص تراكيز المتفاعلات، فهي المنحنى (ص) لا (س).","","التفاعل العكسي يبدأ بمجرد تكوّن النواتج، لا بعد الوصول إلى الاتزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-06T22:20:31.181Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التفاعل العكسي: التفاعل الكيميائي الذي يحدث في الاتجاهين الأمامي والعكسي. التفاعل الأمامي: N₂(g) + 3H₂(g) → 2NH₃(g). التفاعل العكسي: N₂(g) + 3H₂(g) ← 2NH₃(g) (تتحلل الأمونيا إلى نيتروجين وهيدروجين). المعادلة المدمجة: N₂(g) + 3H₂(g) ⇌ 2NH₃(g)، والسهم المزدوج ⇌ يدل على حدوث التفاعلين في الاتجاهين.', '["تعريف التفاعل العكسي","معادلة التفاعل الأمامي موزونة","معادلة التفاعل العكسي","المعادلة المدمجة بالسهم المزدوج ⇌ وبيان دلالته"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التفاعل العكسي","marks":1},{"element":"معادلة التفاعل الأمامي","marks":1},{"element":"معادلة التفاعل العكسي","marks":1},{"element":"المعادلة المدمجة ودلالة الرمز ⇌","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، ومعادلتان صحيحتان، ودمج صحيح بالسهم المزدوج مع بيان دلالته"},{"level":"2–3 درجات","description":"تعريف صحيح مع خطأ أو نقص في المعادلات أو الدمج"},{"level":"1 درجة","description":"تعريف فقط أو معادلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة المعادلات دون وزن (N₂ + H₂ → NH₃)","عكس اتجاه السهم في التفاعل العكسي مع إبقاء المواد في أماكنها خطأً","الخلط بين السهم المزدوج وعلامة المساواة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-06T22:20:31.182Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في التفاعل الأمامي (التسامي) تتحول جزيئات اليود من الحالة الصلبة إلى الحالة الغازية مباشرة، وفي التفاعل العكسي تعود جزيئات اليود الغازية إلى الحالة الصلبة. وعند وصل دورق يحوي اليود المشع I-131 بدورق يحوي اليود غير المشع I-127 ينتقل بخار اليود بين الدورقين، وتظهر جزيئات مشعة في الحالتين الصلبة والغازية في الدورقين؛ وهذا دليل على أن الجزيئات تتحول باستمرار من الصلبة إلى الغازية (التفاعل الأمامي) ومن الغازية إلى الصلبة (التفاعل العكسي)، أي إن التفاعل يحدث في الاتجاهين معًا.', '["التفاعل الأمامي: صلب → غاز مباشرة","اسم التفاعل الأمامي: التسامي","التفاعل العكسي: غاز → صلب","انتقال البخار بين الدورقين","التفسير: التحول مستمر في الاتجاهين"]'::jsonb, '[]'::jsonb, '[{"element":"وصف التفاعل الأمامي وتسميته","marks":1},{"element":"وصف التفاعل العكسي","marks":1},{"element":"بيان انتقال جزيئات اليود المشع بين الدورقين","marks":1},{"element":"الاستنتاج: التفاعل يحدث في الاتجاهين باستمرار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف الاتجاهين وتسمية التسامي وتفسير ظهور اليود المشع في الحالتين تفسيرًا كاملًا"},{"level":"2–3 درجات","description":"وصف الاتجاهين مع تفسير ناقص لتجربة اليود المشع"},{"level":"1 درجة","description":"وصف أحد الاتجاهين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية التفاعل الأمامي انصهارًا أو تبخرًا بدلًا من التسامي","تفسير ظهور اليود المشع في الصلب بأن اليود الصلب انتقل عبر الأنبوب","الاعتقاد أن التحول يتوقف بعد الوصول إلى الاتزان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-06T22:20:31.182Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) في البداية تكون تراكيز المتفاعلات كبيرة فتكون سرعة التفاعل الأمامي كبيرة، ومع استهلاك N₂ وH₂ تقل تراكيزهما فتقل سرعة التفاعل الأمامي؛ وفي الوقت نفسه تتكوّن الأمونيا فيبدأ التفاعل العكسي وتزداد سرعته، فيقل التغير الصافي في التراكيز ويقل الميل تدريجيًّا. (ب) لأن الأمونيا المتكونة تتحلل في التفاعل العكسي معيدة تكوين N₂ وH₂، وعند t₂ تتساوى سرعتا التفاعلين فتثبت التراكيز قبل أن تُستهلك المتفاعلات. (ج) التفاعل عكسي لم يكتمل، ووصل عند t₂ إلى حالة الاتزان الكيميائي.', '["نقص تراكيز المتفاعلات يبطئ التفاعل الأمامي","بدء التفاعل العكسي وزيادة سرعته مع تكوّن الأمونيا","تحلل الأمونيا يعيد تكوين المتفاعلات","تساوي السرعتين عند t₂ وثبات التراكيز","الاستنتاج: تفاعل عكسي غير مكتمل وصل إلى الاتزان"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير تناقص الميل","marks":2},{"element":"تفسير عدم وصول تراكيز المتفاعلات إلى الصفر","marks":2},{"element":"الاستنتاج الصحيح عن نوع التفاعل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل للأجزاء الثلاثة مع الربط بسرعتي التفاعلين"},{"level":"3–4 درجات","description":"تفسير صحيح لجزأين مع نقص في الثالث"},{"level":"1–2 درجة","description":"إجابة جزئية لا تربط بالتفاعل العكسي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التفاعل توقف عند t₂","تفسير عدم وصول التراكيز إلى الصفر بنقص المادة المحفزة أو انتهاء الزمن","إغفال دور التفاعل العكسي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.182Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
