from (values
('mcq', 1, 'ما المقصود بالاتزان الكيميائي؟', null, null, '["حالة النظام عندما تتساوى تراكيز المتفاعلات والنواتج","حالة النظام عندما يتوقف التفاعلان الأمامي والعكسي","حالة النظام عندما تتساوى سرعتا التفاعلين الأمامي والعكسي","حالة النظام عندما تُستهلك المتفاعلات كلها"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 80 — سير تفاعل تكوين الأمونيا وتعريف الاتزان الكيميائي'),
('mcq', 2, 'يمثل الشكل الآتي تغير سرعتي التفاعلين الأمامي والعكسي مع الزمن لتفاعل عكسي في وعاء مغلق. ما الذي يحدث عند الزمن t₂ وبعده؟', null, '[{"src":"qimg/chem22/c3-l1a-rates.svg","alt":"منحنيان لتغير سرعة التفاعل مع الزمن لتفاعل عكسي بدأ بالمتفاعلات فقط في وعاء مغلق، دون قيم عددية. المنحنى المسمى «الأمامي» (سرعة التفاعل الأمامي) يبدأ من قيمة عالية ويتناقص تدريجيًّا، والمنحنى المسمى «العكسي» (سرعة التفاعل العكسي) يبدأ من الصفر ويتزايد تدريجيًّا. يلتقي المنحنيان عند الزمن t₂، ثم يستمران بعده خطًّا أفقيًّا واحدًا فوق الصفر حتى نهاية الرسم. الزمن t₁ مُعلَّم بخط متقطع قبل t₂، وعنده يكون منحنى الأمامي أعلى من منحنى العكسي."}]'::jsonb, '["تتساوى سرعتا التفاعلين ويستمر حدوثهما","يتوقف التفاعلان الأمامي والعكسي","تصبح سرعة التفاعل العكسي أكبر من الأمامي","تُستهلك المتفاعلات كلها فيتوقف التفاعل"]'::jsonb, 'فهم', 'تفسير رسم بياني', 'سهل', 'الكتاب ص 80 — سير تفاعل تكوين الأمونيا وتعريف الاتزان الكيميائي'),
('mcq', 3, 'أيّ المجموعات الآتية تمثل خواص التفاعلات التي تصل إلى حالة الاتزان الكيميائي؟', null, null, '["نظام مفتوح، ودرجة حرارة ثابتة، وحركة ديناميكية","نظام مغلق، ودرجة حرارة متغيرة، وحالة ساكنة","نظام مغلق، وتراكيز متساوية، وحالة ساكنة","نظام مغلق، ودرجة حرارة ثابتة، وحركة ديناميكية"]'::jsonb, 'تذكر', 'تذكر خواص', 'سهل', 'الكتاب ص 83 — خواص الاتزان وتعبير ثابت الاتزان'),
('mcq', 4, 'لماذا يوصف الاتزان الكيميائي بأنه ديناميكي؟', null, null, '["لأن تراكيز المواد تتغير باستمرار عند الاتزان","لأن التفاعلين الأمامي والعكسي يستمران بالسرعة نفسها","لأن التفاعل يتوقف بعد وصوله إلى الاتزان","لأن كميات المتفاعلات تساوي كميات النواتج"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 83 — خواص الاتزان وتعبير ثابت الاتزان'),
('mcq', 5, 'يمثل المنحنى الآتي تغير التراكيز مع الزمن للتفاعل A(g) ⇌ B(g) في وعاء مغلق بدأ بالمادة A فقط. عند أيّ الأزمنة المُعلَّمة يكون النظام في حالة اتزان؟', null, '[{"src":"qimg/chem22/c3-l1a-conc-cross.svg","alt":"منحنيا تغير التركيز (mol/L) مع الزمن للتفاعل A(g) ⇌ B(g) في وعاء مغلق بدأ بالمادة A فقط. المحور الرأسي مدرج من 0.0 إلى 1.0 كل 0.1. منحنى [A] يبدأ من 1.0 ويتناقص، ومنحنى [B] يبدأ من 0.0 ويتزايد. ثلاثة أزمنة مُعلَّمة بخطوط رأسية متقطعة: عند t₁ يتقاطع المنحنيان فيكون [A] = [B] = 0.5 والمنحنيان ما زالا يتغيران بوضوح؛ وعند t₂ يكون [A] نحو 0.34 و[B] نحو 0.66 والمنحنيان ما زالا يتغيران ببطء؛ ثم يصبح المنحنيان أفقيين عند [A] = 0.3 و[B] = 0.7، ويبقيان كذلك عند t₃ وحتى نهاية الرسم."}]'::jsonb, '["t₃ فقط","t₁ فقط","t₂ فقط","t₁ وt₂ وt₃"]'::jsonb, 'تحليل', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 81 — الطبيعة الديناميكية للاتزان'),
('mcq', 6, 'يبيّن الشكل الآتي إيثانول سائلًا وبخاره في دورق عند درجة حرارة ثابتة. لماذا يجب أن يبقى الدورق مغلقًا حتى يصل النظام إلى حالة الاتزان؟', null, '[{"src":"qimg/chem22/c3-l1a-flask-ethanol.svg","alt":"دورق زجاجي مغلق بسدادة عند درجة حرارة ثابتة، في أسفله إيثانول سائل مكتوب بجانبه C₂H₅OH(l)، وفي الفراغ فوقه جزيئات من بخار الإيثانول مكتوب بجانبها C₂H₅OH(g). سهم أحمر صاعد من سطح السائل نحو البخار مكتوب بجانبه «تبخر»، وسهم أزرق نازل من البخار نحو سطح السائل مكتوب بجانبه «تكثف»."}]'::jsonb, '["حتى تتوقف عملية التبخر تمامًا بعد مدة من الزمن","حتى يتحول الإيثانول السائل كله إلى بخار يملأ الدورق","حتى لا يهرب البخار فتتساوى سرعتا التكثف والتبخر","حتى تتساوى كتلة الإيثانول السائل وكتلة بخاره في الدورق"]'::jsonb, 'فهم', 'تفسير خاصية', 'متوسط', 'الكتاب ص 83، 86 — خواص الاتزان والشكل 3-8'),
('mcq', 7, 'مبنيان متصلان بممر، ويبقى عدد الأشخاص في كل منهما ثابتًا مع أن الناس يعبرون الممر ذهابًا وإيابًا. أيّ العبارات الآتية تربط هذا الموقف بالاتزان الكيميائي ربطًا صحيحًا؟', null, null, '["لا يعبر أحد الممر، كتوقف التفاعلين عند الاتزان","عدد العابرين في الاتجاهين متساوٍ، كتساوي سرعتي التفاعلين الأمامي والعكسي","عدد الأشخاص في المبنيين متساوٍ، كتساوي تراكيز المتفاعلات والنواتج","يعبر الأشخاص في اتجاه واحد فقط، كما في التفاعل المكتمل"]'::jsonb, 'تحليل', 'تطبيق تشبيه', 'صعب', 'الكتاب ص 82 — الشكل 3-5 المبنيان المتصلان'),
('essay', 1, 'عدّد ثلاث خواص يجب أن تتوافر في خليط تفاعل ليصل إلى حالة الاتزان، ثم وضّح المقصود بأن الاتزان «ديناميكي وليس ساكنًا».', null, null, null, 'فهم', 'تعداد وتوضيح', 'متوسط', 'الكتاب ص 83 — خواص الاتزان وتعبير ثابت الاتزان'),
('essay', 2, 'يمثل الشكل الآتي تغير سرعتي التفاعلين الأمامي والعكسي مع الزمن لتفاعل عكسي بدأ بالمتفاعلات فقط. (أ) صف تغير كل من السرعتين بين بداية التفاعل والزمن t₂، وفسّر هذا التغير بدلالة التراكيز. (ب) ماذا يحدث للتراكيز بعد t₂؟ ولماذا؟ (ج) اكتب تعريف الاتزان الكيميائي مستعينًا بالشكل.', null, '[{"src":"qimg/chem22/c3-l1a-rates.svg","alt":"منحنيان لتغير سرعة التفاعل مع الزمن لتفاعل عكسي بدأ بالمتفاعلات فقط في وعاء مغلق، دون قيم عددية. المنحنى المسمى «الأمامي» (سرعة التفاعل الأمامي) يبدأ من قيمة عالية ويتناقص تدريجيًّا، والمنحنى المسمى «العكسي» (سرعة التفاعل العكسي) يبدأ من الصفر ويتزايد تدريجيًّا. يلتقي المنحنيان عند الزمن t₂، ثم يستمران بعده خطًّا أفقيًّا واحدًا فوق الصفر حتى نهاية الرسم. الزمن t₁ مُعلَّم بخط متقطع قبل t₂، وعنده يكون منحنى الأمامي أعلى من منحنى العكسي."}]'::jsonb, null, 'فهم', 'تفسير رسم بياني', 'صعب', 'الكتاب ص 80 — سير تفاعل تكوين الأمونيا وتعريف الاتزان الكيميائي'),
('essay', 3, 'قال طالب: «عند الاتزان تتوقف التفاعلات الكيميائية، وتتساوى تراكيز المتفاعلات وتراكيز النواتج». قوّم هذه العبارة، وصحّح ما فيها من أخطاء، مستشهدًا بتجربة دورقين متصلين يحتوي أحدهما على بلورات يود مشع I-131 والآخر على بلورات يود غير مشع I-127 في حالة الاتزان I₂(s) ⇌ I₂(g).', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 81–83 — الطبيعة الديناميكية للاتزان وتسامي اليود')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
