from (values
('mcq', 1, 2, 'الاتزان الكيميائي حالة النظام عندما تتساوى سرعتا التفاعل الأمامي والعكسي، وعندها تثبت تراكيز المواد المتفاعلة والناتجة.', '["التراكيز عند الاتزان ثابتة لا متساوية؛ وتساويها حالة نادرة.","التفاعلان مستمران عند الاتزان؛ فالاتزان ديناميكي لا ساكن.","","استهلاك المتفاعلات كلها يعني اكتمال التفاعل، لا الاتزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.183Z"}'::jsonb),
('mcq', 2, 0, 'عند t₂ يلتقي منحنيا السرعتين ويستمران خطًّا أفقيًّا واحدًا فوق الصفر؛ أي تتساوى سرعة التفاعل الأمامي وسرعة التفاعل العكسي ويستمر التفاعلان، وهذه حالة الاتزان الكيميائي.', '["","السرعتان بعد t₂ ثابتتان ولا تساويان صفرًا، فالتفاعلان مستمران.","المنحنيان يلتقيان ويستمران خطًّا واحدًا، فالسرعتان متساويتان.","سرعة التفاعل الأمامي لا تصل إلى الصفر، فالمتفاعلات لم تُستهلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-06T22:20:31.183Z"}'::jsonb),
('mcq', 3, 3, 'خواص الاتزان: أن يتم التفاعل في نظام مغلق، وأن تبقى درجة الحرارة ثابتة، وأن توجد المتفاعلات والنواتج معًا في حركة ديناميكية ثابتة.', '["يجب أن يكون النظام مغلقًا؛ فلا يخرج منه أو يدخله أي من المتفاعلات أو النواتج.","يجب أن تبقى درجة الحرارة ثابتة، والاتزان ديناميكي لا ساكن.","التراكيز عند الاتزان ثابتة لا متساوية، والحالة ديناميكية لا ساكنة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-06T22:20:31.183Z"}'::jsonb),
('mcq', 4, 1, 'الاتزان ديناميكي لأن المتفاعلات والنواتج في حركة مستمرة؛ إذ يستمر التفاعل الأمامي والتفاعل العكسي بسرعتين متساويتين، فتثبت التراكيز مع أن التفاعلين لم يتوقفا.', '["التراكيز عند الاتزان ثابتة لا تتغير.","","لو توقف التفاعل لكان الاتزان ساكنًا لا ديناميكيًّا.","الكميات عند الاتزان ليست متساوية في الغالب، وتساويها لا يجعل الاتزان ديناميكيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-06T22:20:31.183Z"}'::jsonb),
('mcq', 5, 0, 'علامة الاتزان ثبات التراكيز، أي أن تصبح المنحنيات أفقية. عند t₃ فقط يكون [A] = 0.3 و[B] = 0.7 ثابتين، أما عند t₁ (التقاطع) وt₂ فالتراكيز ما زالت تتغير.', '["","عند t₁ يتساوى التركيزان لحظيًّا، لكن المنحنيين ما زالا يتغيران، والاتزان لا يعني تساوي التراكيز.","عند t₂ ما زال [A] يتناقص و[B] يتزايد ببطء، فالتراكيز لم تثبت بعد.","عند t₁ وt₂ ما زالت التراكيز تتغير، فلم يصل النظام إلى الاتزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-06T22:20:31.183Z"}'::jsonb),
('mcq', 6, 2, 'من خواص الاتزان أن يكون النظام مغلقًا، فلا يخرج منه ولا يدخله أي من المواد. ففي الدورق المغلق يبقى البخار داخل النظام، فيتكثف جزء منه، وتزداد سرعة التكثف حتى تساوي سرعة التبخر؛ أما في الدورق المفتوح فيهرب البخار ولا يتحقق الاتزان.', '["التبخر لا يتوقف عند الاتزان، بل تتساوى سرعته مع سرعة التكثف.","لو تحول السائل كله إلى بخار لما وُجد اتزان بين الحالتين.","","الاتزان لا يتطلب تساوي الكميات، بل تساوي سرعتي العمليتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-06T22:20:31.184Z"}'::jsonb),
('mcq', 7, 1, 'يبقى العدد في كل مبنى ثابتًا لأن عدد من يعبرون في اتجاه يساوي عدد من يعبرون في الاتجاه المعاكس؛ وهذا يشبه الاتزان الكيميائي الذي تثبت فيه التراكيز لأن سرعتي التفاعلين الأمامي والعكسي متساويتان مع استمرارهما.', '["الناس يعبرون باستمرار، كما يستمر التفاعلان عند الاتزان.","","الثابت هو عدد الأشخاص في كل مبنى لا تساويه بين المبنيين، كما أن التراكيز ثابتة لا متساوية.","لو عبروا في اتجاه واحد لتغير العدد في كل مبنى، وهذا لا يمثل الاتزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-06T22:20:31.184Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخواص: (1) أن يتم التفاعل في نظام مغلق، فلا يخرج من النظام ولا يدخله أي من النواتج أو المتفاعلات. (2) أن تبقى درجة الحرارة ثابتة. (3) أن توجد النواتج والمتفاعلات معًا في حركة ديناميكية ثابتة. ومعنى أن الاتزان ديناميكي أن التفاعلين الأمامي والعكسي لا يتوقفان، بل يستمران بسرعتين متساويتين، فتثبت التراكيز مع استمرار تحول المتفاعلات إلى نواتج والنواتج إلى متفاعلات.', '["نظام مغلق","درجة حرارة ثابتة","وجود المتفاعلات والنواتج معًا في حركة ديناميكية","التفاعلان مستمران بسرعتين متساويتين"]'::jsonb, '[]'::jsonb, '[{"element":"كل خاصية صحيحة (3 خواص)","marks":3},{"element":"توضيح معنى الاتزان الديناميكي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ثلاث خواص صحيحة وتوضيح صحيح لمعنى ديناميكي"},{"level":"2–3 درجات","description":"خاصيتان أو ثلاث دون توضيح، أو خاصية مع توضيح"},{"level":"1 درجة","description":"خاصية واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر «تساوي التراكيز» خاصيةً للاتزان","ذكر «نظام مفتوح»","وصف الاتزان بأن التفاعل توقف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.184Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) سرعة التفاعل الأمامي تبدأ كبيرة ثم تتناقص؛ لأن تراكيز المتفاعلات تقل باستهلاكها. وسرعة التفاعل العكسي تبدأ من الصفر لعدم وجود نواتج، ثم تزداد مع زيادة تركيز النواتج. (ب) بعد t₂ تتساوى السرعتان، فتتكوّن النواتج بالسرعة نفسها التي تتحلل بها، فتثبت تراكيز المتفاعلات والنواتج (ثابتة لا متساوية)، مع استمرار التفاعلين. (ج) الاتزان الكيميائي: حالة النظام عندما تتساوى سرعتا التفاعل الأمامي والعكسي، وعندها تثبت تراكيز المواد المتفاعلة والناتجة؛ وفي الشكل يتحقق ذلك من t₂ فما بعد.', '["تناقص سرعة التفاعل الأمامي بنقص تراكيز المتفاعلات","تزايد سرعة التفاعل العكسي بزيادة تراكيز النواتج","تساوي السرعتين بعد t₂ وثبات التراكيز","التفاعلان مستمران","تعريف الاتزان الكيميائي"]'::jsonb, '[]'::jsonb, '[{"element":"وصف وتفسير تغير سرعة التفاعل الأمامي","marks":1},{"element":"وصف وتفسير تغير سرعة التفاعل العكسي","marks":1},{"element":"ثبات التراكيز بعد t₂ وسببه","marks":2},{"element":"تعريف الاتزان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف وتفسير صحيحان للسرعتين، وتفسير ثبات التراكيز، وتعريف صحيح"},{"level":"3–4 درجات","description":"إجابة صحيحة مع نقص في أحد التفسيرات"},{"level":"1–2 درجة","description":"وصف للمنحنيين دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السرعتين تصبحان صفرًا بعد t₂","القول إن التراكيز تتساوى بعد t₂","تفسير تزايد السرعة العكسية بزيادة درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-06T22:20:31.185Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة في جزأيها. أولًا: التفاعلات لا تتوقف عند الاتزان؛ فالاتزان ديناميكي، ويستمر التفاعلان الأمامي والعكسي بسرعتين متساويتين. والدليل: بعد فتح المحبس بين الدورقين المتزنين تظهر جزيئات اليود المشع I-131 في الحالتين الصلبة والغازية في الدورق الآخر، أي إن الجزيئات تستمر في التحول من الصلبة إلى الغازية ومن الغازية إلى الصلبة مع أن كميات اليود الصلب والغازي لا تتغير. ثانيًا: التراكيز عند الاتزان ثابتة لا متساوية؛ وتساويها حالة نادرة الحدوث، بل تكون سرعة تكوّن النواتج مساوية لسرعة تكوّن المتفاعلات. التصحيح: «عند الاتزان يستمر التفاعلان الأمامي والعكسي بسرعتين متساويتين، فتثبت تراكيز المتفاعلات والنواتج دون أن تكون متساوية بالضرورة».', '["الحكم بأن العبارة خاطئة","التفاعلات مستمرة بسرعتين متساويتين","الاستشهاد بانتقال اليود المشع إلى الحالتين في الدورق الآخر","التراكيز ثابتة لا متساوية","صياغة العبارة الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"تصحيح الجزء الأول (التفاعلات مستمرة)","marks":1},{"element":"الاستشهاد بتجربة اليود المشع وتفسيرها","marks":2},{"element":"تصحيح الجزء الثاني (التراكيز ثابتة لا متساوية)","marks":1},{"element":"صياغة العبارة الصحيحة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم كامل للجزأين مع استشهاد صحيح بتجربة اليود وصياغة صحيحة"},{"level":"3–4 درجات","description":"تصحيح الجزأين مع استشهاد ناقص"},{"level":"1–2 درجة","description":"تصحيح جزء واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح جزء واحد وإغفال الآخر","تفسير التجربة بانتشار البخار فقط دون الإشارة إلى ظهور اليود المشع في الحالة الصلبة","استبدال «ثابتة» بـ«متساوية» في التصحيح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-06T22:20:31.185Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
