('mcq', 2, 'ما تعبير ثابت الاتزان للتفاعل الآتي: 2H₂S(g) ⇌ 2H₂(g) + S₂(g)؟', null, null, '["Keq = [H₂][S₂]/[H₂S]","Keq = [H₂]²[S₂]/[H₂S]²","Keq = [H₂S]²/[H₂]²[S₂]","Keq = ([H₂]² + [S₂])/[H₂S]²"]'::jsonb, 'تطبيق', 'كتابة تعبير اتزان متجانس', 'سهل', 'الكتاب ص 85 — المثال 3-1 ومسائل تدريبية 1–2'),
('mcq', 3, 'ما تعبير ثابت الاتزان للتفاعل الآتي: CaCO₃(s) ⇌ CaO(s) + CO₂(g)؟', null, null, '["Keq = [CaO][CO₂]/[CaCO₃]","Keq = [CaO]/[CaCO₃]","Keq = [CO₂]","Keq = 1/[CO₂]"]'::jsonb, 'تطبيق', 'كتابة تعبير اتزان غير متجانس', 'متوسط', 'الكتاب ص 87 — المثال 3-2 ومسائل تدريبية 3–4'),
('mcq', 4, 'أيّ المعادلات الآتية يمثلها تعبير ثابت الاتزان Keq = [CO]²[O₂]/[CO₂]²؟', null, null, '["2CO₂(g) ⇌ 2CO(g) + O₂(g)","2CO(g) + O₂(g) ⇌ 2CO₂(g)","CO₂(g) ⇌ CO(g) + O₂(g)","2CO₂(g) ⇌ CO(g) + 2O₂(g)"]'::jsonb, 'تطبيق', 'كتابة المعادلة من التعبير', 'متوسط', 'الكتاب ص 85 — المثال 3-1 ومسائل تدريبية 1–2'),
('mcq', 5, 'لماذا لا تُكتب المواد الصلبة النقية والسوائل النقية في تعابير ثابت الاتزان؟', null, null, '["لأنها لا تشارك فعليًّا في التفاعل الكيميائي","لأن تركيز كل منها يساوي صفرًا عند الاتزان","لأن تركيز كل منها ثابت مهما تغيرت كميته","لأن كتلة كل منها لا تتغير مطلقًا أثناء التفاعل"]'::jsonb, 'فهم', 'تفسير قاعدة', 'متوسط', 'الكتاب ص 86 — تعابير الاتزان غير المتجانس'),
('mcq', 6, 'يتفاعل الحديد الصلب مع غاز الكلور لتكوين كلوريد الحديد III الصلب FeCl₃ في نظام متزن. ما تعبير ثابت الاتزان لهذا التفاعل؟', null, null, '["Keq = [FeCl₃]²/[Fe]²[Cl₂]³","Keq = 1/[Cl₂]³","Keq = [Cl₂]³","Keq = 1/[Cl₂]"]'::jsonb, 'تطبيق', 'وزن معادلة وكتابة تعبير', 'صعب', 'الكتاب ص 87 — المثال 3-2 ومسائل تدريبية 3–4'),
('mcq', 7, 'ما تعبير ثابت الاتزان للتفاعل الآتي: 4NH₃(g) + 5O₂(g) ⇌ 4NO(g) + 6H₂O(g)؟', null, null, '["Keq = [NO]⁴/[NH₃]⁴[O₂]⁵","Keq = [NH₃]⁴[O₂]⁵/[NO]⁴[H₂O]⁶","Keq = [NO]⁶[H₂O]⁴/[NH₃]⁵[O₂]⁴","Keq = [NO]⁴[H₂O]⁶/[NH₃]⁴[O₂]⁵"]'::jsonb, 'تطبيق', 'كتابة تعبير اتزان متجانس', 'متوسط', 'الكتاب ص 85 — المثال 3-1 ومسائل تدريبية 1–2'),
('essay', 1, 'اكتب تعبير ثابت الاتزان لكل من التفاعلين الآتيين: (أ) CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g)  (ب) CH₄(g) + 2H₂S(g) ⇌ CS₂(g) + 4H₂(g)', null, null, null, 'تطبيق', 'كتابة تعابير', 'سهل', 'الكتاب ص 85 — المثال 3-1 ومسائل تدريبية 1–2'),
('essay', 2, 'اكتب تعبير ثابت الاتزان لكل اتزان غير متجانس مما يأتي، ثم فسّر لماذا اختلف عدد المواد في التعبير عن عددها في المعادلة: (أ) 2NaHCO₃(s) ⇌ Na₂CO₃(s) + CO₂(g) + H₂O(g)  (ب) FeO(s) + CO(g) ⇌ Fe(s) + CO₂(g)  (ج) H₂O(l) ⇌ H₂O(g)', null, null, null, 'تطبيق', 'كتابة تعابير وتفسير', 'صعب', 'الكتاب ص 87 — المثال 3-2 ومسائل تدريبية 3–4'),
('essay', 3, 'إذا مرّ بخار ماء خلال برادة حديد ساخنة، ينتج أكسيد الحديد III الصلب Fe₂O₃ وغاز الهيدروجين في نظام متزن. (أ) اكتب معادلة كيميائية موزونة لهذا الاتزان بالحالات الفيزيائية. (ب) اكتب تعبير ثابت الاتزان Keq للتفاعل الذي ينتج Fe₂O₃ وH₂. (ج) اكتب معادلة التفاعل العكسي (الذي ينتج Fe وH₂O) وتعبير ثابت الاتزان له Keq′، ثم قارن التعبيرين، واستنتج العلاقة الرياضية بين Keq′ وKeq.', null, null, null, 'تحليل', 'كتابة معادلة وتعابير', 'صعب', 'الكتاب ص 112 — السؤال 45 والسؤال 40')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
