from (values
('mcq', 1, 3, 'تعبير ثابت الاتزان = تراكيز النواتج في البسط على تراكيز المتفاعلات في المقام، ويُرفع كل تركيز إلى أس يساوي معامله: Keq = [NO₂]²/[N₂O₄].', '["هذا مقلوب التعبير؛ فتراكيز النواتج تُكتب في البسط وتراكيز المتفاعلات في المقام.","المعامل 2 يُكتب أسًّا للتركيز، لا معاملًا مضروبًا فيه.","أُهمل المعامل 2؛ ويجب رفع كل تركيز إلى أس يساوي معامله في المعادلة الموزونة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-06T22:20:31.186Z"}'::jsonb),
('mcq', 2, 1, 'النواتج H₂ (معامله 2) وS₂ (معامله 1) في البسط مضروبة، والمتفاعل H₂S (معامله 2) في المقام: Keq = [H₂]²[S₂]/[H₂S]².', '["أُهملت المعاملات؛ فالأسس يجب أن تساوي المعاملات 2 و1 و2.","","هذا مقلوب التعبير؛ فالنواتج H₂ وS₂ في البسط.","تراكيز النواتج تُضرب بعضها في بعض، ولا تُجمع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-06T22:20:31.186Z"}'::jsonb),
('mcq', 3, 2, 'الاتزان غير متجانس؛ والمواد الصلبة النقية (CaCO₃ وCaO) تراكيزها ثابتة فلا تُكتب في التعبير، فيبقى الغاز الناتج وحده: Keq = [CO₂].', '["CaCO₃ وCaO مادتان صلبتان نقيتان تركيزاهما ثابتان، فلا يُكتبان في التعبير.","حُذف الغاز وأُبقيت المادتان الصلبتان؛ والصحيح العكس.","","CO₂ ناتج، فيُكتب في البسط لا في المقام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-06T22:20:31.186Z"}'::jsonb),
('mcq', 4, 0, 'المواد في البسط نواتج والمواد في المقام متفاعلات، والأسس معاملات: المتفاعل CO₂ بمعامل 2، والناتجان CO بمعامل 2 وO₂ بمعامل 1، فالمعادلة 2CO₂(g) ⇌ 2CO(g) + O₂(g)، وهي موزونة.', '["","في هذه المعادلة CO₂ ناتج، فيكون في البسط لا في المقام.","المعادلة غير موزونة، ولا تعطي الأسين 2 لكل من [CO] و[CO₂].","المعاملات تعطي [CO][O₂]²، لا [CO]²[O₂]."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-06T22:20:31.186Z"}'::jsonb),
('mcq', 5, 2, 'تركيز المادة الصلبة أو السائلة النقية هو كثافتها معبرًا عنها بـ mol/L، والكثافة ثابتة عند درجة حرارة معينة؛ فمهما كانت الكمية كبيرة أو صغيرة يبقى تركيزها ثابتًا، فيُدمج مع K ليعطي Keq.', '["هذه المواد تشارك فعلًا في التفاعل وقد تُستهلك أو تتكوّن.","تركيزها ليس صفرًا، بل قيمة ثابتة تُدمج مع K.","","كتلتها قد تتغير، لكن تركيزها (الكثافة معبرًا عنها بـ mol/L) هو الثابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.186Z"}'::jsonb),
('mcq', 6, 1, 'المعادلة الموزونة: 2Fe(s) + 3Cl₂(g) ⇌ 2FeCl₃(s). تُحذف المادتان الصلبتان، ويبقى المتفاعل الغازي Cl₂ في المقام بأس 3، والبسط 1: Keq = 1/[Cl₂]³.', '["Fe وFeCl₃ مادتان صلبتان، فلا تُكتبان في التعبير.","","Cl₂ مادة متفاعلة، فيُكتب تركيزها في المقام لا في البسط.","أُهمل وزن المعادلة؛ فمعامل Cl₂ في المعادلة الموزونة 3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.187Z"}'::jsonb),
('mcq', 7, 3, 'جميع المواد غازية (اتزان متجانس)، فتُكتب كلها: النواتج في البسط NO بأس 4 وH₂O بأس 6، والمتفاعلات في المقام NH₃ بأس 4 وO₂ بأس 5.', '["حُذف بخار الماء خطأً؛ فهو غاز (g) لا سائل نقي، فيُكتب في التعبير.","هذا مقلوب التعبير؛ فالنواتج NO وH₂O في البسط.","تبادلت الأسس بين المواد؛ فأس كل تركيز هو معامل المادة نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-06T22:20:31.187Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) Keq = [CH₄][H₂O]/[CO][H₂]³. (ب) Keq = [CS₂][H₂]⁴/[CH₄][H₂S]².', '["(أ): النواتج CH₄ وH₂O في البسط","(أ): [H₂]³ في المقام مع [CO]","(ب): [CS₂][H₂]⁴ في البسط","(ب): [CH₄][H₂S]² في المقام"]'::jsonb, '["كتابة تراكيز النواتج في البسط وتراكيز المتفاعلات في المقام","رفع كل تركيز إلى أس يساوي معامله في المعادلة الموزونة","كتابة التعبير النهائي لكل تفاعل"]'::jsonb, '[{"element":"تعبير (أ): البسط والمقام","marks":1},{"element":"تعبير (أ): الأسس","marks":1},{"element":"تعبير (ب): البسط والمقام","marks":1},{"element":"تعبير (ب): الأسس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعبيران صحيحان كاملان"},{"level":"2–3 درجات","description":"تعبير صحيح وآخر فيه خطأ في الأسس أو الموضع"},{"level":"1 درجة","description":"وضع النواتج في البسط صحيحًا مع أخطاء في الأسس في التعبيرين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الأسين 3 و4 للهيدروجين","حذف H₂O(g) ظنًّا أنه سائل","عكس البسط والمقام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-06T22:20:31.187Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Keq = [CO₂][H₂O]. (ب) Keq = [CO₂]/[CO]. (ج) Keq = [H₂O(g)]. التفسير: المواد الصلبة النقية (NaHCO₃ وNa₂CO₃ وFeO وFe) والسائل النقي H₂O(l) تراكيزها ثابتة عند درجة حرارة معينة مهما تغيرت كمياتها، فتُدمج مع ثابت الاتزان ولا تُكتب في التعبير؛ لذا لا يبقى في التعبير إلا الغازات.', '["(أ) Keq = [CO₂][H₂O]","(ب) Keq = [CO₂]/[CO]","(ج) Keq = [H₂O(g)]","الصلبة والسائلة النقية تراكيزها ثابتة فتُحذف"]'::jsonb, '["تحديد الحالة الفيزيائية لكل مادة","حذف المواد الصلبة والسوائل النقية","كتابة تراكيز الغازات الناتجة في البسط والمتفاعلة في المقام بأسس معاملاتها"]'::jsonb, '[{"element":"تعبير (أ)","marks":1},{"element":"تعبير (ب)","marks":1},{"element":"تعبير (ج)","marks":1},{"element":"تفسير حذف المواد الصلبة والسائلة النقية","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"ثلاثة تعابير صحيحة وتفسير كامل"},{"level":"3–4 درجات","description":"تعبيران أو ثلاثة صحيحة مع تفسير ناقص"},{"level":"1–2 درجة","description":"تعبير واحد صحيح أو تفسير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة [NaHCO₃]² في المقام","حذف H₂O(g) في (أ) لأنه ماء","كتابة [H₂O(g)]/[H₂O(l)] في (ج)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.187Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) 2Fe(s) + 3H₂O(g) ⇌ Fe₂O₃(s) + 3H₂(g). (ب) تُحذف المادتان الصلبتان Fe وFe₂O₃: Keq = [H₂]³/[H₂O]³. (ج) التفاعل العكسي Fe₂O₃(s) + 3H₂(g) ⇌ 2Fe(s) + 3H₂O(g) وتعبيره Keq′ = [H₂O]³/[H₂]³؛ وبمقارنة التعبيرين نجد أن البسط في أحدهما هو المقام في الآخر، فـ Keq′ مقلوب Keq، أي Keq′ = 1/Keq.', '["المعادلة الموزونة بالحالات الفيزيائية","حذف Fe وFe₂O₃ الصلبتين","Keq = [H₂]³/[H₂O]³","تعبير التفاعل العكسي [H₂O]³/[H₂]³","المقارنة: التعبيران مقلوبان، Keq′ = 1/Keq"]'::jsonb, '["كتابة الصيغ والحالات: Fe(s)، H₂O(g)، Fe₂O₃(s)، H₂(g)","وزن المعادلة: 2Fe + 3H₂O ⇌ Fe₂O₃ + 3H₂","حذف المواد الصلبة وكتابة Keq = [H₂]³/[H₂O]³","عكس المعادلة فيصبح التعبير [H₂O]³/[H₂]³ = 1/Keq"]'::jsonb, '[{"element":"المعادلة الموزونة","marks":2},{"element":"تعبير التفاعل الأمامي","marks":2},{"element":"تعبير التفاعل العكسي والعلاقة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"معادلة موزونة وتعبيران صحيحان مع بيان أن أحدهما مقلوب الآخر"},{"level":"3–5 درجات","description":"معادلة صحيحة وتعبير صحيح مع خطأ في الجزء الثالث أو في الأسس"},{"level":"1–2 درجة","description":"معادلة غير موزونة أو تعبير يتضمن المواد الصلبة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة FeO بدل Fe₂O₃","إدخال [Fe] و[Fe₂O₃] في التعبير","إهمال الأس 3","القول إن تعبير التفاعل العكسي هو نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.188Z"}'::jsonb)
