('mcq', 6, 'كتب طالب: «القيمة المنخفضة لثابت الاتزان Keq تعني أن كلا التفاعلين الأمامي والعكسي يحدثان ببطء». أيّ تصحيح لهذه العبارة هو الصحيح؟', null, null, '["القيمة المنخفضة لـ Keq تعني أن التفاعل الأمامي يتوقف قبل بلوغ الاتزان","القيمة المنخفضة لـ Keq تعني أن سرعة التفاعل العكسي أكبر من الأمامي عند الاتزان","القيمة المنخفضة لـ Keq تعني أن التفاعل يصل إلى الاتزان ببطء شديد","القيمة المنخفضة لـ Keq تعني أن تراكيز المتفاعلات أكبر من تراكيز النواتج عند الاتزان"]'::jsonb, 'تقويم', 'تصحيح مفهوم خاطئ', 'صعب', 'الكتاب ص 114 — السؤال 71'),
('mcq', 7, 'قيمة ثابت الاتزان لذوبان غاز ثاني أكسيد الكربون في سائل افتراضي اسمه البولان CO₂(g) ⇌ CO₂(yo) تساوي 3.4×10⁶. ماذا تعني هذه القيمة؟', null, null, '["يكون CO₂ المذاب في البولان أكثر بكثير من CO₂ الغازي عند الاتزان","يبقى معظم CO₂ في الحالة الغازية عند الاتزان","يذوب CO₂ في البولان بسرعة كبيرة جدًّا","يتساوى تركيز CO₂ الغازي وتركيز CO₂ المذاب"]'::jsonb, 'فهم', 'تفسير قيمة Keq', 'سهل', 'الكتاب ص 115 — السؤال 82'),
('essay', 1, 'فسّر كيف ترتبط قيمة ثابت الاتزان Keq بكمية النواتج عند الاتزان، مستعينًا بمقارنة الكسرين 5/1 و1/5، ثم طبّق ذلك على التفاعل H₂(g) + I₂(g) ⇌ 2HI(g) الذي قيمة Keq له 49.7 عند 731 K.', null, null, null, 'فهم', 'تفسير وتطبيق', 'متوسط', 'الكتاب ص 84 — دلالة قيمة Keq وتعابير الاتزان المتجانس'),
('essay', 2, 'يمثل الشكل الآتي تغير التراكيز مع الزمن لتفاعلين مختلفين (س) و(ص) من النوع A ⇌ B عند درجة الحرارة نفسها. (أ) اكتب تعبير ثابت الاتزان، واحسب قيمة Keq لكل تفاعل من تراكيز الاتزان في الشكل. (ب) فسّر دلالة كل قيمة. (ج) في أيّ التفاعلين يكون الحصول على الناتج B أكثر جدوى؟ ولماذا؟', null, '[{"src":"qimg/chem22/c3-l1a-two-eq.svg","alt":"لوحتان لتفاعلين مختلفين، كل منهما من النوع A ⇌ B، عند درجة الحرارة نفسها، بدأ كل منهما بتركيز 1.0 mol/L من A فقط. في كل لوحة المحور الرأسي التركيز (mol/L) من 0.0 إلى 1.0، والمحور الأفقي الزمن. في اللوحة (س): يتناقص [A] من 1.0 ويثبت عند 0.2، ويتزايد [B] من 0.0 ويثبت عند 0.8. وفي اللوحة (ص): يتناقص [A] من 1.0 ويثبت عند 0.75، ويتزايد [B] من 0.0 ويثبت عند 0.25."}]'::jsonb, null, 'تحليل', 'حساب وتفسير من رسم بياني', 'صعب', 'الكتاب ص 84 — دلالة قيمة Keq وتعابير الاتزان المتجانس'),
('essay', 3, 'لنظام اتزان A(g) + B(g) ⇌ C(g) قيمة Keq تساوي 1.0 عند درجة حرارة معينة. قال طالب: «إذن يتكون خليط الاتزان من 50% متفاعلات و50% نواتج». قوّم هذه العبارة، مستعملًا خليط اتزان فيه [A] = 2.0 mol/L و[B] = 2.0 mol/L و[C] = 4.0 mol/L.', null, null, null, 'تقويم', 'تقويم عبارة بالدليل', 'صعب', 'الكتاب ص 114 — السؤال 74')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L1-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'Keq نسبة تراكيز النواتج إلى تراكيز المتفاعلات؛ والكسر الذي بسطه أكبر من مقامه أكبر من 1. لذا فـ Keq > 1 تعني أن تراكيز المواد الناتجة أكبر من تراكيز المواد المتفاعلة عند الاتزان.', '["","هذا ما تعنيه Keq < 1، لا Keq > 1.","Keq > 1 تعني أن البسط (النواتج) أكبر من المقام (المتفاعلات)، لا مساويًا له.","Keq تُحسب من تراكيز الاتزان، فهي تصف خليطًا وصل إلى الاتزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-06T22:20:31.188Z"}'::jsonb),
('mcq', 2, 2, 'قيمة Keq أصغر بكثير من 1، فتراكيز المتفاعلات أكبر بكثير من تراكيز النواتج؛ أي إن كمية NO الناتجة عمليًّا تكون شبه معدومة عند الاتزان عند 298 K.', '["القيمة الصغيرة جدًّا تعني العكس: المتفاعلات هي السائدة.","قيمة Keq تصف تراكيز الاتزان، ولا تدل على سرعة التفاعل.","","لو تساوت التراكيز لما كانت Keq صغيرة إلى هذا الحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.189Z"}'::jsonb),
('mcq', 3, 1, 'Keq = [B]/[A]. في (س): 0.8/0.2 = 4.0 > 1 لأن الناتج أكبر تركيزًا عند الاتزان. وفي (ص): 0.25/0.75 = 0.33 < 1 لأن المتفاعل أكبر تركيزًا.', '["في (ص) يثبت [A] = 0.75 أكبر من [B] = 0.25، فالمتفاعل سائد وKeq < 1.","","عُكس الحكم؛ ففي (س) الناتج B هو الأكبر عند الاتزان.","في (س) يثبت [B] = 0.8 أكبر من [A] = 0.2، فالناتج سائد وKeq > 1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-06T22:20:31.189Z"}'::jsonb),
('mcq', 4, 3, 'كلما كبرت قيمة Keq كبرت نسبة تراكيز النواتج إلى تراكيز المتفاعلات. وأكبر قيمة 4.500 عند 373 K، وهي أكبر من 1، فيكون تركيز النواتج أكبر عند هذه الدرجة.', '["Keq الصغيرة تعني أن المتفاعلات هي السائدة لا النواتج.","القرب من 1 لا يعني تركيز نواتج أكبر؛ فكلما زادت Keq زادت نسبة النواتج.","Keq تتغير بتغير درجة الحرارة، فتختلف نسبة النواتج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-06T22:20:31.189Z"}'::jsonb),
('mcq', 5, 1, 'كلما صغرت Keq كانت تراكيز المتفاعلات أكبر نسبيًّا. أصغر قيمة هي 3.1×10⁻⁵ للتفاعل (2)، فهي الأصغر من 1 بفارق كبير، فتكون المتفاعلات فيه هي السائدة بأكبر قدر.', '["Keq = 4.6×10² أكبر من 1، فالنواتج هي السائدة.","","Keq = 0.85 أصغر من 1 لكنها أكبر بكثير من 3.1×10⁻⁵، فسيادة المتفاعلات فيه أقل.","Keq = 1.6×10⁴ أكبر من 1، فالنواتج هي السائدة بقوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-06T22:20:31.189Z"}'::jsonb),
('mcq', 6, 3, 'Keq نسبة تراكيز النواتج إلى المتفاعلات عند الاتزان، ولا علاقة لها بسرعة التفاعل. فالقيمة المنخفضة (Keq < 1) تعني أن تراكيز المتفاعلات أكبر من تراكيز النواتج عند الاتزان.', '["التفاعل الأمامي لا يتوقف؛ فعند الاتزان يستمر التفاعلان بسرعتين متساويتين.","السرعتان متساويتان عند الاتزان مهما كانت قيمة Keq.","Keq لا تدل على سرعة الوصول إلى الاتزان، بل على تراكيز الاتزان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-06T22:20:31.190Z"}'::jsonb),
('mcq', 7, 0, 'Keq = [CO₂(yo)]/[CO₂(g)] = 3.4×10⁶، وهي أكبر بكثير من 1، فتركيز CO₂ المذاب في البولان (الناتج) أكبر بكثير من تركيز CO₂ الغازي عند الاتزان؛ أي إن البولان قادر على إذابة كمية كبيرة من الغاز.', '["","Keq كبيرة جدًّا، فالناتج (CO₂ المذاب) هو السائد لا الغاز.","Keq لا تدل على السرعة، بل على نسبة التراكيز عند الاتزان.","التساوي يقابل قيمة قريبة من 1، لا 3.4×10⁶."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.190Z"}'::jsonb),
('essay', 1, null::int, null, null, 'Keq نسبة حاصل ضرب تراكيز النواتج (في البسط) إلى حاصل ضرب تراكيز المتفاعلات (في المقام). والكسر الذي بسطه أكبر من مقامه أكبر من 1 (مثل 5/1 = 5)، والكسر الذي بسطه أصغر من مقامه أصغر من 1 (مثل 1/5 = 0.2). لذا إذا كانت Keq > 1 كانت تراكيز النواتج أكبر من تراكيز المتفاعلات، وإذا كانت Keq < 1 كانت تراكيز المتفاعلات أكبر. وللتفاعل H₂ + I₂ ⇌ 2HI قيمة Keq = 49.7 أكبر من 1، فالناتج HI موجود بكميات أكبر من المتفاعلين H₂ وI₂ عند الاتزان عند 731 K.', '["النواتج في البسط والمتفاعلات في المقام","مقارنة 5/1 > 1 و1/5 < 1","Keq > 1: النواتج أكبر؛ Keq < 1: المتفاعلات أكبر","التطبيق: 49.7 > 1 فـ HI هو السائد"]'::jsonb, '[]'::jsonb, '[{"element":"بيان موضع النواتج والمتفاعلات في التعبير","marks":1},{"element":"استعمال مقارنة الكسرين","marks":1},{"element":"ربط Keq > 1 وKeq < 1 بالتراكيز","marks":1},{"element":"التطبيق على تفاعل HI","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مستعين بالكسرين وتطبيق صحيح"},{"level":"2–3 درجات","description":"تفسير صحيح دون الكسرين أو دون التطبيق"},{"level":"1 درجة","description":"ذكر القاعدة فقط دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس القاعدة","الربط بين Keq وسرعة التفاعل","القول إن Keq = 49.7 تعني أن التفاعل اكتمل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-06T22:20:31.190Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Keq = [B]/[A]. للتفاعل (س): Keq = 0.8/0.2 = 4.0. وللتفاعل (ص): Keq = 0.25/0.75 = 0.33. (ب) في (س) Keq > 1 فتركيز الناتج B أكبر من تركيز المتفاعل A عند الاتزان (النواتج مفضلة)؛ وفي (ص) Keq < 1 فتركيز المتفاعل أكبر (المتفاعلات مفضلة). (ج) التفاعل (س)؛ لأن قيمة Keq فيه أكبر من 1، فيتحول جزء أكبر من A إلى B عند الاتزان.', '["Keq = [B]/[A]","قراءة تراكيز الاتزان من الجزء الأفقي","(س) 4.0 و(ص) 0.33","دلالة Keq > 1 وKeq < 1","اختيار (س) مع التعليل"]'::jsonb, '["قراءة تراكيز الاتزان من الجزء الأفقي: (س) [A] = 0.2، [B] = 0.8؛ (ص) [A] = 0.75، [B] = 0.25","Keq(س) = 0.8/0.2 = 4.0","Keq(ص) = 0.25/0.75 = 0.33","المقارنة بالعدد 1"]'::jsonb, '[{"element":"كتابة التعبير","marks":1},{"element":"حساب القيمتين","marks":2},{"element":"تفسير الدلالة","marks":1},{"element":"الاختيار والتعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تعبير صحيح وحسابان صحيحان وتفسير واختيار مُعلَّل"},{"level":"3–4 درجات","description":"حساب صحيح مع نقص في التفسير أو التعليل"},{"level":"1–2 درجة","description":"تعبير صحيح فقط أو حساب واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال التراكيز الابتدائية بدل تراكيز الاتزان","قلب النسبة [A]/[B]","اختيار (ص) لأن تغير [A] فيه أبطأ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-06T22:20:31.191Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة ليست قاعدة صحيحة دائمًا. نتحقق أولًا أن الخليط في حالة اتزان: Keq = [C]/[A][B] = 4.0/(2.0 × 2.0) = 1.0، فهو خليط اتزان. مجموع تراكيز المتفاعلات = 2.0 + 2.0 = 4.0 mol/L، وتركيز الناتج = 4.0 mol/L، أي إن المتفاعلات 50% والنواتج 50% في هذا الخليط؛ لكن هذا ليس قاعدة: فخليط آخر عند الدرجة نفسها مثل [A] = 1.0 و[B] = 4.0 و[C] = 4.0 يعطي أيضًا Keq = 4.0/(1.0 × 4.0) = 1.0، مع أن المتفاعلات فيه 5.0 mol/L والناتج 4.0 mol/L. فقيمة Keq = 1 تعني أن نسبة حاصل ضرب تراكيز النواتج (مرفوعة لأسسها) إلى حاصل ضرب تراكيز المتفاعلات تساوي 1، لا أن النسب المئوية متساوية؛ وللنظام عدد غير محدود من مواضع الاتزان عند درجة الحرارة نفسها.', '["التحقق من أن الخليط المعطى متزن (Keq = 1.0)","حساب نسب الخليط المعطى","مثال مضاد يعطي Keq = 1.0 بنسب مختلفة","Keq نسبة حاصل ضرب لا نسبة مئوية","عدد غير محدود من مواضع الاتزان"]'::jsonb, '["Keq = [C]/[A][B] = 4.0/(2.0 × 2.0) = 1.0","إيجاد خليط آخر: [A] = 1.0، [B] = 4.0، [C] = 4.0 ⇐ Keq = 4.0/(1.0 × 4.0) = 1.0","المقارنة: النسب المئوية تختلف مع بقاء Keq = 1.0"]'::jsonb, '[{"element":"التحقق من اتزان الخليط المعطى بالحساب","marks":2},{"element":"تقديم مثال مضاد صحيح أو تعليل مكافئ","marks":2},{"element":"الحكم وصياغة المعنى الصحيح لـ Keq = 1","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح، ومثال مضاد صحيح، وحكم مُعلَّل"},{"level":"3–4 درجات","description":"حساب صحيح وحكم صحيح دون مثال مضاد واضح"},{"level":"1–2 درجة","description":"حساب Keq فقط أو حكم دون دليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن الخليط المعطى فيه 50% لكل منهما","حساب Keq بجمع تراكيز المتفاعلات في المقام","الخلط بين Keq = 1 وتساوي التراكيز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-06T22:20:31.191Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C3-L1-O04') and x.type = v.type and x.number = v.number
