insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L1-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'احسب قيمة Keq للاتزان N₂O₄(g) ⇌ 2NO₂(g) إذا علمت أن [N₂O₄] = 0.0185 mol/L و[NO₂] = 0.0627 mol/L عند الاتزان.', null, null, '["4.71","0.213","3.39","6.78"]'::jsonb, 'تطبيق', 'حساب Keq', 'سهل', 'الكتاب ص 89 — المثال 3-3 ومسائل تدريبية 5–7'),
('mcq', 2, 'يمثل الشكل الآتي تغير التراكيز مع الزمن للتفاعل N₂O₄(g) ⇌ 2NO₂(g) في وعاء مغلق عند درجة حرارة ثابتة. ما قيمة Keq عند هذه الدرجة؟', null, '[{"src":"qimg/chem22/c3-l1a-conc-n2o4.svg","alt":"منحنيا تغير التركيز (mol/L) مع الزمن (s) للتفاعل N₂O₄(g) ⇌ 2NO₂(g) في وعاء مغلق عند درجة حرارة ثابتة. المحور الرأسي مدرج من 0.000 إلى 0.180 mol/L كل 0.020، والأفقي من 0 إلى 100 s كل 20 s. منحنى [N₂O₄] يبدأ من 0.100 mol/L عند 0 s ويتناقص حتى يثبت عند 0.020 mol/L بدءًا من 60 s. ومنحنى [NO₂] يبدأ من 0.000 ويتزايد حتى يثبت عند 0.160 mol/L بدءًا من 60 s. يتقاطع المنحنيان قرب 14 s عند نحو 0.067 mol/L، ويبقى التركيزان ثابتين من 60 s إلى 100 s."}]'::jsonb, '["0.26","8.0","1.3","0.78"]'::jsonb, 'تطبيق', 'حساب Keq من رسم بياني', 'متوسط', 'الكتاب ص 89 — المثال 3-3 ومسائل تدريبية 5–7'),
('mcq', 3, 'احسب قيمة Keq عند 400 K للتفاعل PCl₅(g) ⇌ PCl₃(g) + Cl₂(g) إذا علمت أن تراكيز الاتزان: [PCl₅] = 0.135 mol/L و[PCl₃] = 0.550 mol/L و[Cl₂] = 0.550 mol/L.', null, null, '["0.446","8.15","4.07","2.24"]'::jsonb, 'تطبيق', 'حساب Keq', 'سهل', 'الكتاب ص 90 — التقويم 3-1'),
('mcq', 4, 'احسب قيمة Keq للاتزان CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g) إذا علمت أن تراكيز الاتزان: [CO] = 0.0613 mol/L و[H₂] = 0.1839 mol/L و[CH₄] = 0.0387 mol/L و[H₂O] = 0.0387 mol/L.', null, null, '["3.93","0.133","0.255","0.0443"]'::jsonb, 'تطبيق', 'حساب Keq', 'متوسط', 'الكتاب ص 89 — المثال 3-3 ومسائل تدريبية 5–7'),
('mcq', 5, 'يمثل الشكل الآتي خليطًا في حالة اتزان للتفاعل H₂(g) + I₂(g) ⇌ 2HI(g) في وعاء حجمه 1.0 L، وكل جزيء في الرسم يمثل 0.10 mol. ما قيمة Keq؟', null, '[{"src":"qimg/chem22/c3-l1a-particles-hi.svg","alt":"رسم جسيمات لخليط في حالة اتزان للتفاعل H₂(g) + I₂(g) ⇌ 2HI(g) داخل وعاء مغلق حجمه 1.0 L. يحتوي الوعاء على جزيئين من H₂ (كل جزيء ذرتان صغيرتان زرقاوان فاتحتان)، وجزيئين من I₂ (كل جزيء ذرتان كبيرتان بنفسجيتان)، وثمانية جزيئات من HI (كل جزيء ذرة زرقاء صغيرة مرتبطة بذرة بنفسجية كبيرة). يبيّن المفتاح بجانب الوعاء شكل كل جزيء، ويذكر أن كل جزيء في الرسم يمثل 0.10 mol."}]'::jsonb, '["20","0.063","2.0","16"]'::jsonb, 'تطبيق', 'حساب Keq من رسم جسيمات', 'متوسط', 'الكتاب ص 84 — دلالة قيمة Keq وتعابير الاتزان المتجانس'),
('mcq', 6, 'في الاتزان الغازي: 2SO₂(g) + O₂(g) ⇌ 2SO₃(g) كانت تراكيز الاتزان عند درجة حرارة معينة: [SO₃] = 0.0400 M و[SO₂] = 0.0200 M و[O₂] = 0.0500 M. ما قيمة Keq لهذا التفاعل؟', null, null, '["80.0","40.0","0.0125","1.60"]'::jsonb, 'تطبيق', 'حساب Keq', 'متوسط', 'الكتاب ص 84–86 — حساب قيمة ثابت الاتزان'),
('mcq', 7, 'وُضع 1.0000 mol من CO و1.0000 mol من Cl₂ في وعاء حجمه 10.00 L، فحدث الاتزان CO(g) + Cl₂(g) ⇌ COCl₂(g)، ووُجد أن تركيز كل من CO وCl₂ عند الاتزان 0.0086 mol/L. ما قيمة Keq؟', null, null, '["1.4×10³","1.2×10³","8.1×10⁻⁴","10.6"]'::jsonb, 'تحليل', 'حساب Keq من كميات ابتدائية', 'صعب', 'الكتاب ص 115 — السؤال 80'),
('essay', 1, 'في إحدى تجارب التفاعل H₂(g) + I₂(g) ⇌ 2HI(g) عند 731 K كانت تراكيز الاتزان: [H₂] = 0.2485 mol/L و[I₂] = 0.2485 mol/L و[HI] = 1.7515 mol/L. اكتب تعبير ثابت الاتزان، ثم احسب قيمته.', null, null, null, 'تطبيق', 'حساب Keq', 'سهل', 'الكتاب ص 88 — ثوابت الاتزان (الجدول 3-1)'),
('essay', 2, 'في خليط اتزان للتفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) عند درجة حرارة معينة كانت التراكيز: [N₂] = 0.250 mol/L و[H₂] = 0.750 mol/L و[NH₃] = 0.150 mol/L. (أ) احسب قيمة Keq. (ب) هل تتوقع أن تتغير هذه القيمة إذا أُعيدت التجربة عند درجة الحرارة نفسها بتراكيز ابتدائية مختلفة؟ فسّر إجابتك.', null, null, null, 'تطبيق', 'حساب وتفسير', 'متوسط', 'الكتاب ص 88 — ثوابت الاتزان (الجدول 3-1)'),
('essay', 3, 'قيمة Keq للتفاعل A + 2B ⇌ C تساوي 3.63 عند درجة حرارة معينة. يبيّن الجدول الآتي تراكيز المتفاعلات والنواتج في خليطين للتفاعل عند درجة الحرارة نفسها. حدّد بالحساب هل كل خليط في حالة اتزان، وفسّر إجابتك.', '{"headers":["الخليط","A (mol/L)","B (mol/L)","C (mol/L)"],"rows":[["1","0.500","0.621","0.700"],["2","0.250","0.525","0.250"]]}'::jsonb, null, null, 'تحليل', 'حساب ومقارنة', 'صعب', 'الكتاب ص 112 — السؤال 44')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L1-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'Keq = [NO₂]²/[N₂O₄] = (0.0627)²/0.0185 = 0.00393/0.0185 = 0.213 (ثلاثة أرقام معنوية).', '["هذا مقلوب الناتج؛ قُسم [N₂O₄] على [NO₂]².","","أُهمل تربيع [NO₂]: 0.0627/0.0185.","ضُرب [NO₂] في المعامل 2 بدل رفعه إلى الأس 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-06T22:20:31.192Z"}'::jsonb),
('mcq', 2, 2, 'تُقرأ تراكيز الاتزان من الجزء الأفقي (بعد 60 s): [N₂O₄] = 0.020 mol/L و[NO₂] = 0.160 mol/L. Keq = [NO₂]²/[N₂O₄] = (0.160)²/0.020 = 0.0256/0.020 = 1.28 ≈ 1.3 (رقمان معنويان كما في 0.020).', '["استُعمل التركيز الابتدائي لـ N₂O₄ (0.100 mol/L) بدل تركيز الاتزان (0.020 mol/L).","أُهمل تربيع [NO₂]: 0.160/0.020.","","هذا مقلوب الناتج: [N₂O₄]/[NO₂]²."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-06T22:20:31.192Z"}'::jsonb),
('mcq', 3, 3, 'Keq = [PCl₃][Cl₂]/[PCl₅] = (0.550 × 0.550)/0.135 = 0.3025/0.135 = 2.24.', '["هذا مقلوب الناتج؛ وُضع المتفاعل في البسط.","جُمع تركيزا النواتج (0.550 + 0.550) بدل ضربهما.","استُعمل تركيز ناتج واحد فقط: 0.550/0.135.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-06T22:20:31.192Z"}'::jsonb),
('mcq', 4, 0, 'Keq = [CH₄][H₂O]/[CO][H₂]³ = (0.0387 × 0.0387)/(0.0613 × 0.1839³) = 0.001498/(0.0613 × 0.006219) = 3.93.', '["","لم يُرفع [H₂] إلى الأس 3.","هذا مقلوب الناتج؛ وُضعت المتفاعلات في البسط.","ضُرب [H₂] في المعامل 3 بدل رفعه إلى الأس 3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.193Z"}'::jsonb),
('mcq', 5, 3, 'في الرسم: جزيئان H₂ ⇐ 0.20 mol، وجزيئان I₂ ⇐ 0.20 mol، وثمانية جزيئات HI ⇐ 0.80 mol، في 1.0 L؛ فالتراكيز: [H₂] = [I₂] = 0.20 mol/L و[HI] = 0.80 mol/L. Keq = [HI]²/[H₂][I₂] = (0.80)²/(0.20 × 0.20) = 0.64/0.040 = 16.', '["لم يُربَّع [HI]: 0.80/(0.20 × 0.20).","هذا مقلوب الناتج: (0.20 × 0.20)/(0.80)².","جُمع تركيزا المتفاعلين في المقام ولم يُربَّع [HI]: 0.80/(0.20 + 0.20).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-06T22:20:31.193Z"}'::jsonb),
('mcq', 6, 0, 'Keq = [SO₃]²/([SO₂]²[O₂]) = (0.0400)²/((0.0200)² × 0.0500) = 0.00160/0.0000200 = 80.0 (دون وحدة).', '["","أُهملت المعاملات أسسًا: 0.0400/(0.0200 × 0.0500) = 40.0، والمعامل 2 لكل من SO₃ وSO₂ يجب أن يكون أسًّا.","هذا مقلوب الناتج؛ وُضعت تراكيز المتفاعلات في البسط والنواتج في المقام.","رُفع [SO₃] للأس 2 ونُسي أس [SO₂]: (0.0400)²/(0.0200 × 0.0500) = 1.60."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-06T22:20:31.194Z"}'::jsonb),
('mcq', 7, 1, 'التركيز الابتدائي لكل من CO وCl₂ = 1.0000/10.00 = 0.10000 mol/L. استُهلك منهما 0.10000 − 0.0086 = 0.0914 mol/L، فتكوّن [COCl₂] = 0.0914 mol/L. Keq = [COCl₂]/[CO][Cl₂] = 0.0914/(0.0086)² = 1.2×10³ (رقمان معنويان).', '["استُعمل تركيز COCl₂ مساويًا لـ 0.10 mol/L (التركيز الابتدائي للمتفاعل) بدل 0.10 − 0.0086 = 0.0914 mol/L.","","هذا مقلوب الناتج؛ وُضع المتفاعلان في البسط.","قُسم [COCl₂] على تركيز متفاعل واحد فقط ولم يُضرب في الآخر: 0.0914/0.0086 = 10.6."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.194Z"}'::jsonb),
('essay', 1, null::int, null, null, 'Keq = [HI]²/[H₂][I₂] = (1.7515)²/(0.2485 × 0.2485) = 3.0678/0.06175 = 49.68 ≈ 49.7 (دون وحدة).', '["Keq = [HI]²/[H₂][I₂]","التعويض الصحيح","الناتج 49.7 دون وحدة"]'::jsonb, '["كتابة التعبير: Keq = [HI]²/[H₂][I₂]","التعويض: (1.7515)²/(0.2485 × 0.2485)","البسط 3.0678 والمقام 0.06175","Keq = 49.7"]'::jsonb, '[{"element":"كتابة التعبير","marks":1},{"element":"التعويض","marks":1},{"element":"الحساب الصحيح","marks":1},{"element":"كتابة الناتج دون وحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعبير وتعويض وحساب صحيح دون وحدة"},{"level":"2–3 درجات","description":"تعبير صحيح مع خطأ حسابي أو إهمال التربيع"},{"level":"1 درجة","description":"تعبير صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تربيع [HI] فيكون الناتج 28.4","إضافة وحدة إلى Keq","قلب النسبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-06T22:20:31.194Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Keq = [NH₃]²/[N₂][H₂]³ = (0.150)²/(0.250 × 0.750³) = 0.0225/(0.250 × 0.4219) = 0.0225/0.1055 = 0.213. (ب) لا تتغير؛ لأن قيمة Keq ثابتة لتفاعل معين عند درجة حرارة معينة بغض النظر عن التراكيز الابتدائية؛ فالتراكيز الابتدائية المختلفة تعطي تراكيز اتزان مختلفة (موضع اتزان مختلف)، لكن نسبتها في تعبير ثابت الاتزان تبقى 0.213.', '["التعبير Keq = [NH₃]²/[N₂][H₂]³","التعويض والحساب = 0.213","Keq لا تتغير بتغير التراكيز الابتدائية عند الدرجة نفسها","تتغير تراكيز الاتزان (الموضع) لا قيمة Keq"]'::jsonb, '["Keq = [NH₃]²/[N₂][H₂]³","البسط: (0.150)² = 0.0225","المقام: 0.250 × (0.750)³ = 0.250 × 0.4219 = 0.1055","Keq = 0.0225/0.1055 = 0.213"]'::jsonb, '[{"element":"كتابة التعبير","marks":1},{"element":"التعويض والحساب الصحيح","marks":2},{"element":"الإجابة عن (ب) مع التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح وتفسير صحيح لثبات Keq"},{"level":"3–4 درجات","description":"حساب صحيح وتفسير ناقص، أو خطأ حسابي بسيط مع تفسير صحيح"},{"level":"1–2 درجة","description":"تعبير صحيح فقط أو إجابة (ب) دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم رفع [H₂] إلى الأس 3 فيكون الناتج 0.120","إهمال الأسس كلها فيكون الناتج 0.800","القول إن Keq تتغير بتغير التراكيز الابتدائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-06T22:20:31.194Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تعبير ثابت الاتزان: Keq = [C]/[A][B]². الخليط 1: 0.700/(0.500 × 0.621²) = 0.700/(0.500 × 0.3856) = 0.700/0.1928 = 3.63، وهي تساوي Keq، فالخليط 1 في حالة اتزان. الخليط 2: 0.250/(0.250 × 0.525²) = 0.250/(0.250 × 0.2756) = 0.250/0.06891 = 3.63، وهي تساوي Keq أيضًا، فالخليط 2 في حالة اتزان. التفسير: عند درجة حرارة معينة تكون نسبة تعبير ثابت الاتزان لأي خليط متزن مساوية لـ Keq، مع أن تراكيز الخليطين مختلفة؛ فللتفاعل عدد غير محدود من مواضع الاتزان.', '["Keq = [C]/[A][B]²","الخليط 1: 3.63 متزن","الخليط 2: 3.63 متزن","التراكيز المختلفة تعطي Keq نفسها (مواضع اتزان مختلفة)"]'::jsonb, '["كتابة التعبير Keq = [C]/[A][B]²","الخليط 1: 0.700/(0.500 × 0.621²) = 3.63","الخليط 2: 0.250/(0.250 × 0.525²) = 3.63","مقارنة كل نسبة بـ Keq = 3.63"]'::jsonb, '[{"element":"كتابة التعبير بالأس الصحيح","marks":1},{"element":"حساب نسبة الخليط 1 والحكم","marks":2},{"element":"حساب نسبة الخليط 2 والحكم","marks":2},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تعبير صحيح وحسابان صحيحان وحكمان صحيحان مع التفسير"},{"level":"3–5 درجات","description":"حساب أحد الخليطين صحيحًا أو إهمال تربيع [B] مع منهجية صحيحة"},{"level":"1–2 درجة","description":"تعبير صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال تربيع [B]","الحكم بعدم اتزان الخليط 2 لأن تراكيزه تختلف عن الخليط 1","قلب النسبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-06T22:20:31.195Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
