insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L1-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالاتزان المتجانس؟', null, null, '["اتزان توجد فيه المتفاعلات والنواتج في أكثر من حالة فيزيائية","اتزان تتساوى فيه تراكيز المتفاعلات وتراكيز النواتج","اتزان تكون فيه المتفاعلات والنواتج جميعها في الحالة الفيزيائية نفسها","اتزان يحدث في وعاء مفتوح على الهواء الجوي"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 84 — دلالة قيمة Keq وتعابير الاتزان المتجانس'),
('mcq', 2, 'أيّ الاتزانات الآتية غير متجانس؟', null, null, '["H₂(g) + I₂(g) ⇌ 2HI(g)","N₂O₄(g) ⇌ 2NO₂(g)","2NO(g) + O₂(g) ⇌ 2NO₂(g)","C₁₀H₈(s) ⇌ C₁₀H₈(g)"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 87 — المثال 3-2 ومسائل تدريبية 3–4'),
('mcq', 3, 'هل يمثل الاتزان H₂O(s) ⇌ H₂O(l) اتزانًا متجانسًا أم غير متجانس؟', null, null, '["غير متجانس؛ لأن الماء موجود في حالتين فيزيائيتين: صلبة وسائلة","متجانس؛ لأن المادة نفسها (الماء) موجودة في طرفي المعادلة","متجانس؛ لأن الماء لا يتغير تركيبه الكيميائي","غير متجانس؛ لأن تركيز الماء في الطرفين متساوٍ"]'::jsonb, 'فهم', 'تصنيف مع تعليل', 'متوسط', 'الكتاب ص 112 — السؤال 35'),
('mcq', 4, 'يبيّن الشكل الآتي اتزانًا بين الإيثانول السائل وبخاره في دورق مغلق عند درجة حرارة ثابتة. ما نوع هذا الاتزان، وما تعبير ثابت الاتزان له؟', null, '[{"src":"qimg/chem22/c3-l1a-flask-ethanol.svg","alt":"دورق زجاجي مغلق بسدادة عند درجة حرارة ثابتة، في أسفله إيثانول سائل مكتوب بجانبه C₂H₅OH(l)، وفي الفراغ فوقه جزيئات من بخار الإيثانول مكتوب بجانبها C₂H₅OH(g). سهم أحمر صاعد من سطح السائل نحو البخار مكتوب بجانبه «تبخر»، وسهم أزرق نازل من البخار نحو سطح السائل مكتوب بجانبه «تكثف»."}]'::jsonb, '["متجانس، وKeq = [C₂H₅OH(g)]","غير متجانس، وKeq = [C₂H₅OH(g)]","غير متجانس، وKeq = [C₂H₅OH(g)]/[C₂H₅OH(l)]","متجانس، وKeq = [C₂H₅OH(l)]/[C₂H₅OH(g)]"]'::jsonb, 'فهم', 'تصنيف وكتابة تعبير من شكل', 'متوسط', 'الكتاب ص 86 — تعابير الاتزان غير المتجانس'),
('mcq', 5, 'ما الفرق بين كتابة تعبير ثابت الاتزان للاتزان المتجانس وكتابته للاتزان غير المتجانس؟', null, null, '["تُحذف المواد الصلبة والسوائل النقية من تعبير الاتزان غير المتجانس","تُحذف الغازات من تعبير الاتزان غير المتجانس","لا يُكتب تعبير ثابت اتزان للاتزان غير المتجانس","تُرفع التراكيز إلى أسس المعاملات في المتجانس فقط"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 86 — تعابير الاتزان غير المتجانس'),
('mcq', 6, 'أيّ الأزواج الآتية يتكون من اتزان متجانس ثم اتزان غير متجانس على الترتيب؟', null, null, '["CaCO₃(s) ⇌ CaO(s) + CO₂(g) ، ثم 2H₂S(g) ⇌ 2H₂(g) + S₂(g)","2H₂S(g) ⇌ 2H₂(g) + S₂(g) ، ثم CaCO₃(s) ⇌ CaO(s) + CO₂(g)","N₂O₄(g) ⇌ 2NO₂(g) ، ثم 2H₂S(g) ⇌ 2H₂(g) + S₂(g)","I₂(s) ⇌ I₂(g) ، ثم H₂O(l) ⇌ H₂O(g)"]'::jsonb, 'تحليل', 'تصنيف ومقارنة', 'متوسط', 'الكتاب ص 84، 86–87 — الاتزان المتجانس وغير المتجانس'),
('mcq', 7, 'في دورق مغلق يحدث الاتزان I₂(s) ⇌ I₂(g) عند درجة حرارة ثابتة. قال طالب: «إذا أضفنا مزيدًا من بلورات اليود الصلب تزداد قيمة Keq». أيّ العبارات الآتية تقوّم قوله تقويمًا صحيحًا؟', null, null, '["قوله صحيح؛ لأن Keq = [I₂(g)]/[I₂(s)] فتتغير بتغير كمية الصلب","قوله صحيح؛ لأن Keq = [I₂(s)] واليود الصلب هو المادة المتفاعلة","قوله خاطئ؛ لأن Keq = [I₂(g)] فقط، ولا تؤثر كمية اليود الصلب في قيمته","قوله خاطئ؛ لأن إضافة اليود الصلب تُنقص قيمة Keq"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 86 — تعابير الاتزان غير المتجانس'),
('essay', 1, 'قارن بين الاتزان المتجانس والاتزان غير المتجانس من حيث: التعريف، ومثال على كل منهما، والمواد التي تُكتب في تعبير ثابت الاتزان.', null, null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 90 — التقويم 3-1'),
('essay', 2, 'صنّف كل اتزان مما يأتي إلى متجانس أو غير متجانس، واكتب تعبير ثابت الاتزان له: (أ) C₆H₆(l) ⇌ C₆H₆(g)  (ب) 2NbCl₄(g) ⇌ NbCl₃(g) + NbCl₅(g)  (ج) C(s) + H₂O(g) ⇌ CO(g) + H₂(g)  (د) H₂(g) + Cl₂(g) ⇌ 2HCl(g)', null, null, null, 'تطبيق', 'تصنيف وكتابة تعابير', 'صعب', 'الكتاب ص 112، 117 — السؤال 42 وأسئلة الاختبار المقنن'),
('essay', 3, 'يبيّن الشكل الآتي الإيثانول السائل وبخاره في دورق مغلق عند درجة حرارة ثابتة. (أ) اكتب معادلة هذا الاتزان، وبيّن نوعه مع التعليل. (ب) اكتب النسبة K = [C₂H₅OH(g)]/[C₂H₅OH(l)]، ثم وضّح خطوة بخطوة كيف نصل منها إلى تعبير ثابت الاتزان Keq. (ج) ما الشرط على سرعتي العمليتين المبيّنتين بالسهمين عند الاتزان؟', null, '[{"src":"qimg/chem22/c3-l1a-flask-ethanol.svg","alt":"دورق زجاجي مغلق بسدادة عند درجة حرارة ثابتة، في أسفله إيثانول سائل مكتوب بجانبه C₂H₅OH(l)، وفي الفراغ فوقه جزيئات من بخار الإيثانول مكتوب بجانبها C₂H₅OH(g). سهم أحمر صاعد من سطح السائل نحو البخار مكتوب بجانبه «تبخر»، وسهم أزرق نازل من البخار نحو سطح السائل مكتوب بجانبه «تكثف»."}]'::jsonb, null, 'تحليل', 'اشتقاق وتفسير', 'صعب', 'الكتاب ص 86 — تعابير الاتزان غير المتجانس')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L1-O06') and x.type = v.type and x.number = v.number);
