from (values
('mcq', 1, 2, 'الاتزان المتجانس هو الاتزان الذي تكون فيه المتفاعلات والنواتج في الحالة الفيزيائية نفسها، مثل H₂(g) + I₂(g) ⇌ 2HI(g) الذي جميع مواده غازية.', '["هذا تعريف الاتزان غير المتجانس.","تساوي التراكيز لا يحدد نوع الاتزان، ولا يتحقق عادة.","","الاتزان بنوعيه يتطلب نظامًا مغلقًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-06T22:20:31.195Z"}'::jsonb),
('mcq', 2, 3, 'في الاتزان C₁₀H₈(s) ⇌ C₁₀H₈(g) توجد المادة في حالتين فيزيائيتين: صلبة وغازية، فهو اتزان غير متجانس؛ أما البدائل الأخرى فجميع موادها غازية.', '["جميع المواد غازية، فالاتزان متجانس.","المادتان غازيتان، فالاتزان متجانس.","جميع المواد غازية، فالاتزان متجانس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-06T22:20:31.195Z"}'::jsonb),
('mcq', 3, 0, 'الاتزان غير المتجانس هو الذي توجد فيه المتفاعلات والنواتج في أكثر من حالة فيزيائية. وهنا يوجد الماء صلبًا (s) وسائلًا (l)، فالاتزان غير متجانس.', '["","نوع الاتزان يُحدَّد بالحالات الفيزيائية لا بنوع المادة.","ثبات التركيب الكيميائي لا يجعل الاتزان متجانسًا؛ فالحالتان مختلفتان.","الحكم صحيح لكن التعليل خاطئ؛ فالسبب اختلاف الحالة الفيزيائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-06T22:20:31.195Z"}'::jsonb),
('mcq', 4, 1, 'الإيثانول موجود في حالتين فيزيائيتين (سائلة وغازية)، فالاتزان C₂H₅OH(l) ⇌ C₂H₅OH(g) غير متجانس. وتركيز السائل النقي ثابت، فيُدمج مع K، ويصبح Keq = [C₂H₅OH(g)].', '["التعبير صحيح لكن النوع خاطئ؛ فالمادة في حالتين: سائلة وغازية.","","النوع صحيح، لكن السائل النقي تركيزه ثابت فيُدمج مع K ولا يُكتب في Keq.","النوع خاطئ، والتعبير مقلوب ويتضمن السائل النقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-06T22:20:31.196Z"}'::jsonb),
('mcq', 5, 0, 'في الاتزان المتجانس تُكتب تراكيز جميع المواد لأنها في الحالة نفسها. أما في الاتزان غير المتجانس فتُحذف المواد الصلبة والسوائل النقية لأن تراكيزها ثابتة، وتبقى المواد الغازية (أو الذائبة)، مع رفع التراكيز إلى أسس معاملاتها في الحالتين.', '["","الغازات تبقى في التعبير؛ والمحذوف هو المواد الصلبة والسوائل النقية.","يُكتب له تعبير، مثل Keq = [CO₂][H₂O] لتحلل صودا الخبز.","قاعدة الأسس تنطبق على النوعين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.196Z"}'::jsonb),
('mcq', 6, 1, '2H₂S(g) ⇌ 2H₂(g) + S₂(g) جميع مواده غازية فهو متجانس، وCaCO₃(s) ⇌ CaO(s) + CO₂(g) فيه مواد صلبة وغاز فهو غير متجانس؛ فهذا الزوج مرتب كما هو مطلوب.', '["الترتيب معكوس؛ فالأول غير متجانس والثاني متجانس.","","الاتزانان كلاهما متجانس؛ فجميع موادهما غازية.","الاتزانان كلاهما غير متجانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-06T22:20:31.196Z"}'::jsonb),
('mcq', 7, 2, 'الاتزان I₂(s) ⇌ I₂(g) غير متجانس، وتركيز اليود الصلب ثابت مهما كانت كميته، فلا يُكتب في التعبير: Keq = [I₂(g)]. لذا لا تؤثر إضافة اليود الصلب في قيمة Keq، فقول الطالب خاطئ.', '["اليود الصلب مادة نقية تركيزها ثابت، فلا يُكتب في التعبير.","Keq لا تتضمن المادة الصلبة؛ والمتبقي هو تركيز اليود الغازي.","","Keq لا تتغير بإضافة مادة صلبة؛ فهي تعتمد على درجة الحرارة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-06T22:20:31.196Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الاتزان المتجانس: تكون فيه المتفاعلات والنواتج في الحالة الفيزيائية نفسها، مثل H₂(g) + I₂(g) ⇌ 2HI(g)، وتُكتب تراكيز جميع المواد في تعبيره: Keq = [HI]²/[H₂][I₂]. الاتزان غير المتجانس: توجد فيه المتفاعلات والنواتج في أكثر من حالة فيزيائية، مثل C₂H₅OH(l) ⇌ C₂H₅OH(g)، ولا تُكتب في تعبيره المواد الصلبة والسوائل النقية لأن تراكيزها ثابتة: Keq = [C₂H₅OH(g)].', '["تعريف المتجانس","تعريف غير المتجانس","مثال صحيح لكل نوع","المتجانس: تُكتب جميع المواد","غير المتجانس: تُحذف الصلبة والسائلة النقية"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف كل نوع","marks":2},{"element":"مثال صحيح لكل نوع","marks":2},{"element":"المقارنة في كتابة التعبير","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تعريفان ومثالان صحيحان ومقارنة صحيحة في كتابة التعبير"},{"level":"3–5 درجات","description":"تعريفان صحيحان مع نقص في الأمثلة أو المقارنة"},{"level":"1–2 درجة","description":"تعريف نوع واحد أو مثال فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف المتجانس بتساوي التراكيز","ذكر مثال متجانس فيه مادة صلبة","القول إن الغازات تُحذف من التعبير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.196Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) غير متجانس (سائل وغاز): Keq = [C₆H₆(g)]. (ب) متجانس (كلها غازات): Keq = [NbCl₃][NbCl₅]/[NbCl₄]². (ج) غير متجانس (صلب وغازات): Keq = [CO][H₂]/[H₂O]. (د) متجانس (كلها غازات): Keq = [HCl]²/[H₂][Cl₂].', '["(أ) غير متجانس، Keq = [C₆H₆(g)]","(ب) متجانس، Keq = [NbCl₃][NbCl₅]/[NbCl₄]²","(ج) غير متجانس، Keq = [CO][H₂]/[H₂O]","(د) متجانس، Keq = [HCl]²/[H₂][Cl₂]"]'::jsonb, '["تحديد الحالات الفيزيائية في كل معادلة","التصنيف: حالة واحدة ⇐ متجانس؛ أكثر من حالة ⇐ غير متجانس","حذف C(s) وC₆H₆(l) من التعبيرين","كتابة التعابير بأسس المعاملات"]'::jsonb, '[{"element":"تصنيف كل اتزان (4 × 1)","marks":4},{"element":"تعبير كل اتزان (4 × 1)","marks":4}]'::jsonb, '[{"level":"8 درجات","description":"تصنيفات وتعابير صحيحة كلها"},{"level":"4–7 درجات","description":"معظم التصنيفات صحيحة مع خطأ أو خطأين في التعابير"},{"level":"1–3 درجات","description":"تصنيفات صحيحة دون تعابير صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إدخال [C] في تعبير (ج)","كتابة [C₆H₆(g)]/[C₆H₆(l)] في (أ)","إهمال الأس 2 لـ [NbCl₄] أو [HCl]"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.196Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) C₂H₅OH(l) ⇌ C₂H₅OH(g)، وهو اتزان غير متجانس لأن المادة موجودة في حالتين فيزيائيتين: سائلة وغازية. (ب) K = [C₂H₅OH(g)]/[C₂H₅OH(l)]. المقام يمثل الإيثانول السائل النقي، وتركيزه هو كثافته معبرًا عنها بـ mol/L، والكثافة ثابتة عند درجة حرارة معينة، فتركيز السائل ثابت مهما كانت كميته. لذا يُدمج مع K: K[C₂H₅OH(l)] = [C₂H₅OH(g)] = Keq، فيصبح Keq = [C₂H₅OH(g)]. (ج) عند الاتزان تكون سرعة التبخر مساوية لسرعة التكثف.', '["المعادلة بالحالات الفيزيائية","غير متجانس لوجود حالتين","تركيز السائل النقي = كثافته بـ mol/L وهي ثابتة","دمج الثابت مع K ⇐ Keq = [C₂H₅OH(g)]","سرعة التبخر = سرعة التكثف"]'::jsonb, '["K = [C₂H₅OH(g)]/[C₂H₅OH(l)]","[C₂H₅OH(l)] ثابت لأن الكثافة ثابتة عند درجة حرارة معينة","ضرب الطرفين في [C₂H₅OH(l)]: K[C₂H₅OH(l)] = [C₂H₅OH(g)]","الطرف الأيسر ثابت يُسمى Keq ⇐ Keq = [C₂H₅OH(g)]"]'::jsonb, '[{"element":"المعادلة والنوع مع التعليل","marks":2},{"element":"خطوات الوصول إلى Keq","marks":2},{"element":"شرط تساوي السرعتين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلة ونوع مُعلَّل، واشتقاق صحيح، وشرط الاتزان"},{"level":"3–4 درجات","description":"معادلة ونوع صحيحان مع اشتقاق ناقص"},{"level":"1–2 درجة","description":"معادلة أو نوع فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف الاتزان متجانسًا لأن المادة واحدة","القول إن تركيز السائل صفر","القول إن كمية السائل تساوي كمية البخار عند الاتزان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-06T22:20:31.197Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C3-L1-O06') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L1-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا يوصف الاتزان الكيميائي بأنه اتزان ديناميكي (حركي)؟', null, null, '["لأن التفاعلين الأمامي والعكسي يستمران في الحدوث بسرعتين متساويتين","لأن التفاعل يتوقف تمامًا عند الاتزان بعد أن تُستهلك المتفاعلات","لأن تراكيز المتفاعلات والنواتج تبقى في تغير مستمر عند الاتزان","لأن تراكيز المتفاعلات تصبح مساوية لتراكيز النواتج عند الاتزان"]'::jsonb, 'فهم', 'تفسير مفهوم', 'سهل', 'الكتاب ص 81 — الطبيعة الديناميكية للاتزان'),
('mcq', 2, 'يمثل الشكل الآتي دورقين مغلقين متصلين بمحبس يحتوي كل منهما على اليود الصلب والغازي في حالة اتزان عند 298 K: (أ) قبل فتح المحبس، و(ب) بعد فتحه بمدة. ما الذي يدل عليه ظهور جزيئات I-131 المشعة داخل اليود الصلب في الدورق الأيسر في (ب)؟', null, '[{"src":"qimg/chem22/c3-l1b-iodine-flasks.svg","alt":"رسم من لوحتين لدورقين كرويين مغلقين متصلين بأنبوب عليه محبس، وفي قاع كل دورق طبقة من اليود الصلب I₂(s) وفوقها جزيئات يود غازية I₂(g)، والجسيمات الرمادية جزيئات يود غير مشع (I-127) والحمراء جزيئات يود مشع (I-131). اللوحة (أ): المحبس مغلق؛ الدورق الأيسر كل جزيئاته الصلبة والغازية رمادية غير مشعة وعداد الإشعاع عنده يقرأ: لا إشعاع، والدورق الأيمن كل جزيئاته الصلبة والغازية حمراء مشعة وعداده يقرأ: إشعاع. اللوحة (ب): بعد فتح المحبس بمدة؛ في كل دورق خليط من الجزيئات الرمادية والحمراء في الحالة الغازية وفي الطبقة الصلبة أيضًا، وعداد الإشعاع عند كل من الدورقين يقرأ: إشعاع."}]'::jsonb, '["أن تسامي اليود الصلب توقف بعد فتح المحبس ووصول النظام إلى الاتزان","أن الاتزان تحقق في الدورق الأيمن وحده الذي بدأ باليود المشع","أن جزيئات I₂(g) تتحول باستمرار إلى الحالة الصلبة عند الاتزان","أن جزيئات النظير المشع I-131 تحولت إلى جزيئات النظير I-127"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 82 — تجربة تسامي نظيري اليود (الشكل 3-6)'),
('mcq', 3, 'ماذا يُسمّى التفاعل الأمامي في الاتزان I₂(s) ⇌ I₂(g) الذي تتحول فيه جزيئات اليود من الحالة الصلبة إلى الحالة الغازية مباشرة؟', null, null, '["التبخر","التسامي","التكثف","الانصهار"]'::jsonb, 'تذكر', 'مصطلح', 'سهل', 'الكتاب ص 82 — تجربة تسامي نظيري اليود (الشكل 3-6)'),
('mcq', 4, 'مبنيان متصلان بممر يعبر الناس خلاله ذهابًا وإيابًا، ويبقى عدد الأشخاص في كل مبنى ثابتًا. ما الذي يمثل في هذا التشبيه تساوي سرعتي التفاعلين الأمامي والعكسي عند الاتزان؟', null, null, '["توقف جميع الأشخاص عن العبور بين المبنيين","تساوي عدد الأشخاص الموجودين في المبنيين","بقاء الأشخاص أنفسهم دائمًا في المبنى نفسه","تساوي عدد العابرين في الاتجاهين في المدة نفسها"]'::jsonb, 'فهم', 'تشبيه', 'متوسط', 'الكتاب ص 82 — الشكل 3-5 (المبنيان والممر)'),
('mcq', 5, 'يبين المنحنى الآتي سرعتي التفاعلين الأمامي والعكسي مع الزمن لتفاعل في وعاء مغلق. أيّ العبارات الآتية تصف النظام بعد الزمن t₁؟', null, '[{"src":"qimg/chem22/c3-l1b-rates.svg","alt":"منحنى بياني محوره الأفقي الزمن ومحوره الرأسي سرعة التفاعل، بلا أرقام. فيه منحنيان: منحنى التفاعل الأمامي (أزرق) يبدأ من قيمة كبيرة ويتناقص تدريجيًّا، ومنحنى التفاعل العكسي (أحمر) يبدأ من الصفر ويتزايد تدريجيًّا. يقترب المنحنيان حتى يلتقيا عند قيمة واحدة لا تساوي صفرًا، ثم يستمران خطًّا أفقيًّا واحدًا. خط رأسي متقطع عند الزمن t₁ يقع في الجزء الذي صار فيه المنحنيان خطًّا أفقيًّا مشتركًا."}]'::jsonb, '["تتساوى سرعتا التفاعلين وكلتاهما لا تساوي صفرًا، فتبقى التراكيز ثابتة","تصبح سرعة كل من التفاعلين صفرًا، فيتوقف التفاعل وتثبت التراكيز","يتوقف التفاعل الأمامي ويستمر العكسي وحده بسرعة ثابتة","تزيد سرعة التفاعل العكسي على سرعة الأمامي، فيتناقص تركيز النواتج"]'::jsonb, 'تحليل', 'تفسير منحنى', 'صعب', 'الكتاب ص 80–81 — تعريف الاتزان الكيميائي والطبيعة الديناميكية'),
('mcq', 6, 'سُكب 20 mL من ماء ملون في مخبار مدرج، وتُرك كأس مثله فارغًا، ثم نقل طالبان الماء في الوقت نفسه بماصتين متماثلتين: أحدهما من المخبار إلى الكأس والآخر من الكأس إلى المخبار. بعد عدد من مرات النقل ثبت حجم الماء في كل وعاء مع استمرار النقل. ماذا يمثل هذا النموذج؟', null, null, '["تفاعلًا يكتمل فتتحول فيه كل المتفاعلات إلى نواتج","اتزانًا ديناميكيًّا يستمر فيه الانتقال بمعدلين متساويين","نظامًا يتوقف فيه الانتقال عند تساوي الحجمين في الوعاءين","تفاعلًا يحدث في اتجاه واحد فقط من المخبار إلى الكأس"]'::jsonb, 'فهم', 'تفسير نموذج', 'متوسط', 'الكتاب ص 77 — تجربة استهلالية (ما التساوي في الاتزان؟)'),
('mcq', 7, 'دورق مغلق عند 298 K يحتوي على I₂(s) وI₂(g) غير مشعين في حالة اتزان. أُدخلت إليه كمية صغيرة من بلورات I₂ المشعة (I-131) دون تغيير درجة الحرارة. ماذا يُتوقع أن يُلاحظ بعد مدة؟', null, null, '["يبقى الإشعاع محصورًا في الحالة الصلبة لأن النظام كان في حالة اتزان","يزداد تركيز I₂(g) زيادة دائمة لأن كمية اليود الصلب ازدادت","يظهر إشعاع في I₂(g) مع بقاء تركيز I₂(g) عند قيمته نفسها","لا يظهر إشعاع في الغاز إلا إذا رُفعت درجة حرارة الدورق"]'::jsonb, 'تحليل', 'تنبؤ وتعليل', 'صعب', 'الكتاب ص 82 — تجربة تسامي نظيري اليود (الشكل 3-6)'),
('essay', 1, 'إذا قيل لك إن تراكيز المتفاعلات والنواتج لا تتغير عند الاتزان، فلماذا تُستعمل كلمة (ديناميكي) لوصف الاتزان الكيميائي؟ وضح إجابتك بالاتزان N₂(g) + 3H₂(g) ⇌ 2NH₃(g).', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 112 — س34، وص 80–81'),
('essay', 2, 'يمثل الشكل الآتي تجربة على دورقين مغلقين متصلين بمحبس عند 298 K وضغط 1 atm، في كل منهما يود صلب في حالة اتزان مع بخاره؛ (أ) قبل فتح المحبس، و(ب) بعد فتحه بمدة.
(أ) اكتب معادلة الاتزان في كل دورق، وسمِّ التفاعلين الأمامي والعكسي.
(ب) صف قراءات عدادي الإشعاع في (أ) و(ب).
(ج) فسر كيف تثبت هذه التجربة أن الاتزان ديناميكي، مبينًا دلالة وجود I-131 في الحالة الصلبة في الدورق الأيسر.', null, '[{"src":"qimg/chem22/c3-l1b-iodine-flasks.svg","alt":"رسم من لوحتين لدورقين كرويين مغلقين متصلين بأنبوب عليه محبس، وفي قاع كل دورق طبقة من اليود الصلب I₂(s) وفوقها جزيئات يود غازية I₂(g)، والجسيمات الرمادية جزيئات يود غير مشع (I-127) والحمراء جزيئات يود مشع (I-131). اللوحة (أ): المحبس مغلق؛ الدورق الأيسر كل جزيئاته الصلبة والغازية رمادية غير مشعة وعداد الإشعاع عنده يقرأ: لا إشعاع، والدورق الأيمن كل جزيئاته الصلبة والغازية حمراء مشعة وعداده يقرأ: إشعاع. اللوحة (ب): بعد فتح المحبس بمدة؛ في كل دورق خليط من الجزيئات الرمادية والحمراء في الحالة الغازية وفي الطبقة الصلبة أيضًا، وعداد الإشعاع عند كل من الدورقين يقرأ: إشعاع."}]'::jsonb, null, 'تحليل', 'تفسير تجربة', 'صعب', 'الكتاب ص 82 — تجربة تسامي نظيري اليود (الشكل 3-6)'),
('essay', 3, 'في لعبة شد الحبل، يشد فريقان الحبل بقوتين متساويتين في المقدار ومتعاكستين في الاتجاه فلا يتحرك الحبل رغم أن كلا الفريقين يبذل جهدًا.
(أ) وضح وجه الشبه بين هذه الحالة والاتزان الكيميائي.
(ب) ماذا يحدث للحبل إذا صارت قوة أحد الفريقين أكبر؟ وما الذي يقابل ذلك في تفاعل كيميائي عكسي لم يصل بعد إلى الاتزان؟', null, null, null, 'فهم', 'تشبيه وتفسير', 'متوسط', 'الكتاب ص 78 و81 — الربط مع الحياة والطبيعة الديناميكية للاتزان')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L1-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'عند الاتزان لا يتوقف التفاعل، بل يستمر التفاعلان الأمامي والعكسي معًا بسرعتين متساويتين؛ فتتكون النواتج بالسرعة نفسها التي تتحلل بها، وهذه الحركة المستمرة هي معنى الطبيعة الديناميكية للاتزان.', '["","التفاعل لا يتوقف عند الاتزان؛ والمتفاعلات لا تُستهلك كاملة بل تبقى موجودة مع النواتج.","التراكيز عند الاتزان ثابتة لا تتغير؛ الحركة المستمرة في الجسيمات لا في قيم التراكيز.","التراكيز ثابتة لكنها ليست متساوية بالضرورة، وتساويها حالة نادرة لا تفسر صفة الديناميكية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-06T22:20:31.197Z"}'::jsonb),
('mcq', 2, 2, 'الدورق الأيسر لم يكن فيه يود مشع أصلًا؛ فوصول جزيئات I-131 إلى صلبه يعني أنها انتقلت إليه في الحالة الغازية ثم تحولت إلى الحالة الصلبة (التفاعل العكسي)، أي أن جزيئات I₂(g) تتحول باستمرار إلى الصلبة حتى والنظام في حالة اتزان.', '["التسامي لا يتوقف عند الاتزان؛ فوجود الجزيئات المشعة وغير المشعة في الحالتين الصلبة والغازية في الدورقين دليل على استمرار التحول في الاتجاهين.","عدادا الإشعاع يدلان على انتقال الجزيئات بين الدورقين، والاتزان يتحقق في الحجم الكلي للدورقين معًا.","","النظير لا يتحول إلى نظير آخر في هذا التغير الفيزيائي؛ تغير الحالة لا يغير هوية الجزيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.198Z"}'::jsonb),
('mcq', 3, 1, 'تحول المادة من الحالة الصلبة إلى الحالة الغازية مباشرة دون المرور بالحالة السائلة يُسمّى التسامي، وهو التفاعل الأمامي في I₂(s) ⇌ I₂(g).', '["التبخر تحول من الحالة السائلة إلى الغازية، ولا يوجد يود سائل في هذا الاتزان.","","التكثف تحول من الغازية إلى السائلة، وهو عكس اتجاه التفاعل الأمامي هنا.","الانصهار تحول من الصلبة إلى السائلة، والناتج هنا غاز لا سائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-06T22:20:31.198Z"}'::jsonb),
('mcq', 4, 3, 'يبقى عدد الأشخاص في كل مبنى ثابتًا لأن عدد من يعبرون في اتجاه يساوي عدد من يعبرون في الاتجاه المعاكس خلال المدة نفسها؛ وهذا يقابل تساوي سرعة التفاعل الأمامي وسرعة التفاعل العكسي.', '["لو توقف العبور لكان النظام ساكنًا، والاتزان الكيميائي ديناميكي تستمر فيه الحركة.","ثبات العدد لا يعني تساويه في المبنيين، كما أن تراكيز الاتزان ثابتة وليست متساوية بالضرورة.","الأشخاص يتبدلون باستمرار مع بقاء العدد ثابتًا، كما تتبدل الجزيئات بين المتفاعلات والنواتج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-06T22:20:31.198Z"}'::jsonb),
('mcq', 5, 0, 'بعد t₁ يلتقي المنحنيان عند قيمة واحدة أعلى من الصفر ويستمران أفقيين؛ أي أن التفاعلين مستمران بسرعتين متساويتين لا تساويان صفرًا، فتتكون كل مادة بالسرعة التي تُستهلك بها وتبقى التراكيز ثابتة.', '["","المنحنيان يستقران فوق محور الزمن، فالسرعتان لا تساويان صفرًا والتفاعل لم يتوقف.","منحنى التفاعل الأمامي لا يهبط إلى الصفر، بل يبقى مساويًا لمنحنى العكسي.","بعد t₁ ينطبق المنحنيان فلا تزيد إحدى السرعتين على الأخرى، ولذلك لا تتغير التراكيز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-06T22:20:31.198Z"}'::jsonb),
('mcq', 6, 1, 'ثبات الحجم في كل وعاء مع استمرار النقل في الاتجاهين يعني أن ما يُنقل في اتجاه يساوي ما يُنقل في الاتجاه المعاكس في المدة نفسها، وهذا نموذج للاتزان الديناميكي: عمليتان متعاكستان مستمرتان بمعدلين متساويين.', '["الماء لا ينتقل كله إلى الكأس، بل يبقى جزء منه في المخبار كما تبقى بعض المتفاعلات عند الاتزان.","","النقل لم يتوقف، والحجمان ثابتان لكن ليس بالضرورة أن يكونا متساويين.","النقل يحدث في الاتجاهين معًا، وهذا ما يجعله نموذجًا لتفاعل عكسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-06T22:20:31.199Z"}'::jsonb),
('mcq', 7, 2, 'التسامي والترسب مستمران عند الاتزان؛ فبعض جزيئات I-131 الصلبة تتسامى فيظهر الإشعاع في الحالة الغازية. أما تركيز I₂(g) فيبقى كما هو لأن Keq = [I₂(g)] ثابت عند درجة الحرارة نفسها مهما كانت كمية الصلب.', '["الاتزان ديناميكي؛ فجزيئات الصلب تتسامى باستمرار ولا يبقى الإشعاع محصورًا فيه.","زيادة كمية الصلب لا تغير [I₂(g)] عند الاتزان؛ لأن تركيز الصلب النقي ثابت ولا يدخل في Keq.","","التسامي يحدث عند 298 K باستمرار، ولا يحتاج إلى رفع درجة الحرارة لكي تنتقل الجزيئات المشعة إلى الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.199Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ثبات التراكيز لا يعني توقف التفاعل؛ فعند الاتزان يستمر التفاعل الأمامي (اتحاد N₂ وH₂ لتكوين NH₃) والتفاعل العكسي (تحلل NH₃ إلى N₂ وH₂) في الحدوث معًا بسرعتين متساويتين. لذلك تتكون جزيئات NH₃ بالسرعة نفسها التي تتحلل بها، فيبقى تركيز كل مادة ثابتًا رغم استمرار التحول. الاتزان إذن حالة حركة مستمرة (ديناميكية) وليس حالة سكون.', '["التفاعل لا يتوقف عند الاتزان","التفاعلان الأمامي والعكسي مستمران بسرعتين متساويتين","تطبيق ذلك على تكون NH₃ وتحلله","ثبات التراكيز ناتج عن تساوي السرعتين لا عن السكون"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن التفاعل مستمر وأن الاتزان ليس سكونًا","marks":1},{"element":"تساوي سرعتي التفاعلين الأمامي والعكسي","marks":1},{"element":"التطبيق على تفاعل الأمونيا في الاتجاهين","marks":1},{"element":"ربط ثبات التراكيز بتساوي السرعتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط ثبات التراكيز بتساوي السرعتين مع تطبيق صحيح على الأمونيا"},{"level":"2–3 درجات","description":"يذكر تساوي السرعتين دون تطبيق أو دون ربطه بثبات التراكيز"},{"level":"1 درجة","description":"يذكر أن التفاعل مستمر فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التفاعل يتوقف عند الاتزان","الخلط بين ثبات التراكيز وتساويها","ذكر التفاعل الأمامي وحده"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-06T22:20:31.199Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) I₂(s) ⇌ I₂(g)؛ التفاعل الأمامي تسامي اليود (تحول الصلب إلى غاز مباشرة)، والتفاعل العكسي تحول الغاز إلى صلب.
(ب) في (أ): العداد عند الدورق الأيسر لا يسجل إشعاعًا لأن يوده من النظير غير المشع I-127، والعداد عند الأيمن يسجل إشعاعًا لأن يوده من النظير المشع I-131. في (ب): كلا العدادين يسجل إشعاعًا.
(ج) بعد فتح المحبس انتقلت جزيئات I-131 الغازية إلى الدورق الأيسر، ووجودها في الحالة الصلبة هناك يعني أنها تحولت من غاز إلى صلب، كما وُجدت جزيئات I-127 في غاز الدورق الأيمن وصلبه. أي أن جزيئات اليود تتحول باستمرار من الصلبة إلى الغازية (الأمامي) ومن الغازية إلى الصلبة (العكسي) حتى والنظام في حالة اتزان، فالاتزان ديناميكي وليس ساكنًا.', '["معادلة الاتزان I₂(s) ⇌ I₂(g)","التسامي هو التفاعل الأمامي والعكسي تحول الغاز إلى صلب","قراءات العدادين قبل فتح المحبس وبعده","انتقال I-131 إلى صلب الدورق الأيسر دليل على التفاعل العكسي","استمرار التفاعلين عند الاتزان يعني أنه ديناميكي"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة معادلة الاتزان","marks":1},{"element":"تسمية التفاعلين الأمامي والعكسي","marks":1},{"element":"وصف قراءات العدادين في الحالتين","marks":1},{"element":"دلالة I-131 في الصلب الأيسر","marks":1},{"element":"الاستنتاج أن الاتزان ديناميكي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلة صحيحة وتسمية صحيحة ووصف كامل للقراءات وتفسير يربط انتقال النظير بالتفاعلين"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع نقص في دلالة النظير أو في وصف القراءات"},{"level":"1–2 درجة","description":"معادلة أو وصف صحيح للقراءات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية التفاعل الأمامي تبخرًا بدل التسامي","الظن أن اليود المشع بقي في الحالة الغازية فقط","تفسير الإشعاع في الدورق الأيسر بتحول النظير غير المشع إلى مشع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.200Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الحبل لا يتحرك لأن محصلة القوتين المتساويتين المتعاكستين صفر، مع أن كل فريق مستمر في الشد. وكذلك في الاتزان الكيميائي: التفاعلان الأمامي والعكسي مستمران في الحدوث، لكن سرعتيهما متساويتان فلا يحدث تغير صافٍ في التراكيز.
(ب) يتحرك الحبل في اتجاه القوة الأكبر. ويقابل ذلك تفاعل عكسي سرعة أحد اتجاهيه أكبر من الآخر (كبداية التفاعل حين تكون سرعة التفاعل الأمامي أكبر)، فيحدث تغير صافٍ في التراكيز: تتناقص المتفاعلات وتزداد النواتج، ويستمر ذلك حتى تتساوى السرعتان ويصل النظام إلى الاتزان.', '["القوتان متساويتان ومتعاكستان ومستمرتان ↔ سرعتا التفاعلين متساويتان ومستمرتان","لا تغير صافٍ في موضع الحبل ↔ التراكيز ثابتة","القوة الأكبر تحرك الحبل ↔ السرعة الأكبر تغير التراكيز","التغير يستمر حتى تتساوى السرعتان"]'::jsonb, '[]'::jsonb, '[{"element":"وجه الشبه: استمرار الشد/التفاعلين مع تساويهما","marks":2},{"element":"عدم تحرك الحبل يقابل ثبات التراكيز","marks":1},{"element":"حركة الحبل تقابل تغير التراكيز عند عدم تساوي السرعتين حتى الاتزان","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تشبيه دقيق في الجزأين مع ربط واضح بسرعتي التفاعلين والتراكيز"},{"level":"3–4 درجات","description":"تشبيه صحيح في جزء ونقص في الآخر"},{"level":"1–2 درجة","description":"ذكر عام للتوازن دون ربط بسرعتي التفاعلين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفريقين توقفا عن الشد كما يتوقف التفاعل","مقابلة القوتين بتركيزي المتفاعلات والنواتج بدل سرعتي التفاعلين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-06T22:20:31.200Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C3-L1-O07') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L1-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين المنحنى الآتي تغير تراكيز ثلاث مواد A وB وC مع الزمن في تفاعل يجري في وعاء مغلق. ما الدليل في المنحنى على أن التفاعل وصل إلى حالة الاتزان؟', null, '[{"src":"qimg/chem22/c3-l1b-abc.svg","alt":"منحنى بياني محوره الأفقي الزمن ومحوره الرأسي التركيز (mol/L)، بلا أرقام. فيه ثلاثة منحنيات: المنحنى A يبدأ عند أعلى قيمة ويتناقص ثم يثبت عند قيمة صغيرة لا تساوي صفرًا. المنحنى C يبدأ من الصفر ويتزايد ثم يثبت عند أعلى قيمة بين المنحنيات الثلاثة. المنحنى B يبدأ من الصفر ويتزايد ثم يثبت عند قيمة متوسطة بين A وC. في الجزء الأيمن من الرسم تصبح المنحنيات الثلاثة خطوطًا أفقية متوازية غير متطابقة."}]'::jsonb, '["تقاطع منحنى A مع منحنيي B وC في بداية التفاعل","تحول المنحنيات الثلاثة إلى خطوط أفقية في نهاية الرسم","تساوي تراكيز المواد الثلاث في الجزء الأيمن من الرسم","وصول تركيز المادة A إلى الصفر في نهاية الرسم"]'::jsonb, 'فهم', 'تفسير منحنى', 'سهل', 'الكتاب ص 117 — اختبار مقنن (س10–12)'),
('mcq', 2, 'يمثل المنحنى الآتي تغير تراكيز N₂ وH₂ وNH₃ مع الزمن للتفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) في وعاء مغلق. أيّ العبارات الآتية صحيحة بعد الزمن t₁؟', null, '[{"src":"qimg/chem22/c3-l1b-nh3-conc.svg","alt":"منحنى بياني للتفاعل N₂ + 3H₂ ⇌ 2NH₃ في وعاء مغلق: المحور الأفقي الزمن، والمحور الرأسي التركيز (mol/L) من 0 إلى 3.2. منحنى H₂ يبدأ عند 3.0 mol/L ويتناقص حتى يثبت عند 1.8 mol/L. منحنى N₂ يبدأ عند 1.0 mol/L ويتناقص حتى يثبت عند 0.6 mol/L. منحنى NH₃ يبدأ من الصفر ويتزايد حتى يثبت عند 0.8 mol/L، ويتقاطع مع منحنى N₂ في بداية التفاعل. خط رأسي متقطع عند الزمن t₁ تكون بعده المنحنيات الثلاثة خطوطًا أفقية."}]'::jsonb, '["تراكيز المواد الثلاث متساوية وتبقى كذلك مع الزمن","تركيزا N₂ وH₂ يساويان صفرًا لأن المتفاعلات استُهلكت","تركيز NH₃ مستمر في الزيادة وتركيزا N₂ وH₂ في النقصان","تراكيز المواد الثلاث ثابتة لكنها غير متساوية"]'::jsonb, 'تحليل', 'تفسير منحنى', 'سهل', 'الكتاب ص 79 — الشكل 3-2 (تراكيز المتفاعلات والنواتج مع الزمن)'),
('mcq', 3, 'في التفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) في وعاء مغلق، تناقص تركيز H₂ من 3.0 mol/L إلى 1.8 mol/L، وازداد تركيز NH₃ من 0 إلى 0.8 mol/L حتى ثبتا. ما نسبة النقص في [H₂] إلى الزيادة في [NH₃]، وبمَ تُفسَّر؟', null, null, '["3 : 2؛ لأنها تساوي نسبة معاملي H₂ وNH₃ في المعادلة الموزونة","2 : 3؛ لأنها تساوي نسبة معاملي NH₃ وH₂ في المعادلة الموزونة","1 : 1؛ لأن ما يُستهلك من المتفاعل يساوي ما يتكون من الناتج","3 : 1؛ لأنها تساوي نسبة معاملي H₂ وN₂ في المعادلة الموزونة"]'::jsonb, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 79 — الشكل 3-2 (تراكيز المتفاعلات والنواتج مع الزمن)'),
('mcq', 4, 'يمثل المنحنى الآتي تغير تراكيز N₂O₄ وNO₂ مع الزمن للتفاعل N₂O₄(g) ⇌ 2NO₂(g) في وعاء مغلق بدأ بـ 0.0500 mol/L من N₂O₄ وحده. أيّ المنحنيين يمثل NO₂، وما الدليل؟', null, '[{"src":"qimg/chem22/c3-l1b-xy-n2o4.svg","alt":"منحنى بياني للتفاعل N₂O₄(g) ⇌ 2NO₂(g) في وعاء مغلق بدأ بـ N₂O₄ وحده: المحور الأفقي الزمن، والمحور الرأسي التركيز (mol/L) من 0 إلى 0.07. المنحنى (س) يبدأ عند 0.0500 mol/L ويتناقص حتى يثبت عند 0.0185 mol/L تقريبًا. المنحنى (ص) يبدأ من الصفر ويتزايد بسرعة ثم يثبت عند 0.0630 mol/L تقريبًا. يتقاطع المنحنيان قرب بداية التفاعل عند نحو 0.03 mol/L، ثم يصبح كلاهما خطًّا أفقيًّا."}]'::jsonb, '["(س)؛ لأنه يبدأ من 0.0500 mol/L ثم يتناقص حتى يثبت","(ص)؛ لأنه يبدأ من الصفر وزيادته مثلا النقص في (س)","(س)؛ لأن تركيزه عند الاتزان أصغر من تركيز (ص)","(ص)؛ لأن تركيزه يصبح مساويًا لتركيز (س) عند الاتزان"]'::jsonb, 'تحليل', 'تحليل منحنى', 'صعب', 'الكتاب ص 79 و89 — الشكل 3-2 والمسألة 5'),
('mcq', 5, 'يبين المنحنى الآتي تغير تركيزي متفاعل وناتج مع الزمن في وعاء مغلق؛ يتقاطع المنحنيان عند t₁ ويصبحان أفقيين عند t₂. متى يكون التفاعل قد وصل إلى الاتزان؟', null, '[{"src":"qimg/chem22/c3-l1b-crossing.svg","alt":"منحنى بياني محوره الأفقي الزمن ومحوره الرأسي التركيز (mol/L)، بلا أرقام. منحنى المتفاعل (أزرق) يبدأ مرتفعًا ويتناقص، ومنحنى الناتج (أحمر) يبدأ من الصفر ويتزايد. يتقاطع المنحنيان عند الزمن t₁ المعلَّم بخط رأسي متقطع، ويستمران بعده في التغير: الناتج يواصل الزيادة والمتفاعل يواصل النقصان. عند الزمن t₂ المعلَّم بخط رأسي متقطع آخر يكون المنحنيان قد صارا خطين أفقيين، والناتج أعلى من المتفاعل، ولا يصل المتفاعل إلى الصفر."}]'::jsonb, '["عند t₁؛ لأن تركيز المتفاعل يساوي تركيز الناتج عندها","عند t₁؛ لأن سرعتي التفاعلين تتساويان عند تقاطع منحنيي التركيز","عند t₂؛ لأن تراكيز المواد تتوقف عن التغير ابتداءً منها","لا يصل إليه؛ لأن تركيز المتفاعل لا ينخفض إلى الصفر"]'::jsonb, 'تحليل', 'تحليل منحنى', 'صعب', 'الكتاب ص 81 — التراكيز عند الاتزان ثابتة لا متساوية'),
('mcq', 6, 'تمثل اللوحتان (أ) و(ب) في الشكل الآتي تغير تركيزي متفاعل وناتج مع الزمن في تفاعلين مختلفين. أيّ العبارات الآتية تصف اللوحتين وصفًا صحيحًا؟', null, '[{"src":"qimg/chem22/c3-l1b-complete-vs-eq.svg","alt":"لوحتان لمنحنيين بيانيين، في كل منهما المحور الأفقي الزمن والمحور الرأسي التركيز (mol/L) بلا أرقام. اللوحة (أ): منحنى المتفاعل يبدأ مرتفعًا ويتناقص حتى يصل إلى الصفر ويبقى عليه، ومنحنى الناتج يبدأ من الصفر ويتزايد حتى يثبت عند قيمة مساوية للتركيز الابتدائي للمتفاعل. اللوحة (ب): منحنى المتفاعل يبدأ عند القيمة نفسها ويتناقص حتى يثبت عند نحو ثلث قيمته الابتدائية دون أن يصل إلى الصفر، ومنحنى الناتج يبدأ من الصفر ويتزايد حتى يثبت عند نحو ثلثي تلك القيمة. في اللوحتين تصبح المنحنيات خطوطًا أفقية في النهاية."}]'::jsonb, '["(أ) تفاعل وصل إلى الاتزان، و(ب) تفاعل مكتمل؛ لأن الناتج في (أ) يصل إلى أكبر قيمة ممكنة","كلتاهما تمثل تفاعلًا وصل إلى الاتزان؛ لأن المنحنيات فيهما تصبح أفقية في النهاية","(أ) تفاعل مكتمل، و(ب) تفاعل وصل إلى الاتزان؛ لأن المتفاعل في (ب) لا يُستهلك كاملًا","كلتاهما تمثل تفاعلًا مكتملًا؛ لأن التراكيز فيهما تتوقف عن التغير في النهاية"]'::jsonb, 'تحليل', 'مقارنة منحنيات', 'متوسط', 'الكتاب ص 79 و82 — بقاء المتفاعلات غير مستهلكة عند الاتزان'),
('mcq', 7, 'اعتمادًا على المنحنى الآتي، أيّ المواد متفاعلات وأيها نواتج؟', null, '[{"src":"qimg/chem22/c3-l1b-abc.svg","alt":"منحنى بياني محوره الأفقي الزمن ومحوره الرأسي التركيز (mol/L)، بلا أرقام. فيه ثلاثة منحنيات: المنحنى A يبدأ عند أعلى قيمة ويتناقص ثم يثبت عند قيمة صغيرة لا تساوي صفرًا. المنحنى C يبدأ من الصفر ويتزايد ثم يثبت عند أعلى قيمة بين المنحنيات الثلاثة. المنحنى B يبدأ من الصفر ويتزايد ثم يثبت عند قيمة متوسطة بين A وC. في الجزء الأيمن من الرسم تصبح المنحنيات الثلاثة خطوطًا أفقية متوازية غير متطابقة."}]'::jsonb, '["A متفاعل، وB وC ناتجان","A ناتج، وB وC متفاعلان","A وB متفاعلان، وC ناتج","A وC متفاعلان، وB ناتج"]'::jsonb, 'فهم', 'تفسير منحنى', 'سهل', 'الكتاب ص 117 — اختبار مقنن (س10–12)'),
('essay', 1, 'استعمل المنحنى الآتي للإجابة:
(أ) صف شكل المنحنيات عند حدوث الاتزان.
(ب) فسر لماذا لا يساوي تركيز المادة A صفرًا في نهاية التفاعل.
(ج) صنف نوع هذا التفاعل، وبيّن كيف تدعم بيانات المنحنى استنتاجك.', null, '[{"src":"qimg/chem22/c3-l1b-abc.svg","alt":"منحنى بياني محوره الأفقي الزمن ومحوره الرأسي التركيز (mol/L)، بلا أرقام. فيه ثلاثة منحنيات: المنحنى A يبدأ عند أعلى قيمة ويتناقص ثم يثبت عند قيمة صغيرة لا تساوي صفرًا. المنحنى C يبدأ من الصفر ويتزايد ثم يثبت عند أعلى قيمة بين المنحنيات الثلاثة. المنحنى B يبدأ من الصفر ويتزايد ثم يثبت عند قيمة متوسطة بين A وC. في الجزء الأيمن من الرسم تصبح المنحنيات الثلاثة خطوطًا أفقية متوازية غير متطابقة."}]'::jsonb, null, 'تحليل', 'تفسير منحنى', 'متوسط', 'الكتاب ص 117 — اختبار مقنن (س10–12)'),
('essay', 2, 'يمثل المنحنى الآتي تغير تراكيز N₂ وH₂ وNH₃ مع الزمن للتفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) في وعاء مغلق.
(أ) صف ميل كل منحنى في الطرف الأيسر من الرسم، وكيف يختلف عن ميله في الطرف الأيمن.
(ب) فسر هذا الاختلاف بدلالة سرعتي التفاعلين الأمامي والعكسي.
(ج) احسب التغير في تركيز كل مادة حتى الاتزان، وبيّن علاقة هذه التغيرات بالمعادلة الموزونة.', null, '[{"src":"qimg/chem22/c3-l1b-nh3-conc.svg","alt":"منحنى بياني للتفاعل N₂ + 3H₂ ⇌ 2NH₃ في وعاء مغلق: المحور الأفقي الزمن، والمحور الرأسي التركيز (mol/L) من 0 إلى 3.2. منحنى H₂ يبدأ عند 3.0 mol/L ويتناقص حتى يثبت عند 1.8 mol/L. منحنى N₂ يبدأ عند 1.0 mol/L ويتناقص حتى يثبت عند 0.6 mol/L. منحنى NH₃ يبدأ من الصفر ويتزايد حتى يثبت عند 0.8 mol/L، ويتقاطع مع منحنى N₂ في بداية التفاعل. خط رأسي متقطع عند الزمن t₁ تكون بعده المنحنيات الثلاثة خطوطًا أفقية."}]'::jsonb, null, 'تحليل', 'تحليل منحنى وحساب', 'متوسط', 'الكتاب ص 79 — الشكل 3-2 (تراكيز المتفاعلات والنواتج مع الزمن)'),
('essay', 3, 'يبين المنحنى الآتي تغير تركيزي متفاعل وناتج مع الزمن في وعاء مغلق. قال طالب: «وصل التفاعل إلى الاتزان عند الزمن t₁، لأن تركيز المتفاعل صار مساويًا لتركيز الناتج، والاتزان يعني تساوي التراكيز».
(أ) قوّم رأي الطالب.
(ب) حدد الزمن الذي يكون فيه النظام في حالة اتزان، مع الدليل من المنحنى.
(ج) قارن بين تركيزي المتفاعل والناتج عند الاتزان في هذا المنحنى.', null, '[{"src":"qimg/chem22/c3-l1b-crossing.svg","alt":"منحنى بياني محوره الأفقي الزمن ومحوره الرأسي التركيز (mol/L)، بلا أرقام. منحنى المتفاعل (أزرق) يبدأ مرتفعًا ويتناقص، ومنحنى الناتج (أحمر) يبدأ من الصفر ويتزايد. يتقاطع المنحنيان عند الزمن t₁ المعلَّم بخط رأسي متقطع، ويستمران بعده في التغير: الناتج يواصل الزيادة والمتفاعل يواصل النقصان. عند الزمن t₂ المعلَّم بخط رأسي متقطع آخر يكون المنحنيان قد صارا خطين أفقيين، والناتج أعلى من المتفاعل، ولا يصل المتفاعل إلى الصفر."}]'::jsonb, null, 'تقويم', 'تقويم رأي', 'صعب', 'الكتاب ص 81 — التراكيز عند الاتزان ثابتة لا متساوية')
