from (values
('mcq', 1, 1, 'عند الاتزان تثبت تراكيز جميع المواد فلا تتغير مع الزمن، وهذا يظهر في المنحنى على شكل خطوط أفقية لكل المواد في الجزء الأيمن من الرسم.', '["التقاطع يعني تساوي تركيزين في لحظة عابرة، والتراكيز بعده تستمر في التغير فلا يدل على الاتزان.","","الخطوط الأفقية الثلاثة عند مستويات مختلفة؛ فالتراكيز عند الاتزان ثابتة لكنها غير متساوية.","منحنى A يثبت عند قيمة لا تساوي صفرًا؛ ولو وصل إلى الصفر لكان التفاعل مكتملًا لا متزنًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-06T22:20:31.201Z"}'::jsonb),
('mcq', 2, 3, 'بعد t₁ تصبح المنحنيات الثلاثة أفقية عند قيم مختلفة: H₂ عند 1.8 mol/L، وNH₃ عند 0.8 mol/L، وN₂ عند 0.6 mol/L؛ فالتراكيز ثابتة لكنها غير متساوية.', '["المنحنيات الثلاثة تستقر عند مستويات مختلفة (1.8 و0.8 و0.6 mol/L)، فالتراكيز ليست متساوية.","منحنيا N₂ وH₂ يثبتان عند 0.6 و1.8 mol/L ولا يصلان إلى الصفر؛ فالمتفاعلات لا تُستهلك كاملة.","بعد t₁ تكون المنحنيات أفقية، أي أن التراكيز توقفت عن التغير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-06T22:20:31.201Z"}'::jsonb),
('mcq', 3, 0, 'النقص في [H₂] = 3.0 − 1.8 = 1.2 mol/L، والزيادة في [NH₃] = 0.8 mol/L؛ والنسبة 1.2 : 0.8 = 3 : 2، وهي نسبة معاملي H₂ (3) وNH₃ (2) في المعادلة الموزونة.', '["","هذه النسبة مقلوبة: 1.2 : 0.8 تساوي 3 : 2 لا 2 : 3؛ فالنقص في H₂ أكبر من الزيادة في NH₃.","النقص (1.2 mol/L) لا يساوي الزيادة (0.8 mol/L)؛ فالتغيرات تتبع معاملات المعادلة لا تتساوى.","3 : 1 نسبة H₂ إلى N₂، والسؤال عن نسبة التغير في H₂ إلى التغير في NH₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.202Z"}'::jsonb),
('mcq', 4, 1, 'NO₂ ناتج لم يكن موجودًا في البداية فيبدأ منحناه من الصفر، ومن المعادلة يتكون 2 mol من NO₂ لكل 1 mol يتفكك من N₂O₄؛ و(ص) يزداد من 0 إلى 0.0630 mol/L بينما (س) يتناقص من 0.0500 إلى 0.0185 mol/L أي بمقدار 0.0315 mol/L، والزيادة مثلا النقص. إذن (ص) هو NO₂.', '["المنحنى الذي يبدأ عند 0.0500 mol/L ويتناقص هو المتفاعل N₂O₄ لا الناتج NO₂.","","صغر التركيز عند الاتزان لا يحدد هوية المادة، و(س) يبدأ بالتركيز الابتدائي لـ N₂O₄ فهو المتفاعل.","(ص) هو NO₂ فعلًا، لكن تركيزه عند الاتزان (0.0630 mol/L) لا يساوي تركيز (س) (0.0185 mol/L)؛ التراكيز تتساوى لحظيًّا عند التقاطع فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-06T22:20:31.202Z"}'::jsonb),
('mcq', 5, 2, 'علامة الاتزان ثبات التراكيز لا تساويها؛ فعند t₁ يتساوى التركيزان لحظيًّا ثم يستمران في التغير، أما عند t₂ فيصبح المنحنيان أفقيين أي أن التراكيز ثابتة، فالاتزان يتحقق عند t₂.', '["تساوي التركيزين عند t₁ لحظة عابرة، فبعدها يستمر الناتج في الزيادة والمتفاعل في النقصان.","تقاطع منحنيي التركيز لا يعني تساوي السرعتين؛ فالتراكيز تستمر في التغير بعد t₁ مما يدل على أن السرعة الأمامية ما زالت أكبر.","","عدم وصول المتفاعل إلى الصفر هو سمة التفاعل الذي يصل إلى الاتزان، لا دليل على عدم وصوله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-06T22:20:31.202Z"}'::jsonb),
('mcq', 6, 2, 'في الاتزان تبقى المتفاعلات والنواتج موجودة معًا بتراكيز ثابتة؛ وفي (ب) يثبت تركيز المتفاعل عند قيمة لا تساوي صفرًا مع ثبات تركيز الناتج، فالمتفاعل لم يُستهلك كاملًا والتفاعل وصل إلى الاتزان. أما في (أ) فيصل المتفاعل إلى الصفر، أي أنه استُهلك كاملًا فالتفاعل مكتمل.', '["الوصف معكوس: في (أ) يصل المتفاعل إلى الصفر أي يُستهلك كاملًا فالتفاعل مكتمل، أما في (ب) فيبقى المتفاعل مع الناتج بتركيزين ثابتين.","الثبات وحده لا يكفي؛ ففي (أ) يثبت المتفاعل عند الصفر، أي أنه استُهلك كاملًا فالتفاعل مكتمل لا متزن.","","في (ب) يثبت المتفاعل عند قيمة لا تساوي صفرًا مع وجود الناتج، فهي تمثل اتزانًا لا تفاعلًا مكتملًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-06T22:20:31.203Z"}'::jsonb),
('mcq', 7, 0, 'المادة التي يبدأ منحناها مرتفعًا ثم يتناقص تُستهلك فهي متفاعل، وهي A. أما B وC فيبدأ كل منهما من الصفر ثم يتزايد، فهما ناتجان يتكونان أثناء التفاعل.', '["","التصنيف معكوس: A يتناقص فهو يُستهلك (متفاعل)، وB وC يبدآن من الصفر ويتزايدان (ناتجان).","B يبدأ من الصفر ويتزايد فهو ناتج، وانخفاض تركيزه عند الاتزان عن C لا يجعله متفاعلًا.","C يبدأ من الصفر ويتزايد حتى أعلى قيمة فهو ناتج لا متفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-06T22:20:31.203Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) عند الاتزان تصبح المنحنيات الثلاثة خطوطًا أفقية متوازية عند مستويات مختلفة؛ أي أن تراكيز A وB وC ثابتة لا تتغير مع الزمن لكنها غير متساوية.
(ب) لأن التفاعل عكسي؛ فحين تتكون B وC يبدأ التفاعل العكسي فيعيد تكوين A، وعندما تتساوى سرعتا التفاعلين الأمامي والعكسي يتوقف التغير الصافي في التراكيز قبل أن تُستهلك A كاملة.
(ج) تفاعل عكسي وصل إلى حالة الاتزان الكيميائي؛ والدليل: تركيز المتفاعل A يتناقص ثم يثبت عند قيمة غير صفرية، وتركيزا الناتجين B وC يتزايدان من الصفر ثم يثبتان، فتبقى المتفاعلات والنواتج معًا بتراكيز ثابتة.', '["المنحنيات تصبح أفقية: تراكيز ثابتة","التراكيز الثابتة غير متساوية","التفاعل العكسي يعيد تكوين A","تساوي السرعتين يوقف التغير قبل استهلاك A","التصنيف: تفاعل عكسي في حالة اتزان","الدليل: بقاء A مع B وC بتراكيز ثابتة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف شكل المنحنيات عند الاتزان","marks":1},{"element":"بيان أن التراكيز ثابتة غير متساوية","marks":1},{"element":"تفسير بقاء A بالتفاعل العكسي وتساوي السرعتين","marks":2},{"element":"تصنيف التفاعل","marks":1},{"element":"دعم التصنيف ببيانات المنحنى","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة للأجزاء الثلاثة مع أدلة من المنحنى"},{"level":"4–5 درجات","description":"أجزاء صحيحة مع نقص في التفسير أو في الدليل"},{"level":"1–3 درجات","description":"وصف صحيح للمنحنى فقط أو تصنيف بلا تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التراكيز تتساوى عند الاتزان","تفسير بقاء A بنقص المادة B أو C","تصنيف التفاعل بأنه مكتمل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-06T22:20:31.203Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) في الطرف الأيسر: منحنيا H₂ وN₂ يتجهان إلى أسفل بميل كبير (تركيزهما يتناقص بسرعة)، ومنحنى NH₃ يتجه إلى أعلى بميل كبير (تركيزه يزداد بسرعة). في الطرف الأيمن: ميل المنحنيات الثلاثة صفر (خطوط أفقية).
(ب) في البداية تكون سرعة التفاعل الأمامي كبيرة لارتفاع تراكيز N₂ وH₂، وسرعة التفاعل العكسي صغيرة جدًّا لقلة NH₃، فيحدث تغير صافٍ سريع. ومع الزمن تقل السرعة الأمامية وتزداد العكسية حتى تتساويا، فلا يبقى تغير صافٍ في التراكيز ويصبح الميل صفرًا.
(ج) Δ[N₂] = 0.6 − 1.0 = −0.4 mol/L، وΔ[H₂] = 1.8 − 3.0 = −1.2 mol/L، وΔ[NH₃] = 0.8 − 0 = +0.8 mol/L. والنسبة 0.4 : 1.2 : 0.8 = 1 : 3 : 2، وهي نسبة المعاملات في المعادلة الموزونة.', '["الميل كبير في البداية (تناقص N₂ وH₂ وتزايد NH₃)","الميل صفر عند الاتزان","السرعة الأمامية أكبر في البداية ثم تتساوى مع العكسية","Δ[N₂] = −0.4، Δ[H₂] = −1.2، Δ[NH₃] = +0.8 mol/L","النسبة 1 : 3 : 2 تساوي المعاملات"]'::jsonb, '["Δ[N₂] = 0.6 − 1.0 = −0.4 mol/L","Δ[H₂] = 1.8 − 3.0 = −1.2 mol/L","Δ[NH₃] = 0.8 − 0 = +0.8 mol/L","0.4 : 1.2 : 0.8 = 1 : 3 : 2"]'::jsonb, '[{"element":"وصف الميل في الطرفين","marks":2},{"element":"التفسير بسرعتي التفاعلين","marks":2},{"element":"حساب التغيرات الثلاثة","marks":1},{"element":"ربط النسبة بالمعاملات","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"وصف وتفسير وحساب صحيح كامل"},{"level":"4–5 درجات","description":"وصف وتفسير صحيحان مع خطأ في الحساب أو الربط"},{"level":"1–3 درجات","description":"وصف للميل فقط أو حساب فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الميل في الطرف الأيمن سالب صغير","تفسير ثبات التراكيز بتوقف التفاعل","حساب التغير في H₂ مساويًا للتغير في NH₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-06T22:20:31.204Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) رأي الطالب خاطئ؛ فالاتزان لا يعني تساوي التراكيز بل ثباتها، وتساويها حالة نادرة. وعند t₁ يتساوى التركيزان لحظيًّا فقط، ثم يستمر تركيز الناتج في الزيادة وتركيز المتفاعل في النقصان، فالسرعة الأمامية ما زالت أكبر من العكسية.
(ب) يكون النظام في حالة اتزان عند t₂ وما بعده؛ لأن المنحنيين يصبحان خطين أفقيين، أي أن التراكيز ثابتة لا تتغير مع الزمن.
(ج) عند الاتزان يكون تركيز الناتج أكبر من تركيز المتفاعل، والتركيزان ثابتان لكنهما غير متساويين، ولا يصل تركيز المتفاعل إلى الصفر.', '["الحكم بخطأ الطالب","الاتزان ثبات التراكيز لا تساويها","التساوي عند t₁ لحظي والتغير مستمر بعده","الاتزان عند t₂ لأن المنحنيين أفقيان","عند الاتزان: الناتج أكبر من المتفاعل، والتركيزان ثابتان غير متساويين"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على رأي الطالب مع التعليل","marks":2},{"element":"تحديد t₂ مع الدليل","marks":1},{"element":"المقارنة بين التركيزين عند الاتزان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم معلل وتحديد صحيح للزمن ومقارنة صحيحة"},{"level":"2–3 درجات","description":"تحديد صحيح للزمن مع تقويم ناقص التعليل"},{"level":"1 درجة","description":"تحديد الزمن الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد الطالب لأن المنحنيين يتقاطعان","اختيار t₁ زمنًا للاتزان","القول إن التركيزين يتساويان عند t₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-06T22:20:31.204Z"}'::jsonb)
