insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L1-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ينص قانون الاتزان الكيميائي على أنه:', null, null, '["عند الاتزان تصبح تراكيز المتفاعلات مساوية لتراكيز النواتج عند أي درجة حرارة","عند درجة حرارة معينة يمكن للتفاعل أن يصل إلى حالة تصبح فيها نسب تراكيز المتفاعلات والنواتج ثابتة","عند درجة حرارة معينة يتوقف التفاعلان الأمامي والعكسي فتثبت كميات المتفاعلات والنواتج","عند أي درجة حرارة تبقى نسب تراكيز المتفاعلات والنواتج ثابتة مهما تغير الضغط"]'::jsonb, 'تذكر', 'نص قانون', 'سهل', 'الكتاب ص 83 — قانون الاتزان الكيميائي'),
('mcq', 2, 'من الكيميائيان اللذان قدما قانون الاتزان الكيميائي، وفي أي عام؟', null, null, '["هنري لويس لوتشاتلييه، عام 1888م","لوتشاتلييه وجولدبرج، عام 1864م","جولدبرج وويج، عام 1864م","جولدبرج وويج، عام 1888م"]'::jsonb, 'تذكر', 'تاريخ علمي', 'سهل', 'الكتاب ص 83 — قانون الاتزان الكيميائي'),
('mcq', 3, 'إذا طُبق قانون الاتزان الكيميائي على التفاعل العام aA + bB ⇌ cC + dD، فأيّ مما يأتي يمثل تعبير ثابت الاتزان؟', null, null, '["Keq = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ","Keq = [A]ᵃ[B]ᵇ / [C]ᶜ[D]ᵈ","Keq = [C][D] / [A][B]","Keq = c[C] × d[D] / a[A] × b[B]"]'::jsonb, 'تذكر', 'صيغة قانون', 'متوسط', 'الكتاب ص 83 — قانون الاتزان الكيميائي'),
('mcq', 4, 'وفق قانون الاتزان الكيميائي، ما الشرط اللازم لكي تبقى نسبة تراكيز النواتج إلى تراكيز المتفاعلات ثابتة لتفاعل معين؟', null, null, '["أن تكون التراكيز الابتدائية للمتفاعلات ثابتة","أن يبقى ضغط النظام ثابتًا طوال التفاعل","أن يُضاف إلى النظام عامل محفز مناسب","أن تبقى درجة حرارة النظام ثابتة"]'::jsonb, 'فهم', 'شروط قانون', 'متوسط', 'الكتاب ص 83 — قانون الاتزان الكيميائي'),
('mcq', 5, 'وفق قانون الاتزان الكيميائي، أيّ الكميات الآتية تكون لها القيمة نفسها في جميع خلائط الاتزان الممكنة للتفاعل H₂(g) + I₂(g) ⇌ 2HI(g) عند 731 K؟', null, null, '["تركيز HI وحده عند الاتزان","مجموع تراكيز H₂ وI₂ وHI عند الاتزان","النسبة [HI]²/[H₂][I₂] عند الاتزان","الفرق بين [HI] و[H₂] عند الاتزان"]'::jsonb, 'فهم', 'دلالة رموز', 'صعب', 'الكتاب ص 83 و84 — قانون الاتزان الكيميائي'),
('mcq', 6, 'ما المقصود بثابت الاتزان Keq؟', null, null, '["الفرق بين سرعتي التفاعلين الأمامي والعكسي عند وصول النظام إلى الاتزان","نسبة حاصل ضرب تراكيز المتفاعلات إلى حاصل ضرب تراكيز النواتج عند بداية التفاعل","نسبة مجموع تراكيز النواتج إلى مجموع تراكيز المتفاعلات عند الاتزان","نسبة حاصل ضرب تراكيز النواتج إلى حاصل ضرب تراكيز المتفاعلات عند الاتزان، كلٌّ مرفوع لأس معامله"]'::jsonb, 'تذكر', 'تعريف', 'متوسط', 'الكتاب ص 83 — قانون الاتزان الكيميائي'),
('mcq', 7, 'كتب طالب: «قانون الاتزان الكيميائي: عند الاتزان تتساوى تراكيز المتفاعلات والنواتج عند أي درجة حرارة». أيّ مما يأتي يصحح خطأي عبارته؟', null, null, '["القانون يتحدث عن ثبات نسبة التراكيز لا تساويها، وثباتها مشروط بدرجة حرارة معينة","القانون يتحدث عن تساوي سرعتي التفاعلين لا التراكيز، ويصح عند أي درجة حرارة","القانون يخص تراكيز النواتج وحدها، ويشترط ثبات الضغط بدل درجة الحرارة","القانون يشترط اكتمال التفاعل، وتساوي التراكيز يحدث عند الضغط الجوي فقط"]'::jsonb, 'فهم', 'تصحيح خطأ', 'صعب', 'الكتاب ص 83 — قانون الاتزان الكيميائي'),
('essay', 1, '(أ) اذكر نص قانون الاتزان الكيميائي، ومن قدمه، ومتى.
(ب) اكتب تعبير ثابت الاتزان للتفاعل العام aA + bB ⇌ cC + dD، موضحًا ما يمثله كل من [A] و[B] و[C] و[D] والأسس a وb وc وd.', null, null, null, 'تذكر', 'نص قانون وصيغة', 'سهل', 'الكتاب ص 83 — قانون الاتزان الكيميائي'),
('essay', 2, 'يبين الجدول الآتي قيم ثابت الاتزان لتفاعل واحد عند ثلاث درجات حرارة مختلفة.
(أ) وضح لماذا يُقيَّد قانون الاتزان الكيميائي بعبارة «عند درجة حرارة معينة»، مستشهدًا بالجدول.
(ب) عند أي درجة حرارة يكون تركيز النواتج عند الاتزان أكبر نسبيًّا؟ فسر إجابتك.', '{"headers":["درجة الحرارة","263 K","273 K","373 K"],"rows":[["Keq","0.0250","0.500","4.500"]]}'::jsonb, null, null, 'فهم', 'تفسير بيانات', 'متوسط', 'الكتاب ص 83 و90 — قانون الاتزان، والتقويم 3-1 (س12)'),
('essay', 3, 'يتكون ثاني أكسيد النيتروجين (أحد مكونات الضباب الدخاني) وفق الاتزان: 2NO(g) + O₂(g) ⇌ 2NO₂(g)، وتعبير ثابت الاتزان له: Keq = [NO₂]² / [NO]²[O₂].
(أ) وضح كيف يعبّر هذا التعبير عن قانون الاتزان الكيميائي.
(ب) بيّن ما يعنيه وصف هذه النسبة بأنها «ثابتة»، وما الشرط اللازم لذلك.
(ج) قال طالب: «بما أن النسبة ثابتة عند الاتزان فإن تراكيز NO وO₂ وNO₂ تتساوى». قوّم قوله.', null, null, null, 'فهم', 'تطبيق قانون', 'صعب', 'الكتاب ص 76 و83 — 2NO + O₂ ⇌ 2NO₂ وقانون الاتزان')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L1-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'قانون الاتزان الكيميائي: عند درجة حرارة معينة يمكن للتفاعل الكيميائي أن يصل إلى حالة تصبح فيها نسب تراكيز المتفاعلات والنواتج ثابتة.', '["القانون يتحدث عن ثبات نسب التراكيز لا عن تساوي التراكيز، ويشترط درجة حرارة معينة.","","التفاعلان لا يتوقفان عند الاتزان؛ والقانون يتحدث عن ثبات نسب التراكيز.","ثبات النسبة مقيد بدرجة حرارة معينة، فتغير درجة الحرارة يغير قيمتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.205Z"}'::jsonb),
('mcq', 2, 2, 'قدم الكيميائيان النرويجيان كاتو ماكسمليان جولدبرج وبيتر ويج قانون الاتزان الكيميائي عام 1864م.', '["لوتشاتلييه صاحب المبدأ الخاص بإزاحة الاتزان عند تعرضه لجهد (1888م)، لا قانون الاتزان.","لوتشاتلييه لم يشارك في وضع قانون الاتزان، وصاحبا القانون جولدبرج وويج.","","العالمان صحيحان لكن العام خاطئ؛ فقد قُدم القانون عام 1864م، و1888م عام مبدأ لوتشاتلييه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.205Z"}'::jsonb),
('mcq', 3, 0, 'تعبير ثابت الاتزان نسبة التراكيز المولارية للنواتج إلى التراكيز المولارية للمتفاعلات، ويُرفع كل تركيز إلى أس يساوي معامله في المعادلة الموزونة: Keq = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ.', '["","هذا مقلوب التعبير؛ النواتج توضع في البسط والمتفاعلات في المقام.","أُهملت المعاملات؛ يجب أن يُرفع كل تركيز إلى أس يساوي معامله.","المعاملات لا تُضرب في التراكيز، بل تُكتب أسسًا لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-06T22:20:31.205Z"}'::jsonb),
('mcq', 4, 3, 'ينص القانون على ثبات النسبة «عند درجة حرارة معينة»؛ فقيمة ثابت الاتزان لتفاعل معين لا تتغير إلا بتغير درجة الحرارة.', '["تختلف التراكيز الابتدائية من تجربة إلى أخرى وتبقى النسبة ثابتة عند الاتزان ما دامت درجة الحرارة ثابتة.","القانون لا يشترط ثبات الضغط؛ الشرط هو درجة حرارة معينة.","العامل المحفز يسرع الوصول إلى الاتزان ولا يؤثر في قيمة النسبة عنده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.205Z"}'::jsonb),
('mcq', 5, 2, 'ينص قانون الاتزان الكيميائي على أنه عند درجة حرارة معينة تصبح نسب تراكيز المتفاعلات والنواتج ثابتة؛ فتراكيز المواد نفسها تختلف من خليط اتزان إلى آخر، لكن النسبة [HI]²/[H₂][I₂] لها القيمة نفسها في جميعها عند 731 K.', '["تركيز HI يختلف من خليط اتزان إلى آخر بحسب التراكيز الابتدائية؛ فالقانون ينص على ثبات نسبة التراكيز لا تركيز مادة بعينها.","القانون يتحدث عن نسبة تراكيز النواتج إلى تراكيز المتفاعلات لا عن مجموعها، والمجموع يختلف من خليط اتزان إلى آخر.","","الفرق بين تركيزين ليس الكمية التي ينص القانون على ثباتها، وهو يختلف من خليط اتزان إلى آخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-06T22:20:31.206Z"}'::jsonb),
('mcq', 6, 3, 'ثابت الاتزان Keq هو القيمة العددية لنسبة حاصل ضرب تراكيز النواتج على حاصل ضرب تراكيز المتفاعلات، ويُرفع كل تركيز إلى أس مساوٍ لمعامله في المعادلة الموزونة، وقيمته ثابتة عند درجة حرارة معينة فقط.', '["سرعتا التفاعلين متساويتان عند الاتزان فالفرق بينهما صفر؛ وKeq نسبة تراكيز لا فرق سرعات.","Keq يُحسب من تراكيز الاتزان لا التراكيز الابتدائية، والنواتج في البسط لا في المقام.","التراكيز تُضرب (حاصل ضرب) ولا تُجمع، ويُرفع كل منها إلى أس معامله.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.206Z"}'::jsonb),
('mcq', 7, 0, 'خطأ الطالب الأول أنه جعل القانون عن تساوي التراكيز، والقانون عن ثبات نسب تراكيز المتفاعلات والنواتج؛ وخطؤه الثاني أنه أطلقه «عند أي درجة حرارة»، والقانون مقيد بدرجة حرارة معينة.', '["","تساوي السرعتين تعريف حالة الاتزان لا نص القانون، وثبات النسبة لا يصح عند أي درجة حرارة.","القانون يربط تراكيز النواتج والمتفاعلات معًا في نسبة، وشرطه درجة الحرارة لا الضغط.","التفاعل الذي يصل إلى الاتزان لا يكتمل، والقانون لا يتحدث عن تساوي التراكيز أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.206Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) قانون الاتزان الكيميائي: عند درجة حرارة معينة يمكن للتفاعل الكيميائي أن يصل إلى حالة تصبح فيها نسب تراكيز المتفاعلات والنواتج ثابتة. قدمه الكيميائيان النرويجيان جولدبرج وويج عام 1864م.
(ب) Keq = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ؛ حيث [A] و[B] التراكيز المولارية للمتفاعلات عند الاتزان، و[C] و[D] التراكيز المولارية للنواتج عند الاتزان، والأسس a وb وc وd معاملات المواد في المعادلة الموزونة.', '["نص القانون مع قيد درجة الحرارة المعينة","جولدبرج وويج عام 1864م","Keq = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ","الأقواس تراكيز مولارية (mol/L) عند الاتزان","الأسس معاملات المعادلة الموزونة"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون كاملًا","marks":2},{"element":"العالمان والعام","marks":1},{"element":"تعبير ثابت الاتزان","marks":1},{"element":"دلالة الأقواس والأسس","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"نص دقيق وأسماء وتاريخ صحيحان وتعبير صحيح مع دلالة الرموز"},{"level":"3–4 درجات","description":"نص صحيح مع نقص في التاريخ أو دلالة الرموز"},{"level":"1–2 درجة","description":"تعبير صحيح فقط أو نص ناقص"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال قيد (عند درجة حرارة معينة)","نسبة القانون إلى لوتشاتلييه","قلب التعبير بوضع المتفاعلات في البسط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-06T22:20:31.207Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) لأن نسبة تراكيز النواتج إلى المتفاعلات تكون ثابتة ما دامت درجة الحرارة ثابتة فقط؛ فإذا تغيرت درجة الحرارة تغيرت قيمة هذه النسبة. ويظهر ذلك في الجدول: Keq للتفاعل نفسه 0.0250 عند 263 K، و0.500 عند 273 K، و4.500 عند 373 K.
(ب) عند 373 K؛ لأن Keq عندها أكبر قيمة (4.500 > 1)، أي أن بسط التعبير (تراكيز النواتج) كبير نسبيًّا مقارنة بالمقام، فالنواتج مفضلة عند الاتزان.', '["ثبات النسبة مشروط بثبات درجة الحرارة","الاستشهاد بتغير Keq من 0.0250 إلى 0.500 إلى 4.500","373 K","أكبر Keq يعني أكبر نسبة للنواتج"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير قيد درجة الحرارة","marks":1},{"element":"الاستشهاد ببيانات الجدول","marks":1},{"element":"تحديد 373 K","marks":1},{"element":"التفسير بقيمة Keq","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح مع استشهاد وتحديد وتعليل صحيحين"},{"level":"2–3 درجات","description":"تحديد صحيح مع نقص في التفسير أو الاستشهاد"},{"level":"1 درجة","description":"تحديد درجة الحرارة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن Keq يتغير بتغير التراكيز الابتدائية","اختيار 263 K لأن الحرارة الأقل تعني نواتج أكثر دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.207Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) ينص قانون الاتزان الكيميائي على أنه عند درجة حرارة معينة يمكن للتفاعل أن يصل إلى حالة تصبح فيها نسب تراكيز المتفاعلات والنواتج ثابتة؛ وهذا التعبير هو تلك النسبة لهذا التفاعل: تراكيز النواتج (NO₂) في البسط وتراكيز المتفاعلات (NO وO₂) في المقام، كلٌّ مرفوع لأس معامله.
(ب) يعني أنه مهما كانت التراكيز الابتدائية لـ NO وO₂ وNO₂، فإن التعويض بتراكيزها عند الاتزان في هذا التعبير يعطي القيمة العددية نفسها، بشرط أن تكون درجة الحرارة هي نفسها.
(ج) قوله خاطئ؛ فالقانون ينص على ثبات نسبة التراكيز لا على تساوي التراكيز، فقد تكون تراكيز المواد الثلاث عند الاتزان مختلفة وتبقى نسبتها في التعبير ثابتة.', '["نص القانون: ثبات نسب التراكيز عند درجة حرارة معينة","التعبير هو هذه النسبة: النواتج في البسط والمتفاعلات في المقام","النسبة نفسها عند الاتزان مهما كانت التراكيز الابتدائية","الشرط: درجة حرارة معينة ثابتة","الثابت نسبة التراكيز لا تساويها"]'::jsonb, '[]'::jsonb, '[{"element":"ربط التعبير بنص القانون","marks":2},{"element":"معنى ثبات النسبة","marks":1},{"element":"شرط درجة الحرارة","marks":1},{"element":"تقويم قول الطالب مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ربط صحيح بالقانون وتفسير كامل لمعنى الثبات وشرطه وتقويم معلل"},{"level":"3–4 درجات","description":"ربط صحيح مع نقص في أحد التفسيرين أو في التقويم"},{"level":"1–2 درجة","description":"ذكر نص القانون أو الشرط فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النسبة ثابتة عند أي درجة حرارة","الخلط بين ثبات نسبة التراكيز وتساوي التراكيز","القول إن النسبة تختلف باختلاف التراكيز الابتدائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.207Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
