from (values
('mcq', 1, 'أُجريت ثلاث تجارب للتفاعل H₂(g) + I₂(g) ⇌ 2HI(g) عند 731 K، بدأت كل منها بتراكيز ابتدائية مختلفة. ماذا يُتوقع لقيمة Keq المحسوبة من تراكيز الاتزان في التجارب الثلاث؟', null, null, '["تكون أكبر في التجربة ذات التراكيز الابتدائية الأكبر","تختلف من تجربة إلى أخرى لأن تراكيز الاتزان مختلفة","تكون متساوية في التجارب الثلاث","تساوي صفرًا في التجربة التي لا تحتوي HI في بدايتها"]'::jsonb, 'فهم', 'تنبؤ', 'سهل', 'الكتاب ص 88 — ثوابت الاتزان والجدول 3-1'),
