from (values
('mcq', 1, 2, 'قيمة Keq لتفاعل معين ثابتة عند درجة حرارة معينة بغض النظر عن التراكيز الابتدائية؛ والتجارب الثلاث عند 731 K نفسها، فتكون Keq متساوية فيها (49.70).', '["التراكيز الابتدائية تغير موضع الاتزان لا قيمة Keq.","تراكيز الاتزان تختلف فعلًا، لكن نسبتها في تعبير Keq تبقى القيمة نفسها عند درجة الحرارة نفسها.","","Keq يُحسب من تراكيز الاتزان، وعند الاتزان يكون HI قد تكوّن فلا تكون القيمة صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.208Z"}'::jsonb),
('mcq', 2, 0, 'تراكيز الاتزان في المحاولات الثلاث مختلفة (مثلًا [HI] = 1.8682 و3.8950 و1.7515 mol/L)، أي أن لكل محاولة موضع اتزان مختلفًا، ومع ذلك تعطي جميعها Keq نفسها (49.70)؛ فقيمة Keq لا تعتمد على التراكيز الابتدائية عند درجة الحرارة نفسها.', '["","تراكيز الاتزان مختلفة بوضوح بين المحاولات؛ الثابت هو نسبتها في تعبير Keq لا قيمها.","[HI] عند الاتزان في المحاولة 2 أكبر منه في 1 و3 وقيمة Keq واحدة في الثلاث.","التراكيز الابتدائية مختلفة في المحاولات الثلاث وKeq واحدة، فهي لا تعتمد عليها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-06T22:20:31.209Z"}'::jsonb),
('mcq', 3, 1, 'Keq = [HI]² / [H₂][I₂] = (3.8950)² / (0.5525 × 0.5525) = 15.171 / 0.30526 = 49.70، وهي القيمة نفسها في المحاولة 1 رغم اختلاف التراكيز الابتدائية.', '["هذه قيمة [HI]/[H₂] = 3.8950/0.5525؛ نُسي تربيع [HI] وضرب [H₂] في [I₂].","","هذه مقلوب Keq؛ وُضعت المتفاعلات في البسط والنواتج في المقام.","هذه 2[HI]/[H₂]؛ ضُرب المعامل في التركيز بدل أن يُرفع التركيز إلى أس المعامل، وأُهمل [I₂]."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-06T22:20:31.209Z"}'::jsonb),
('mcq', 4, 3, 'Keq = [AB]²/[A₂][B₂]. الحاوية (1): (0.40)²/(0.20 × 0.20) = 4.0. الحاوية (2): (0.40)²/(0.10 × 0.40) = 4.0 مساوية لـ Keq فهي في حالة اتزان رغم اختلاف تركيبها. الحاوية (3): (0.20)²/(0.30 × 0.30) = 0.44 لا تساوي 4.0 فهي ليست في حالة اتزان. إذن الحاوية (2) فقط.', '["نسبة التراكيز في (3) تساوي 0.44 لا 4.0؛ وتساوي عدد جزيئات A₂ وB₂ فيها لا يجعلها متزنة.","(3) لا تحقق قيمة Keq (0.44 ≠ 4.0)، فليست في حالة اتزان.","اختلاف تركيب الحاويتين عن (1) لا يمنع الاتزان؛ فلكل نظام مواضع اتزان كثيرة، و(2) تعطي القيمة 4.0 نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-06T22:20:31.210Z"}'::jsonb),
('mcq', 5, 1, 'موضع الاتزان هو مجموعة تراكيز الاتزان، وهي تعتمد على التراكيز الابتدائية؛ فيمكن الوصول إلى عدد غير محدود من هذه المجموعات، لكن التعويض بأي منها في تعبير Keq يعطي القيمة نفسها عند درجة الحرارة نفسها.', '["Keq للتفاعل الواحد قيمة واحدة عند درجة حرارة معينة؛ الذي يتعدد هو تراكيز الاتزان.","","كل محاولة تصل إلى موضع اتزان تثبت فيه التراكيز؛ تعدد المواضع لا يعني عدم الوصول إليها.","بعد الوصول إلى الاتزان تثبت التراكيز؛ والتعدد يكون بين محاولات بتراكيز ابتدائية مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-06T22:20:31.210Z"}'::jsonb),
('mcq', 6, 2, 'قيمة Keq لا تتغير بتغير التراكيز الابتدائية عند 731 K، لذا: [HI]² = Keq × [H₂][I₂] = 49.70 × 0.100 × 0.100 = 0.4970، ومنها [HI] = √0.4970 = 0.705 mol/L.', '["هذه قيمة [HI]² لا [HI]؛ نُسي أخذ الجذر التربيعي.","هذه من قلب العلاقة: [HI]² = [H₂][I₂]/Keq، أي وضع المتفاعلات في البسط.","","هذه من ضرب Keq في مجموع التركيزين (0.100 + 0.100) بدل حاصل ضربهما ثم دون جذر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.210Z"}'::jsonb),
('mcq', 7, 0, 'قيمة Keq لتفاعل معين ثابتة عند درجة حرارة معينة فقط (49.70 عند 731 K)، فلا تتغير إلا بإجراء التفاعل عند درجة حرارة أخرى؛ أما تغيير التراكيز الابتدائية أو المادة التي يبدأ بها التفاعل فيغير موضع الاتزان (تراكيز الاتزان) دون أن يغير Keq، وترك الخليط بعد الاتزان لا يغير التراكيز أصلًا.', '["","تغيير التركيز الابتدائي يغير تراكيز الاتزان فقط، وتبقى Keq = 49.70 عند 731 K.","في المحاولة التي بدأت بـ HI وحده كانت Keq أيضًا 49.70؛ فالمادة الابتدائية لا تغير Keq.","بعد الوصول إلى الاتزان تبقى التراكيز ثابتة مع الزمن، فلا تتغير قيمة Keq."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.211Z"}'::jsonb),
('essay', 1, null::int, null, null, 'إذا أُجري التفاعل نفسه عند درجة الحرارة نفسها عدة مرات بتراكيز ابتدائية مختلفة، فإن كل محاولة تصل إلى موضع اتزان مختلف (تراكيز اتزان مختلفة)، لكن التعويض بتراكيز الاتزان في تعبير ثابت الاتزان يعطي القيمة نفسها في كل مرة؛ ولذلك للنظام عدد غير محدود من مواضع الاتزان وقيمة واحدة لـ Keq. والعامل الوحيد الذي يغير قيمة Keq هو درجة الحرارة.', '["تراكيز ابتدائية مختلفة تؤدي إلى مواضع اتزان مختلفة","التعويض في تعبير Keq يعطي القيمة نفسها","العامل الوحيد: درجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"بيان اختلاف مواضع الاتزان بحسب التراكيز الابتدائية","marks":1},{"element":"ثبات Keq عند التعويض بتراكيز الاتزان","marks":1},{"element":"ذكر درجة الحرارة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"توضيح كامل وذكر درجة الحرارة"},{"level":"2 درجتان","description":"توضيح جزئي مع ذكر درجة الحرارة"},{"level":"1 درجة","description":"ذكر درجة الحرارة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن تراكيز الاتزان واحدة في كل المحاولات","ذكر الضغط أو العامل المحفز عاملًا يغير Keq"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.211Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Keq = [HI]² / [H₂][I₂].
المحاولة 1: Keq = (1.8682)² / (0.06587 × 1.0659) = 3.4902 / 0.070211 = 49.7.
المحاولة 2: Keq = (3.8950)² / (0.5525 × 0.5525) = 15.171 / 0.30526 = 49.7.
(ب) موضعا الاتزان مختلفان؛ ففي المحاولة 1 يكون [H₂] صغيرًا جدًّا و[I₂] كبيرًا نسبيًّا، وفي المحاولة 2 يتساوى [H₂] و[I₂] ويكون [HI] أكبر بكثير، ومع ذلك قيمتا Keq متساويتان (49.7). نستنتج أن Keq ثابتة عند درجة حرارة معينة مهما اختلفت التراكيز الابتدائية، وأن التراكيز الابتدائية تحدد موضع الاتزان فقط.', '["Keq = [HI]²/[H₂][I₂]","Keq للمحاولة 1 = 49.7","Keq للمحاولة 2 = 49.7","موضعا الاتزان مختلفان","Keq ثابتة لا تعتمد على التراكيز الابتدائية"]'::jsonb, '["Keq = [HI]² / [H₂][I₂]","المحاولة 1: (1.8682)² = 3.4902؛ 0.06587 × 1.0659 = 0.070211؛ Keq = 3.4902 / 0.070211 = 49.7","المحاولة 2: (3.8950)² = 15.171؛ (0.5525)² = 0.30526؛ Keq = 15.171 / 0.30526 = 49.7","المقارنة: قيمتان متساويتان رغم اختلاف تراكيز الاتزان"]'::jsonb, '[{"element":"كتابة تعبير Keq","marks":1},{"element":"حساب Keq للمحاولة 1","marks":2},{"element":"حساب Keq للمحاولة 2","marks":2},{"element":"المقارنة والاستنتاج","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تعبير صحيح وحسابان صحيحان واستنتاج سليم"},{"level":"4–5 درجات","description":"تعبير صحيح وحساب واحد صحيح مع استنتاج"},{"level":"1–3 درجات","description":"تعبير صحيح فقط أو حساب واحد دون استنتاج"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تربيع [HI]","التعويض بالتراكيز الابتدائية بدل تراكيز الاتزان","الاستنتاج أن موضعي الاتزان متطابقان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-06T22:20:31.211Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الحاوية (1): [A₂] = 0.20، [B₂] = 0.20، [AB] = 0.40 mol/L؛ Keq = (0.40)² / (0.20 × 0.20) = 0.16 / 0.040 = 4.0.
(ب) الحاوية (2): [A₂] = 0.10، [B₂] = 0.40، [AB] = 0.40 mol/L؛ النسبة = 0.16 / 0.040 = 4.0 = Keq، فهي في حالة اتزان. الحاوية (3): [A₂] = 0.30، [B₂] = 0.30، [AB] = 0.20 mol/L؛ النسبة = 0.040 / 0.090 = 0.44 ≠ 4.0، فليست في حالة اتزان.
(ج) لأن للنظام عند درجة حرارة معينة عددًا غير محدود من مواضع الاتزان تحددها التراكيز الابتدائية؛ والشرط الوحيد للاتزان أن تعطي التراكيز قيمة Keq نفسها (4.0)، لا أن تتطابق التراكيز.', '["Keq = 4.0 من الحاوية (1)","الحاوية (2): النسبة 4.0 فهي متزنة","الحاوية (3): النسبة 0.44 فليست متزنة","تعدد مواضع الاتزان مع ثبات Keq عند درجة الحرارة نفسها"]'::jsonb, '["(1): Keq = (0.40)² / (0.20 × 0.20) = 4.0","(2): (0.40)² / (0.10 × 0.40) = 4.0","(3): (0.20)² / (0.30 × 0.30) = 0.44","المقارنة بـ Keq = 4.0"]'::jsonb, '[{"element":"قراءة التراكيز من الرسم وحساب Keq","marks":1},{"element":"حساب نسبة الحاوية (2) والحكم","marks":1},{"element":"حساب نسبة الحاوية (3) والحكم","marks":1},{"element":"تفسير تعدد مواضع الاتزان","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة وأحكام صحيحة وتفسير واضح"},{"level":"3–4 درجات","description":"حسابات صحيحة مع تفسير ناقص"},{"level":"1–2 درجة","description":"حساب Keq فقط أو حكم دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الجزيئات دون تحويلها إلى تراكيز ثم الخطأ في الأسس","الحكم على (3) بالاتزان لتساوي [A₂] و[B₂]","نسيان تربيع [AB]"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-06T22:20:31.212Z"}'::jsonb)
