('mcq', 1, 'لماذا لا تُكتب تراكيز المواد الصلبة والسوائل النقية في تعبير ثابت الاتزان؟', null, null, '["لأنها لا تشارك في التفاعلين الأمامي والعكسي","لأن تركيزها ثابت عند درجة حرارة ثابتة مهما تغيرت كميتها","لأن تركيزها يصبح صفرًا عندما يصل النظام إلى الاتزان","لأن كميتها عند الاتزان صغيرة جدًّا فيمكن إهمالها"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 86 — تعابير الاتزان غير المتجانس'),
('mcq', 2, 'بمَ يُعبَّر عن تركيز سائل نقي مثل الإيثانول C₂H₅OH(l)؟', null, null, '["بكتلته بالجرام، وهي تتغير بتغير حجمه","بعدد مولاته، وهو يزداد بزيادة كميته","بحجمه باللتر، وهو يقل كلما تبخر جزء منه","بكثافته بوحدة mol/L، وهي ثابتة عند درجة حرارة ثابتة"]'::jsonb, 'فهم', 'تفسير مفهوم', 'متوسط', 'الكتاب ص 86 — تعابير الاتزان غير المتجانس'),
('mcq', 3, 'يمثل الشكل الآتي إيثانولًا في دورق مغلق عند درجة حرارة ثابتة وقد وصل إلى الاتزان C₂H₅OH(l) ⇌ C₂H₅OH(g). ما تعبير ثابت الاتزان الصحيح، ولماذا؟', null, '[{"src":"qimg/chem22/c3-l1b-ethanol-flask.svg","alt":"دورق زجاجي كروي مغلق بسدادة، في قاعه طبقة من الإيثانول السائل C₂H₅OH(l) تُرسم جزيئاته دوائر برتقالية متقاربة، وفوقه في الفراغ جزيئات قليلة متباعدة من بخار الإيثانول C₂H₅OH(g). عند سطح السائل سهم أخضر يتجه إلى أعلى يمثل التبخر (انتقال جزيئات من السائل إلى البخار)، وسهم أحمر يتجه إلى أسفل يمثل التكثف (عودة جزيئات من البخار إلى السائل). درجة الحرارة ثابتة."}]'::jsonb, '["Keq = [C₂H₅OH(g)]؛ لأن تركيز السائل النقي ثابت فيُدمج مع K","Keq = [C₂H₅OH(g)]/[C₂H₅OH(l)]؛ لأن جميع المواد تُكتب في التعبير","Keq = 1/[C₂H₅OH(g)]؛ لأن البخار يتكثف فيعود إلى الحالة السائلة","Keq = [C₂H₅OH(l)]؛ لأن السائل هو المادة المتفاعلة في الاتزان"]'::jsonb, 'فهم', 'تعليل تعبير', 'سهل', 'الكتاب ص 86 — تعابير الاتزان غير المتجانس'),
('mcq', 4, 'تحتوي الحاويتان المتساويتان في الحجم في الشكل الآتي على يود صلب في حالة اتزان مع بخاره I₂(s) ⇌ I₂(g) عند درجة الحرارة نفسها، وكمية اليود الصلب فيهما مختلفة (حجم الصلب صغير يمكن إهماله). ماذا تستنتج؟', null, '[{"src":"qimg/chem22/c3-l1b-iodine-amounts.svg","alt":"حاويتان مغلقتان متساويتان في الحجم عند درجة الحرارة نفسها، مرقمتان (1) و(2)، في قاع كل منهما كومة صغيرة من اليود الصلب I₂(s) تُرسم دوائر بنفسجية داكنة متراصة، وفي باقي الحاوية جزيئات يود غازية I₂(g) تُرسم دوائر بنفسجية متفرقة. الحاوية (1): كومة كبيرة نسبيًّا من اليود الصلب (خمسة صفوف)، وستة جزيئات من I₂(g). الحاوية (2): كومة صغيرة جدًّا من اليود الصلب (صفان فقط)، وستة جزيئات من I₂(g) أيضًا. حجم الصلب صغير مقارنة بحجم الحاوية."}]'::jsonb, '["[I₂(g)] في (1) أكبر لأنها تحتوي على كمية أكبر من اليود الصلب","Keq في (2) أكبر لأن نسبة الغاز إلى الصلب فيها أكبر","[I₂(g)] متساوٍ في الحاويتين، فقيمة Keq لا تتأثر بكمية الصلب","Keq في (1) أكبر لأن مجموع كمية اليود فيها أكبر"]'::jsonb, 'تحليل', 'تحليل رسم جسيمات', 'صعب', 'الكتاب ص 86 — تعابير الاتزان غير المتجانس'),
('mcq', 5, 'عند كتابة تعبير ثابت الاتزان للتفاعل CaCO₃(s) ⇌ CaO(s) + CO₂(g)، أيّ المواد تُحذف ولماذا؟', null, null, '["CO₂ فقط؛ لأنه غاز يمكن أن يتسرب من الوعاء","CaO فقط؛ لأنه ناتج صلب يترسب في قاع الوعاء","لا تُحذف أي مادة؛ لأن جميع المواد تشارك في التفاعل","CaCO₃ وCaO؛ لأنهما صلبتان نقيتان تركيزاهما ثابتان"]'::jsonb, 'تطبيق', 'تطبيق قاعدة', 'متوسط', 'الكتاب ص 87 — مسائل تدريبية (س3c)'),
('mcq', 6, 'لماذا لا يظهر Mg(OH)₂ في تعبير ثابت حاصل الذائبية للاتزان Mg(OH)₂(s) ⇌ Mg²⁺(aq) + 2OH⁻(aq)؟', null, null, '["لأنه لا يذوب في الماء إطلاقًا فلا يشارك في الاتزان","لأنه مادة صلبة نقية تركيزها ثابت عند درجة حرارة محددة","لأن تركيزه يساوي تركيز أيونات Mg²⁺ في المحلول المشبع","لأنه يتحول كله إلى أيونات عندما يصل المحلول إلى الاتزان"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 100–101 — كتابة تعبير ثابت حاصل الذائبية'),
('mcq', 7, 'وعاء مغلق عند 25°C فيه ماء سائل في حالة اتزان مع بخاره H₂O(l) ⇌ H₂O(g). أُضيفت إليه كمية أخرى من الماء السائل مع بقاء درجة الحرارة ثابتة. ماذا يحدث لقيمة Keq؟', null, null, '["تزداد؛ لأن كمية المادة المتفاعلة زادت في الوعاء","تقل؛ لأن تركيز الماء السائل في مقام التعبير زاد","لا تتغير؛ لأن Keq = [H₂O(g)] وتركيز الماء السائل ثابت","تزداد؛ لأن [H₂O(g)] عند الاتزان يزداد بزيادة كمية السائل"]'::jsonb, 'تحليل', 'تنبؤ وتعليل', 'صعب', 'الكتاب ص 86–87 — الاتزان غير المتجانس (س3b)'),
('essay', 1, 'يمثل الشكل الآتي إيثانولًا في دورق مغلق عند درجة حرارة ثابتة وقد وصل إلى الاتزان C₂H₅OH(l) ⇌ C₂H₅OH(g).
(أ) اكتب النسبة K بين تركيز الناتج وتركيز المادة المتفاعلة.
(ب) علل: يمكن دمج [C₂H₅OH(l)] مع K.
(ج) اكتب تعبير Keq النهائي، وبيّن على ماذا تعتمد قيمته.', null, '[{"src":"qimg/chem22/c3-l1b-ethanol-flask.svg","alt":"دورق زجاجي كروي مغلق بسدادة، في قاعه طبقة من الإيثانول السائل C₂H₅OH(l) تُرسم جزيئاته دوائر برتقالية متقاربة، وفوقه في الفراغ جزيئات قليلة متباعدة من بخار الإيثانول C₂H₅OH(g). عند سطح السائل سهم أخضر يتجه إلى أعلى يمثل التبخر (انتقال جزيئات من السائل إلى البخار)، وسهم أحمر يتجه إلى أسفل يمثل التكثف (عودة جزيئات من البخار إلى السائل). درجة الحرارة ثابتة."}]'::jsonb, null, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 86 — تعابير الاتزان غير المتجانس'),
('essay', 2, '(أ) علل: تُحذف المواد الصلبة والسوائل النقية من تعبير ثابت الاتزان.
(ب) تمتص صودا الخبز الروائح في الثلاجات، وتتحلل وفق الاتزان: 2NaHCO₃(s) ⇌ Na₂CO₃(s) + CO₂(g) + H₂O(g). اكتب تعبير ثابت الاتزان لهذا التفاعل، وحدد المواد المحذوفة.', null, null, null, 'فهم', 'تعليل وتطبيق', 'سهل', 'الكتاب ص 86–87 — مثال 3-2'),
('essay', 3, 'مكعب من فلز المنجنيز النقي طول ضلعه 5.25 cm وكتلته 1076.6 g (الكتلة المولية للمنجنيز 54.938 g/mol).
(أ) احسب التركيز المولاري للمنجنيز في المكعب (mol/L).
(ب) قُطع من المكعب مكعب صغير طول ضلعه نصف طول الضلع الأصلي (كتلته ثُمن الكتلة الأصلية). احسب التركيز المولاري للمنجنيز في المكعب الصغير.
(ج) ماذا تستنتج من النتيجتين؟ وكيف يفسر ذلك حذف المواد الصلبة النقية من تعبير ثابت الاتزان؟', null, null, null, 'تحليل', 'حساب واستنتاج', 'صعب', 'الكتاب ص 112 — س43، وص 86')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
