insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تركيز المادة الصلبة أو السائلة النقية هو كثافتها معبرًا عنها بوحدة mol/L، والكثافة ثابتة عند درجة حرارة ثابتة مهما كانت كمية المادة؛ فيُدمج هذا التركيز الثابت مع الثابت K ولا يُكتب في تعبير Keq.', '["المواد الصلبة والسوائل النقية تشارك في التفاعل (مثل تسامي I₂(s))، لكن تركيزها ثابت فلا يُكتب.","","يجب أن تكون المادة الصلبة موجودة عند الاتزان، وتركيزها لا يساوي صفرًا بل يساوي قيمة ثابتة.","الحذف لا يتعلق بصغر الكمية؛ فحتى الكمية الكبيرة من الصلب تركيزها ثابت ولا يُكتب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-06T22:20:31.212Z"}'::jsonb),
('mcq', 2, 3, 'تركيز السائل النقي هو كثافته معبرًا عنها بوحدة mol/L (عدد مولات المادة في لتر منها)، والكثافة ثابتة عند درجة حرارة ثابتة؛ لذلك يبقى تركيز الإيثانول السائل ثابتًا سواء كانت كميته كبيرة أو صغيرة.', '["الكتلة ليست تركيزًا؛ التركيز كمية المادة في وحدة الحجم.","عدد المولات وحده ليس تركيزًا؛ فزيادة الكمية تزيد المولات والحجم معًا وتبقى النسبة ثابتة.","الحجم وحده ليس تركيزًا؛ والتركيز (mol/L) يبقى ثابتًا رغم تبخر جزء من السائل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-06T22:20:31.213Z"}'::jsonb),
('mcq', 3, 0, 'K = [C₂H₅OH(g)]/[C₂H₅OH(l)]، وتركيز الإيثانول السائل النقي ثابت (كثافته بوحدة mol/L ثابتة عند درجة حرارة ثابتة)، فيُدمج مع K: K[C₂H₅OH(l)] = [C₂H₅OH(g)] = Keq.', '["","هذه هي النسبة الأولية K، لكن المقام تركيز سائل نقي ثابت فيُدمج مع K ولا يبقى في Keq.","هذا مقلوب التعبير؛ البخار هو الناتج ويوضع في البسط، والتكثف هو التفاعل العكسي فقط.","السائل النقي هو الذي يُحذف لثبات تركيزه، ويبقى تركيز البخار وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-06T22:20:31.213Z"}'::jsonb),
('mcq', 4, 2, 'Keq = [I₂(g)]؛ لأن تركيز اليود الصلب النقي ثابت مهما كانت كميته. والحاويتان متساويتان في الحجم ودرجة الحرارة وفي كل منهما ستة جزيئات من I₂(g)، فتركيز الغاز متساوٍ فيهما وKeq واحدة رغم اختلاف كمية الصلب.', '["عدد جزيئات I₂(g) واحد في الحاويتين المتساويتين في الحجم، فكمية الصلب الأكبر لا تزيد تركيز الغاز عند الاتزان.","الصلب لا يدخل في تعبير Keq، فلا معنى لنسبة الغاز إلى الصلب في حسابه.","","Keq يعتمد على [I₂(g)] فقط، لا على مجموع كمية اليود في الحاوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-06T22:20:31.213Z"}'::jsonb),
('mcq', 5, 3, 'CaCO₃ وCaO مادتان صلبتان نقيتان، تركيز كل منهما ثابت عند درجة حرارة ثابتة فلا يُكتب؛ ويبقى الغاز وحده: Keq = [CO₂].', '["CO₂ هو المادة الوحيدة التي يتغير تركيزها، فهو الذي يبقى في التعبير؛ والاتزان يحدث في نظام مغلق.","CaCO₃ صلب نقي أيضًا ويُحذف مع CaO؛ والسبب ثبات التركيز لا الترسب.","المشاركة في التفاعل لا تكفي لكتابة المادة؛ فالمواد الصلبة النقية تُحذف لثبات تراكيزها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.213Z"}'::jsonb),
('mcq', 6, 1, 'تركيز المادة الصلبة النقية يُعبَّر عنه بكثافتها بوحدة mol/L ويكون ثابتًا عند درجة حرارة محددة، فيُحذف من التعبير كما تُحذف المواد الصلبة في الاتزان غير المتجانس: Ksp = [Mg²⁺][OH⁻]².', '["Mg(OH)₂ يذوب قليلًا ويكون في اتزان مع أيوناته في المحلول المشبع؛ وحذفه سببه ثبات تركيزه.","","تركيز الصلب النقي كثافته بوحدة mol/L، ولا علاقة له بتركيز الأيونات الذائبة.","عند الاتزان يجب أن يبقى بعض الصلب غير ذائب؛ فلا يتحول كله إلى أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-06T22:20:31.214Z"}'::jsonb),
('mcq', 7, 2, 'Keq = [H₂O(g)]؛ فالماء السائل النقي تركيزه ثابت مهما زادت كميته ولا يُكتب في التعبير. وKeq لا تتغير إلا بتغير درجة الحرارة، ودرجة الحرارة ثابتة، فلا تتغير قيمتها.', '["زيادة كمية السائل النقي لا تغير تركيزه (كثافته ثابتة)، فلا تؤثر في Keq.","تركيز الماء السائل لا يزيد بزيادة كميته، ولا يُكتب أصلًا في تعبير Keq.","","[H₂O(g)] عند الاتزان يساوي Keq الثابتة عند درجة الحرارة نفسها، فلا يتغير بزيادة كمية السائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-06T22:20:31.214Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) K = [C₂H₅OH(g)] / [C₂H₅OH(l)].
(ب) لأن المقام يمثل الإيثانول السائل، وهو مادة نقية تركيزها هو كثافتها معبرًا عنها بوحدة mol/L، والكثافة ثابتة عند درجة حرارة ثابتة؛ فيبقى [C₂H₅OH(l)] ثابتًا سواء كانت كمية السائل كبيرة أو صغيرة، فيُدمج مع K.
(ج) K[C₂H₅OH(l)] = [C₂H₅OH(g)] = Keq؛ فـ Keq = [C₂H₅OH(g)]، وتعتمد قيمته على تركيز بخار الإيثانول في النظام فقط (عند درجة حرارة معينة).', '["K = [C₂H₅OH(g)]/[C₂H₅OH(l)]","تركيز السائل النقي = كثافته بوحدة mol/L","الكثافة ثابتة عند درجة حرارة ثابتة مهما كانت الكمية","Keq = [C₂H₅OH(g)]","Keq يعتمد على تركيز البخار فقط"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة النسبة K","marks":1},{"element":"تعليل دمج تركيز السائل مع K","marks":2},{"element":"كتابة Keq النهائي","marks":1},{"element":"بيان ما تعتمد عليه قيمته","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"نسبة صحيحة وتعليل كامل بالكثافة وتعبير نهائي صحيح"},{"level":"3–4 درجات","description":"تعبير نهائي صحيح مع تعليل ناقص"},{"level":"1–2 درجة","description":"تعبير نهائي صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعليل الحذف بأن السائل لا يشارك في التفاعل","إبقاء [C₂H₅OH(l)] في المقام","القول إن تركيز السائل يزداد بزيادة كميته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-06T22:20:31.214Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) لأن تركيز المادة الصلبة أو السائلة النقية يساوي كثافتها بوحدة mol/L، وهي ثابتة عند درجة حرارة ثابتة مهما كانت كمية المادة؛ فيُدمج تركيزها الثابت مع ثابت الاتزان.
(ب) Keq = [CO₂][H₂O]؛ وحُذف NaHCO₃ وNa₂CO₃ لأنهما مادتان صلبتان نقيتان.', '["تركيز الصلب أو السائل النقي = كثافته بوحدة mol/L","ثابت عند درجة حرارة ثابتة فيُدمج مع الثابت","Keq = [CO₂][H₂O]","المحذوفان NaHCO₃ وNa₂CO₃"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل الحذف","marks":2},{"element":"كتابة التعبير","marks":1},{"element":"تحديد المواد المحذوفة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل صحيح وتعبير صحيح وتحديد صحيح"},{"level":"2–3 درجات","description":"تعبير صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"تحديد المواد المحذوفة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة [NaHCO₃]² في المقام","حذف H₂O(g) ظنًّا أنه سائل نقي","تعليل الحذف بأن الصلب لا يتفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-06T22:20:31.214Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الحجم = (5.25 cm)³ = 144.7 cm³ = 0.1447 L؛ عدد المولات = 1076.6 g ÷ 54.938 g/mol = 19.60 mol؛ التركيز = 19.60 mol ÷ 0.1447 L = 135 mol/L.
(ب) الحجم = (2.625 cm)³ = 18.09 cm³ = 0.01809 L؛ الكتلة = 1076.6 ÷ 8 = 134.6 g؛ عدد المولات = 134.6 ÷ 54.938 = 2.450 mol؛ التركيز = 2.450 ÷ 0.01809 = 135 mol/L.
(ج) التركيز المولاري واحد (135 mol/L) رغم اختلاف الكمية؛ لأن الكتلة والحجم يتغيران بالنسبة نفسها، فتركيز المادة الصلبة النقية يساوي كثافتها بوحدة mol/L وهو ثابت عند درجة حرارة ثابتة. ولذلك لا يتغير تركيز المادة الصلبة بتغير كميتها في خليط الاتزان، فيُدمج مع الثابت ولا يُكتب في تعبير Keq.', '["V = 0.1447 L","n = 19.60 mol","التركيز 135 mol/L","المكعب الصغير: 135 mol/L أيضًا","التركيز = الكثافة المولية ثابتة مهما كانت الكمية","لذلك يُحذف الصلب النقي من Keq"]'::jsonb, '["V = (5.25)³ = 144.7 cm³ = 0.1447 L","n = 1076.6 ÷ 54.938 = 19.60 mol","M = 19.60 ÷ 0.1447 = 135 mol/L","المكعب الصغير: V = (2.625)³ = 18.09 cm³ = 0.01809 L؛ m = 134.6 g؛ n = 2.450 mol","M = 2.450 ÷ 0.01809 = 135 mol/L"]'::jsonb, '[{"element":"حساب الحجم باللتر","marks":1},{"element":"حساب عدد المولات","marks":1},{"element":"حساب التركيز في المكعب الكبير","marks":1},{"element":"حساب التركيز في المكعب الصغير","marks":1},{"element":"الاستنتاج: التركيز ثابت لا يعتمد على الكمية","marks":1},{"element":"الربط بحذف الصلب من Keq","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"حسابات صحيحة بالأرقام المعنوية والوحدات واستنتاج وربط صحيحان"},{"level":"4–5 درجات","description":"حسابات صحيحة مع نقص في الربط أو خطأ بسيط في التحويل"},{"level":"1–3 درجات","description":"حساب جزئي صحيح أو استنتاج دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل cm³ إلى L فيخرج التركيز 0.135","حساب الحجم 5.25 × 3 بدل التكعيب","قسمة الكتلة على الحجم دون تحويلها إلى مولات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.215Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C3-L1-O11') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L2-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ينص مبدأ لوتشاتلييه على أنه إذا بُذل جهد على نظام في حالة اتزان فإن ذلك يؤدي إلى:', null, null, '["إزاحة النظام في اتجاه يزيد أثر هذا الجهد","إزاحة النظام في اتجاه يخفف أثر هذا الجهد","بقاء موضع الاتزان ثابتًا دون أي إزاحة","توقف التفاعلين الأمامي والعكسي حتى يزول الجهد"]'::jsonb, 'تذكر', 'تذكر نص مبدأ', 'سهل', 'الكتاب ص 92 — مبدأ لوتشاتلييه'),
('mcq', 2, 'ما المقصود بالجهد في مبدأ لوتشاتلييه؟', null, null, '["الحد الأدنى من الطاقة اللازمة لبدء التفاعل","الطاقة اللازمة لتكسير الروابط في المتفاعلات","الضغط الذي يبذله المكبس على جدار الوعاء فقط","أي تغير يؤثر في اتزان نظام معين"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 92 — مبدأ لوتشاتلييه (الجهد)'),
('mcq', 3, 'أيّ مما يأتي يُعدّ جهدًا على نظام غازي في حالة اتزان داخل وعاء مغلق؟', null, null, '["إضافة كمية من أحد المتفاعلات إلى الوعاء","ترك الوعاء مدة أطول عند الظروف نفسها","إعادة كتابة معادلة التفاعل بطريقة عكسية","قياس لون الخليط دون تغيير ظروفه"]'::jsonb, 'فهم', 'تمييز أمثلة', 'سهل', 'الكتاب ص 92 — مبدأ لوتشاتلييه (الجهد)'),
('mcq', 4, 'يوضح المنحنى الآتي سرعتي التفاعل الأمامي والعكسي لنظام متزن، بُذل عليه جهد عند اللحظة t₁. أيّ وصف لما بعد t₁ يتفق مع مبدأ لوتشاتلييه؟', null, '[{"src":"qimg/chem22/c3-l2-rates.svg","alt":"رسم بياني: المحور الرأسي «سرعة التفاعل»، والمحور الأفقي «الزمن»، وعليه خط رأسي متقطع عند اللحظة t₁. منحنى أزرق متصل «السرعة الأمامية» يبدأ مرتفعًا ويتناقص، ومنحنى أحمر متقطع «السرعة العكسية» يبدأ من الصفر ويتزايد، حتى يلتقيا ويصبحا خطًّا أفقيًّا واحدًا قبل t₁. عند t₁ تقفز السرعة الأمامية فجأة إلى قيمة أعلى، ولا تقفز السرعة العكسية. بعد t₁ تتناقص السرعة الأمامية تدريجيًّا وتتزايد السرعة العكسية تدريجيًّا حتى تتساويا من جديد عند قيمة أعلى قليلًا مما كانت عليه قبل t₁، ثم تبقيان ثابتتين."}]'::jsonb, '["تبقى السرعة الأمامية أكبر من العكسية بعد t₁ دون أن تتساويا","تتناقص السرعتان معًا حتى تصلا إلى الصفر فيتوقف التفاعل","تتناقص السرعة الأمامية بعد قفزتها حتى تتساوى السرعتان من جديد","تقفز السرعة العكسية فجأة وتبقى السرعة الأمامية ثابتة"]'::jsonb, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 92 — تطبيق مبدأ لوتشاتلييه'),
('mcq', 5, 'يزيد العدّاء سرعة ركضه كلما زادت سرعة آلة المشي ليبقى في مكانه. ما الفكرة التي يشبهها هذا الموقف في الأنظمة المتزنة؟', null, null, '["استجابة النظام المتزن للتغير بما يعيده إلى حالة اتزان","توقف التفاعل الكيميائي عند الوصول إلى الاتزان","تساوي تراكيز المتفاعلات والنواتج عند الاتزان","زيادة سرعة التفاعل الأمامي وحده دون حد"]'::jsonb, 'فهم', 'تفسير تشبيه', 'متوسط', 'الكتاب ص 91 — الشكل 3-10'),
('mcq', 6, 'وفق مبدأ لوتشاتلييه، إذا زاد تركيز إحدى المواد في نظام متزن فإن النظام يزاح في الاتجاه الذي:', null, null, '["يُنتَج فيه مزيد من المادة المضافة","تتساوى فيه تراكيز جميع المواد","تزداد فيه قيمة Keq لتعوض الزيادة","يُستهلك فيه جزء من المادة المضافة"]'::jsonb, 'فهم', 'تطبيق نص المبدأ', 'متوسط', 'الكتاب ص 92 — مبدأ لوتشاتلييه'),
('mcq', 7, 'كتب طالب: «إذا بُذل جهد على نظام متزن فإنه يزاح دائمًا نحو النواتج». ما التصحيح العلمي لهذه العبارة؟', null, null, '["العبارة صحيحة، لأن أي جهد يزيد كمية النواتج دائمًا","يزاح في الاتجاه الذي يخفف أثر الجهد، نحو النواتج أو نحو المتفاعلات","يزاح دائمًا نحو المتفاعلات، لأن الجهد يعكس اتجاه التفاعل","لا يزاح أبدًا، لأن Keq يبقى ثابتًا عند بذل الجهد"]'::jsonb, 'تقويم', 'تصحيح مفهوم خاطئ', 'صعب', 'الكتاب ص 92–93 — مبدأ لوتشاتلييه والشكل 3-12'),
('essay', 1, 'اكتب نص مبدأ لوتشاتلييه، ثم وضح المقصود بالجهد، واذكر ثلاثة أنواع من الجهود التي يمكن أن تؤثر في نظام متزن.', null, null, null, 'تذكر', 'نص مبدأ وتعريف', 'سهل', 'الكتاب ص 92، 97، 111 — مبدأ لوتشاتلييه'),
('essay', 2, 'يمثل المنحنى الآتي تراكيز المواد في النظام المتزن A(g) + B(g) ⇌ C(g) قبل اللحظة t₁ وبعدها. حدد الجهد الذي بُذل على النظام عند t₁، ثم فسر تغير تراكيز المواد الثلاث بعد t₁ في ضوء مبدأ لوتشاتلييه.', null, '[{"src":"qimg/chem22/c3-l2-add-a.svg","alt":"رسم بياني: المحور الرأسي «التركيز (mol/L)» من 0 إلى 1.0، والمحور الأفقي «الزمن»، وعليه خط رأسي متقطع عند اللحظة t₁. ثلاثة منحنيات للمواد A (أزرق) وB (أخضر) وC (أحمر). قبل t₁ الخطوط الثلاثة أفقية ثابتة: [C] = 0.60 mol/L، و[A] = 0.40 mol/L، و[B] = 0.30 mol/L. عند t₁ يقفز [A] فجأة إلى 0.80 mol/L، ثم يتناقص تدريجيًّا حتى يثبت عند 0.70 mol/L. وبعد t₁ يتناقص [B] تدريجيًّا (دون قفزة) حتى يثبت عند 0.20 mol/L، ويتزايد [C] تدريجيًّا (دون قفزة) حتى يثبت عند 0.70 mol/L."}]'::jsonb, null, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 92 — تطبيق مبدأ لوتشاتلييه'),
('essay', 3, 'في النظام المتزن CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g) عند 1200 K، كان [CO] = 0.30000 M، ثم أضيفت كمية من CO حتى أصبح تركيزه لحظيًّا 1.00 M، وعند الوصول إلى الاتزان الجديد كان [CO] = 0.99254 M. قال طالب: «وفق مبدأ لوتشاتلييه يجب أن يعود تركيز CO إلى 0.30000 M تمامًا». قوّم عبارة الطالب مستعينًا بنص المبدأ.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 92 — الجدول 3-2')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L2-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'نص مبدأ لوتشاتلييه: إذا بُذل جهد على نظام في حالة اتزان فإن ذلك يؤدي إلى إزاحة النظام في اتجاه يخفف أثر هذا الجهد.', '["هذا عكس المبدأ؛ فالنظام يستجيب بما يقاوم الجهد ويخففه لا بما يضاعفه.","","الجهد يخل بالاتزان، فيزاح النظام إلى موضع اتزان جديد ولا يبقى في موضعه.","الاتزان ديناميكي، ولا يتوقف التفاعلان عند بذل الجهد بل تتغير سرعتاهما حتى تتساويا من جديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-06T22:20:31.215Z"}'::jsonb),
('mcq', 2, 3, 'الجهد هو أي تغير يؤثر في اتزان نظام معين، مثل تغير التركيز أو الحجم (الضغط) أو درجة الحرارة.', '["هذا تعريف طاقة التنشيط، لا الجهد المبذول على نظام متزن.","تكسير الروابط جزء من آلية التفاعل، وليس هو الجهد الذي يقصده المبدأ.","الضغط أحد أنواع الجهد فقط؛ فتغير التركيز ودرجة الحرارة جهد أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-06T22:20:31.215Z"}'::jsonb),
('mcq', 3, 0, 'إضافة متفاعل تغير تركيزه، وتغير التركيز جهد يخل بالاتزان فيستجيب له النظام بالإزاحة.', '["","مرور الوقت دون تغيير الظروف لا يغير شيئًا؛ فالتراكيز تبقى ثابتة عند الاتزان.","كتابة المعادلة على الورق لا تغير شيئًا في النظام نفسه، فليست جهدًا عليه.","الملاحظة والقياس لا يغيران تركيزًا ولا حجمًا ولا درجة حرارة، فلا يُعدّان جهدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-06T22:20:31.215Z"}'::jsonb),
('mcq', 4, 2, 'الجهد رفع السرعة الأمامية فجأة، فاستجاب النظام بما يخفف أثره: تتناقص السرعة الأمامية وتتزايد العكسية تدريجيًّا حتى تتساويا عند اتزان جديد.', '["يُظهر المنحنى أن السرعتين تلتقيان من جديد؛ فالنظام يصل إلى اتزان جديد ولا يبقى غير متزن.","الاتزان ديناميكي ولا يتوقف التفاعلان؛ والمنحنيان يستويان عند قيمة أعلى من الصفر.","","القفزة المفاجئة عند t₁ في السرعة الأمامية لا العكسية، فالعكسية تتزايد تدريجيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-06T22:20:31.216Z"}'::jsonb),
('mcq', 5, 0, 'كما يغير العدّاء سرعته ليتكيف مع تغير سرعة الآلة ويبقى متزنًا، يستجيب النظام المتزن لأي تغير (جهد) بالإزاحة حتى يصل إلى حالة اتزان جديدة.', '["","العدّاء لا يتوقف بل يتحرك باستمرار، وكذلك التفاعلان عند الاتزان لا يتوقفان.","التشبيه لا يتعلق بتساوي الكميات؛ والتراكيز عند الاتزان ثابتة لا متساوية.","العدّاء يزيد سرعته بقدر ما يعيد التوازن فقط، لا زيادة بلا حد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-06T22:20:31.216Z"}'::jsonb),
('mcq', 6, 3, 'تخفيف أثر زيادة تركيز مادة يكون باستهلاك جزء منها؛ فيزاح الاتزان في الاتجاه الذي تُستهلك فيه.', '["إنتاج المزيد من المادة المضافة يزيد أثر الجهد بدل أن يخففه.","الإزاحة لا تجعل التراكيز متساوية، بل تصل بالنظام إلى تراكيز اتزان جديدة ثابتة.","Keq لا تتغير بتغير التركيز؛ لا يغيرها إلا تغير درجة الحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-06T22:20:31.217Z"}'::jsonb),
('mcq', 7, 1, 'اتجاه الإزاحة يحدده نوع الجهد: النظام يزاح في الاتجاه الذي يخفف أثر الجهد، فقد يكون نحو النواتج (كإضافة متفاعل) أو نحو المتفاعلات (كإضافة ناتج).', '["إضافة ناتج أو إزالة متفاعل مثلًا تزيح الاتزان نحو المتفاعلات، فالعبارة ليست صحيحة دائمًا.","","هذا تعميم خاطئ آخر؛ فإضافة متفاعل مثلًا تزيح الاتزان نحو النواتج.","ثبات Keq عند تغير التركيز لا يمنع تغير موضع الاتزان؛ فالنظام يزاح إلى موضع جديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-06T22:20:31.217Z"}'::jsonb),
('essay', 1, null::int, null, null, 'مبدأ لوتشاتلييه: إذا بُذل جهد على نظام في حالة اتزان فإن ذلك يؤدي إلى إزاحة النظام في اتجاه يخفف أثر هذا الجهد. والجهد هو أي تغير يؤثر في اتزان نظام معين. ومن أنواعه: تغير التركيز (إضافة مادة متفاعلة أو ناتجة أو إزالتها)، وتغير الحجم أو الضغط في الأنظمة الغازية، وتغير درجة الحرارة.', '["نص المبدأ كاملًا: جهد على نظام متزن ← إزاحة في اتجاه يخفف أثر الجهد","تعريف الجهد: أي تغير يؤثر في اتزان النظام","ذكر ثلاثة أنواع: التركيز، والحجم/الضغط، ودرجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"نص المبدأ","marks":2},{"element":"تعريف الجهد","marks":1},{"element":"ثلاثة أنواع من الجهود (درجة لكل نوع)","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"نص المبدأ كاملًا وتعريف الجهد وثلاثة أنواع صحيحة"},{"level":"3–5 درجات","description":"نص المبدأ صحيح مع نقص في التعريف أو الأمثلة"},{"level":"1–2 درجة","description":"عنصر واحد صحيح أو نص ناقص للمبدأ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النظام يزاح ليزيد أثر الجهد","عدّ العامل المحفز جهدًا يزيح الاتزان","الاكتفاء بالضغط مثالًا وحيدًا للجهد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-06T22:20:31.217Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الجهد: إضافة كمية من المادة A عند t₁ (قفز [A] فجأة من 0.40 mol/L إلى 0.80 mol/L). وفق مبدأ لوتشاتلييه يستجيب النظام بما يخفف أثر هذه الزيادة، أي باستهلاك جزء من A؛ فيزاح الاتزان نحو اليمين: يتفاعل A مع B فيتناقص [A] تدريجيًّا (حتى 0.70 mol/L) ويتناقص [B] (حتى 0.20 mol/L)، ويتزايد [C] (حتى 0.70 mol/L). ولا يعود [A] إلى قيمته الأصلية؛ لأن النظام يخفف الجهد ولا يلغيه.', '["تحديد الجهد: إضافة A","اتجاه الإزاحة نحو اليمين لاستهلاك جزء من A","تفسير تناقص [A] و[B] وتزايد [C]","ملاحظة أن [A] لا يعود إلى قيمته الأصلية (تخفيف لا إلغاء)"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الجهد","marks":1},{"element":"اتجاه الإزاحة مع الربط بالمبدأ","marks":1},{"element":"تفسير تغير التراكيز الثلاثة","marks":1},{"element":"التخفيف لا الإلغاء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الجهد إزالة C لأن [C] تغير","القول إن [A] يعود إلى 0.40 mol/L","الخلط بين القفزة المفاجئة والتغير التدريجي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-06T22:20:31.217Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عبارة الطالب غير صحيحة. ينص المبدأ على أن النظام يزاح في اتجاه يخفف أثر الجهد، لا في اتجاه يلغيه. فقد استهلك النظام جزءًا فقط من CO المضاف بالإزاحة نحو اليمين (انخفض تركيزه من 1.00 M إلى 0.99254 M) فتكوّن مزيد من CH₄ وH₂O، لكنه بقي أكبر كثيرًا من 0.30000 M. فالموضع الجديد للاتزان مختلف عن الأصلي، مع بقاء Keq نفسه عند درجة الحرارة نفسها.', '["الحكم: العبارة غير صحيحة","الاستناد إلى كلمة «يخفف» في نص المبدأ","الاستشهاد بالأرقام: 1.00 M ← 0.99254 M وليس 0.30000 M","الاتزان الجديد موضع مختلف وKeq ثابت"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"التبرير بنص المبدأ (يخفف لا يلغي)","marks":1},{"element":"الاستشهاد بالبيانات","marks":1},{"element":"موضع اتزان جديد مع ثبات Keq","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول عبارة الطالب","القول إن النظام يزاح نحو اليسار","الظن أن Keq تغير لأن التراكيز تغيرت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-06T22:20:31.218Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
