('mcq', 1, 'في النظام المتزن CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g)، أضيفت كمية من غاز CO إلى وعاء التفاعل. كيف يستجيب النظام؟', null, null, '["يزاح نحو اليسار، فيزداد تركيز H₂","يزاح نحو اليمين، فيقل تركيز H₂O","يزاح نحو اليمين، فيزداد تركيز CH₄","لا يزاح، لأن قيمة Keq لا تتغير"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'سهل', 'الكتاب ص 92 — إضافة مواد متفاعلة'),
('mcq', 2, 'في النظام المتزن CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g)، أضيفت مادة مجففة تمتص بخار الماء من وعاء التفاعل. ماذا يحدث لتركيز CH₄؟', null, null, '["يزداد، لأن الاتزان يزاح نحو اليمين","يقل، لأن الاتزان يزاح نحو اليسار","لا يتغير، لأن CH₄ نفسه لم يُزَل","يقل، لأن المادة المجففة تمتص CH₄ أيضًا"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'متوسط', 'الكتاب ص 93 — إزالة النواتج'),
('mcq', 3, 'يمثل المنحنى الآتي تراكيز المواد في النظام المتزن A(g) + B(g) ⇌ C(g) قبل اللحظة t₁ وبعدها. ما الجهد الذي بُذل عند t₁، وما اتجاه الإزاحة؟', null, '[{"src":"qimg/chem22/c3-l2-add-c.svg","alt":"رسم بياني: المحور الرأسي «التركيز (mol/L)» من 0 إلى 1.2، والمحور الأفقي «الزمن»، وعليه خط رأسي متقطع عند اللحظة t₁. ثلاثة منحنيات للمواد A (أزرق) وB (أخضر) وC (أحمر). قبل t₁ الخطوط الثلاثة أفقية ثابتة: [C] = 0.60 mol/L، و[A] = 0.40 mol/L، و[B] = 0.30 mol/L. عند t₁ يقفز [C] فجأة إلى 1.10 mol/L، ثم يتناقص تدريجيًّا حتى يثبت عند 1.00 mol/L. وبعد t₁ يتزايد [A] تدريجيًّا (دون قفزة) حتى يثبت عند 0.50 mol/L، ويتزايد [B] تدريجيًّا حتى يثبت عند 0.40 mol/L."}]'::jsonb, '["إضافة كمية من A، والإزاحة نحو اليمين","إزالة كمية من C، والإزاحة نحو اليمين","إزالة كمية من B، والإزاحة نحو اليسار","إضافة كمية من C، والإزاحة نحو اليسار"]'::jsonb, 'تحليل', 'تفسير منحنى', 'متوسط', 'الكتاب ص 93 — إضافة النواتج'),
('mcq', 4, 'يمثل المنحنى الآتي النظام المتزن A(g) + B(g) ⇌ C(g)، وقد أزيلت كمية من المادة A عند اللحظة t₁. لماذا يتزايد [B] بعد t₁؟', null, '[{"src":"qimg/chem22/c3-l2-remove-a.svg","alt":"رسم بياني: المحور الرأسي «التركيز (mol/L)» من 0 إلى 1.0، والمحور الأفقي «الزمن»، وعليه خط رأسي متقطع عند اللحظة t₁. ثلاثة منحنيات للمواد A (أزرق) وB (أخضر) وC (أحمر). قبل t₁ الخطوط الثلاثة أفقية ثابتة: [C] = 0.60 mol/L، و[A] = 0.40 mol/L، و[B] = 0.30 mol/L. عند t₁ ينخفض [A] فجأة إلى 0.15 mol/L، ثم يتزايد تدريجيًّا حتى يثبت عند 0.25 mol/L. وبعد t₁ يتزايد [B] تدريجيًّا (دون قفزة) حتى يثبت عند 0.40 mol/L، ويتناقص [C] تدريجيًّا حتى يثبت عند 0.50 mol/L."}]'::jsonb, '["لأن الاتزان يزاح نحو اليمين فيتكون مزيد من B","لأن الاتزان يزاح نحو اليسار فيتفكك جزء من C إلى A وB","لأن إزالة A تزيد قيمة Keq فيزداد تركيز B","لأن جزيئات B تتحول مباشرة إلى A لتعوض النقص"]'::jsonb, 'تحليل', 'تفسير منحنى', 'صعب', 'الكتاب ص 93 — الشكل 3-12'),
('mcq', 5, 'في النظام المتزن CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g)، أزيلت كمية من غاز H₂. أيّ العبارات الآتية صحيحة؟', null, null, '["يزاح الاتزان نحو اليمين، فيزداد تركيز CH₄","يزاح الاتزان نحو اليسار، فيقل تركيز CO","لا يزاح الاتزان، لأن H₂ ليس من النواتج","يزاح الاتزان نحو اليسار، فيزداد تركيز CO"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'متوسط', 'الكتاب ص 93 — الشكل 3-12'),
('mcq', 6, 'يمثل الاتزان الآتي محلول كلوريد الكوبلت II:
Co(H₂O)₆²⁺(aq) + 4Cl⁻(aq) ⇌ CoCl₄²⁻(aq) + 6H₂O(l)
عند إضافة حمض HCl المركز (مصدر لأيونات Cl⁻) إلى المحلول المتزن، ماذا يحدث؟', null, null, '["يزاح الاتزان نحو اليمين، فيزداد تركيز CoCl₄²⁻","يزاح الاتزان نحو اليسار، فيزداد تركيز Co(H₂O)₆²⁺","يزاح الاتزان نحو اليمين، فيقل تركيز CoCl₄²⁻","لا يتأثر الاتزان، لأن الحمض لا يدخل في المعادلة"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'متوسط', 'الكتاب ص 96 — تجربة التغير في موضع الاتزان'),
('mcq', 7, 'قيمة Keq للنظام CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g) تساوي 3.933 عند 1200 K. أضيفت كمية من CO، ثم وصل النظام إلى موضع اتزان جديد عند درجة الحرارة نفسها. ما قيمة Keq في الموضع الجديد؟', null, null, '["أكبر من 3.933، لأن تركيز CH₄ زاد","تبقى 3.933 دون تغيير","أقل من 3.933، لأن تركيز CO زاد","صفر، لأن الاتزان اختل بالإضافة"]'::jsonb, 'فهم', 'ثبات Keq', 'سهل', 'الكتاب ص 92 — الجدول 3-2'),
('essay', 1, 'يمثل المنحنى الآتي تراكيز المواد في النظام المتزن A(g) + B(g) ⇌ C(g) قبل اللحظة t₁ وبعدها. حدد الجهد الذي بُذل عند t₁ واتجاه الإزاحة، وفسر تغير [A] و[B]، ثم بيّن بالحساب أن Keq لم تتغير.', null, '[{"src":"qimg/chem22/c3-l2-remove-c.svg","alt":"رسم بياني: المحور الرأسي «التركيز (mol/L)» من 0 إلى 1.0، والمحور الأفقي «الزمن»، وعليه خط رأسي متقطع عند اللحظة t₁. ثلاثة منحنيات للمواد A (أزرق) وB (أخضر) وC (أحمر). قبل t₁ الخطوط الثلاثة أفقية ثابتة: [C] = 0.60 mol/L، و[A] = 0.40 mol/L، و[B] = 0.30 mol/L. عند t₁ ينخفض [C] فجأة إلى 0.20 mol/L، ثم يتزايد تدريجيًّا حتى يثبت عند 0.30 mol/L. وبعد t₁ يتناقص [A] تدريجيًّا (دون قفزة) حتى يثبت عند 0.30 mol/L، ويتناقص [B] تدريجيًّا حتى يثبت عند 0.20 mol/L."}]'::jsonb, null, 'تحليل', 'تفسير منحنى وحساب', 'صعب', 'الكتاب ص 92–93 — إزالة النواتج'),
('essay', 2, 'في النظام المتزن CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g)، توقع اتجاه إزاحة الاتزان في كل حالة مما يأتي، مع التعليل: (أ) إضافة CO. (ب) إزالة H₂O. (ج) إضافة CH₄. (د) إزالة H₂.', null, null, null, 'تطبيق', 'توقع اتجاه الإزاحة', 'متوسط', 'الكتاب ص 92–93 — الشكل 3-12'),
('essay', 3, 'يُنتَج إيثانوات الإيثيل من الاتزان الآتي:
CH₃COOH + CH₃CH₂OH ⇌ CH₃COOCH₂CH₃ + H₂O
فسّر لماذا تسبب إزالة الماء إنتاج المزيد من إيثانوات الإيثيل، ثم توقع أثر إضافة كمية من الإيثانول CH₃CH₂OH في كمية إيثانوات الإيثيل.', null, null, null, 'تطبيق', 'تفسير وتوقع', 'متوسط', 'الكتاب ص 114 — سؤال 67')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
