insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'إضافة CO (متفاعل) جهد يخففه النظام باستهلاك جزء منه، فيزاح الاتزان نحو اليمين ويتكون مزيد من CH₄ وH₂O.', '["إضافة متفاعل تزيح الاتزان نحو النواتج لا نحو المتفاعلات، فيقل H₂ لا يزداد.","الإزاحة نحو اليمين تنتج مزيدًا من H₂O، فيزداد تركيزه لا يقل.","","ثبات Keq لا يعني ثبات الموضع؛ فإضافة CO تجعل النظام غير متزن فيزاح حتى يتحقق Keq من جديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-06T22:20:31.218Z"}'::jsonb),
('mcq', 2, 0, 'إزالة الماء (ناتج) تُخفض تركيزه، فيخفف النظام الجهد بإنتاج مزيد منه، أي يزاح نحو اليمين، فيتكون مزيد من CH₄.', '["","إزالة ناتج تزيح الاتزان نحو اليمين لتعويض النقص، لا نحو اليسار.","إزالة H₂O تخل بالاتزان كله، فتؤدي الإزاحة نحو اليمين إلى تكوين مزيد من CH₄ أيضًا.","المادة المجففة تمتص الماء فقط، وتركيز CH₄ يزداد نتيجة الإزاحة نحو اليمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-06T22:20:31.218Z"}'::jsonb),
('mcq', 3, 3, 'قفز [C] فجأة عند t₁ فهو المادة المضافة، ثم تناقص [C] وتزايد [A] و[B] تدريجيًّا؛ أي تحول جزء من C إلى A وB، فالإزاحة نحو اليسار.', '["القفزة المفاجئة في [C] لا في [A]؛ و[A] يتزايد تدريجيًّا نتيجة الإزاحة.","[C] قفز إلى أعلى (من 0.60 إلى 1.10 mol/L)، فهي إضافة لا إزالة.","[B] لم ينخفض فجأة، بل تزايد تدريجيًّا بعد t₁.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-06T22:20:31.219Z"}'::jsonb),
('mcq', 4, 1, 'إزالة A (متفاعل) جهد يخففه النظام بإنتاج مزيد منه عبر التفاعل العكسي: يتفكك جزء من C إلى A وB، فيتناقص [C] ويتزايد [A] و[B].', '["B من المتفاعلات؛ والإزاحة نحو اليمين تستهلكه، والمنحنى يُظهر تناقص [C] أي إزاحة نحو اليسار.","","Keq لا يتغير بتغير التركيز؛ وتزايد [B] سببه الإزاحة لا تغير Keq.","لا يتحول B إلى A؛ فالمادتان تتكونان معًا من تفكك C في التفاعل العكسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-06T22:20:31.219Z"}'::jsonb),
('mcq', 5, 3, 'إزالة H₂ تخفض تركيزه، فيخفف النظام الجهد بإنتاج مزيد منه عبر التفاعل العكسي، فيزاح نحو اليسار ويتكون مزيد من CO وH₂.', '["إزالة متفاعل تزيح الاتزان نحو المتفاعلات لتعويضه، فيقل CH₄ لا يزداد.","الإزاحة نحو اليسار تنتج CO وH₂ معًا، فيزداد [CO] لا يقل.","إزالة أي متفاعل أو ناتج تخل بالاتزان؛ فالمتفاعلات جزء من النظام المتزن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-06T22:20:31.219Z"}'::jsonb),
('mcq', 6, 0, 'أيونات Cl⁻ من المتفاعلات؛ فزيادة تركيزها جهد يخففه النظام باستهلاكها، فيزاح الاتزان نحو اليمين ويتكون مزيد من CoCl₄²⁻.', '["","زيادة Cl⁻ (متفاعل) تستهلك Co(H₂O)₆²⁺ بالإزاحة نحو اليمين، فيقل تركيزه لا يزداد.","الإزاحة نحو اليمين تكوّن مزيدًا من CoCl₄²⁻، فيزداد تركيزه.","أيونات Cl⁻ من الحمض متفاعل في المعادلة، فزيادة تركيزها جهد يزيح الاتزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-06T22:20:31.219Z"}'::jsonb),
('mcq', 7, 1, 'تغير التركيز يغير موضع الاتزان فقط؛ فعند الاتزان الجديد ([CO] = 0.99254 M، [H₂] = 0.07762 M، [CH₄] = 0.06648 M، [H₂O] = 0.02746 M) تبقى Keq = 3.933 لأن درجة الحرارة لم تتغير.', '["زيادة البسط يقابلها زيادة في [CO] في المقام، فتبقى النسبة 3.933.","","النظام يعدّل التراكيز كلها حتى تعود النسبة إلى القيمة نفسها؛ فلا يغير Keq إلا تغير درجة الحرارة.","الاختلال مؤقت؛ وعند الاتزان الجديد تتحقق قيمة Keq نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-06T22:20:31.220Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الجهد: إزالة كمية من الناتج C (انخفض [C] فجأة من 0.60 إلى 0.20 mol/L). يخفف النظام الجهد بإنتاج مزيد من C، فيزاح الاتزان نحو اليمين: يتفاعل A مع B فيتناقص [A] من 0.40 إلى 0.30 mol/L و[B] من 0.30 إلى 0.20 mol/L، ويتزايد [C] إلى 0.30 mol/L. قبل t₁: Keq = 0.60 ÷ (0.40 × 0.30) = 5.0، وبعد الاتزان الجديد: Keq = 0.30 ÷ (0.30 × 0.20) = 5.0؛ فالقيمة لم تتغير.', '["الجهد: إزالة C","الإزاحة نحو اليمين","تفسير تناقص [A] و[B]","حساب Keq قبل وبعد = 5.0"]'::jsonb, '["Keq = [C] ÷ ([A][B])","قبل t₁: 0.60 ÷ (0.40 × 0.30) = 5.0","بعد الاتزان الجديد: 0.30 ÷ (0.30 × 0.20) = 5.0","القيمتان متساويتان، فـ Keq لم تتغير"]'::jsonb, '[{"element":"تحديد الجهد","marks":1},{"element":"اتجاه الإزاحة","marks":1},{"element":"تفسير تغير [A] و[B]","marks":1},{"element":"حساب Keq قبل وبعد","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"كل العناصر صحيحة مع الحسابين"},{"level":"3–4 درجات","description":"التحديد والتفسير صحيحان مع خطأ في أحد الحسابين"},{"level":"1–2 درجة","description":"تحديد الجهد أو الاتجاه فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الجهد إضافة A أو B","استعمال تراكيز اللحظة t₁ (0.20 mol/L لـ C) في حساب Keq","القول إن Keq يقل لأن [C] قل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-06T22:20:31.220Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نحو اليمين؛ لاستهلاك جزء من CO المضاف. (ب) نحو اليمين؛ لإنتاج مزيد من H₂O يعوض النقص. (ج) نحو اليسار؛ لاستهلاك جزء من CH₄ المضاف بتحويله إلى متفاعلات. (د) نحو اليسار؛ لإنتاج مزيد من H₂ يعوض النقص.', '["(أ) يمين مع التعليل","(ب) يمين مع التعليل","(ج) يسار مع التعليل","(د) يسار مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الاتجاه عند إزالة مادة","القول إن إضافة ناتج لا تؤثر في الاتزان","ذكر الاتجاه دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-06T22:20:31.220Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الماء أحد النواتج؛ فإزالته تخفض تركيزه، ويخفف النظام هذا الجهد بإنتاج مزيد من الماء، أي بالإزاحة نحو اليمين، فيتكون معه مزيد من إيثانوات الإيثيل. وإضافة الإيثانول (متفاعل) جهد يخففه النظام باستهلاك جزء منه، فيزاح الاتزان نحو اليمين أيضًا وتزداد كمية إيثانوات الإيثيل.', '["الماء ناتج وإزالته تخفض تركيزه","الإزاحة نحو اليمين وتكوّن مزيد من الإستر","إضافة الإيثانول تزيح الاتزان نحو اليمين","زيادة كمية إيثانوات الإيثيل"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير إزالة الماء","marks":2},{"element":"توقع أثر إضافة الإيثانول مع التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن إزالة الماء تزيح الاتزان نحو اليسار","الظن أن إضافة متفاعل تقلل الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-06T22:20:31.220Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
