from (values
('mcq', 1, 'التفاعل CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g) طارد للحرارة (ΔH° = −206.5 kJ). كيف يستجيب الاتزان عند رفع درجة الحرارة؟', null, null, '["يزاح نحو اليمين، فيزداد تركيز CH₄","يزاح نحو اليمين، لأن الحرارة تسرّع التفاعل الأمامي فقط","لا يزاح، لأن الحرارة لا تُكتب في معادلة التفاعل","يزاح نحو اليسار، فيقل تركيز CH₄"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'سهل', 'الكتاب ص 94–95 — تغير درجة الحرارة'),
('mcq', 2, 'في الاتزان: حرارة + PCl₅(g) ⇌ PCl₃(g) + Cl₂(g)، ماذا يحدث لتركيز Cl₂ عند رفع درجة الحرارة؟', null, null, '["يقل، لأن الاتزان يزاح نحو اليسار","يزداد، لأن الاتزان يزاح نحو اليمين","لا يتغير، لأن تغير الحرارة لا يؤثر في التراكيز","يقل، لأن Cl₂ يتبخر من الوعاء المغلق"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'متوسط', 'الكتاب ص 113 — سؤالا 52 و55'),
('mcq', 3, 'يمثل المنحنى الآتي تراكيز المواد في النظام المتزن A(g) + B(g) ⇌ C(g) الطارد للحرارة، وقد تغيرت درجة حرارته عند اللحظة t₁. ما التغير الذي حدث؟', null, '[{"src":"qimg/chem22/c3-l2-temp.svg","alt":"رسم بياني: المحور الرأسي «التركيز (mol/L)» من 0 إلى 1.0، والمحور الأفقي «الزمن»، وعليه خط رأسي متقطع عند اللحظة t₁. ثلاثة منحنيات للمواد A (أزرق) وB (أخضر) وC (أحمر). قبل t₁ الخطوط الثلاثة أفقية ثابتة: [C] = 0.60 mol/L، و[A] = 0.40 mol/L، و[B] = 0.30 mol/L. عند t₁ لا تحدث أي قفزة مفاجئة في أي منحنى، بل تتغير التراكيز تدريجيًّا: يتناقص [C] حتى يثبت عند نحو 0.47 mol/L، ويتزايد [A] حتى يثبت عند نحو 0.53 mol/L، ويتزايد [B] حتى يثبت عند نحو 0.43 mol/L."}]'::jsonb, '["رُفعت درجة الحرارة، فأزيح الاتزان نحو اليسار","خُفضت درجة الحرارة، فأزيح الاتزان نحو اليسار","رُفعت درجة الحرارة، فأزيح الاتزان نحو اليمين","خُفضت درجة الحرارة، فأزيح الاتزان نحو اليمين"]'::jsonb, 'تحليل', 'تفسير منحنى', 'صعب', 'الكتاب ص 94–95 — الحرارة وموضع الاتزان'),
('mcq', 4, 'في الاتزان: 2O₃(g) ⇌ 3O₂(g) + حرارة، كيف يتأثر الاتزان بخفض درجة الحرارة؟', null, null, '["يزاح نحو اليسار، فيزداد تركيز O₃","يزاح نحو اليمين، فيقل تركيز O₂","يزاح نحو اليمين، فيزداد تركيز O₂","لا يتأثر، لأن عدد مولات الغاز يتغير"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'متوسط', 'الكتاب ص 114 — سؤال 68'),
('mcq', 5, 'يوضح المنحنى الآتي قيم Keq للاتزان X(g) ⇌ Y(g) عند درجات حرارة مختلفة. أيّ الاستنتاجات الآتية صحيح؟', null, '[{"src":"qimg/chem22/c3-l2-keq-t.svg","alt":"رسم بياني: المحور الرأسي «Keq» من 0 إلى 10، والمحور الأفقي «درجة الحرارة (K)». أربع نقاط موصولة بخط متناقص: عند 300 K قيمة Keq = 8.6، وعند 400 K قيمة Keq = 3.9، وعند 500 K قيمة Keq = 2.0، وعند 600 K قيمة Keq = 1.1. أي إن Keq تقل كلما ارتفعت درجة الحرارة."}]'::jsonb, '["التفاعل الأمامي ماص للحرارة، ورفع الحرارة يزيح الاتزان نحو Y","التفاعل الأمامي طارد للحرارة، ورفع الحرارة يزيح الاتزان نحو X","التفاعل الأمامي طارد للحرارة، ورفع الحرارة يزيح الاتزان نحو Y","لا يمكن الاستنتاج، لأن Keq لا يتأثر بدرجة الحرارة"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 95 — درجة الحرارة وKeq'),
('mcq', 6, 'في الاتزان: حرارة + N₂(g) + O₂(g) ⇌ 2NO(g)، أيّ تغير في درجة الحرارة يزيد تركيز NO؟', null, null, '["خفض درجة الحرارة، لأن التفاعل الأمامي ماص للحرارة","خفض درجة الحرارة، لأن التفاعل الأمامي طارد للحرارة","لا يغيره أي تغير في درجة الحرارة","رفع درجة الحرارة، لأن التفاعل الأمامي ماص للحرارة"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'سهل', 'الكتاب ص 114 — سؤال 69'),
('mcq', 7, 'تُستعمل أملاح كربونات الأمونيوم لإنعاش الشخص فاقد الوعي؛ لأن تفككها الماص للحرارة يطلق غاز الأمونيا:
(NH₄)₂CO₃(s) ⇌ 2NH₃(g) + CO₂(g) + H₂O(g)
متى تتوقع أن يكون استنشاق هذه الأملاح أكثر فعالية؟', null, null, '["في أيام الشتاء الباردة، لأن البرودة تزيح الاتزان نحو إنتاج NH₃","في أيام الصيف الحارة، لأن الحرارة تزيد قيمة Keq للتفاعل العكسي","في أيام الصيف الحارة، لأن الحرارة تزيح الاتزان نحو إنتاج NH₃","فعاليتها متساوية في الفصلين، لأن المادة الصلبة لا تُكتب في Keq"]'::jsonb, 'تطبيق', 'تطبيق حياتي', 'صعب', 'الكتاب ص 114 — سؤال 75'),
('essay', 1, 'التفاعل CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g) طارد للحرارة (ΔH° = −206.5 kJ). (أ) أعد كتابة المعادلة بحيث تظهر الحرارة فيها. (ب) توقع اتجاه إزاحة الاتزان عند رفع درجة الحرارة وأثر ذلك في [CH₄]. (ج) توقع اتجاه الإزاحة عند خفض درجة الحرارة وأثر ذلك في [CO].', null, null, null, 'تطبيق', 'توقع اتجاه الإزاحة', 'متوسط', 'الكتاب ص 94–95 — الشكل 3-15'),
('essay', 2, 'في الاتزان: حرارة + PCl₅(g) ⇌ PCl₃(g) + Cl₂(g)، وُضع الخليط المتزن في وعاء مغلق. توقع أثر رفع درجة الحرارة في كل من [Cl₂] و[PCl₅] وقيمة Keq، ثم توقع أثر خفضها في [PCl₃]، مع التعليل.', null, null, null, 'تطبيق', 'توقع وتعليل', 'متوسط', 'الكتاب ص 113 — سؤالا 52 و55'),
('essay', 3, 'يُعطى الاتزان: C₂H₂(g) + H₂O(g) ⇌ CH₃CHO(g)، ΔH° = −151 kJ. قرر ما إذا كان رفع درجة الحرارة أو خفضها ينتج المزيد من CH₃CHO، وبيّن كيف تتغير قيمة Keq في الحالة التي اخترتها، مع التبرير.', null, null, null, 'تحليل', 'قرار مع تبرير', 'صعب', 'الكتاب ص 97 — سؤال 15')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
