insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'في التفاعل الطارد تُعدّ الحرارة ناتجًا: CO + 3H₂ ⇌ CH₄ + H₂O + حرارة. رفع درجة الحرارة جهد يخففه النظام باستهلاك الحرارة، فيزاح نحو اليسار ويقل تركيز CH₄.', '["الحرارة ناتج في التفاعل الطارد؛ فإضافتها تزيح الاتزان نحو اليسار لا اليمين.","الحرارة تؤثر في التفاعلين؛ والنظام يزاح في الاتجاه الذي يستهلك الحرارة، وهو العكسي هنا.","تُعامل الحرارة كناتج في التفاعل الطارد، وتغير درجة الحرارة يغير الموضع وKeq معًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-06T22:20:31.221Z"}'::jsonb),
('mcq', 2, 1, 'التفاعل ماص للحرارة والحرارة فيه متفاعل؛ فرفع درجة الحرارة يزيح الاتزان نحو اليمين لاستهلاك الحرارة، فيتكون مزيد من PCl₃ وCl₂.', '["الحرارة متفاعل هنا؛ فإضافتها تزيح الاتزان نحو النواتج لا نحو المتفاعلات.","","تغير درجة الحرارة يغير موضع الاتزان وKeq، فتتغير التراكيز.","الوعاء مغلق ولا يخرج منه Cl₂؛ وتركيزه يزداد بالإزاحة نحو اليمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-06T22:20:31.221Z"}'::jsonb),
('mcq', 3, 0, 'بعد t₁ يتناقص [C] ويتزايد [A] و[B] تدريجيًّا دون قفزة، أي أزيح الاتزان نحو اليسار. وفي التفاعل الطارد تكون الحرارة ناتجًا، فالإزاحة نحو اليسار تستهلك حرارة، وهذا يحدث عند رفع درجة الحرارة.', '["","خفض درجة حرارة تفاعل طارد يزيحه نحو اليمين (اتجاه إنتاج الحرارة)، لا اليسار.","المنحنى يُظهر تناقص [C] وتزايد [A] و[B]، أي إزاحة نحو اليسار لا اليمين.","المنحنى يُظهر إزاحة نحو اليسار (تناقص الناتج C)، فلا يتفق مع الإزاحة نحو اليمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-06T22:20:31.221Z"}'::jsonb),
('mcq', 4, 2, 'التفاعل الأمامي طارد للحرارة (الحرارة ناتج)؛ فخفض درجة الحرارة جهد يخففه النظام بإنتاج حرارة، فيزاح نحو اليمين ويزداد تركيز O₂.', '["الحرارة ناتج هنا؛ وخفضها يزيح الاتزان نحو إنتاج الحرارة، أي نحو اليمين.","الإزاحة نحو اليمين تنتج O₂، فيزداد تركيزه.","","عدد مولات الغاز يخص أثر الحجم والضغط، أما خفض درجة الحرارة فيزيح الاتزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-06T22:20:31.221Z"}'::jsonb),
('mcq', 5, 1, 'Keq تقل من 8.6 عند 300 K إلى 1.1 عند 600 K؛ أي إن رفع الحرارة يزيح الاتزان نحو X (المتفاعل)، وهذا سلوك تفاعل أمامي طارد للحرارة تكون الحرارة فيه ناتجًا.', '["لو كان ماصًّا لزادت Keq بارتفاع درجة الحرارة، والمنحنى يُظهر تناقصها.","","تناقص Keq بارتفاع الحرارة يعني أن [Y] النسبي يقل، أي إن الإزاحة نحو X.","Keq يتغير بتغير درجة الحرارة، وهي العامل الوحيد الذي يغيره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-06T22:20:31.222Z"}'::jsonb),
('mcq', 6, 3, 'الحرارة متفاعل في هذا التفاعل الماص؛ فرفع درجة الحرارة يزيح الاتزان نحو اليمين لاستهلاكها، فيزداد تركيز NO.', '["خفض الحرارة في تفاعل ماص يزيح الاتزان نحو اليسار فيقل NO.","الحرارة مكتوبة مع المتفاعلات، فالتفاعل الأمامي ماص لا طارد.","تغير درجة الحرارة يغير موضع الاتزان وقيمة Keq.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-06T22:20:31.222Z"}'::jsonb),
('mcq', 7, 2, 'التفكك ماص للحرارة، فالحرارة متفاعل؛ ورفع درجة الحرارة في الصيف يزيح الاتزان نحو اليمين فينطلق مزيد من NH₃، فيكون الاستنشاق أكثر فعالية.', '["التفاعل ماص؛ والبرودة تزيح الاتزان نحو اليسار فيقل NH₃ المنطلق.","رفع الحرارة يزيد Keq للتفاعل الأمامي الماص لا العكسي، والتعليل هنا خاطئ.","","عدم كتابة المادة الصلبة في Keq لا يمنع تأثر الاتزان بدرجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-06T22:20:31.222Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g) + حرارة؛ لأن التفاعل الأمامي طارد فالحرارة ناتج. (ب) رفع درجة الحرارة يعني إضافة ناتج، فيزاح الاتزان نحو اليسار لاستهلاك الحرارة، فيقل [CH₄]. (ج) خفض درجة الحرارة يعني إزالة ناتج، فيزاح الاتزان نحو اليمين لإنتاج الحرارة، فيقل [CO] لأنه يُستهلك.', '["كتابة الحرارة في جهة النواتج","رفع الحرارة: إزاحة نحو اليسار ونقص CH₄","خفض الحرارة: إزاحة نحو اليمين ونقص CO"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الثلاثة صحيحة مع التعليل"},{"level":"3–4 درجات","description":"جزآن صحيحان أو الثلاثة دون تعليل كافٍ"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الحرارة مع المتفاعلات في التفاعل الطارد","القول إن التسخين يزيح كل تفاعل نحو النواتج","القول إن [CO] يزداد عند التبريد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-06T22:20:31.222Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التفاعل الأمامي ماص للحرارة (الحرارة متفاعل). عند رفع درجة الحرارة يزاح الاتزان نحو اليمين لاستهلاك الحرارة: يزداد [Cl₂] ويقل [PCl₅]، وتزداد قيمة Keq لأن النواتج أصبحت أكثر نسبيًّا ودرجة الحرارة هي العامل الذي يغير Keq. وعند خفض درجة الحرارة يزاح الاتزان نحو اليسار لإنتاج الحرارة، فيقل [PCl₃].', '["تحديد أن الحرارة متفاعل (ماص)","رفع الحرارة: يزداد Cl₂ ويقل PCl₅","رفع الحرارة: تزداد Keq","خفض الحرارة: يقل PCl₃"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد نوع التفاعل","marks":1},{"element":"أثر الرفع في التركيزين","marks":1},{"element":"أثر الرفع في Keq","marks":1},{"element":"أثر الخفض في PCl₃","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن Keq لا تتغير بتغير درجة الحرارة","عكس اتجاه الإزاحة في التفاعل الماص"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-06T22:20:31.222Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التفاعل الأمامي طارد للحرارة (ΔH° سالبة)، فالحرارة ناتج: C₂H₂ + H₂O ⇌ CH₃CHO + حرارة. خفض درجة الحرارة جهد يخففه النظام بإنتاج حرارة، أي بالإزاحة نحو اليمين، فيتكون مزيد من CH₃CHO. وبما أن الإزاحة نحو النواتج نتجت عن تغير درجة الحرارة فإن قيمة Keq تزداد عند خفض درجة الحرارة. أما رفعها فيزيح الاتزان نحو اليسار ويقلل CH₃CHO.', '["ΔH° سالبة: الحرارة ناتج","القرار: خفض درجة الحرارة","التبرير بالإزاحة نحو اليمين","Keq تزداد عند الخفض"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير إشارة ΔH°","marks":1},{"element":"القرار الصحيح","marks":1},{"element":"التبرير بمبدأ لوتشاتلييه","marks":1},{"element":"تغير Keq","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار رفع الحرارة لأنه يسرّع التفاعل","القول إن Keq ثابتة عند تغير درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-06T22:20:31.223Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C3-L2-O03') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L2-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'قُلِّل حجم الوعاء الذي يحتوي على النظام المتزن CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g) عند درجة حرارة ثابتة. في أي اتجاه يزاح الاتزان؟', null, null, '["نحو اليمين، لأن عدد مولات الغاز في النواتج أقل","نحو اليسار، لأن عدد مولات الغاز في المتفاعلات أكبر","نحو اليسار، لأن تقليل الحجم يقلل الضغط","لا يزاح، لأن جميع المواد في الحالة الغازية"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'سهل', 'الكتاب ص 93–94 — التغير في الحجم والضغط'),
('mcq', 2, 'قُلِّل حجم وعاء يحتوي على النظام المتزن H₂(g) + Cl₂(g) ⇌ 2HCl(g) عند درجة حرارة ثابتة. كيف يتأثر موضع الاتزان؟', null, null, '["يزاح نحو اليمين، لأن HCl مركب واحد فقط","يزاح نحو اليسار، لأن في المتفاعلات مادتين","لا يتأثر، لأن عدد مولات الغاز متساوٍ في الطرفين","يزاح نحو اليمين، لأن زيادة الضغط تزيد النواتج دائمًا"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'متوسط', 'الكتاب ص 94، 97 — سؤال 14'),
('mcq', 3, 'يمثل المنحنى الآتي تراكيز N₂O₄ وNO₂ في النظام المتزن N₂O₄(g) ⇌ 2NO₂(g) داخل وعاء مغلق عند درجة حرارة ثابتة، وقد حدث تغير عند اللحظة t₁. ما التغير الذي حدث، وكيف استجاب النظام؟', null, '[{"src":"qimg/chem22/c3-l2-volume.svg","alt":"رسم بياني لنظام N₂O₄(g) ⇌ 2NO₂(g) في وعاء مغلق: المحور الرأسي «التركيز (mol/L)» من 0 إلى 1.0، والمحور الأفقي «الزمن»، وعليه خط رأسي متقطع عند اللحظة t₁. منحنى أزرق لـ [N₂O₄] ومنحنى بني لـ [NO₂]. قبل t₁ الخطان أفقيان ثابتان: [N₂O₄] = 0.40 mol/L و[NO₂] = 0.20 mol/L. عند t₁ يقفز التركيزان كلاهما فجأة إلى مثلي قيمتيهما: [N₂O₄] إلى 0.80 mol/L و[NO₂] إلى 0.40 mol/L. بعد ذلك يتزايد [N₂O₄] تدريجيًّا حتى يثبت عند نحو 0.85 mol/L، ويتناقص [NO₂] تدريجيًّا حتى يثبت عند نحو 0.29 mol/L."}]'::jsonb, '["أضيفت كمية من N₂O₄ فقط، فأزيح الاتزان نحو NO₂","قُلِّل حجم الوعاء إلى النصف، فأزيح الاتزان نحو N₂O₄","زيد حجم الوعاء إلى المثلين، فأزيح الاتزان نحو NO₂","أضيفت كمية من NO₂ فقط، فأزيح الاتزان نحو N₂O₄"]'::jsonb, 'تحليل', 'تفسير منحنى', 'صعب', 'الكتاب ص 93–94 — الشكل 3-13'),
('mcq', 4, 'زيد حجم الوعاء الذي يحتوي على النظام المتزن 2SO₂(g) + O₂(g) ⇌ 2SO₃(g) عند درجة حرارة ثابتة. ماذا يحدث؟', null, null, '["يزاح الاتزان نحو اليمين، فتزداد كمية SO₃ (عدد مولاته)","يزاح الاتزان نحو اليسار، فتزداد كمية SO₃ (عدد مولاته)","لا يزاح الاتزان، لأن الحجم لا يؤثر في الأنظمة الغازية","يزاح الاتزان نحو اليسار، فتزداد كمية SO₂ (عدد مولاته)"]'::jsonb, 'تطبيق', 'توقع اتجاه الإزاحة', 'متوسط', 'الكتاب ص 94، 97 — سؤال 14'),
('mcq', 5, 'يتفكك كربونات الماغنسيوم وفق الاتزان: MgCO₃(s) ⇌ MgO(s) + CO₂(g). كيف يُنظَّم الضغط لتعزيز تكوين النواتج؟', null, null, '["يُرفع الضغط، لأن المتفاعلات مادة صلبة واحدة","يُرفع الضغط، لأن النواتج تحتوي على مادتين","يُخفض الضغط، لأن الغاز موجود في جهة النواتج فقط","لا أثر للضغط، لأن المواد الصلبة لا تتأثر به"]'::jsonb, 'تطبيق', 'اقتراح ظرف', 'صعب', 'الكتاب ص 113 — سؤال 56'),
('mcq', 6, 'أيّ الأنظمة المتزنة الآتية لا يتأثر موضع اتزانه بتقليل حجم الوعاء عند درجة حرارة ثابتة؟', null, null, '["N₂(g) + 3H₂(g) ⇌ 2NH₃(g)","2SO₃(g) ⇌ 2SO₂(g) + O₂(g)","N₂O₄(g) ⇌ 2NO₂(g)","H₂(g) + I₂(g) ⇌ 2HI(g)"]'::jsonb, 'فهم', 'تمييز أمثلة', 'متوسط', 'الكتاب ص 94 — عدد مولات المتفاعلات مقابل عدد مولات النواتج'),
('mcq', 7, 'لماذا يُعدّ تقليل حجم وعاء يحتوي على نظام غازي متزن جهدًا على النظام عند درجة حرارة ثابتة؟', null, null, '["لأنه يزيد الضغط بزيادة تصادمات جسيمات الغاز مع جدران الوعاء","لأنه يرفع درجة حرارة النظام فيغير قيمة Keq","لأنه يقلل عدد جسيمات الغاز الموجودة في الوعاء","لأنه يضيف مادة متفاعلة جديدة إلى الوعاء"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 94 — الضغط وعدد جسيمات الغاز'),
('essay', 1, 'وضح كيف يؤثر تقليل حجم وعاء التفاعل عند درجة حرارة ثابتة في موضع الاتزان لكل من النظامين الآتيين، مستعينًا بعدد مولات الغاز:
(أ) 2SO₂(g) + O₂(g) ⇌ 2SO₃(g)
(ب) H₂(g) + Cl₂(g) ⇌ 2HCl(g)', null, null, null, 'تطبيق', 'توقع اتجاه الإزاحة', 'متوسط', 'الكتاب ص 97 — سؤال 14'),
('essay', 2, 'يمثل المنحنى الآتي تراكيز N₂O₄ وNO₂ في النظام المتزن N₂O₄(g) ⇌ 2NO₂(g) عند درجة حرارة ثابتة، وقد قُلِّل حجم الوعاء إلى النصف عند اللحظة t₁. (أ) فسّر قفز التركيزين معًا عند t₁. (ب) فسّر تغير التركيزين بعد t₁ بمبدأ لوتشاتلييه. (ج) احسب Keq قبل t₁ وبعد الاتزان الجديد ([N₂O₄] = 0.85 mol/L، [NO₂] = 0.29 mol/L تقريبًا) وعلّق على النتيجة.', null, '[{"src":"qimg/chem22/c3-l2-volume.svg","alt":"رسم بياني لنظام N₂O₄(g) ⇌ 2NO₂(g) في وعاء مغلق: المحور الرأسي «التركيز (mol/L)» من 0 إلى 1.0، والمحور الأفقي «الزمن»، وعليه خط رأسي متقطع عند اللحظة t₁. منحنى أزرق لـ [N₂O₄] ومنحنى بني لـ [NO₂]. قبل t₁ الخطان أفقيان ثابتان: [N₂O₄] = 0.40 mol/L و[NO₂] = 0.20 mol/L. عند t₁ يقفز التركيزان كلاهما فجأة إلى مثلي قيمتيهما: [N₂O₄] إلى 0.80 mol/L و[NO₂] إلى 0.40 mol/L. بعد ذلك يتزايد [N₂O₄] تدريجيًّا حتى يثبت عند نحو 0.85 mol/L، ويتناقص [NO₂] تدريجيًّا حتى يثبت عند نحو 0.29 mol/L."}]'::jsonb, null, 'تحليل', 'تفسير منحنى وحساب', 'صعب', 'الكتاب ص 93–94 — الشكل 3-13'),
('essay', 3, 'إذا أعطيت التفاعلين الآتيين عند الاتزان:
(أ) N₂(g) + 3H₂(g) ⇌ 2NH₃(g)
(ب) H₂(g) + Cl₂(g) ⇌ 2HCl(g)
فسّر لماذا يسبب تغيير حجم الوعاء تغير موضع الاتزان في (أ) ولا يؤثر في (ب)، ثم بيّن كيف تخفف الإزاحة في (أ) من أثر زيادة الضغط عند تقليل الحجم.', null, null, null, 'تطبيق', 'تفسير مقارن', 'متوسط', 'الكتاب ص 94، 113 — سؤال 54')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L2-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
