from (values
('mcq', 1, 0, 'في المتفاعلات 4 mol من الغاز (1 CO + 3 H₂) وفي النواتج 2 mol (1 CH₄ + 1 H₂O). تقليل الحجم يزيد الضغط، فيخففه النظام بالإزاحة نحو العدد الأقل من مولات الغاز، أي نحو اليمين.', '["","زيادة الضغط تزيح الاتزان نحو العدد الأقل من مولات الغاز (2 mol في النواتج)، لا نحو الأكبر.","تقليل الحجم عند درجة حرارة ثابتة يزيد الضغط لا يقلله.","كون المواد كلها غازية لا يمنع الإزاحة؛ المهم أن عدد مولات الغاز مختلف في الطرفين (4 مقابل 2)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-06T22:20:31.223Z"}'::jsonb),
('mcq', 2, 2, 'في المتفاعلات 2 mol من الغاز (1 H₂ + 1 Cl₂) وفي النواتج 2 mol من HCl؛ فلا يوجد اتجاه يقلل عدد مولات الغاز، ولذلك لا يؤثر تغيير الحجم في موضع الاتزان.', '["تُعدّ مولات الغاز لا أنواع المواد؛ وفي النواتج 2 mol كما في المتفاعلات.","عدد أنواع المواد لا يحدد الإزاحة؛ عدد مولات الغاز متساوٍ (2 = 2).","","زيادة الضغط تزيح الاتزان نحو العدد الأقل من مولات الغاز فقط، ولا أقل هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-06T22:20:31.223Z"}'::jsonb),
('mcq', 3, 1, 'تضاعف التركيزان فجأة عند t₁، وهذا ما يحدث عند تقليل الحجم إلى النصف (زيادة الضغط). ثم تناقص [NO₂] وتزايد [N₂O₄]؛ أي أزيح الاتزان نحو N₂O₄، وهو الطرف الذي فيه عدد أقل من مولات الغاز (1 mol مقابل 2 mol).', '["قفز التركيزان معًا إلى مثليهما، وإضافة N₂O₄ وحده لا تغير [NO₂] فجأة؛ ثم إن [NO₂] تناقص بعد t₁.","","زيادة الحجم تخفض التراكيز إلى النصف، والمنحنى يُظهر تضاعفها.","اتجاه الإزاحة صحيح، لكن إضافة NO₂ وحده لا ترفع [N₂O₄] فجأة عند t₁، والمنحنى يُظهر قفز التركيزين معًا إلى مثليهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.224Z"}'::jsonb),
('mcq', 4, 3, 'زيادة الحجم تقلل الضغط، فيخفف النظام الجهد بزيادة عدد جسيمات الغاز، أي بالإزاحة نحو الطرف الذي فيه 3 mol من الغاز (المتفاعلات)، فتزداد كمية SO₂ وO₂.', '["زيادة الحجم تقلل الضغط، فيزاح الاتزان نحو العدد الأكبر من مولات الغاز (3 mol في المتفاعلات).","الإزاحة نحو اليسار تستهلك SO₃ فتقل كميته لا تزداد.","الحجم يؤثر في الأنظمة الغازية إذا اختلف عدد مولات الغاز في الطرفين، وهو مختلف هنا (3 مقابل 2).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-06T22:20:31.224Z"}'::jsonb),
('mcq', 5, 2, 'عدد مولات الغاز صفر في المتفاعلات و1 mol (CO₂) في النواتج. خفض الضغط (زيادة الحجم) يخففه النظام بزيادة عدد جسيمات الغاز، أي بالإزاحة نحو اليمين وتكوين مزيد من النواتج.', '["المواد الصلبة لا تُحسب؛ وفي النواتج 1 mol من الغاز مقابل صفر في المتفاعلات، فرفع الضغط يزيح الاتزان نحو اليسار.","تُعدّ مولات الغاز فقط لا عدد المواد؛ ورفع الضغط يقلل النواتج هنا.","","CO₂ غاز، فتغير الضغط يغير موضع الاتزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-06T22:20:31.224Z"}'::jsonb),
('mcq', 6, 3, 'في H₂ + I₂ ⇌ 2HI عدد مولات الغاز 2 في كل طرف؛ فلا يوجد اتجاه يقلل عدد الجسيمات، ولا يتأثر موضع الاتزان بتغيير الحجم.', '["في المتفاعلات 4 mol من الغاز وفي النواتج 2 mol، فيزاح الاتزان نحو اليمين.","في المتفاعلات 2 mol من الغاز وفي النواتج 3 mol، فيزاح الاتزان نحو اليسار.","في المتفاعلات 1 mol من الغاز وفي النواتج 2 mol، فيزاح الاتزان نحو اليسار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-06T22:20:31.225Z"}'::jsonb),
('mcq', 7, 0, 'الضغط يعتمد على عدد جسيمات الغاز التي تتصادم مع جدران الوعاء؛ فتقليل الحجم عند درجة حرارة ثابتة يزيد الضغط، وهذا جهد يخففه النظام بالإزاحة نحو العدد الأقل من مولات الغاز.', '["","درجة الحرارة ثابتة في هذه الحالة؛ وتقليل الحجم لا يغير Keq.","عدد الجسيمات لا يتغير لحظة تقليل الحجم؛ الذي يزداد هو عددها في وحدة الحجم والضغط.","تقليل الحجم لا يضيف مادة؛ بل يزيد تراكيز كل الغازات والضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-06T22:20:31.225Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تقليل الحجم يزيد الضغط، فيزاح الاتزان نحو الطرف الذي فيه عدد أقل من مولات الغاز. (أ) في المتفاعلات 3 mol من الغاز وفي النواتج 2 mol، فيزاح الاتزان نحو اليمين ويتكون مزيد من SO₃. (ب) في كل طرف 2 mol من الغاز، فلا يؤثر تغيير الحجم في موضع الاتزان.', '["تقليل الحجم يزيد الضغط","(أ) عدّ المولات 3 مقابل 2","(أ) الإزاحة نحو اليمين","(ب) 2 = 2 فلا إزاحة"]'::jsonb, '[]'::jsonb, '[{"element":"الربط بين الحجم والضغط","marks":1},{"element":"(أ) عدّ المولات","marks":1},{"element":"(أ) اتجاه الإزاحة","marks":1},{"element":"(ب) لا إزاحة مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ أنواع المواد بدل مولات الغاز","القول إن النظام (ب) يزاح نحو اليمين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-06T22:20:31.225Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تقليل الحجم إلى النصف يضاعف تركيز كل غاز لحظيًّا (من 0.40 إلى 0.80 mol/L لـ N₂O₄، ومن 0.20 إلى 0.40 mol/L لـ NO₂)، ويزيد الضغط. (ب) يخفف النظام زيادة الضغط بالإزاحة نحو العدد الأقل من مولات الغاز، أي نحو N₂O₄ (1 mol مقابل 2 mol)، فيتناقص [NO₂] ويتزايد [N₂O₄]. (ج) قبل t₁: Keq = (0.20)² ÷ 0.40 = 0.10، وبعد الاتزان الجديد: Keq = (0.29)² ÷ 0.85 ≈ 0.099 ≈ 0.10؛ فالقيمة لم تتغير لأن درجة الحرارة ثابتة، والذي تغير هو موضع الاتزان فقط.', '["تقليل الحجم يضاعف التراكيز لحظيًّا","الإزاحة نحو N₂O₄ (مولات غاز أقل)","Keq قبل = 0.10","Keq بعد ≈ 0.10 فلم تتغير"]'::jsonb, '["Keq = [NO₂]² ÷ [N₂O₄]","قبل t₁: (0.20)² ÷ 0.40 = 0.10","بعد الاتزان الجديد: (0.29)² ÷ 0.85 ≈ 0.099 ≈ 0.10","القيمتان متساويتان تقريبًا: تغير الموضع ولم تتغير Keq"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج) الحسابان والتعليق","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"كل الأجزاء صحيحة مع الحسابين والتعليق"},{"level":"3–4 درجات","description":"التفسيران صحيحان مع خطأ في الحساب أو نقص في التعليق"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تربيع [NO₂] في تعبير Keq","القول إن الإزاحة نحو NO₂ لأنه الناتج","استعمال تراكيز لحظة t₁ على أنها تراكيز اتزان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.225Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في (أ) عدد مولات الغاز في المتفاعلات 4 (1 + 3) وفي النواتج 2؛ فعند تقليل الحجم يزداد الضغط فيزاح الاتزان نحو اليمين حيث عدد مولات الغاز أقل. أما في (ب) فعدد مولات الغاز 2 في كل طرف، فلا يوجد اتجاه يغير عدد الجسيمات، فلا يؤثر تغيير الحجم. والإزاحة نحو اليمين في (أ) تقلل العدد الكلي لجسيمات الغاز في الوعاء، فيقل الضغط داخله، لكنه لا يعود إلى قيمته الأصلية تمامًا.', '["(أ) 4 mol مقابل 2 mol","(ب) 2 mol مقابل 2 mol","الإزاحة نحو اليمين تقلل عدد الجسيمات","الضغط يقل لكن لا يعود إلى قيمته الأصلية"]'::jsonb, '[]'::jsonb, '[{"element":"عدّ المولات في (أ)","marks":1},{"element":"عدّ المولات في (ب)","marks":1},{"element":"تفسير تخفيف الضغط","marks":1},{"element":"عدم عودة الضغط إلى قيمته الأصلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["احتساب أنواع المواد بدل المولات","القول إن الضغط يعود إلى قيمته الأصلية تمامًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-06T22:20:31.226Z"}'::jsonb)
