('mcq', 1, 'كيف تؤثر إضافة عامل محفز إلى نظام في حالة اتزان في موضع الاتزان؟', null, null, '["تزيح الاتزان نحو النواتج فتزداد كميتها","لا تغير موضع الاتزان ولا كمية النواتج","تزيح الاتزان نحو المتفاعلات فتزداد كميتها","تزيد قيمة Keq فتزداد نسبة النواتج"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 95 — العوامل المحفزة والاتزان'),
('mcq', 2, 'ما سبب عدم تأثر موضع الاتزان بإضافة عامل محفز؟', null, null, '["أنه يزيد سرعتي التفاعلين الأمامي والعكسي بالتساوي","أنه يزيد سرعة التفاعل الأمامي وحده","أنه يُستهلك في التفاعل فيزول أثره سريعًا","أنه يرفع طاقة التنشيط للتفاعلين معًا"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 95 — العوامل المحفزة والاتزان'),
('mcq', 3, 'يوضح المنحنى الآتي تركيز ناتج تفاعل مع الزمن في تجربتين متماثلتين، إحداهما دون محفز والأخرى مع محفز. ماذا يُظهر المنحنى عن أثر المحفز؟', null, '[{"src":"qimg/chem22/c3-l2-catalyst.svg","alt":"رسم بياني: المحور الرأسي «تركيز الناتج (mol/L)» من 0 إلى 0.8، والمحور الأفقي «الزمن». منحنيان يبدآن من الصفر عند بداية التفاعل نفسه وعند درجة الحرارة نفسها: منحنى أزرق متصل «دون محفز» يرتفع ببطء ولا يستوي إلا في نهاية المدة، ومنحنى أحمر متقطع «مع محفز» يرتفع بسرعة ويستوي مبكرًا. يستوي المنحنيان كلاهما عند القيمة نفسها: 0.60 mol/L."}]'::jsonb, '["يزيد تركيز الناتج عند الاتزان إلى أكثر من 0.60 mol/L","يبطئ الوصول إلى الاتزان لكنه يزيد كمية الناتج","يصل التفاعل إلى الاتزان أسرع، بتركيز الناتج نفسه","يمنع التفاعل العكسي فيكتمل تحول المتفاعلات"]'::jsonb, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 95 — العوامل المحفزة والاتزان'),
('mcq', 4, 'يُنتَج الميثانول وفق الاتزان: CO(g) + 2H₂(g) ⇌ CH₃OH(g) + حرارة. ما أثر إضافة عامل محفز إلى هذا النظام المتزن؟', null, null, '["يزاح الاتزان نحو اليمين فتزداد كمية CH₃OH","يزاح الاتزان نحو اليسار لأن المحفز يمتص الحرارة","تقل قيمة Keq لأن التفاعل العكسي يتسارع","لا يتغير موضع الاتزان ولا كمية CH₃OH"]'::jsonb, 'تطبيق', 'توقع أثر', 'متوسط', 'الكتاب ص 112 — سؤال 50'),
('mcq', 5, 'يوفر العامل المحفز مسارًا بديلًا للتفاعل قمته (المعقد المنشط) أخفض، دون أن يغير طاقة المتفاعلات أو طاقة النواتج. إذا قلّت طاقة التنشيط للتفاعل الأمامي في نظام متزن بمقدار 20 kJ عند إضافة محفز، فماذا يحدث لطاقة التنشيط للتفاعل العكسي؟', null, null, '["تقل بمقدار 20 kJ أيضًا، فيتسارع التفاعلان بالتساوي","تزداد بمقدار 20 kJ، فيتباطأ التفاعل العكسي","لا تتغير، فيتسارع التفاعل الأمامي وحده","تصبح مساوية لطاقة تنشيط التفاعل الأمامي"]'::jsonb, 'تحليل', 'تفسير بالطاقة', 'صعب', 'الكتاب ص 95 — العوامل المحفزة والاتزان'),
('mcq', 6, 'لماذا تُستعمل المحفزات في عمليات صناعية تصل إلى الاتزان، مع أنها لا تزيد كمية النواتج عند الاتزان؟', null, null, '["لأنها تزيد قيمة Keq فتزداد نسبة النواتج","لأنها تقلل الزمن اللازم للوصول إلى الاتزان","لأنها تزيح الاتزان نحو النواتج عند أي درجة حرارة","لأنها تتحول إلى نواتج إضافية مع الوقت"]'::jsonb, 'فهم', 'تطبيق صناعي', 'متوسط', 'الكتاب ص 95 — العوامل المحفزة والاتزان'),
('mcq', 7, 'أضاف طالب عاملًا محفزًا إلى نظام في حالة اتزان، وقال: «ستتغير تراكيز المواد حتى يصل النظام إلى موضع اتزان جديد». ما تقويمك لعبارته؟', null, null, '["صحيحة؛ لأن المحفز جهد يزيح الاتزان نحو النواتج","صحيحة؛ لأن المحفز يغير قيمة Keq","خاطئة؛ فالسرعتان تزدادان بالتساوي وتبقى التراكيز كما هي","خاطئة؛ لأن المحفز يوقف التفاعلين الأمامي والعكسي"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 95 — العوامل المحفزة والاتزان'),
('essay', 1, 'فسّر لماذا لا تؤثر إضافة عامل محفز في موضع الاتزان مع أنه يزيد سرعة التفاعل، ثم اذكر الفائدة التي يحققها المحفز في التفاعلات التي تصل إلى الاتزان.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 95 — العوامل المحفزة والاتزان'),
('essay', 2, 'يوضح المنحنى الآتي تركيز ناتج تفاعل مع الزمن في تجربتين متماثلتين عند درجة الحرارة نفسها، إحداهما دون محفز والأخرى مع محفز. قارن بين المنحنيين من حيث: الزمن اللازم للوصول إلى الاتزان، وتركيز الناتج عند الاتزان، ثم فسّر نتيجتك.', null, '[{"src":"qimg/chem22/c3-l2-catalyst.svg","alt":"رسم بياني: المحور الرأسي «تركيز الناتج (mol/L)» من 0 إلى 0.8، والمحور الأفقي «الزمن». منحنيان يبدآن من الصفر عند بداية التفاعل نفسه وعند درجة الحرارة نفسها: منحنى أزرق متصل «دون محفز» يرتفع ببطء ولا يستوي إلا في نهاية المدة، ومنحنى أحمر متقطع «مع محفز» يرتفع بسرعة ويستوي مبكرًا. يستوي المنحنيان كلاهما عند القيمة نفسها: 0.60 mol/L."}]'::jsonb, null, 'فهم', 'مقارنة منحنيين', 'متوسط', 'الكتاب ص 95 — العوامل المحفزة والاتزان'),
('essay', 3, 'وُضعت الكميات نفسها من المتفاعلات في وعاءين متماثلين عند درجة الحرارة نفسها، وأضيف عامل محفز إلى الوعاء الثاني فقط. قارن بين الوعاءين في: (أ) كمية النواتج بعد زمن قصير من البدء وقبل وصول أي منهما إلى الاتزان. (ب) كمية النواتج بعد وصول الوعاءين كليهما إلى الاتزان. (ج) قيمة Keq. وفسّر كل إجابة.', null, null, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 95 — العوامل المحفزة والاتزان')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
