from (values
('mcq', 1, 1, 'العامل المحفز يزيد سرعة التفاعل بالتساوي في الاتجاهين، فيبقى موضع الاتزان وكمية النواتج دون تغيير.', '["المحفز يسرّع التفاعلين بالتساوي، فلا يفضل اتجاه النواتج.","","المحفز لا يفضل أي اتجاه، فلا يزيح الاتزان نحو المتفاعلات أيضًا.","Keq لا يغيرها إلا تغير درجة الحرارة، والمحفز لا يغيرها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-06T22:20:31.226Z"}'::jsonb),
('mcq', 2, 0, 'العامل المحفز يزيد سرعة التفاعل بالتساوي في كلا الاتجاهين؛ فتبقى السرعتان متساويتين ولا يتغير موضع الاتزان.', '["","لو سرّع الأمامي وحده لأزيح الاتزان نحو النواتج؛ لكنه يسرّع الاتجاهين بالتساوي.","المحفز لا يُستهلك في التفاعل، وسبب عدم الإزاحة تساوي أثره في الاتجاهين.","المحفز يقلل طاقة التنشيط لا يرفعها، فيزيد السرعتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-06T22:20:31.226Z"}'::jsonb),
('mcq', 3, 2, 'المنحنى المتقطع (مع محفز) يستوي مبكرًا، والمنحنى المتصل يستوي متأخرًا، وكلاهما عند 0.60 mol/L؛ فالمحفز يقصّر زمن الوصول إلى الاتزان دون أن يغير تركيز الناتج عنده.', '["المنحنيان يستويان عند 0.60 mol/L نفسها؛ فالمحفز لا يزيد كمية الناتج.","المنحنى مع المحفز يستوي أبكر لا أبطأ، ولا تزيد كمية الناتج.","","المحفز يسرّع التفاعل العكسي أيضًا، والمنحنى يستوي عند قيمة الاتزان نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-06T22:20:31.227Z"}'::jsonb),
('mcq', 4, 3, 'المحفز يسرّع التفاعلين الأمامي والعكسي بالتساوي؛ فالنظام المتزن يبقى متزنًا بالتراكيز نفسها، ولا تتغير كمية CH₃OH ولا Keq.', '["المحفز لا يفضل التفاعل الأمامي، فلا يزيد كمية CH₃OH عند الاتزان.","المحفز لا يمتص الحرارة ولا يغير درجة الحرارة، فلا يزيح الاتزان.","التفاعلان يتسارعان بالتساوي، وKeq لا يتغير إلا بتغير درجة الحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.227Z"}'::jsonb),
('mcq', 5, 0, 'المحفز يخفض قمة مسار التفاعل دون أن يغير طاقة المتفاعلات أو النواتج؛ فتقل طاقة التنشيط للاتجاهين بالمقدار نفسه (20 kJ)، ويتسارع التفاعلان بالتساوي فلا يتغير موضع الاتزان.', '["","المحفز يوفر مسارًا أقل طاقة للاتجاهين، فلا يرفع طاقة تنشيط أي منهما.","المسار الجديد نفسه يسلكه التفاعلان؛ فانخفاض القمة يقلل طاقة تنشيط العكسي أيضًا بالمقدار نفسه.","الفرق بين طاقتي التنشيط الأمامي والعكسي يساوي ΔH، ولا يغيره المحفز لأنه لا يغير طاقة المتفاعلات والنواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-06T22:20:31.227Z"}'::jsonb),
('mcq', 6, 1, 'مع المحفز يصل التفاعل إلى حالة الاتزان أسرع؛ فيُحصل على كمية النواتج نفسها في زمن أقل، وهذا مفيد اقتصاديًّا.', '["المحفز لا يغير Keq؛ فلا يغيرها إلا تغير درجة الحرارة.","","المحفز لا يزيح الاتزان في أي اتجاه.","المحفز لا يُستهلك ولا يتحول إلى نواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-06T22:20:31.227Z"}'::jsonb),
('mcq', 7, 2, 'العبارة خاطئة: المحفز يزيد سرعتي التفاعلين الأمامي والعكسي بالتساوي، فتبقى السرعتان متساويتين ويبقى النظام في موضع الاتزان نفسه بالتراكيز نفسها.', '["المحفز ليس جهدًا مزيحًا للاتزان؛ لأنه لا يفضل أي اتجاه.","المحفز لا يغير Keq، فلا يوجد موضع اتزان جديد.","","المحفز يسرّع التفاعلين ولا يوقفهما؛ فالتعليل هنا خاطئ وإن كان الحكم صحيحًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-06T22:20:31.227Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العامل المحفز يزيد سرعة التفاعل بالتساوي في الاتجاهين الأمامي والعكسي؛ لأنه يقلل طاقة التنشيط للاتجاهين. فإذا كان النظام متزنًا تبقى السرعتان متساويتين ولا تتغير التراكيز، فلا يتغير موضع الاتزان ولا كمية النواتج. وفائدته أن التفاعل يصل إلى حالة الاتزان أسرع، فنحصل على كمية النواتج نفسها في زمن أقل.', '["المحفز يسرّع الاتجاهين بالتساوي","السرعتان تبقيان متساويتين فلا يتغير الموضع","لا تتغير كمية النواتج","الفائدة: الوصول إلى الاتزان أسرع"]'::jsonb, '[]'::jsonb, '[{"element":"تسريع الاتجاهين بالتساوي","marks":1},{"element":"بقاء السرعتين متساويتين","marks":1},{"element":"ثبات كمية النواتج","marks":1},{"element":"الفائدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحفز يسرّع التفاعل الأمامي فقط","القول إن المحفز يزيد كمية النواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-06T22:20:31.228Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الزمن: المنحنى مع المحفز (المتقطع) يستوي مبكرًا، أي يصل التفاعل إلى الاتزان في زمن أقل من التجربة دون محفز. التركيز عند الاتزان: يستوي المنحنيان عند القيمة نفسها (0.60 mol/L). التفسير: المحفز يزيد سرعة التفاعلين الأمامي والعكسي بالتساوي، فيصل النظام إلى الاتزان أسرع دون أن يغير كمية النواتج المتكونة أو موضع الاتزان.', '["مع المحفز يصل إلى الاتزان أسرع","تركيز الناتج عند الاتزان متساوٍ (0.60 mol/L)","التفسير: تسريع الاتجاهين بالتساوي"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة الزمن","marks":1},{"element":"مقارنة التركيز عند الاتزان","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحفز يرفع التركيز النهائي","الخلط بين المنحنيين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-06T22:20:31.228Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) كمية النواتج في الوعاء الثاني أكبر؛ لأن المحفز يزيد سرعة التفاعل الأمامي فيتكون الناتج أسرع قبل الاتزان. (ب) كمية النواتج متساوية في الوعاءين؛ لأن المحفز يزيد سرعتي التفاعلين بالتساوي فلا يغير موضع الاتزان. (ج) قيمة Keq متساوية؛ لأن درجة الحرارة واحدة، والمحفز لا يغير Keq.', '["(أ) الثاني أكبر قبل الاتزان مع التعليل","(ب) متساوية عند الاتزان مع التعليل","(ج) Keq متساوية مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الثلاثة صحيحة مع التفسير"},{"level":"3–4 درجات","description":"جزآن صحيحان مع التفسير"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكميتين متساويتان في كل وقت","القول إن الوعاء الثاني فيه نواتج أكثر عند الاتزان","القول إن المحفز يغير Keq"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-06T22:20:31.228Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
