('mcq', 1, 'أيّ العوامل الآتية يغير قيمة Keq لتفاعل معين؟', null, null, '["تركيز المتفاعلات","ضغط النظام","العامل المحفز","درجة الحرارة"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 95، 97 — درجة الحرارة وKeq'),
('mcq', 2, 'عند إزاحة الاتزان استجابة لتغير التركيز أو الحجم، ماذا يحدث؟', null, null, '["يتغير موضع الاتزان وقيمة Keq معًا","تتغير قيمة Keq، ويبقى موضع الاتزان ثابتًا","يتغير موضع الاتزان، وتبقى قيمة Keq ثابتة","لا يتغير موضع الاتزان ولا قيمة Keq"]'::jsonb, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 97 — الخلاصة'),
('mcq', 3, 'يمثل المنحنى الآتي النظام المتزن A(g) + B(g) ⇌ C(g)، حيث Keq = [C] ÷ ([A][B]). ما قيمتا Keq عند الاتزان قبل اللحظة t₁ وبعد الوصول إلى الاتزان الجديد؟', null, '[{"src":"qimg/chem22/c3-l2-add-a.svg","alt":"رسم بياني: المحور الرأسي «التركيز (mol/L)» من 0 إلى 1.0، والمحور الأفقي «الزمن»، وعليه خط رأسي متقطع عند اللحظة t₁. ثلاثة منحنيات للمواد A (أزرق) وB (أخضر) وC (أحمر). قبل t₁ الخطوط الثلاثة أفقية ثابتة: [C] = 0.60 mol/L، و[A] = 0.40 mol/L، و[B] = 0.30 mol/L. عند t₁ يقفز [A] فجأة إلى 0.80 mol/L، ثم يتناقص تدريجيًّا حتى يثبت عند 0.70 mol/L. وبعد t₁ يتناقص [B] تدريجيًّا (دون قفزة) حتى يثبت عند 0.20 mol/L، ويتزايد [C] تدريجيًّا (دون قفزة) حتى يثبت عند 0.70 mol/L."}]'::jsonb, '["قبل t₁: 5.0، وبعد الاتزان الجديد: 5.0","قبل t₁: 5.0، وبعد الاتزان الجديد: 2.5","قبل t₁: 1.5، وبعد الاتزان الجديد: 1.0","قبل t₁: 0.20، وبعد الاتزان الجديد: 0.20"]'::jsonb, 'تطبيق', 'حساب من منحنى', 'متوسط', 'الكتاب ص 92 — الجدول 3-2'),
('mcq', 4, 'يمثل المنحنى الآتي النظام المتزن A(g) + B(g) ⇌ C(g) الطارد للحرارة، وقد تغيرت درجة حرارته عند t₁. كانت Keq = 5.0 قبل t₁، وعند الاتزان الجديد كانت [A] = 0.535 mol/L و[B] = 0.435 mol/L و[C] = 0.465 mol/L. ماذا حدث لقيمة Keq؟', null, '[{"src":"qimg/chem22/c3-l2-temp.svg","alt":"رسم بياني: المحور الرأسي «التركيز (mol/L)» من 0 إلى 1.0، والمحور الأفقي «الزمن»، وعليه خط رأسي متقطع عند اللحظة t₁. ثلاثة منحنيات للمواد A (أزرق) وB (أخضر) وC (أحمر). قبل t₁ الخطوط الثلاثة أفقية ثابتة: [C] = 0.60 mol/L، و[A] = 0.40 mol/L، و[B] = 0.30 mol/L. عند t₁ لا تحدث أي قفزة مفاجئة في أي منحنى، بل تتغير التراكيز تدريجيًّا: يتناقص [C] حتى يثبت عند نحو 0.47 mol/L، ويتزايد [A] حتى يثبت عند نحو 0.53 mol/L، ويتزايد [B] حتى يثبت عند نحو 0.43 mol/L."}]'::jsonb, '["بقيت 5.0، لأن تغير الحرارة لا يغير Keq","قلت من 5.0 إلى 2.0 تقريبًا","أصبحت 0.50 تقريبًا","زادت، لأن تركيزي A وB ازدادا"]'::jsonb, 'تحليل', 'حساب وتفسير', 'صعب', 'الكتاب ص 95، 97 — درجة الحرارة وKeq'),
('mcq', 5, 'في الاتزان N₂O₄(g) ⇌ 2NO₂(g)، ΔH° = +55.3 kJ، ماذا يحدث لقيمة Keq عند رفع درجة الحرارة؟', null, null, '["تقل، لأن الاتزان يزاح نحو N₂O₄","تزداد، لأن الاتزان يزاح نحو NO₂","لا تتغير، لأن Keq ثابتة لكل تفاعل","تقل، لأن التفاعل الأمامي ماص للحرارة"]'::jsonb, 'فهم', 'توقع تغير Keq', 'متوسط', 'الكتاب ص 95 — الشكل 3-14'),
('mcq', 6, 'قُلِّل حجم الوعاء الذي يحتوي على النظام المتزن N₂(g) + 3H₂(g) ⇌ 2NH₃(g) عند درجة حرارة ثابتة. ماذا يحدث لقيمة Keq؟', null, null, '["تزداد، لأن الاتزان يزاح نحو NH₃","تقل، لأن الضغط داخل الوعاء يزداد","تزداد، لأن عدد التصادمات يزداد","تبقى ثابتة، مع أن الاتزان يزاح نحو NH₃"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 94، 97 — التغير في الحجم والضغط'),
('mcq', 7, 'يبين الجدول الآتي قيم Keq للاتزان 2NO(g) + 2CO(g) ⇌ N₂(g) + 2CO₂(g) عند درجات حرارة مختلفة. عند أي درجة حرارة تكون نسبة النواتج إلى المتفاعلات عند الاتزان أكبر؟', '{"headers":["درجة الحرارة (K)","Keq"],"rows":[["700","9.10 × 10⁸⁷"],["800","1.04 × 10⁶⁶"],["900","4.66 × 10⁵⁴"],["1000","3.27 × 10⁴⁵"]]}'::jsonb, null, '["700 K","800 K","900 K","1000 K"]'::jsonb, 'تحليل', 'قراءة بيانات', 'متوسط', 'الكتاب ص 115 — الجدول 3-7'),
('essay', 1, 'قارن بين أثر كل مما يأتي في موضع الاتزان وفي قيمة Keq: (أ) إضافة مادة متفاعلة. (ب) تقليل حجم وعاء نظام غازي يختلف فيه عدد مولات الغاز في الطرفين. (ج) رفع درجة الحرارة. (د) إضافة عامل محفز.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 95، 97، 111 — الخلاصة'),
('essay', 2, 'يبين الجدول الآتي تراكيز المواد في موضعي اتزان للنظام CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g) عند 1200 K، قبل إضافة CO (الموضع 1) وبعدها (الموضع 2). احسب Keq لكل موضع، ثم ماذا تستنتج عن أثر تغير التركيز في قيمة Keq؟', '{"headers":["موضع الاتزان","[CO] (M)","[H₂] (M)","[CH₄] (M)","[H₂O] (M)"],"rows":[["1","0.30000","0.10000","0.05900","0.02000"],["2","0.99254","0.07762","0.06648","0.02746"]]}'::jsonb, null, null, 'تطبيق', 'حساب واستنتاج', 'متوسط', 'الكتاب ص 92 — الجدول 3-2'),
('essay', 3, 'يوضح المنحنى الآتي قيم Keq للاتزان X(g) ⇌ Y(g) عند درجات حرارة مختلفة. (أ) هل التفاعل الأمامي ماص أم طارد للحرارة؟ برر إجابتك بمبدأ لوتشاتلييه. (ب) توقع هل تكون Keq عند 700 K أكبر أم أصغر من 1.1. (ج) فسّر لماذا تغيرت Keq هنا، بينما لا تتغير عند تغير تركيز X.', null, '[{"src":"qimg/chem22/c3-l2-keq-t.svg","alt":"رسم بياني: المحور الرأسي «Keq» من 0 إلى 10، والمحور الأفقي «درجة الحرارة (K)». أربع نقاط موصولة بخط متناقص: عند 300 K قيمة Keq = 8.6، وعند 400 K قيمة Keq = 3.9، وعند 500 K قيمة Keq = 2.0، وعند 600 K قيمة Keq = 1.1. أي إن Keq تقل كلما ارتفعت درجة الحرارة."}]'::jsonb, null, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 95، 115 — درجة الحرارة وKeq والسؤال 86')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L2-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'Keq ثابتة لتفاعل معين عند درجة حرارة معينة؛ فدرجة الحرارة هي العامل الوحيد الذي يغير قيمتها.', '["تغير التركيز يغير موضع الاتزان فقط، وتبقى Keq ثابتة.","تغير الحجم أو الضغط يغير موضع الاتزان فقط، وتبقى Keq ثابتة.","المحفز لا يغير موضع الاتزان ولا قيمة Keq.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-06T22:20:31.229Z"}'::jsonb),
('mcq', 2, 2, 'عند إزاحة الاتزان استجابة لتغير التركيز أو الحجم يتغير موضع الاتزان، ولكن Keq تبقى ثابتة؛ أما التغير في درجة الحرارة فيغير الموضع وKeq معًا.', '["هذا ما يحدث عند تغير درجة الحرارة فقط، لا عند تغير التركيز أو الحجم.","العكس هو الصحيح: يتغير الموضع وتبقى Keq.","","تغير التركيز أو الحجم جهد يزيح الاتزان إلى موضع جديد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-06T22:20:31.229Z"}'::jsonb),
('mcq', 3, 0, 'قبل t₁: Keq = 0.60 ÷ (0.40 × 0.30) = 5.0. بعد الاتزان الجديد: Keq = 0.70 ÷ (0.70 × 0.20) = 5.0. فإضافة A غيرت موضع الاتزان ولم تغير Keq.', '["","القيمة 2.5 ناتجة عن استعمال [A] = 0.80 mol/L لحظة الإضافة، وهو ليس تركيز اتزان.","هذه القيم ناتجة عن إهمال [B] في المقام.","هذه القيم ناتجة عن قلب النسبة: ([A][B]) ÷ [C]؛ والنواتج تُكتب في البسط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.229Z"}'::jsonb),
('mcq', 4, 1, 'Keq الجديدة = 0.465 ÷ (0.535 × 0.435) ≈ 2.0؛ فقد قلت من 5.0 إلى 2.0، لأن رفع درجة حرارة التفاعل الطارد أزاح الاتزان نحو المتفاعلات وغيّر قيمة Keq.', '["تغير درجة الحرارة هو العامل الوحيد الذي يغير Keq، والحساب يعطي 2.0.","","هذه القيمة ناتجة عن قلب النسبة: ([A][B]) ÷ [C].","زيادة [A] و[B] في المقام ونقص [C] في البسط تجعل Keq أصغر لا أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.229Z"}'::jsonb),
('mcq', 5, 1, 'التفاعل الأمامي ماص للحرارة (الحرارة متفاعل)؛ فرفع درجة الحرارة يزيح الاتزان نحو NO₂، فيزداد [NO₂] ويقل [N₂O₄] وتزداد قيمة Keq = [NO₂]² ÷ [N₂O₄].', '["التفاعل ماص؛ ورفع الحرارة يزيحه نحو NO₂ لا نحو N₂O₄.","","Keq ثابتة عند درجة حرارة معينة فقط، وتتغير بتغيرها.","كون التفاعل ماصًّا يعني أن Keq تزداد بالتسخين لا تقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-06T22:20:31.229Z"}'::jsonb),
('mcq', 6, 3, 'تقليل الحجم يزيد الضغط فيزاح الاتزان نحو NH₃ (2 mol مقابل 4 mol)، لكن درجة الحرارة ثابتة فتبقى Keq ثابتة؛ والذي تغير هو موضع الاتزان فقط.', '["الإزاحة سببها تغير الحجم، وهذا يغير الموضع لا قيمة Keq.","تغير الضغط لا يغير Keq عند درجة حرارة ثابتة.","زيادة التصادمات تسرّع التفاعل ولا تغير قيمة Keq.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-06T22:20:31.230Z"}'::jsonb),
('mcq', 7, 0, 'كلما كبرت Keq كانت النواتج أكثر تفضيلًا؛ وأكبر قيمة لـ Keq في الجدول هي 9.10 × 10⁸⁷ عند 700 K.', '["","Keq عند 800 K (1.04 × 10⁶⁶) أصغر منها عند 700 K.","Keq عند 900 K (4.66 × 10⁵⁴) أصغر منها عند 700 K.","هذه أصغر قيمة لـ Keq في الجدول، فنسبة النواتج فيها أقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-06T22:20:31.230Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) إضافة متفاعل: يتغير موضع الاتزان (يزاح نحو النواتج)، وتبقى Keq ثابتة. (ب) تقليل الحجم: يتغير موضع الاتزان (نحو العدد الأقل من مولات الغاز)، وتبقى Keq ثابتة. (ج) رفع درجة الحرارة: يتغير موضع الاتزان وتتغير قيمة Keq معًا (تزداد في التفاعل الماص وتقل في الطارد). (د) إضافة محفز: لا يتغير موضع الاتزان ولا قيمة Keq، ويصل النظام إلى الاتزان أسرع.', '["(أ) الموضع يتغير وKeq ثابتة","(ب) الموضع يتغير وKeq ثابتة","(ج) الموضع وKeq يتغيران","(د) لا يتغير أي منهما"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن Keq تتغير بتغير التركيز","القول إن المحفز يغير Keq","نسيان أن الحرارة تغير الموضع وKeq معًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.230Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Keq = [CH₄][H₂O] ÷ ([CO][H₂]³). الموضع 1: (0.05900 × 0.02000) ÷ (0.30000 × (0.10000)³) = 3.933. الموضع 2: (0.06648 × 0.02746) ÷ (0.99254 × (0.07762)³) = 3.933. القيمتان متساويتان؛ فتغير التركيز غيّر موضع الاتزان (التراكيز) ولم يغير قيمة Keq، لأن درجة الحرارة لم تتغير.', '["كتابة تعبير Keq","حساب Keq للموضع 1 = 3.933","حساب Keq للموضع 2 = 3.933","الاستنتاج: Keq لا تتغير بتغير التركيز"]'::jsonb, '["Keq = [CH₄][H₂O] ÷ ([CO][H₂]³)","الموضع 1: (0.05900)(0.02000) ÷ [(0.30000)(0.10000)³] = 3.933","الموضع 2: (0.06648)(0.02746) ÷ [(0.99254)(0.07762)³] = 3.933","تساوي القيمتين عند درجة الحرارة نفسها"]'::jsonb, '[{"element":"تعبير Keq","marks":1},{"element":"حساب الموضع 1","marks":1},{"element":"حساب الموضع 2","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان رفع [H₂] إلى الأس 3","قلب النسبة بين النواتج والمتفاعلات","استنتاج أن Keq تغيرت لأن التراكيز تغيرت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-06T22:20:31.230Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) طارد للحرارة: فـ Keq تقل من 8.6 عند 300 K إلى 1.1 عند 600 K، أي إن رفع الحرارة يزيح الاتزان نحو X؛ وهذا يعني أن الحرارة ناتج، فالنظام يستهلكها بالتفاعل العكسي. (ب) أصغر من 1.1؛ لأن Keq تستمر في التناقص بارتفاع درجة الحرارة. (ج) تغير درجة الحرارة يغير موضع الاتزان وقيمة Keq معًا، أما تغير تركيز X فيغير موضع الاتزان فقط: يعدّل النظام التراكيز حتى تعود النسبة [Y] ÷ [X] إلى قيمة Keq نفسها عند درجة الحرارة نفسها.', '["(أ) طارد مع التبرير من تناقص Keq","(ب) أصغر من 1.1","(ج) الحرارة تغير Keq، والتركيز يغير الموضع فقط"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الحكم","marks":1},{"element":"(أ) التبرير","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء كلها صحيحة مع التبرير"},{"level":"3–4 درجات","description":"الحكم صحيح مع نقص في التبرير أو في (ج)"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأنه ماص لأن الحرارة تسرّع التفاعل","توقع أن Keq عند 700 K أكبر","القول إن تغير التركيز يغير Keq"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-06T22:20:31.231Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C3-L2-O06') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L2-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يرتبط الهيموجلوبين بالأكسجين في الدم وفق الاتزان: Hgb(aq) + 4O₂(g) ⇌ Hgb(O₂)₄(aq). عند الصعود إلى مكان جبلي مرتفع يقل فيه الأكسجين، كيف يستجيب هذا الاتزان؟', null, null, '["يزاح نحو اليسار، فيقل تركيز Hgb(O₂)₄ في الدم","يزاح نحو اليمين، فيزداد تركيز Hgb(O₂)₄ في الدم","يزاح نحو اليسار، فيزداد تركيز Hgb(O₂)₄ في الدم","لا يتأثر، لأن الهيموجلوبين في الحالة المائية"]'::jsonb, 'تطبيق', 'تطبيق حيوي', 'سهل', 'الكتاب ص 109 — الكيمياء والصحة'),
('mcq', 2, 'يوضح المنحنى الآتي الضغط الجزئي للأكسجين في الهواء عند ارتفاعات مختلفة. ماذا يحدث للاتزان Hgb(aq) + 4O₂(g) ⇌ Hgb(O₂)₄(aq) في دم متسلق يصعد من مستوى سطح البحر إلى قمة إفرست؟', null, '[{"src":"qimg/chem22/c3-l2-altitude.svg","alt":"رسم بياني: المحور الرأسي «الضغط الجزئي للأكسجين (mmHg)» من 0 إلى 160 تقريبًا، والمحور الأفقي «الارتفاع عن سطح البحر (km)» من 0 إلى 10. منحنى أزرق متناقص باستمرار يبدأ عند نحو 159 mmHg عند مستوى سطح البحر (0 km)، وينتهي عند نحو 50 mmHg عند قمة إفرست (نحو 8.8 km)."}]'::jsonb, '["يزداد الضغط الجزئي لـ O₂، فيزاح الاتزان نحو اليمين","يقل الضغط الجزئي لـ O₂ إلى نحو الثلث، فيزاح الاتزان نحو اليمين","يبقى الضغط الجزئي لـ O₂ ثابتًا، فلا يتأثر الاتزان","يقل الضغط الجزئي لـ O₂ إلى نحو الثلث، فيزاح الاتزان نحو اليسار"]'::jsonb, 'تحليل', 'تفسير منحنى', 'متوسط', 'الكتاب ص 109 — الشكل 1 (الأكسجين مقابل الارتفاع)'),
('mcq', 3, 'عندما يصل Hgb(O₂)₄ عبر الدم إلى أنسجة الجسم التي يكون فيها تركيز الأكسجين منخفضًا، ماذا يحدث للاتزان Hgb(aq) + 4O₂(g) ⇌ Hgb(O₂)₄(aq)؟', null, null, '["يزاح نحو اليمين، فيرتبط مزيد من الأكسجين بالهيموجلوبين","يزاح نحو اليسار، فيتحرر الأكسجين للأنسجة","يزاح نحو اليسار، فيرتبط مزيد من الأكسجين بالهيموجلوبين","يتوقف التفاعل، لأن الأكسجين نفد من الأنسجة"]'::jsonb, 'تطبيق', 'تطبيق حيوي', 'متوسط', 'الكتاب ص 109 — اتزان الهيموجلوبين-أكسجين (في الأنسجة)'),
('mcq', 4, 'يمكث متسلقو الجبال أيامًا في مخيمات على ارتفاعات متدرجة قبل صعود القمة. كيف يفيدهم ذلك وفق الاتزان Hgb(aq) + 4O₂(g) ⇌ Hgb(O₂)₄(aq)؟', null, null, '["يقل إنتاج الجسم من Hgb فيزاح الاتزان نحو اليمين","يزداد O₂ في هواء الجبال فيزاح الاتزان نحو اليمين","ينتج الجسم مزيدًا من Hgb فيزاح الاتزان نحو اليمين","ينتج الجسم مزيدًا من Hgb فيزاح الاتزان نحو اليسار"]'::jsonb, 'تطبيق', 'تطبيق حيوي', 'متوسط', 'الكتاب ص 109 — تكيفات الجسم والشكل 2'),
('mcq', 5, 'يحتوي المشروب الغازي على الاتزان: H₂CO₃(aq) ⇌ H₂O(l) + CO₂(g). لماذا يفقد المشروب طعمه عند ترك غطاء القارورة مفتوحًا؟', null, null, '["يتسرب CO₂ فيزاح الاتزان نحو اليمين ويتفكك مزيد من H₂CO₃","يتسرب CO₂ فيزاح الاتزان نحو اليسار ويتكون مزيد من H₂CO₃","يدخل الهواء فيزاح الاتزان نحو اليسار لأن الهواء يحتوي على CO₂","يتبخر الماء فيزاح الاتزان نحو اليسار ويزداد H₂CO₃"]'::jsonb, 'تطبيق', 'تطبيق حياتي', 'متوسط', 'الكتاب ص 113 — سؤال 51'),
('mcq', 6, 'أضيف مذيب سائل يذيب الكلور إلى دورق يحتوي على الاتزان: حرارة + PCl₅(g) ⇌ PCl₃(g) + Cl₂(g). كيف يتأثر الاتزان عند ذوبان كمية من غاز الكلور؟', null, null, '["يزاح نحو اليسار، لأن المذيب يضيف Cl₂ إلى النظام","لا يتأثر، لأن الكلور ما زال موجودًا في الدورق","يزاح نحو اليمين، لأن تركيز Cl₂ الغازي يقل","يزاح نحو اليسار، لأن ذوبان Cl₂ يمتص الحرارة"]'::jsonb, 'تطبيق', 'تطبيق مخبري', 'صعب', 'الكتاب ص 113 — سؤال 53'),
('mcq', 7, 'يُنتَج الميثانول صناعيًّا وفق الاتزان: CO(g) + 2H₂(g) ⇌ CH₃OH(g) + حرارة. ما فائدة سحب CH₃OH باستمرار من وعاء التفاعل؟', null, null, '["يزاح الاتزان نحو اليسار فيزداد CO وH₂ للاستعمال لاحقًا","تزداد قيمة Keq فيتحول المزيد من CO إلى CH₃OH","ترتفع درجة حرارة الوعاء فيزداد إنتاج CH₃OH","يزاح الاتزان نحو اليمين باستمرار فيُنتَج مزيد من CH₃OH"]'::jsonb, 'تطبيق', 'تطبيق صناعي', 'سهل', 'الكتاب ص 112 — سؤال 50'),
('essay', 1, 'يوضح المنحنى الآتي الضغط الجزئي للأكسجين في الهواء مقابل الارتفاع عن سطح البحر. استعمل المنحنى والاتزان Hgb(aq) + 4O₂(g) ⇌ Hgb(O₂)₄(aq) لتفسير: (أ) شعور الناس بالتعب والدوار عند السفر إلى أماكن جبلية مرتفعة. (ب) كيف يتكيف الجسم مع مرور الوقت لتخفيف هذه الأعراض.', null, '[{"src":"qimg/chem22/c3-l2-altitude.svg","alt":"رسم بياني: المحور الرأسي «الضغط الجزئي للأكسجين (mmHg)» من 0 إلى 160 تقريبًا، والمحور الأفقي «الارتفاع عن سطح البحر (km)» من 0 إلى 10. منحنى أزرق متناقص باستمرار يبدأ عند نحو 159 mmHg عند مستوى سطح البحر (0 km)، وينتهي عند نحو 50 mmHg عند قمة إفرست (نحو 8.8 km)."}]'::jsonb, null, 'تطبيق', 'تطبيق حيوي', 'متوسط', 'الكتاب ص 109 — الكيمياء والصحة'),
('essay', 2, 'يحتوي المشروب الغازي على الاتزان: H₂CO₃(aq) ⇌ H₂O(l) + CO₂(g). (أ) استعمل مبدأ لوتشاتلييه لتفسير فقدان المشروب طعمه عند ترك غطاء القارورة مفتوحًا. (ب) فسّر لماذا يحتفظ المشروب بطعمه مدة أطول إذا أُغلقت القارورة بإحكام بعد فتحها مباشرة.', null, null, null, 'تطبيق', 'تطبيق حياتي', 'متوسط', 'الكتاب ص 113 — سؤال 51'),
('essay', 3, 'عند مرور غازي NO وCO الملوثين فوق سبيكة محفزة في السيارة ينشأ الاتزان: 2NO(g) + 2CO(g) ⇌ N₂(g) + 2CO₂(g). ويبين الجدول الآتي قيم Keq لهذا الاتزان عند درجات حرارة مختلفة. (أ) اكتب تعبير Keq. (ب) استنتج من الجدول هل التفاعل الأمامي ماص أم طارد للحرارة، مستعملًا مبدأ لوتشاتلييه. (ج) فسّر كيف يساعد مبرد السيارة المطلي بالسبيكة المحفزة على تقليل NO وCO في الهواء.', '{"headers":["درجة الحرارة (K)","Keq"],"rows":[["700","9.10 × 10⁸⁷"],["800","1.04 × 10⁶⁶"],["900","4.66 × 10⁵⁴"],["1000","3.27 × 10⁴⁵"]]}'::jsonb, null, null, 'تحليل', 'تطبيق صناعي/بيئي', 'صعب', 'الكتاب ص 115 — أسئلة المستندات 85–87')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L2-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'نقص O₂ في هواء الجبال جهد يخففه النظام بإنتاج O₂، أي بالإزاحة نحو اليسار، فيقل تركيز الهيموجلوبين المؤكسج ويقل الأكسجين الذي يصل إلى الأنسجة فيشعر الشخص بالتعب.', '["","نقص O₂ (متفاعل) يزيح الاتزان نحو المتفاعلات لا نحو النواتج.","الإزاحة نحو اليسار تفكك Hgb(O₂)₄ فيقل تركيزه لا يزداد.","O₂ متفاعل في الاتزان، فنقص تركيزه جهد يزيحه مهما كانت حالة الهيموجلوبين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.231Z"}'::jsonb),
('mcq', 2, 3, 'يقل الضغط الجزئي لـ O₂ من نحو 159 mmHg إلى نحو 50 mmHg (قرابة الثلث)، فيقل O₂ المتاح؛ ويخفف النظام هذا الجهد بالإزاحة نحو اليسار، فيقل Hgb(O₂)₄ في الدم.', '["المنحنى متناقص: الضغط الجزئي لـ O₂ يقل من نحو 159 mmHg إلى نحو 50 mmHg.","نقص O₂ (متفاعل) يزيح الاتزان نحو اليسار لا اليمين.","المنحنى يُظهر تناقصًا واضحًا في الضغط الجزئي لـ O₂ مع الارتفاع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.231Z"}'::jsonb),
('mcq', 3, 1, 'انخفاض تركيز O₂ في الأنسجة جهد يخففه النظام بإنتاج O₂، فيزاح الاتزان نحو اليسار ويتحرر الأكسجين لتستعمله الخلايا في عمليات الأيض التي تولد الطاقة.', '["هذا ما يحدث في الرئتين حيث تركيز O₂ مرتفع، لا في الأنسجة.","","الإزاحة نحو اليسار تفكك Hgb(O₂)₄ وتحرر O₂ لا تربطه.","الاتزان ديناميكي ولا يتوقف؛ ونقص O₂ يزيحه نحو اليسار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.232Z"}'::jsonb),
('mcq', 4, 2, 'يتكيف الجسم مع نقص الأكسجين بإنتاج المزيد من الهيموجلوبين؛ وزيادة Hgb (متفاعل) تزيح الاتزان نحو اليمين، فيزداد Hgb(O₂)₄ ويصل مزيد من الأكسجين إلى الأنسجة.', '["نقص Hgb (متفاعل) يزيح الاتزان نحو اليسار، والجسم يتكيف بزيادته لا بنقصه.","الأكسجين في هواء الجبال يبقى قليلًا؛ والتكيف يكون في الجسم لا في الهواء.","","إضافة متفاعل (Hgb) تزيح الاتزان نحو اليمين لا اليسار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.232Z"}'::jsonb),
('mcq', 5, 0, 'عند فتح القارورة يخرج غاز CO₂ (ناتج) من النظام، فيخفف النظام هذا الجهد بالإزاحة نحو اليمين؛ فيتفكك مزيد من H₂CO₃ ويخرج CO₂ باستمرار حتى يفقد المشروب طعمه.', '["","إزالة ناتج (CO₂) تزيح الاتزان نحو اليمين لا نحو اليسار.","نسبة CO₂ في الهواء قليلة جدًّا، والذي يحدث هو خروج CO₂ من القارورة.","الماء سائل نقي لا يُكتب في Keq، والسبب الفعلي هو خروج غاز CO₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-06T22:20:31.232Z"}'::jsonb),
('mcq', 6, 2, 'ذوبان Cl₂ في المذيب يزيله من الطور الغازي فيقل تركيزه؛ فيخفف النظام الجهد بإنتاج مزيد من Cl₂، أي بالإزاحة نحو اليمين.', '["المذيب يزيل Cl₂ من الحالة الغازية بإذابته، لا يضيفه.","Cl₂ المذاب لم يعد جزءًا من خليط الغازات المتزن، فتركيز Cl₂(g) يقل.","","لم يُذكر تغير في درجة الحرارة؛ والجهد المؤثر هو نقص تركيز Cl₂ الغازي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-06T22:20:31.232Z"}'::jsonb),
('mcq', 7, 3, 'إزالة CH₃OH (ناتج) تخفض تركيزه، فيخفف النظام الجهد بإنتاج المزيد منه، فيزاح الاتزان نحو اليمين باستمرار ويزداد الإنتاج.', '["إزالة ناتج تزيح الاتزان نحو النواتج لا نحو المتفاعلات.","إزالة الناتج تغير الموضع فقط، ولا تغير Keq إلا درجة الحرارة.","سحب الناتج لا يرفع درجة الحرارة؛ ورفعها أصلًا يقلل CH₃OH لأن التفاعل طارد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-06T22:20:31.233Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) يقل الضغط الجزئي للأكسجين بالارتفاع (من نحو 159 mmHg عند سطح البحر إلى نحو 50 mmHg عند قمة إفرست)، فيقل O₂ المتاح. ويستجيب الاتزان لهذا الجهد بإنتاج O₂، أي بالإزاحة نحو اليسار، فيقل تركيز الهيموجلوبين المؤكسج Hgb(O₂)₄ في الدم، ويقل الأكسجين الواصل إلى الأنسجة، فيقل مقدار الطاقة الناتج ويشعر الشخص بالتعب والدوار. (ب) يتكيف الجسم بإنتاج المزيد من الهيموجلوبين؛ وزيادة Hgb (متفاعل) تزيح الاتزان نحو اليمين، فيزداد تركيز Hgb(O₂)₄ ويتحرر مزيد من الأكسجين في الأنسجة.', '["قراءة المنحنى: تناقص الضغط الجزئي لـ O₂ بالارتفاع","الإزاحة نحو اليسار ونقص Hgb(O₂)₄","ربط النقص بالتعب (طاقة أقل)","التكيف: إنتاج Hgb يزيح الاتزان نحو اليمين"]'::jsonb, '[]'::jsonb, '[{"element":"قراءة المنحنى","marks":1},{"element":"اتجاه الإزاحة في (أ)","marks":1},{"element":"الربط بالأعراض","marks":1},{"element":"تفسير التكيف في (ب)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة لكل العناصر مع التبرير"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع نقص في التبرير"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الاتزان يزاح نحو اليمين في الجبال","القول إن الجسم يتكيف بزيادة الأكسجين في الهواء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.233Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) عند ترك الغطاء مفتوحًا يتسرب غاز CO₂ (ناتج) من القارورة، فيقل تركيزه؛ ويخفف النظام هذا الجهد بإنتاج مزيد من CO₂، فيزاح الاتزان نحو اليمين ويتفكك H₂CO₃ باستمرار، فيقل تركيزه ويفقد المشروب طعمه. (ب) عند إغلاق القارورة لا يخرج CO₂ من النظام، فيتجمع فوق السائل ويصل النظام المغلق إلى حالة اتزان تبقى فيها كمية من H₂CO₃ ذائبة، ولا يستمر تفككه.', '["خروج CO₂ (ناتج) يقلل تركيزه","الإزاحة نحو اليمين وتفكك H₂CO₃","القارورة المغلقة نظام مغلق يصل إلى الاتزان","بقاء H₂CO₃ فيحتفظ بطعمه"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الجهد","marks":1},{"element":"(أ) الإزاحة ونتيجتها","marks":1},{"element":"(ب) النظام المغلق والاتزان","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الاتزان يزاح نحو اليسار عند الفتح","كتابة H₂O(l) سببًا للإزاحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-06T22:20:31.233Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) Keq = [N₂][CO₂]² ÷ ([NO]²[CO]²). (ب) Keq تقل كلما ارتفعت درجة الحرارة (من 9.10 × 10⁸⁷ عند 700 K إلى 3.27 × 10⁴⁵ عند 1000 K)؛ أي إن رفع الحرارة يزيح الاتزان نحو المتفاعلات، وهذا يعني أن الحرارة ناتج، فالتفاعل الأمامي طارد للحرارة. (ج) قيم Keq كبيرة جدًّا، فالنواتج N₂ وCO₂ مفضلة عند الاتزان، لكن التفاعل يحتاج إلى أن يصل إلى الاتزان بسرعة؛ والمحفز يسرّع الوصول إلى الاتزان. كما أن حرارة المبرد أقل من حرارة المحرك، وخفض درجة الحرارة يزيح هذا الاتزان الطارد نحو النواتج ويزيد Keq، فيتحول مزيد من NO وCO إلى N₂ وCO₂.', '["تعبير Keq صحيح بالأسس","Keq تقل بارتفاع الحرارة فالتفاعل طارد","المحفز يسرّع الوصول إلى الاتزان المفضل للنواتج","انخفاض الحرارة يزيح الاتزان الطارد نحو النواتج"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج) دور المحفز","marks":1},{"element":"(ج) دور انخفاض الحرارة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة لكل العناصر مع التبرير"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع نقص في التبرير"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحفز يزيد كمية النواتج عند الاتزان","نسيان الأسس في تعبير Keq","الحكم بأنه ماص لأن Keq كبيرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-06T22:20:31.233Z"}'::jsonb)
