('mcq', 3, 'نُقل أنبوب مغلق فيه مزيج الاتزان N₂O₄(g) ⇌ 2NO₂(g) (ΔH° = +55.3 kJ) من حمام ماء ساخن إلى حمام ماء مثلج. ماذا يحدث للون المزيج؟', null, null, '["يصبح أغمق، لأن الاتزان يزاح نحو NO₂","يصبح أفتح، لأن الاتزان يزاح نحو NO₂","لا يتغير، لأن الأنبوب مغلق","يصبح أفتح، لأن الاتزان يزاح نحو N₂O₄"]'::jsonb, 'تطبيق', 'توقع ملاحظة', 'متوسط', 'الكتاب ص 95 — الشكل 3-15 (المعادلة 4)'),
('mcq', 4, 'يمثل الشكل الآتي مزيج الاتزان N₂O₄(g) ⇌ 2NO₂(g) (ΔH° = +55.3 kJ) في صندوقين متساويين في الحجم عند درجتي حرارة مختلفتين. أيّ الصندوقين يمثل المزيج عند درجة الحرارة الأعلى؟', null, '[{"src":"qimg/chem22/c3-l2-boxes.svg","alt":"شكل لصندوقين متساويين في الحجم، عنوانهما (س) و(ص)، يمثلان مزيج الاتزان N₂O₄(g) ⇌ 2NO₂(g) نفسه عند درجتي حرارة مختلفتين. مفتاح الرموز: جزيء N₂O₄ (عديم اللون) يُرسم دائرتين بيضاوين متلاصقتين، وجزيء NO₂ (بني) يُرسم دائرة بنية واحدة. الصندوق (س) فيه 6 جزيئات N₂O₄ وجزيئان من NO₂. الصندوق (ص) فيه جزيئان من N₂O₄ و10 جزيئات NO₂. عدد ذرات النيتروجين الكلي متساوٍ في الصندوقين (14 ذرة)."}]'::jsonb, '["(ص)، لأن نسبة NO₂ فيه أكبر","(س)، لأن عدد جزيئات N₂O₄ فيه أكبر","(ص)، لأن عدد جزيئات N₂O₄ فيه أكبر","لا يمكن الحكم، لأن عدد ذرات النيتروجين متساوٍ"]'::jsonb, 'تحليل', 'تفسير نموذج جسيمي', 'صعب', 'الكتاب ص 95 — الشكل 3-14'),
('mcq', 5, 'يمثل الشكل الآتي مزيج الاتزان N₂O₄(g) ⇌ 2NO₂(g) في صندوقين متساويين في الحجم عند درجتي حرارة مختلفتين، وKeq = [NO₂]² ÷ [N₂O₄]. كيف تقارن قيمة Keq بين الصندوقين؟', null, '[{"src":"qimg/chem22/c3-l2-boxes.svg","alt":"شكل لصندوقين متساويين في الحجم، عنوانهما (س) و(ص)، يمثلان مزيج الاتزان N₂O₄(g) ⇌ 2NO₂(g) نفسه عند درجتي حرارة مختلفتين. مفتاح الرموز: جزيء N₂O₄ (عديم اللون) يُرسم دائرتين بيضاوين متلاصقتين، وجزيء NO₂ (بني) يُرسم دائرة بنية واحدة. الصندوق (س) فيه 6 جزيئات N₂O₄ وجزيئان من NO₂. الصندوق (ص) فيه جزيئان من N₂O₄ و10 جزيئات NO₂. عدد ذرات النيتروجين الكلي متساوٍ في الصندوقين (14 ذرة)."}]'::jsonb, '["Keq في (س) أكبر، لأن عدد جزيئات N₂O₄ فيه أكبر","Keq متساوية، لأن المزيج نفسه في الصندوقين","Keq في (ص) أصغر، لأن عدد الجزيئات الكلي فيه أكبر","Keq في (ص) أكبر، لأن التسخين يزيد Keq لهذا التفاعل الماص"]'::jsonb, 'تحليل', 'مقارنة Keq من نموذج', 'صعب', 'الكتاب ص 95 — درجة الحرارة وKeq'),
('mcq', 6, 'لوحظ أن لون مزيج الاتزان N₂O₄(g) ⇌ 2NO₂(g) يصبح بنيًّا غامقًا عند تسخينه. ماذا تستنتج عن التفاعل الأمامي من هذه الملاحظة وحدها؟', null, null, '["أنه طارد للحرارة","أن قيمة Keq له لا تتأثر بالحرارة","أنه ماص للحرارة","أن التسخين يوقف التفاعل العكسي"]'::jsonb, 'تحليل', 'استنتاج من ملاحظة', 'متوسط', 'الكتاب ص 95 — الشكل 3-14'),
('mcq', 7, 'للتفاعل N₂O₄(g) → 2NO₂(g) قيمة ΔH° = +55.3 kJ. ما ΔH° للتفاعل 2NO₂(g) → N₂O₄(g)، وماذا يفسر ذلك عند تبريد المزيج؟', null, null, '["+55.3 kJ؛ فالتبريد يفضل تكوّن NO₂ فيغمق اللون","−55.3 kJ؛ فالتبريد يفضل تكوّن N₂O₄ فيفتح اللون","−55.3 kJ؛ فالتبريد يفضل تكوّن NO₂ فيغمق اللون","−110.6 kJ؛ فالتبريد يفضل تكوّن N₂O₄ فيفتح اللون"]'::jsonb, 'تحليل', 'ربط ΔH بالإزاحة', 'صعب', 'الكتاب ص 95 — الشكل 3-15، وص 115 — سؤال 81'),
('essay', 1, 'يوضح الشكل الآتي أنبوبين مغلقين فيهما مزيج الاتزان N₂O₄(g) ⇌ 2NO₂(g)، ΔH° = +55.3 kJ. (أ) أعد كتابة المعادلة مظهرًا الحرارة فيها. (ب) فسّر الفرق في اللون بين الأنبوبين بمبدأ لوتشاتلييه.', null, '[{"src":"qimg/chem22/c3-l2-tubes.svg","alt":"شكل لأنبوبين مغلقين يحتويان على مزيج الاتزان نفسه من N₂O₄ وNO₂. الأنبوب (1) على اليسار موضوع في كأس فيها حمام ماء مثلج عند 0 °C، ولون محتواه أصفر باهت فاتح جدًّا. الأنبوب (2) على اليمين موضوع في كأس فيها حمام ماء ساخن عند 80 °C، ولون محتواه بني غامق."}]'::jsonb, null, 'تحليل', 'تفسير ملاحظة', 'متوسط', 'الكتاب ص 95 — الشكل 3-14'),
('essay', 2, 'يمثل الشكل الآتي مزيج الاتزان N₂O₄(g) ⇌ 2NO₂(g) (ΔH° = +55.3 kJ) في صندوقين متساويين في الحجم عند درجتي حرارة مختلفتين. (أ) حدد الصندوق الأغمق لونًا والصندوق الأعلى درجة حرارة، مع التبرير. (ب) باعتبار عدد الجزيئات متناسبًا مع التركيز، احسب النسبة [NO₂]² ÷ [N₂O₄] في كل صندوق، واربط النتيجة بأثر درجة الحرارة في Keq.', null, '[{"src":"qimg/chem22/c3-l2-boxes.svg","alt":"شكل لصندوقين متساويين في الحجم، عنوانهما (س) و(ص)، يمثلان مزيج الاتزان N₂O₄(g) ⇌ 2NO₂(g) نفسه عند درجتي حرارة مختلفتين. مفتاح الرموز: جزيء N₂O₄ (عديم اللون) يُرسم دائرتين بيضاوين متلاصقتين، وجزيء NO₂ (بني) يُرسم دائرة بنية واحدة. الصندوق (س) فيه 6 جزيئات N₂O₄ وجزيئان من NO₂. الصندوق (ص) فيه جزيئان من N₂O₄ و10 جزيئات NO₂. عدد ذرات النيتروجين الكلي متساوٍ في الصندوقين (14 ذرة)."}]'::jsonb, null, 'تحليل', 'تفسير نموذج جسيمي وحساب', 'صعب', 'الكتاب ص 95 — الشكلان 3-14 و3-15'),
('essay', 3, 'وضع طالب أنبوبًا مغلقًا فيه مزيج الاتزان N₂O₄(g) ⇌ 2NO₂(g) (ΔH° = +55.3 kJ) في ماء مثلج فأصبح لونه فاتحًا جدًّا، ثم أعاده إلى درجة حرارة الغرفة فعاد لونه البني الأصلي. استنتج الطالب أن «NO₂ كله تحول إلى N₂O₄ في الماء المثلج». قوّم استنتاجه، وفسّر عودة اللون الأصلي.', null, null, null, 'تقويم', 'تقويم استنتاج', 'صعب', 'الكتاب ص 95 — الشكل 3-14، وص 114 — سؤال 72')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
