insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'N₂O₄ غاز لا لون له، وNO₂ غاز بني اللون؛ ولذلك يدل اشتداد اللون البني على زيادة تركيز NO₂.', '["اللونان معكوسان؛ فـ NO₂ هو الغاز البني.","لو كان الغازان بنيين لما تغير لون المزيج بالتسخين والتبريد.","","المزيج يظهر بلون بني يزداد بالتسخين، فأحد الغازين ملون وهو NO₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-06T22:20:31.234Z"}'::jsonb),
('mcq', 2, 1, 'التفاعل الأمامي ماص للحرارة (الحرارة متفاعل)، فإضافة الحرارة في الماء الساخن تزيح الاتزان نحو اليمين، فيزداد NO₂ البني ويغمق اللون.', '["N₂O₄ عديم اللون، والتسخين يزيح هذا الاتزان الماص نحو NO₂ لا نحو N₂O₄.","","لون كل غاز لا يتغير؛ الذي يتغير هو كمية NO₂ البني في المزيج.","الأنبوبان يحتويان على المزيج نفسه؛ والفرق ناتج عن درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.234Z"}'::jsonb),
('mcq', 3, 3, 'عند التبريد تُزال الحرارة، وهي متفاعل في هذا التفاعل الماص؛ فيزاح الاتزان نحو اليسار لإنتاج الحرارة، فيقل NO₂ البني ويزداد N₂O₄ عديم اللون، فيصبح اللون أفتح.', '["التبريد يزيل حرارة (متفاعلًا) فيزاح الاتزان نحو اليسار لا نحو NO₂.","الإزاحة نحو NO₂ تجعل اللون أغمق لا أفتح؛ والتبريد يزيح الاتزان نحو N₂O₄.","إغلاق الأنبوب يمنع خروج المادة لا انتقال الحرارة؛ فالتبريد يزيح الاتزان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.235Z"}'::jsonb),
('mcq', 4, 0, 'التفاعل الأمامي ماص؛ فرفع درجة الحرارة يزيح الاتزان نحو NO₂. والصندوق (ص) فيه 10 جزيئات NO₂ وجزيئان فقط من N₂O₄، فهو المزيج عند درجة الحرارة الأعلى (ولونه أغمق).', '["","زيادة N₂O₄ تدل على إزاحة نحو اليسار، وهذا يحدث عند التبريد في التفاعل الماص.","في (ص) جزيئان فقط من N₂O₄ مقابل 6 في (س)؛ فالتعليل يخالف الشكل.","تساوي الذرات يدل على أنه المزيج نفسه، أما توزيعها بين الغازين فيدل على درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-06T22:20:31.235Z"}'::jsonb),
('mcq', 5, 3, 'باعتبار التركيز متناسبًا مع عدد الجزيئات (الحجم متساوٍ): في (س) النسبة 2² ÷ 6 ≈ 0.67، وفي (ص) 10² ÷ 2 = 50؛ فـ Keq في (ص) أكبر، وهو الصندوق الأسخن لأن رفع الحرارة يزيد Keq للتفاعل الماص.', '["N₂O₄ في المقام؛ فزيادته تجعل Keq أصغر لا أكبر.","Keq تتغير بتغير درجة الحرارة، والصندوقان عند درجتي حرارة مختلفتين.","Keq لا تُحسب من العدد الكلي؛ ونسبة (NO₂)² إلى N₂O₄ في (ص) أكبر بكثير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-06T22:20:31.235Z"}'::jsonb),
('mcq', 6, 2, 'اشتداد اللون البني يعني زيادة NO₂، أي إزاحة نحو اليمين عند إضافة الحرارة؛ والنظام يزاح بالتسخين نحو الاتجاه الذي يستهلك الحرارة، فالتفاعل الأمامي ماص للحرارة.', '["لو كان طاردًا لأزاحه التسخين نحو N₂O₄ عديم اللون فيفتح اللون.","تغير اللون يدل على تغير موضع الاتزان بالحرارة، وهذا يصاحبه تغير Keq.","","الاتزان ديناميكي؛ والتسخين يزيح الاتزان ولا يوقف أي اتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-06T22:20:31.235Z"}'::jsonb),
('mcq', 7, 1, 'عكس المعادلة يعكس إشارة ΔH°، فيكون تكوّن N₂O₄ من NO₂ طاردًا (−55.3 kJ). والتبريد يزيح الاتزان نحو الاتجاه الطارد الذي ينتج الحرارة، فيتكون مزيد من N₂O₄ عديم اللون ويفتح اللون.', '["عكس التفاعل يعكس إشارة ΔH°، فتكوّن N₂O₄ طارد لا ماص.","","التفاعل الطارد (تكوّن N₂O₄) هو الذي يفضله التبريد، لا تكوّن NO₂.","ΔH° لا تتضاعف عند عكس المعادلة؛ تُعكس إشارتها فقط لأن المعاملات لم تتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-06T22:20:31.235Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) حرارة + N₂O₄(g) ⇌ 2NO₂(g)؛ لأن التفاعل الأمامي ماص فالحرارة متفاعل. (ب) N₂O₄ عديم اللون وNO₂ بني. في الأنبوب (2) (ماء ساخن 80 °C) أضيفت حرارة، فيزاح الاتزان نحو اليمين لاستهلاكها، فيزداد NO₂ ويصبح اللون بنيًّا غامقًا. وفي الأنبوب (1) (ماء مثلج 0 °C) أزيلت حرارة، فيزاح الاتزان نحو اليسار لإنتاجها، فيزداد N₂O₄ عديم اللون ويقل NO₂، فيصبح اللون فاتحًا جدًّا.', '["الحرارة في جهة المتفاعلات","لون كل غاز","الأنبوب الساخن: إزاحة نحو NO₂ ولون غامق","الأنبوب البارد: إزاحة نحو N₂O₄ ولون فاتح"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"لون الغازين","marks":1},{"element":"تفسير الأنبوب (2)","marks":1},{"element":"تفسير الأنبوب (1)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الحرارة مع النواتج","القول إن N₂O₄ بني","تفسير اللون بتغير لون الجزيئات نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.236Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الصندوق (ص) أغمق لونًا لأن فيه 10 جزيئات من NO₂ البني مقابل جزيئين في (س). وهو الأعلى درجة حرارة؛ لأن التفاعل الأمامي ماص، ورفع الحرارة يزيح الاتزان نحو NO₂. (ب) في (س): 2² ÷ 6 = 4 ÷ 6 ≈ 0.67، وفي (ص): 10² ÷ 2 = 100 ÷ 2 = 50. النسبة (التي تتناسب مع Keq) أكبر في (ص)؛ وهذا يتفق مع أن رفع درجة الحرارة يزيد Keq للتفاعل الماص.', '["(ص) أغمق لأن NO₂ فيه أكثر","(ص) الأسخن لأن التفاعل ماص","حساب النسبتين 0.67 و50","Keq تزداد بالتسخين للتفاعل الماص"]'::jsonb, '["(س): (2)² ÷ 6 = 4 ÷ 6 ≈ 0.67","(ص): (10)² ÷ 2 = 100 ÷ 2 = 50","المقارنة: 50 > 0.67، فـ Keq في (ص) أكبر"]'::jsonb, '[{"element":"(أ) الأغمق","marks":1},{"element":"(أ) الأسخن مع التبرير","marks":1},{"element":"(ب) الحسابان","marks":2},{"element":"(ب) الربط بـ Keq","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة لكل العناصر مع التبرير"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع نقص في التبرير"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تربيع عدد جزيئات NO₂","عدّ دائرتي N₂O₄ جزيئين منفصلين","القول إن Keq متساوية في الصندوقين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-06T22:20:31.236Z"}'::jsonb),
('essay', 3, null::int, null, null, 'استنتاج الطالب غير دقيق: التبريد يزيح الاتزان نحو N₂O₄ فيقل NO₂ كثيرًا فيصبح اللون فاتحًا، لكن النظام يبقى في حالة اتزان تحتوي على المادتين معًا، فلا يتحول NO₂ كله (اللون فاتح لا عديم). وعند إعادته إلى درجة حرارة الغرفة تضاف حرارة، والتفاعل الأمامي ماص، فيزاح الاتزان نحو اليمين حتى يصل إلى موضع الاتزان نفسه الذي يناسب درجة حرارة الغرفة (وقيمة Keq نفسها)، فيعود اللون الأصلي؛ وهذا يدل على أن التغير انعكاسي.', '["الحكم: الاستنتاج غير صحيح","الاتزان يبقى بوجود المادتين (لون فاتح لا عديم)","التسخين إلى حرارة الغرفة يزيح الاتزان نحو NO₂","العودة إلى موضع الاتزان نفسه لأن Keq تعتمد على درجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"تبرير الحكم","marks":1},{"element":"تفسير عودة اللون","marks":1},{"element":"الربط بـ Keq/الانعكاسية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل العناصر"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًّا تنقصها بعض العناصر أو التبرير"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول استنتاج الطالب","القول إن التفاعل يتوقف في الماء المثلج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.236Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C3-L2-O08') and x.type = v.type and x.number = v.number
