insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L2-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يرغب كيميائي في زيادة إنتاج الميثان من الاتزان CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g)، ΔH° = −206.5 kJ. أيّ مجموعة الظروف الآتية تحقق ذلك؟', null, null, '["رفع درجة الحرارة وتقليل حجم الوعاء","خفض درجة الحرارة وتقليل حجم الوعاء","خفض درجة الحرارة وزيادة حجم الوعاء","رفع درجة الحرارة وإضافة عامل محفز"]'::jsonb, 'تحليل', 'اقتراح ظروف', 'متوسط', 'الكتاب ص 92–95 — تطبيق مبدأ لوتشاتلييه'),
('mcq', 2, 'في الاتزان: حرارة + PCl₅(g) ⇌ PCl₃(g) + Cl₂(g)، أيّ مجموعة الظروف الآتية تزيد كمية PCl₃ عند الاتزان؟', null, null, '["خفض درجة الحرارة وزيادة حجم الوعاء","رفع درجة الحرارة وزيادة حجم الوعاء","رفع درجة الحرارة وتقليل حجم الوعاء","رفع درجة الحرارة وإضافة كمية من Cl₂"]'::jsonb, 'تحليل', 'اقتراح ظرف', 'متوسط', 'الكتاب ص 113 — سؤالا 52 و53'),
('mcq', 3, 'في الاتزان: C₂H₄(g) + H₂(g) ⇌ C₂H₆(g) + حرارة، كيف تُنظَّم درجة الحرارة لزيادة كمية الهيدروجين في وعاء التفاعل؟', null, null, '["تخفض، لأن ذلك يزيح الاتزان نحو اليسار","ترفع، لأن ذلك يزيح الاتزان نحو اليمين","ترفع، لأن ذلك يزيح الاتزان نحو اليسار","تخفض، لأن ذلك يزيد قيمة Keq"]'::jsonb, 'تحليل', 'اقتراح ظرف', 'متوسط', 'الكتاب ص 113 — سؤال 57'),
('mcq', 4, 'في الاتزان 2SO₂(g) + O₂(g) ⇌ 2SO₃(g)، ΔH° = −198 kJ، أيّ مجموعة الظروف الآتية تزيد كمية SO₃ عند الاتزان؟', null, null, '["إضافة O₂، وخفض درجة الحرارة، وتقليل الحجم","إزالة O₂، وخفض درجة الحرارة، وتقليل الحجم","إضافة O₂، ورفع درجة الحرارة، وتقليل الحجم","إضافة O₂، وخفض درجة الحرارة، وزيادة الحجم"]'::jsonb, 'تحليل', 'اقتراح ظروف', 'صعب', 'الكتاب ص 97 — سؤال 14'),
('mcq', 5, 'في الاتزان: حرارة + N₂(g) + O₂(g) ⇌ 2NO(g)، أيّ الإجراءات الآتية يزيد كمية NO عند الاتزان؟', null, null, '["رفع درجة الحرارة","تقليل حجم الوعاء","إضافة عامل محفز","إزالة جزء من N₂"]'::jsonb, 'تحليل', 'اختيار إجراء', 'متوسط', 'الكتاب ص 114 — سؤال 69'),
('mcq', 6, 'يتفكك كربونات الماغنسيوم في وعاء مغلق وفق الاتزان: MgCO₃(s) ⇌ MgO(s) + CO₂(g). أيّ الإجراءات الآتية يزيد كمية MgO الناتجة؟', null, null, '["إضافة مزيد من MgCO₃(s) إلى الوعاء","إضافة كمية من CO₂ إلى الوعاء","إزالة CO₂ من الوعاء باستمرار","إضافة عامل محفز إلى الوعاء"]'::jsonb, 'تحليل', 'اقتراح إجراء', 'صعب', 'الكتاب ص 113 — سؤال 56'),
('mcq', 7, 'يوضح المنحنى الآتي قيم Keq للاتزان X(g) ⇌ Y(g) عند درجات حرارة مختلفة، ويجري التفاعل حاليًّا عند 600 K. أيّ الاقتراحات الآتية يزيد نسبة Y في مزيج الاتزان؟', null, '[{"src":"qimg/chem22/c3-l2-keq-t.svg","alt":"رسم بياني: المحور الرأسي «Keq» من 0 إلى 10، والمحور الأفقي «درجة الحرارة (K)». أربع نقاط موصولة بخط متناقص: عند 300 K قيمة Keq = 8.6، وعند 400 K قيمة Keq = 3.9، وعند 500 K قيمة Keq = 2.0، وعند 600 K قيمة Keq = 1.1. أي إن Keq تقل كلما ارتفعت درجة الحرارة."}]'::jsonb, '["رفع درجة الحرارة إلى أعلى من 600 K","تقليل حجم الوعاء عند 600 K","إضافة عامل محفز عند 600 K","خفض درجة الحرارة إلى 300 K"]'::jsonb, 'تحليل', 'قراءة منحنى', 'صعب', 'الكتاب ص 95 — درجة الحرارة وKeq'),
('essay', 1, 'اقترح ثلاثة ظروف مختلفة تزيد كمية الميثان الناتجة من الاتزان CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g)، ΔH° = −206.5 kJ، وبرر كل اقتراح بمبدأ لوتشاتلييه. ثم وضح لماذا لا تُعدّ إضافة عامل محفز من هذه الظروف.', null, null, null, 'تحليل', 'اقتراح ظروف', 'متوسط', 'الكتاب ص 92–95 — تطبيق مبدأ لوتشاتلييه'),
('essay', 2, 'صمّم خطة (أو خريطة مفاهيمية) لنظام الاتزان 2SO₂(g) + O₂(g) ⇌ 2SO₃(g)، ΔH° = −198 kJ، تتضمن فرعين: فرعًا لطرائق زيادة كمية SO₃، وفرعًا لطرائق زيادة كمية المتفاعلات، على أن يشمل كل فرع ثلاثة عوامل (التركيز، والحجم/الضغط، ودرجة الحرارة) مع تبرير مختصر لكل منها.', null, null, null, 'إبداع', 'تصميم خريطة مفاهيمية', 'صعب', 'الكتاب ص 97 — سؤال 17'),
('essay', 3, 'يتفاعل الإيثيلين C₂H₄ مع الهيدروجين لإنتاج الإيثان C₂H₆ وفق المعادلة: C₂H₄(g) + H₂(g) ⇌ C₂H₆(g) + حرارة. كيف تنظم درجة حرارة هذا الاتزان لكي: (أ) تزيد كمية الإيثان الناتج؟ (ب) تقل تركيز الإيثيلين؟ (ج) تزيد كمية الهيدروجين في وعاء التفاعل؟ ثم (د) اقترح تغييرًا في حجم الوعاء يزيد كمية الإيثان، مع التبرير.', null, null, null, 'تطبيق', 'اقتراح ظروف', 'متوسط', 'الكتاب ص 113 — سؤال 57')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L2-O09') and x.type = v.type and x.number = v.number);
