select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'التفاعل طارد (الحرارة ناتج)، فخفض الحرارة يزيحه نحو اليمين؛ وتقليل الحجم يزيد الضغط فيزاح الاتزان نحو النواتج (2 mol غاز مقابل 4 mol). فالظرفان معًا يزيدان CH₄.', '["التفاعل طارد، فرفع درجة الحرارة يزيح الاتزان نحو اليسار ويقلل CH₄.","","زيادة الحجم تزيح الاتزان نحو العدد الأكبر من مولات الغاز (4 mol في المتفاعلات).","المحفز لا يزيد كمية النواتج، ورفع الحرارة يقلل CH₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-06T22:20:31.237Z"}'::jsonb),
('mcq', 2, 1, 'التفاعل الأمامي ماص للحرارة (الحرارة متفاعل)، فرفع درجة الحرارة يزيح الاتزان نحو اليمين؛ وزيادة حجم الوعاء تقلل الضغط فيزاح الاتزان نحو العدد الأكبر من مولات الغاز (2 mol في النواتج مقابل 1 mol في المتفاعلات). فالظرفان معًا يزيدان PCl₃.', '["التفاعل ماص؛ فخفض درجة الحرارة يزيح الاتزان نحو اليسار ويقلل PCl₃.","","تقليل الحجم يزيح الاتزان نحو العدد الأقل من مولات الغاز (1 mol من PCl₅)، فيقل PCl₃.","إضافة Cl₂ (ناتج) تزيح الاتزان نحو اليسار فيقل PCl₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-06T22:20:31.237Z"}'::jsonb),
('mcq', 3, 2, 'الحرارة ناتج في هذا التفاعل الطارد؛ فرفع درجة الحرارة يزيح الاتزان نحو اليسار لاستهلاك الحرارة، فيتفكك جزء من C₂H₆ ويزداد H₂ وC₂H₄.', '["خفض الحرارة في التفاعل الطارد يزيحه نحو اليمين فيستهلك H₂.","رفع الحرارة يزيح الاتزان الطارد نحو اليسار لا اليمين.","","زيادة Keq بالخفض تعني نواتج أكثر واستهلاك H₂ لا زيادته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.237Z"}'::jsonb),
('mcq', 4, 0, 'إضافة O₂ (متفاعل) تزيح الاتزان نحو اليمين؛ وخفض الحرارة يزيح التفاعل الطارد نحو اليمين؛ وتقليل الحجم يزيح الاتزان نحو العدد الأقل من مولات الغاز (2 mol مقابل 3 mol). فالظروف الثلاثة تزيد SO₃.', '["","إزالة O₂ (متفاعل) تزيح الاتزان نحو اليسار فتقل SO₃.","التفاعل طارد؛ فرفع الحرارة يزيح الاتزان نحو اليسار.","زيادة الحجم تزيح الاتزان نحو العدد الأكبر من مولات الغاز (3 mol في المتفاعلات)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-06T22:20:31.238Z"}'::jsonb),
('mcq', 5, 0, 'التفاعل الأمامي ماص للحرارة (الحرارة متفاعل)؛ فرفع درجة الحرارة يزيح الاتزان نحو اليمين ويزيد NO. أما الحجم فلا أثر له لتساوي مولات الغاز (2 = 2).', '["","عدد مولات الغاز 2 في كل طرف، فتغيير الحجم لا يزيح الاتزان.","المحفز لا يغير كمية النواتج عند الاتزان.","إزالة متفاعل تزيح الاتزان نحو اليسار فتقل NO."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-06T22:20:31.238Z"}'::jsonb),
('mcq', 6, 2, 'CO₂ هو الغاز الوحيد في الاتزان (Keq = [CO₂])؛ فإزالته باستمرار تخفض تركيزه، ويخففه النظام بإنتاج المزيد منه، فيزاح الاتزان نحو اليمين ويتفكك مزيد من MgCO₃ إلى MgO.', '["MgCO₃ صلب نقي لا يُكتب في Keq؛ فإضافته لا تزيح الاتزان ولا تغير [CO₂] عنده، فلا يتكون مزيد من MgO.","إضافة ناتج تزيح الاتزان نحو اليسار فيقل MgO الناتج.","","المحفز لا يزيد كمية النواتج عند الاتزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-06T22:20:31.238Z"}'::jsonb),
('mcq', 7, 3, 'Keq = [Y] ÷ [X] تزداد من 1.1 عند 600 K إلى 8.6 عند 300 K؛ فخفض درجة الحرارة يزيد نسبة Y في مزيج الاتزان (التفاعل الأمامي طارد للحرارة). أما تغيير الحجم فلا أثر له لتساوي مولات الغاز في الطرفين (1 = 1)، والمحفز لا يغير موضع الاتزان.', '["Keq تقل كلما ارتفعت درجة الحرارة، فرفعها يقلل نسبة Y.","عدد مولات الغاز 1 في كل طرف، فتغيير الحجم لا يزيح الاتزان.","المحفز يسرّع الوصول إلى الاتزان ولا يغير نسبة Y عنده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.239Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الاقتراحات: (1) زيادة تركيز CO أو H₂ (إضافة متفاعل)؛ يخففه النظام باستهلاكه فيزاح نحو اليمين. (2) إزالة الماء الناتج بمادة مجففة؛ فينتج النظام المزيد من النواتج بالإزاحة نحو اليمين. (3) تقليل حجم الوعاء (زيادة الضغط)؛ فيزاح الاتزان نحو العدد الأقل من مولات الغاز (2 mol في النواتج مقابل 4 mol في المتفاعلات). ويصح أيضًا خفض درجة الحرارة؛ لأن التفاعل طارد والحرارة ناتج، فيزاح نحو اليمين وتزداد Keq. أما المحفز فيزيد سرعتي التفاعلين بالتساوي، فيصل النظام إلى الاتزان أسرع دون أن تزداد كمية الميثان.', '["ثلاثة اقتراحات صحيحة (من: إضافة CO/H₂، إزالة H₂O، تقليل الحجم، خفض الحرارة)","تبرير كل اقتراح","المحفز لا يغير كمية النواتج"]'::jsonb, '[]'::jsonb, '[{"element":"ثلاثة اقتراحات (درجة لكل منها)","marks":3},{"element":"تبرير الاقتراحات","marks":1},{"element":"تفسير استبعاد المحفز","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة لكل العناصر مع التبرير"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع نقص في التبرير"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اقتراح رفع درجة الحرارة","اقتراح زيادة الحجم","عدّ المحفز وسيلة لزيادة الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-06T22:20:31.239Z"}'::jsonb),
('essay', 2, null::int, null, null, 'فرع زيادة SO₃: (1) التركيز: إضافة SO₂ أو O₂، أو إزالة SO₃؛ فيزاح الاتزان نحو اليمين. (2) الحجم/الضغط: تقليل الحجم (زيادة الضغط)؛ لأن النواتج 2 mol غاز مقابل 3 mol في المتفاعلات. (3) درجة الحرارة: خفضها؛ لأن التفاعل طارد والحرارة ناتج. فرع زيادة المتفاعلات: (1) التركيز: إضافة SO₃ أو إزالة SO₂ أو O₂؛ فيزاح الاتزان نحو اليسار. (2) الحجم/الضغط: زيادة الحجم (خفض الضغط)؛ فيزاح نحو العدد الأكبر من مولات الغاز. (3) درجة الحرارة: رفعها؛ فيزاح الاتزان نحو اليسار لاستهلاك الحرارة. ويُذكر أن المحفز لا يصلح لأي من الفرعين لأنه لا يغير موضع الاتزان.', '["فرع النواتج: التركيز","فرع النواتج: الحجم/الضغط","فرع النواتج: درجة الحرارة","فرع المتفاعلات: التركيز","فرع المتفاعلات: الحجم/الضغط","فرع المتفاعلات: درجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"فرع النواتج (ثلاثة عوامل مع التبرير)","marks":3},{"element":"فرع المتفاعلات (ثلاثة عوامل مع التبرير)","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"الفرعان كاملان بالعوامل الثلاثة مع التبرير"},{"level":"3–5 درجات","description":"فرع كامل وآخر ناقص، أو عوامل صحيحة دون تبرير كافٍ"},{"level":"1–2 درجة","description":"عامل أو عاملان صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس أثر درجة الحرارة في التفاعل الطارد","عدّ المواد بدل مولات الغاز","إدراج المحفز وسيلة لزيادة النواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.239Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التفاعل الأمامي طارد للحرارة (الحرارة ناتج). (أ) خفض درجة الحرارة؛ فيزاح الاتزان نحو اليمين لإنتاج الحرارة فيزداد C₂H₆. (ب) خفض درجة الحرارة أيضًا؛ لأن الإزاحة نحو اليمين تستهلك C₂H₄ فيقل تركيزه. (ج) رفع درجة الحرارة؛ فيزاح الاتزان نحو اليسار لاستهلاك الحرارة فيزداد H₂. (د) تقليل حجم الوعاء (زيادة الضغط)؛ لأن عدد مولات الغاز في المتفاعلات 2 وفي النواتج 1، فيزاح الاتزان نحو اليمين ويزداد الإيثان.', '["(أ) خفض الحرارة","(ب) خفض الحرارة","(ج) رفع الحرارة","(د) تقليل الحجم مع عدّ المولات 2 مقابل 1"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة لكل العناصر مع التبرير"},{"level":"3–4 درجات","description":"معظم العناصر صحيحة مع نقص في التبرير"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رفع الحرارة لزيادة الإيثان","زيادة الحجم لزيادة الإيثان","الظن أن خفض الحرارة يزيد الإيثيلين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.240Z"}'::jsonb)
