('mcq', 1, 'ينتج الميثان وفق الاتزان CO(g) + 3H₂(g) ⇌ CH₄(g) + H₂O(g)، وثابت اتزانه Keq = 3.933 عند 1200 K. إذا كانت التراكيز عند الاتزان: [CO] = 0.500 M و[H₂] = 1.20 M و[H₂O] = 0.400 M، فما تركيز CH₄ عند الاتزان؟', null, null, '["5.90 mol/L","8.50 mol/L","1.82 mol/L","0.118 mol/L"]'::jsonb, 'تطبيق', 'حساب تركيز ناتج من Keq', 'متوسط', 'الكتاب ص 98 — حساب التراكيز عند الاتزان'),
('mcq', 2, 'يتكون الميثانول وفق الاتزان CO(g) + 2H₂(g) ⇌ CH₃OH(g)، وقيمة Keq = 10.5 عند درجة حرارة معينة. ما [CO] في خليط اتزان عند درجة الحرارة نفسها يحتوي على 0.850 mol/L من H₂ و1.50 mol/L من CH₃OH؟', null, null, '["0.168 M","5.06 M","11.4 M","0.198 M"]'::jsonb, 'تطبيق', 'حساب تركيز متفاعل من Keq', 'سهل', 'الكتاب ص 99 — المسألة 18'),
('mcq', 3, 'يبين المنحنى الآتي تغير التراكيز مع الزمن في الاتزان H₂(g) + I₂(g) ⇌ 2HI(g) الذي ثابت اتزانه Keq = 50.3 عند درجة حرارة التجربة. ما تركيز HI عند الاتزان (القيمة المشار إليها بعلامة الاستفهام)؟', null, '[{"src":"qimg/chem22/c3-l3a-hi-conctime.svg","alt":"منحنى بياني عنوانه H₂(g) + I₂(g) ⇌ 2HI(g)، محوره الأفقي الزمن ومحوره الرأسي التركيز بوحدة mol/L دون تدريج رقمي. منحنى أزرق مشترك لـ H₂ وI₂ يبدأ من قيمة مرتفعة ويتناقص تدريجيًّا حتى يثبت أفقيًّا عند 0.110 M. ومنحنى أحمر لـ HI يبدأ من الصفر ويتزايد حتى يثبت أفقيًّا عند قيمة مكتوب بجانبها علامة استفهام (؟). خط رأسي متقطع عنوانه «بلوغ الاتزان» يبين اللحظة التي تصبح بعدها جميع المنحنيات أفقية."}]'::jsonb, '["0.780 M","0.609 M","2.35 M","0.390 M"]'::jsonb, 'تطبيق', 'حساب تركيز من منحنى وKeq', 'متوسط', 'الكتاب ص 98–99 — حساب التراكيز عند الاتزان'),
('mcq', 4, 'يتفكك كبريتيد الهيدروجين عند 1405 K وفق الاتزان 2H₂S(g) ⇌ 2H₂(g) + S₂(g)، وثابت اتزانه Keq = 2.27 × 10⁻³. ما تركيز H₂ في خليط اتزان فيه [H₂S] = 0.250 mol/L و[S₂] = 0.0400 mol/L؟', null, null, '["3.55 × 10⁻³ mol/L","0.119 mol/L","0.0596 mol/L","16.8 mol/L"]'::jsonb, 'تطبيق', 'حساب تركيز يتطلب جذرًا تربيعيًّا', 'صعب', 'الكتاب ص 99 — المثال 3-4 ومسائل تدريبية'),
('mcq', 5, 'لحساب تركيز أحد النواتج في خليط تفاعل عند الاتزان، ما المعلومات التي تحتاج إليها؟', null, null, '["المعادلة الموزونة، وقيمة Keq عند درجة الحرارة نفسها، وتراكيز بقية المواد عند الاتزان","التراكيز الابتدائية للمتفاعلات فقط، دون الحاجة إلى معرفة قيمة Keq","قيمة Keq فقط؛ لأنها وحدها تحدد تركيز كل مادة في خليط الاتزان","كتل المواد الصلبة والسوائل النقية في الخليط، وقيمة Keq للتفاعل"]'::jsonb, 'فهم', 'متطلبات حساب تركيز الاتزان', 'سهل', 'الكتاب ص 108 — السؤال 27'),
('mcq', 6, 'يبين المنحنى الآتي تغير التراكيز مع الزمن في الاتزان N₂O₄(g) ⇌ 2NO₂(g) الذي ثابت اتزانه Keq = 4.65 × 10⁻³ عند درجة حرارة التجربة. ما تركيز NO₂ عند الاتزان (القيمة المشار إليها بعلامة الاستفهام)؟', null, '[{"src":"qimg/chem22/c3-l3a-n2o4-conctime.svg","alt":"منحنى بياني عنوانه N₂O₄(g) ⇌ 2NO₂(g)، محوره الأفقي الزمن ومحوره الرأسي التركيز بوحدة mol/L دون تدريج رقمي. منحنى برتقالي لـ N₂O₄ يبدأ من قيمة أعلى قليلًا ويتناقص قليلًا حتى يثبت أفقيًّا عند 0.0400 M. ومنحنى أحمر لـ NO₂ يبدأ من الصفر ويتزايد حتى يثبت أفقيًّا عند قيمة مكتوب بجانبها علامة استفهام (؟). خط رأسي متقطع عنوانه «بلوغ الاتزان» تصبح بعده المنحنيات أفقية."}]'::jsonb, '["1.86 × 10⁻⁴ M","0.341 M","9.30 × 10⁻⁵ M","0.0136 M"]'::jsonb, 'تطبيق', 'حساب تركيز من منحنى وKeq', 'صعب', 'الكتاب ص 98–99 — حساب التراكيز عند الاتزان'),
('mcq', 7, 'للاتزان غير المتجانس C(s) + CO₂(g) ⇌ 2CO(g) قيمة Keq = 1.90 عند درجة حرارة معينة. إذا كان [CO₂] = 0.0500 mol/L في خليط الاتزان (مع وجود الكربون الصلب)، فما [CO]؟', null, null, '["0.0950 mol/L","6.16 mol/L","0.308 mol/L","0.0475 mol/L"]'::jsonb, 'تحليل', 'تركيز الاتزان في اتزان غير متجانس', 'متوسط', 'الكتاب ص 98–101 — حساب التراكيز واستبعاد المواد الصلبة'),
('essay', 1, 'يتفكك كبريتيد الهيدروجين عند 1405 K وفق الاتزان 2H₂S(g) ⇌ 2H₂(g) + S₂(g)، وثابت اتزانه Keq = 2.27 × 10⁻³. احسب [S₂] في خليط اتزان فيه [H₂S] = 0.150 mol/L و[H₂] = 0.0300 mol/L، ثم بيّن هل تتفق إجابتك مع ما تتوقعه من قيمة Keq.', null, null, null, 'تطبيق', 'حساب تركيز الاتزان وتقويمه', 'متوسط', 'الكتاب ص 99 — المثال 3-4 ومسائل تدريبية'),
('essay', 2, 'في التفاعل العام A + B ⇌ C + D، وُضع 1.00 mol من A و1.00 mol من B في وعاء حجمه 1.00 L، وسُمح لهما بالتفاعل حتى الاتزان، فكان [A] = 0.400 mol/L عند الاتزان.
(أ) احسب تراكيز B وC وD عند الاتزان، ثم احسب Keq.
(ب) في تجربة أخرى عند درجة الحرارة نفسها بلغ الخليط الاتزان وكان [A] = [B] = 0.200 mol/L و[C] = [D]. احسب [C] في هذا الخليط.', null, null, null, 'تحليل', 'تراكيز الاتزان من نسب المعادلة وKeq', 'صعب', 'الكتاب ص 99 — المسألة 19'),
('essay', 3, 'يبين المنحنى الآتي تغير التراكيز مع الزمن في الاتزان PCl₅(g) ⇌ PCl₃(g) + Cl₂(g) الذي ثابت اتزانه Keq = 0.0450 عند درجة حرارة التجربة. اكتب تعبير ثابت الاتزان، ثم احسب تركيز Cl₂ عند الاتزان (القيمة المشار إليها بعلامة الاستفهام).', null, '[{"src":"qimg/chem22/c3-l3a-pcl5-conctime.svg","alt":"منحنى بياني عنوانه PCl₅(g) ⇌ PCl₃(g) + Cl₂(g)، محوره الأفقي الزمن ومحوره الرأسي التركيز بوحدة mol/L دون تدريج رقمي. منحنى برتقالي لـ PCl₅ يبدأ من قيمة أعلى ويتناقص حتى يثبت أفقيًّا عند 0.200 M. ومنحنى أزرق لـ PCl₃ يبدأ من قيمة صغيرة جدًّا ويتزايد حتى يثبت عند 0.100 M. ومنحنى أخضر لـ Cl₂ يبدأ من الصفر ويتزايد حتى يثبت أفقيًّا تحت منحنى PCl₃ بقليل عند قيمة مكتوب بجانبها علامة استفهام (؟). خط رأسي متقطع عنوانه «بلوغ الاتزان» تصبح بعده المنحنيات الثلاثة أفقية."}]'::jsonb, null, 'تطبيق', 'حساب تركيز من منحنى وKeq', 'سهل', 'الكتاب ص 98 — حساب التراكيز عند الاتزان')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
