insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'Keq = [CH₄][H₂O] / ([CO][H₂]³)، ومنه [CH₄] = Keq × [CO][H₂]³ / [H₂O] = 3.933 × (0.500)(1.20)³ / 0.400 = 3.933 × 0.500 × 1.728 / 0.400 = 8.50 mol/L.', '["أُهمل الأس 3 على [H₂]: 3.933 × 0.500 × 1.20 / 0.400 = 5.90؛ والمعامل 3 في المعادلة يصبح أسًّا في التعبير.","","قُلبت العلاقة: Keq × [H₂O] / ([CO][H₂]³) = 1.82، والصحيح ضرب Keq في [CO][H₂]³ ثم القسمة على [H₂O].","قُسم على Keq بدل الضرب فيه: [H₂O] / (Keq × [CO][H₂]³) = 0.118."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.240Z"}'::jsonb),
('mcq', 2, 3, 'Keq = [CH₃OH] / ([CO][H₂]²)، ومنه [CO] = [CH₃OH] / (Keq × [H₂]²) = 1.50 / (10.5 × 0.850²) = 1.50 / (10.5 × 0.7225) = 0.198 M.', '["أُهمل تربيع [H₂]: 1.50 / (10.5 × 0.850) = 0.168؛ والمعامل 2 يصبح أسًّا.","قُلبت العلاقة: Keq × [H₂]² / [CH₃OH] = 5.06.","ضُربت القيم كلها: 10.5 × 1.50 × 0.850² = 11.4، دون إعادة ترتيب تعبير ثابت الاتزان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-06T22:20:31.241Z"}'::jsonb),
('mcq', 3, 0, 'من المنحنى: [H₂] = [I₂] = 0.110 M عند الاتزان. Keq = [HI]² / ([H₂][I₂])، ومنه [HI]² = 50.3 × 0.110 × 0.110 = 0.609، فـ [HI] = √0.609 = 0.780 M.', '["","هذه قيمة [HI]² (50.3 × 0.110 × 0.110 = 0.609)؛ لم يُؤخذ الجذر التربيعي.","أُهمل [I₂] في المقام: √(50.3 × 0.110) = 2.35، مع أن المتفاعلين كليهما في تعبير الاتزان.","قُسم الناتج الصحيح على المعامل 2 (0.780 ÷ 2)؛ والمعامل يظهر أسًّا في التعبير ولا يُقسم عليه الناتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (69%)"}],"at":"2026-11-06T22:20:31.241Z"}'::jsonb),
('mcq', 4, 2, 'Keq = [H₂]²[S₂] / [H₂S]²، ومنه [H₂]² = Keq × [H₂S]² / [S₂] = 2.27 × 10⁻³ × (0.250)² / 0.0400 = 3.55 × 10⁻³، فـ [H₂] = √(3.55 × 10⁻³) = 0.0596 mol/L.', '["هذه قيمة [H₂]²؛ نُسي أخذ الجذر التربيعي في الخطوة الأخيرة.","أُهمل تربيع [H₂S]: √(2.27 × 10⁻³ × 0.250 / 0.0400) = 0.119.","","قُلبت العلاقة: √([S₂] / (Keq × [H₂S]²)) = 16.8، وهي قيمة غير معقولة لأن Keq < 1 يعني أن [H₂] أقل من [H₂S]."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-06T22:20:31.241Z"}'::jsonb),
('mcq', 5, 0, 'يُكتب تعبير ثابت الاتزان من المعادلة الموزونة، ثم يُعوَّض فيه بقيمة Keq عند درجة الحرارة نفسها وبتراكيز الاتزان لبقية المواد، فيبقى مجهول واحد هو تركيز الناتج المطلوب.', '["","التراكيز الابتدائية وحدها لا تكفي؛ فالحساب يعتمد على تعبير Keq وقيمته.","قيمة Keq وحدها معادلة فيها أكثر من مجهول؛ إذ يلزم معرفة تراكيز الاتزان للمواد الأخرى.","المواد الصلبة والسوائل النقية لا تظهر في تعبير ثابت الاتزان، فلا حاجة إلى كتلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-06T22:20:31.241Z"}'::jsonb),
('mcq', 6, 3, 'من المنحنى: [N₂O₄] = 0.0400 M عند الاتزان. Keq = [NO₂]² / [N₂O₄]، ومنه [NO₂]² = 4.65 × 10⁻³ × 0.0400 = 1.86 × 10⁻⁴، فـ [NO₂] = √(1.86 × 10⁻⁴) = 0.0136 M.', '["هذه قيمة [NO₂]²؛ لم يُؤخذ الجذر التربيعي.","قُلبت العلاقة: √(Keq / [N₂O₄]) = 0.341؛ والصحيح ضرب Keq في [N₂O₄].","عومل المعامل 2 بالقسمة: Keq × [N₂O₄] ÷ 2 = 9.30 × 10⁻⁵، والمعامل يصبح أسًّا (تربيعًا) لا قاسمًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (69%)"}],"at":"2026-11-06T22:20:31.242Z"}'::jsonb),
('mcq', 7, 2, 'الكربون مادة صلبة نقية فلا يظهر في التعبير: Keq = [CO]² / [CO₂]. ومنه [CO]² = 1.90 × 0.0500 = 0.0950، فـ [CO] = √0.0950 = 0.308 mol/L.', '["هذه قيمة [CO]²؛ نُسي أخذ الجذر التربيعي.","قُلبت العلاقة: √(Keq / [CO₂]) = 6.16، والصحيح [CO]² = Keq × [CO₂].","","قُسم Keq × [CO₂] على المعامل 2 بدل أخذ الجذر التربيعي: 0.0950 ÷ 2 = 0.0475."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-06T22:20:31.242Z"}'::jsonb),
('essay', 1, null::int, null, null, 'Keq = [H₂]²[S₂] / [H₂S]²، ومنه [S₂] = Keq × [H₂S]² / [H₂]² = 2.27 × 10⁻³ × (0.150)² / (0.0300)² = 2.27 × 10⁻³ × 0.0225 / 9.00 × 10⁻⁴ = 0.0568 mol/L.
التقويم: Keq < 1 فالمتفاعلات مفضلة في خليط الاتزان؛ وفعلًا [H₂S] = 0.150 mol/L أكبر من تركيز كل من الناتجين (0.0300 و0.0568 mol/L)، فالإجابة معقولة.', '["كتابة تعبير Keq = [H₂]²[S₂]/[H₂S]²","إعادة ترتيب التعبير لإيجاد [S₂]","التعويض الصحيح مع التربيع","[S₂] = 0.0568 mol/L","ربط النتيجة بأن Keq < 1 يعني تفضيل المتفاعلات"]'::jsonb, '["Keq = [H₂]²[S₂] / [H₂S]²","[S₂] = Keq × [H₂S]² / [H₂]²","[S₂] = 2.27 × 10⁻³ × (0.150)² / (0.0300)²","[S₂] = 5.1075 × 10⁻⁵ / 9.00 × 10⁻⁴ = 0.0568 mol/L","Keq < 1 والمتفاعل H₂S أعلى تركيزًا من النواتج، فالنتيجة معقولة"]'::jsonb, '[{"element":"كتابة تعبير ثابت الاتزان","marks":1},{"element":"إعادة الترتيب والتعويض","marks":1},{"element":"الناتج 0.0568 mol/L بالوحدة","marks":1},{"element":"تقويم الإجابة بدلالة قيمة Keq","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعبير صحيح وحساب صحيح بالوحدة وتقويم سليم للنتيجة"},{"level":"2–3 درجات","description":"تعبير صحيح مع خطأ في التربيع أو غياب التقويم"},{"level":"1 درجة","description":"كتابة التعبير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الأس 2 على [H₂] أو [H₂S]","قلب التعبير ووضع المتفاعلات في البسط","إغفال الوحدة mol/L"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-06T22:20:31.242Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) استُهلك من A: 1.00 − 0.400 = 0.600 mol/L، ونسب المعادلة 1 : 1 : 1 : 1، فيُستهلك من B المقدار نفسه: [B] = 0.400 mol/L، ويتكون [C] = [D] = 0.600 mol/L.
Keq = [C][D] / ([A][B]) = (0.600)(0.600) / ((0.400)(0.400)) = 2.25.
(ب) Keq ثابت عند درجة الحرارة نفسها: 2.25 = [C]² / (0.200 × 0.200)، فـ [C]² = 0.0900 و[C] = 0.300 mol/L.', '["[B] = 0.400 mol/L","[C] = [D] = 0.600 mol/L","Keq = 2.25","استعمال قيمة Keq نفسها في التجربة الثانية","[C] = 0.300 mol/L"]'::jsonb, '["المستهلك من A = 1.00 − 0.400 = 0.600 mol/L","[B] = 1.00 − 0.600 = 0.400 mol/L، [C] = [D] = 0.600 mol/L","Keq = (0.600 × 0.600) / (0.400 × 0.400) = 2.25","[C]² = Keq × [A][B] = 2.25 × 0.200 × 0.200 = 0.0900","[C] = √0.0900 = 0.300 mol/L"]'::jsonb, '[{"element":"تراكيز B وC وD من نسب المعادلة","marks":2},{"element":"حساب Keq","marks":1},{"element":"إدراك أن Keq لا يتغير عند درجة الحرارة نفسها","marks":1},{"element":"حساب [C] = 0.300 mol/L","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"التراكيز وKeq وتركيز C في التجربة الثانية كلها صحيحة"},{"level":"3–5 درجات","description":"الجزء (أ) صحيح مع خطأ في الجزء (ب)، أو العكس"},{"level":"1–2 درجة","description":"تحديد بعض التراكيز فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ [C] مساويًا للمتبقي من A (0.400) بدل المستهلك","نسيان أخذ الجذر التربيعي في الجزء (ب)","الظن أن Keq يتغير بتغير التراكيز الابتدائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-06T22:20:31.242Z"}'::jsonb),
('essay', 3, null::int, null, null, 'Keq = [PCl₃][Cl₂] / [PCl₅]. من المنحنى عند الاتزان: [PCl₅] = 0.200 M و[PCl₃] = 0.100 M.
[Cl₂] = Keq × [PCl₅] / [PCl₃] = 0.0450 × 0.200 / 0.100 = 0.0900 M، وهي قيمة أقل قليلًا من [PCl₃] كما يظهر في المنحنى.', '["Keq = [PCl₃][Cl₂]/[PCl₅]","قراءة [PCl₅] = 0.200 M و[PCl₃] = 0.100 M من المنحنى","إعادة الترتيب","[Cl₂] = 0.0900 M"]'::jsonb, '["Keq = [PCl₃][Cl₂] / [PCl₅]","[Cl₂] = Keq × [PCl₅] / [PCl₃]","[Cl₂] = 0.0450 × 0.200 / 0.100 = 0.0900 M"]'::jsonb, '[{"element":"كتابة التعبير","marks":1},{"element":"قراءة التراكيز من المنحنى","marks":1},{"element":"الحساب والناتج بالوحدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعبير صحيح وقراءة صحيحة وناتج صحيح بالوحدة"},{"level":"1–2 درجة","description":"تعبير صحيح مع خطأ في القراءة أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ [Cl₂] مساويًا لـ [PCl₃] دون حساب","قلب التعبير: [Cl₂] = [PCl₃] / (Keq × [PCl₅])","قراءة القيم الابتدائية بدل قيم الجزء الأفقي من المنحنى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-06T22:20:31.243Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C3-L3-O01') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L3-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا تُعد قيم ثابت حاصل الذائبية Ksp مهمة؟', null, null, '["لأنها تحدد سرعة ذوبان المركبات الأيونية في الماء","لأنها تبين كتلة المادة الصلبة المتبقية في قاع الإناء","لأنه يمكن استعمالها في تحديد ذائبية المركبات القليلة الذوبان","لأنها تحدد ذائبية المركبات العالية الذوبان مثل NaCl"]'::jsonb, 'تذكر', 'أهمية Ksp', 'سهل', 'الكتاب ص 102 — استعمال ثابت حاصل الذائبية'),
('mcq', 2, 'لا تُقاس قيمة لثابت حاصل الذائبية Ksp ولا تُسجَّل لمركبات مثل كلوريد الصوديوم NaCl. ما سبب ذلك؟', null, null, '["لأن NaCl عالي الذائبية، وثوابت حاصل الذائبية تُسجل للمركبات القليلة الذوبان فقط","لأن NaCl لا يتفكك إلى أيونات عند ذوبانه في الماء","لأن قيمة Ksp لـ NaCl تساوي صفرًا لشدة ذوبانه في الماء","لأن NaCl مادة صلبة، والمواد الصلبة لا تُكتب في تعبير Ksp"]'::jsonb, 'فهم', 'Ksp للمركبات القليلة الذوبان', 'متوسط', 'الكتاب ص 101 و113 — السؤال 59'),
('mcq', 3, 'يُستعمل هيدروكسيد الماغنسيوم Mg(OH)₂ القليل الذوبان مضادًّا للحموضة، ويتفكك وفق الاتزان Mg(OH)₂(s) ⇌ Mg²⁺(aq) + 2OH⁻(aq). ما تعبير ثابت حاصل الذائبية له؟', null, null, '["Ksp = [Mg²⁺][OH⁻]","Ksp = [Mg²⁺][OH⁻]² / [Mg(OH)₂]","Ksp = [Mg²⁺][2OH⁻]","Ksp = [Mg²⁺][OH⁻]²"]'::jsonb, 'فهم', 'كتابة تعبير Ksp', 'سهل', 'الكتاب ص 101 — الجدول 3-3 ثوابت حاصل الذائبية'),
('mcq', 4, 'يبين الشكل الآتي محلولًا مشبعًا ليوديد الفضة AgI عند 298 K. ماذا تدل عليه القيمة الصغيرة جدًّا لـ Ksp لهذا المركب؟', null, '[{"src":"qimg/chem22/c3-l3a-agi-saturated.svg","alt":"رسم لكأس فيها محلول مائي، وفي قاعها طبقة من حبيبات صلبة مكتوب تحتها «AgI(s) غير ذائب». في المحلول فوق المادة الصلبة عدد قليل من الأيونات: ثلاثة أيونات Ag⁺ وثلاثة أيونات I⁻. وتحت الكأس معادلة الاتزان AgI(s) ⇌ Ag⁺(aq) + I⁻(aq)، وتحتها القيمة Ksp = 8.5 × 10⁻¹⁷ عند 298 K."}]'::jsonb, '["يذوب AgI كله في الماء، ولكن ببطء شديد حتى يبلغ الاتزان","يذوب مقدار ضئيل جدًّا من AgI، فتراكيز أيوناته في المحلول المشبع صغيرة جدًّا","يتوقف الذوبان والترسيب تمامًا عند الاتزان، فلا تحدث أي عملية","كتلة AgI الصلبة المتبقية في قاع الكأس صغيرة جدًّا"]'::jsonb, 'فهم', 'دلالة قيمة Ksp', 'متوسط', 'الكتاب ص 101 — الجدول 3-3 ثوابت حاصل الذائبية'),
('mcq', 5, 'اعتمادًا على قيم Ksp الواردة في الجدول الآتي عند 298 K، أي هاليدات الفضة الآتية له أكبر ذائبية مولارية في الماء؟', '{"headers":["المركب","Ksp عند 298 K"],"rows":[["AgCl","1.8 × 10⁻¹⁰"],["AgBr","5.4 × 10⁻¹³"],["AgI","8.5 × 10⁻¹⁷"]]}'::jsonb, null, '["AgI؛ لأن قيمة Ksp له هي الأصغر","AgCl؛ لأن قيمة Ksp له هي الأكبر","AgBr؛ لأن قيمة Ksp له متوسطة بين الثلاثة","متساوية؛ لأن نسبة الأيونات 1 : 1 فيها جميعًا"]'::jsonb, 'فهم', 'مقارنة الذائبية باستعمال Ksp', 'متوسط', 'الكتاب ص 101 — الجدول 3-3 ثوابت حاصل الذائبية'),
('mcq', 6, 'أي العوامل الآتية يغير قيمة ثابت حاصل الذائبية Ksp لكبريتات الباريوم BaSO₄؟', null, null, '["تغيير درجة الحرارة","إضافة مزيد من BaSO₄ الصلب","إضافة محلول Na₂SO₄ إليه","زيادة حجم الماء في الإناء"]'::jsonb, 'فهم', 'ثبات Ksp', 'سهل', 'الكتاب ص 100 — ثابت حاصل الذائبية'),
('mcq', 7, 'يبين الشكل الآتي محلولًا مشبعًا ليوديد الرصاص II فوق فائض من PbI₂ الصلب. أي العبارات الآتية صحيحة؟', null, '[{"src":"qimg/chem22/c3-l3a-pbi2-saturated.svg","alt":"رسم لكأس فيها محلول مائي مشبع، وفي قاعها طبقة من حبيبات صلبة مكتوب تحتها «PbI₂(s) غير ذائب». في المحلول فوق المادة الصلبة أيونان Pb²⁺ وأربعة أيونات I⁻. وتحت الكأس معادلة الاتزان PbI₂(s) ⇌ Pb²⁺(aq) + 2I⁻(aq)."}]'::jsonb, '["Ksp = [Pb²⁺][I⁻]² / [PbI₂]؛ لأن الصلب أحد طرفي الاتزان","Ksp = [Pb²⁺][2I⁻]؛ لأن لكل أيون Pb²⁺ أيوني I⁻","إضافة مزيد من PbI₂ الصلب تزيد [Pb²⁺] و[I⁻] في المحلول","يلزم وجود PbI₂ صلب للاتزان، ولا يظهر في Ksp = [Pb²⁺][I⁻]²"]'::jsonb, 'فهم', 'المادة الصلبة وتعبير Ksp', 'صعب', 'الكتاب ص 101 — الجدول 3-3 ثوابت حاصل الذائبية'),
('essay', 1, 'فسّر أهمية ثابت حاصل الذائبية Ksp، ثم وضّح كيف يُستعمل لحساب الذائبية المولارية ليوديد الفضة AgI عند 298 K، علمًا بأن Ksp = 8.5 × 10⁻¹⁷.', null, null, null, 'فهم', 'أهمية Ksp واستعماله', 'متوسط', 'الكتاب ص 102 — استعمال ثابت حاصل الذائبية'),
('essay', 2, 'فسّر كلًّا مما يأتي:
(أ) لا تُسجل قيمة Ksp لمركبات مثل كلوريد الصوديوم.
(ب) لا يُكتب تركيز المادة الصلبة في تعبير Ksp، مع أن وجود بعضها في المحلول المشبع ضروري.
(ج) تبقى قيمة Ksp لكبريتات الباريوم ثابتة عند إضافة مزيد من BaSO₄ الصلب إلى محلوله المشبع عند درجة الحرارة نفسها.', null, null, null, 'فهم', 'خصائص Ksp وحدود استعماله', 'صعب', 'الكتاب ص 100 — ثابت حاصل الذائبية'),
('essay', 3, 'يقول طالب: «كلوريد الفضة AgCl (Ksp = 1.8 × 10⁻¹⁰) أكثر ذائبية في الماء من كرومات الفضة Ag₂CrO₄ (Ksp = 1.1 × 10⁻¹²)؛ لأن قيمة Ksp له أكبر». قوّم هذه العبارة بحساب الذائبية المولارية لكل منهما عند 298 K، ثم بيّن متى تصح مقارنة الذائبية بقيم Ksp مباشرة.', null, null, null, 'تقويم', 'مقارنة الذائبية بين أنواع مختلفة', 'صعب', 'الكتاب ص 101 — الجدول 3-3 ثوابت حاصل الذائبية و102–103')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L3-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تُقاس ثوابت حاصل الذائبية بالتجربة، وتكمن أهميتها في أنه يمكن استعمالها في تحديد ذائبية المركبات الأيونية القليلة الذوبان (كمية المادة التي تذوب في حجم معين من الماء عند درجة حرارة معينة).', '["Ksp ثابت اتزان لا علاقة له بسرعة الذوبان، بل بالتراكيز عند الاتزان.","المادة الصلبة لا تظهر في تعبير Ksp، فلا يدل على كمية الصلب المتبقي.","","ثوابت حاصل الذائبية تُقاس وتُسجل للمركبات القليلة الذوبان فقط، لا للعالية الذوبان مثل NaCl."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-06T22:20:31.243Z"}'::jsonb),
('mcq', 2, 0, 'يذوب NaCl بسرعة وبكميات كبيرة في الماء (ذائبيته عالية)، أما ثوابت حاصل الذائبية فتُقاس وتُسجل للمركبات القليلة الذوبان فقط، ولذلك لا تُعطى له قيمة Ksp.', '["","NaCl مركب أيوني يتفكك في الماء: NaCl(s) → Na⁺(aq) + Cl⁻(aq).","لو كانت Ksp صفرًا لكانت تراكيز الأيونات صفرًا، أي أن المركب لا يذوب، وهذا عكس ذائبية NaCl العالية.","المركبات التي تُسجَّل لها قيم Ksp مواد صلبة أيضًا؛ واستبعاد الصلب من التعبير لا يمنع وجود قيمة Ksp للمركب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-06T22:20:31.243Z"}'::jsonb),
('mcq', 3, 3, 'Ksp هو ناتج ضرب تراكيز الأيونات الذائبة كل منها مرفوع لأس يساوي معامله في المعادلة، ولا تُكتب المادة الصلبة؛ فـ Ksp = [Mg²⁺][OH⁻]².', '["أُهمل المعامل 2 لأيون OH⁻؛ فيجب أن يُرفع تركيزه للأس 2.","المادة الصلبة Mg(OH)₂ لا تُكتب في تعبير Ksp؛ لأن تركيزها ثابت.","المعامل يظهر أسًّا لا معاملًا داخل القوس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-06T22:20:31.244Z"}'::jsonb),
('mcq', 4, 1, 'تدل قيمة Ksp الصغيرة على أن النواتج (الأيونات) لا تزداد تراكيزها كثيرًا عند الاتزان؛ أي أن ما يذوب من AgI ضئيل جدًّا وتراكيز Ag⁺ وI⁻ في المحلول المشبع صغيرة جدًّا.', '["يبقى معظم AgI صلبًا في قاع الكأس؛ وKsp يتعلق بمقدار ما يذوب عند الاتزان لا بسرعة الذوبان.","","الاتزان ديناميكي: يستمر الذوبان والترسيب بسرعتين متساويتين.","كمية الصلب لا تظهر في تعبير Ksp، فلا تدل قيمته على كتلة الصلب المتبقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.244Z"}'::jsonb),
('mcq', 5, 1, 'للمركبات الثلاثة النسبة نفسها بين الأيونات (1 : 1)، فالذائبية المولارية s = √Ksp، وكلما كبرت Ksp كبرت الذائبية. أكبر قيمة هي Ksp لـ AgCl (1.8 × 10⁻¹⁰)، فـ AgCl هو الأكثر ذائبية (s ≈ 1.3 × 10⁻⁵ mol/L).', '["أصغر Ksp يعني أقل ذائبية لا أكبرها؛ فـ AgI هو الأقل ذائبية.","","قيمة Ksp لـ AgBr أصغر من قيمة AgCl، فذائبيته أقل منه.","تساوي نسبة الأيونات يجعل المقارنة بـ Ksp مباشرة، لكن قيم Ksp مختلفة فالذائبيات مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.244Z"}'::jsonb),
('mcq', 6, 0, 'Ksp ثابت اتزان، وقيمته ثابتة لمركب معين عند درجة حرارة محددة؛ فالعامل الوحيد بين الخيارات الذي يغيرها هو درجة الحرارة.', '["","المادة الصلبة لا تظهر في تعبير Ksp، فإضافتها لا تغير قيمته.","إضافة أيون مشترك (SO₄²⁻) تقلل ذائبية BaSO₄ لكن Ksp يبقى ثابتًا.","زيادة الماء قد تذيب كمية أكبر من المادة لكن تراكيز الأيونات في المحلول المشبع وKsp لا تتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-06T22:20:31.244Z"}'::jsonb),
('mcq', 7, 3, 'تعتمد قيمة Ksp على تراكيز الأيونات فقط في المحلول المشبع: Ksp = [Pb²⁺][I⁻]²، إلا أن بعض المادة الصلبة يجب أن يوجد في خليط الاتزان مهما كانت كميته قليلة؛ وتركيز الصلب النقي ثابت فلا يُكتب في التعبير.', '["المادة الصلبة النقية لا تُكتب في تعبير Ksp لأن تركيزها ثابت.","المعامل 2 يصبح أسًّا لتركيز I⁻ لا معاملًا داخل القوس.","المحلول مشبع، فإضافة الصلب لا تغير تراكيز الأيونات؛ إذ يبقى ناتج ضربها مساويًا لـ Ksp.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.244Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تكمن أهمية Ksp في أنه يمكن استعماله في تحديد ذائبية المركبات الأيونية القليلة الذوبان؛ إذ يربط تراكيز الأيونات في المحلول المشبع بكمية المادة التي تذوب.
AgI(s) ⇌ Ag⁺(aq) + I⁻(aq)، وKsp = [Ag⁺][I⁻]. لكل مول يذوب من AgI يتكون 1 mol من Ag⁺ و1 mol من I⁻، فإذا كانت الذائبية s فإن [Ag⁺] = [I⁻] = s.
s² = 8.5 × 10⁻¹⁷ ← s = √(8.5 × 10⁻¹⁷) = 9.2 × 10⁻⁹ mol/L.', '["Ksp يُستعمل لتحديد ذائبية المركبات القليلة الذوبان","كتابة معادلة الاتزان وتعبير Ksp","[Ag⁺] = [I⁻] = s","s = 9.2 × 10⁻⁹ mol/L"]'::jsonb, '["AgI(s) ⇌ Ag⁺(aq) + I⁻(aq)","Ksp = [Ag⁺][I⁻] = s × s = s²","s = √(8.5 × 10⁻¹⁷) = 9.2 × 10⁻⁹ mol/L"]'::jsonb, '[{"element":"ذكر أهمية Ksp","marks":1},{"element":"المعادلة والتعبير","marks":1},{"element":"ربط تراكيز الأيونات بالذائبية s","marks":1},{"element":"حساب s بالوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أهمية صحيحة وخطوات كاملة وناتج صحيح"},{"level":"2–3 درجات","description":"أهمية صحيحة مع نقص في الخطوات أو خطأ حسابي"},{"level":"1 درجة","description":"ذكر الأهمية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ Ksp نفسه هو الذائبية","نسيان أخذ الجذر التربيعي","إدخال AgI الصلب في التعبير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-06T22:20:31.245Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) لأن NaCl عالي الذائبية، وثوابت حاصل الذائبية تُقاس وتُسجل للمركبات الأيونية القليلة الذوبان فقط التي يقوم بينها وبين أيوناتها اتزان في محلول مشبع.
(ب) لأن تركيز المادة الصلبة النقية (كثافتها بوحدة mol/L) ثابت عند درجة حرارة محددة، فلا يُكتب في تعابير ثوابت الاتزان غير المتجانس؛ لكن وجود بعض الصلب ضروري ليقوم الاتزان بين الصلب وأيوناته، مهما كانت كميته قليلة.
(ج) لأن Ksp يعتمد فقط على تراكيز الأيونات في المحلول المشبع، والمحلول مشبع أصلًا، فلا يزداد تركيز الأيونات بإضافة الصلب، وKsp لا يتغير إلا بتغير درجة الحرارة.', '["Ksp يُسجل للمركبات القليلة الذوبان فقط","تركيز الصلب النقي ثابت فلا يُكتب","وجود الصلب شرط لقيام الاتزان","Ksp يعتمد على تراكيز الأيونات ودرجة الحرارة فقط"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير (أ)","marks":2},{"element":"تفسير (ب)","marks":2},{"element":"تفسير (ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تفسيرات الأجزاء الثلاثة صحيحة ومكتملة"},{"level":"3–5 درجات","description":"تفسيران صحيحان أو ثلاثة ناقصة"},{"level":"1–2 درجة","description":"تفسير واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول بأن NaCl لا يتفكك إلى أيونات","الظن أن زيادة الصلب تزيد تراكيز الأيونات","الظن أن تركيز الصلب يتغير بتغير كتلته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-06T22:20:31.245Z"}'::jsonb),
('essay', 3, null::int, null, null, 'AgCl: Ksp = [Ag⁺][Cl⁻] = s² ← s = √(1.8 × 10⁻¹⁰) = 1.3 × 10⁻⁵ mol/L.
Ag₂CrO₄(s) ⇌ 2Ag⁺(aq) + CrO₄²⁻(aq): إذا كانت الذائبية x فإن [CrO₄²⁻] = x و[Ag⁺] = 2x، فـ Ksp = (2x)²(x) = 4x³ = 1.1 × 10⁻¹² ← x = ∛(2.75 × 10⁻¹³) = 6.5 × 10⁻⁵ mol/L.
إذن Ag₂CrO₄ أكثر ذائبية مولارية من AgCl رغم أن Ksp له أصغر، فعبارة الطالب خاطئة. تصح مقارنة الذائبية بقيم Ksp مباشرة فقط بين مركبات لها النسبة نفسها بين الأيونات (مثل AgCl وAgBr وAgI).', '["s(AgCl) = 1.3 × 10⁻⁵ mol/L","Ksp = 4x³ لـ Ag₂CrO₄","s(Ag₂CrO₄) = 6.5 × 10⁻⁵ mol/L","الحكم بأن العبارة خاطئة","المقارنة المباشرة تصح للمركبات المتماثلة في نسبة الأيونات"]'::jsonb, '["s(AgCl) = √(1.8 × 10⁻¹⁰) = 1.3 × 10⁻⁵ mol/L","Ag₂CrO₄: Ksp = (2x)²(x) = 4x³","x³ = 1.1 × 10⁻¹² ÷ 4 = 2.75 × 10⁻¹³","x = ∛(2.75 × 10⁻¹³) = 6.5 × 10⁻⁵ mol/L","6.5 × 10⁻⁵ > 1.3 × 10⁻⁵ ← Ag₂CrO₄ أكثر ذائبية"]'::jsonb, '[{"element":"ذائبية AgCl","marks":1},{"element":"تعبير 4x³ وذائبية Ag₂CrO₄","marks":2},{"element":"الحكم على العبارة","marks":1},{"element":"شرط المقارنة المباشرة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابان صحيحان والحكم وشرط المقارنة سليمان"},{"level":"3–4 درجات","description":"حساب واحد صحيح مع حكم سليم، أو خطأ في 4x³"},{"level":"1–2 درجة","description":"حكم دون حساب أو حساب ذائبية AgCl فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال s = √Ksp لـ Ag₂CrO₄","كتابة Ksp = (x)(2x) بدل (2x)²(x)","مقارنة قيم Ksp مباشرة بين مركبين مختلفين في نسبة الأيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.245Z"}'::jsonb)
