from (values
('mcq', 1, 'يشرب المريض خليطًا يحتوي على كبريتات الباريوم BaSO₄ قبل تصوير جهازه الهضمي بالأشعة السينية، مع أن أيونات الباريوم سامة. لماذا يُعد ذلك آمنًا؟', null, null, '["لأن BaSO₄ لا يحتوي على أيونات باريوم في تركيبه","لأن ذائبيته منخفضة جدًّا، فلا يذوب منه إلا مقدار قليل من Ba²⁺","لأن BaSO₄ يذوب كليًّا ويخرج من الجسم بسرعة قبل أن يضر","لأن أيونات SO₄²⁻ تتفاعل مع حمض المعدة فتزيل سمية الباريوم"]'::jsonb, 'فهم', 'تعليل أمان BaSO₄', 'سهل', 'الكتاب ص 100–101 — كبريتات الباريوم والتصوير بالأشعة السينية'),
('mcq', 2, 'ما الذي يجعل تناول مركبات الباريوم العالية الذائبية مثل كلوريد الباريوم BaCl₂ خطرًا على الإنسان؟', null, null, '["أيونات Cl⁻ الناتجة عن تفككه في الجسم","عدم قدرة المركب على امتصاص الأشعة السينية","أيونات Ba²⁺ السامة التي يطلقها بتراكيز عالية","ترسبه في المعدة على هيئة مادة صلبة"]'::jsonb, 'تذكر', 'مصدر سمية مركبات الباريوم', 'سهل', 'الكتاب ص 100–101 — كبريتات الباريوم والتصوير بالأشعة السينية'),
('mcq', 3, 'ثابت حاصل الذائبية لكبريتات الباريوم Ksp = 1.1 × 10⁻¹⁰ عند 298 K. ما تركيز أيونات Ba²⁺ في محلولها المشبع؟', null, null, '["1.1 × 10⁻¹⁰ M","5.5 × 10⁻¹¹ M","2.1 × 10⁻⁵ M","1.0 × 10⁻⁵ M"]'::jsonb, 'تطبيق', 'حساب [Ba²⁺] في محلول BaSO₄ المشبع', 'متوسط', 'الكتاب ص 101 — Ksp لـ BaSO₄'),
