('mcq', 5, 'يبين المنحنى الآتي تغير تركيز أيونات Ba²⁺ في محلول BaSO₄ مشبع عند إضافة كميات متزايدة من كبريتات الصوديوم Na₂SO₄. ما تفسير هذا التغير؟', null, '[{"src":"qimg/chem22/c3-l3a-baso4-common-ion.svg","alt":"منحنى بياني عنوانه «محلول BaSO₄ مشبع عند 298 K». المحور الأفقي تركيز Na₂SO₄ المضاف بوحدة mol/L من 0 إلى 0.10، والمحور الرأسي [Ba²⁺] بوحدة mol/L بتدريج لوغاريتمي من 10⁻¹⁰ إلى 10⁻⁴. يبدأ المنحنى عند تركيز Na₂SO₄ يساوي صفرًا من قيمة قريبة من 10⁻⁵ mol/L، ثم ينخفض بحدة عند إضافة كميات صغيرة من Na₂SO₄، ثم يستمر في الانخفاض ببطء حتى يقارب 10⁻⁹ mol/L عند 0.10 mol/L من Na₂SO₄."}]'::jsonb, '["يتحد Na⁺ مع Ba²⁺ فيكوّنان مركبًا جديدًا غير ذائب في الماء","تزداد قيمة Ksp لـ BaSO₄ بزيادة تركيز Na₂SO₄","يزيح أيون SO₄²⁻ المشترك الاتزان نحو تكوين مزيد من BaSO₄ الصلب","يخفف Na₂SO₄ المحلول فيقل تركيز Ba²⁺ بسبب التخفيف وحده"]'::jsonb, 'فهم', 'تأثير الأيون المشترك في ذائبية BaSO₄', 'متوسط', 'الكتاب ص 107 — تأثير الأيون المشترك وتناول BaSO₄'),
('mcq', 6, 'في كل من الكأسين في الشكل الآتي الكتلة نفسها من مركب للباريوم: إحداهما فيها BaCl₂ والأخرى فيها BaSO₄. أي الكأسين يمثل المركب المستعمل في التصوير بالأشعة السينية، ولماذا؟', null, '[{"src":"qimg/chem22/c3-l3a-ba-beakers.svg","alt":"رسم لكأسين متجاورتين، في كل منهما الكتلة نفسها من مركب للباريوم في 100 mL من الماء عند 25 °C. الكأس (1) على اليسار: لا توجد فيها أي مادة صلبة، ومكتوب تحتها «المركب ذاب كله»، وفي محلولها عدد كبير من الأيونات: خمسة أيونات Ba²⁺ وعشرة أيونات Cl⁻. الكأس (2) على اليمين: في قاعها طبقة سميكة من مادة صلبة غير ذائبة، وفي محلولها أيون Ba²⁺ واحد وأيون SO₄²⁻ واحد فقط."}]'::jsonb, '["الكأس (1)؛ لأن المركب ذاب كله فتنتشر أيوناته في الجهاز الهضمي","الكأس (2)؛ لأن ما يذوب منه قليل جدًّا فيبقى تركيز Ba²⁺ منخفضًا","الكأس (1)؛ لأن أيونات Cl⁻ الكثيرة تمنع امتصاص أيونات Ba²⁺","الكأس (2)؛ لأن المادة الصلبة فيها لا تحتوي على أيونات Ba²⁺"]'::jsonb, 'فهم', 'تفسير نموذج جسيمي للذائبية', 'متوسط', 'الكتاب ص 100–101 — كبريتات الباريوم والتصوير بالأشعة السينية'),
('mcq', 7, 'يبين الجدول الآتي قيم Ksp لثلاثة مركبات قليلة الذوبان للباريوم عند 298 K، ونسبة الأيونات في كل منها 1 : 1. أي المركبات الثلاثة يعطي محلوله المشبع أقل تركيز من أيونات Ba²⁺ السامة، ولماذا؟', '{"headers":["المركب","Ksp عند 298 K"],"rows":[["BaCO₃","2.6 × 10⁻⁹"],["BaCrO₄","1.2 × 10⁻¹⁰"],["BaSO₄","1.1 × 10⁻¹⁰"]]}'::jsonb, null, '["BaSO₄؛ لأن قيمة Ksp له هي الأصغر، فـ [Ba²⁺] = √Ksp فيه هو الأقل","BaCO₃؛ لأن قيمة Ksp الأكبر تعني أن المركب أقل ذائبية","لا يمكن الحكم؛ لأن Ksp لا يدل على الذائبية إلا بمعرفة كتلة الصلب","تتساوى [Ba²⁺] في المحاليل الثلاثة؛ لأن نسبة الأيونات 1 : 1 فيها جميعًا"]'::jsonb, 'تحليل', 'Ksp والأيون المشترك', 'متوسط', 'الكتاب ص 101 — الجدول 3-3 ثوابت حاصل الذائبية وكبريتات الباريوم'),
('essay', 1, 'لماذا تُعد كبريتات الباريوم BaSO₄ (Ksp = 1.1 × 10⁻¹⁰ عند 298 K) أفضل من كلوريد الباريوم BaCl₂ عند التعرض للأشعة السينية، علمًا بأن 37.5 g من BaCl₂ (208.23 g/mol) يمكن أن تذوب في 100 mL من الماء عند 26 °C؟ دعّم إجابتك بحساب تركيز أيونات Ba²⁺ في المحلول المشبع لكل من المركبين.', null, null, null, 'تحليل', 'تعليل مدعوم بحساب', 'صعب', 'الكتاب ص 113 — السؤال 60'),
('essay', 2, 'يُضاف أحيانًا قليل من كبريتات الصوديوم Na₂SO₄ إلى خليط كبريتات الباريوم الذي يتناوله المريض قبل التصوير بالأشعة السينية. اكتب معادلة اتزان ذائبية BaSO₄، ثم فسّر باستعمال مبدأ لوتشاتلييه كيف تزيد هذه الإضافة من أمان المريض.', null, null, null, 'فهم', 'تفسير بمبدأ لوتشاتلييه', 'سهل', 'الكتاب ص 107 — تأثير الأيون المشترك وتناول BaSO₄'),
('essay', 3, 'احسب كتلة كبريتات الباريوم BaSO₄ (الكتلة المولية 233.40 g/mol، Ksp = 1.1 × 10⁻¹⁰ عند 298 K) التي يمكن أن تذوب في 250 mL من الماء، ثم بيّن ما تدل عليه النتيجة بخصوص استعمالها في تصوير الجهاز الهضمي.', null, null, null, 'تطبيق', 'حساب كتلة ذائبة وتفسيرها', 'متوسط', 'الكتاب ص 100–101 — كبريتات الباريوم والتصوير بالأشعة السينية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
