select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'قيمة Ksp لـ BaSO₄ صغيرة (1.1 × 10⁻¹⁰)، فذائبيته منخفضة جدًّا، وكمية أيونات Ba²⁺ التي تذوب منه في الجهاز الهضمي قليلة لا تسبب ضررًا.', '["BaSO₄ مركب أيوني يتكون من أيونات Ba²⁺ وSO₄²⁻، ويتفكك جزء ضئيل منه في الماء.","","BaSO₄ قليل الذوبان جدًّا ولا يذوب كليًّا؛ ولو ذاب كله لكان سامًّا.","لا علاقة لحمض المعدة بالأمان هنا؛ السبب انخفاض ذائبية BaSO₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-06T22:20:31.246Z"}'::jsonb),
('mcq', 2, 2, 'أيونات الباريوم Ba²⁺ مادة سامة للإنسان، وBaCl₂ عالي الذائبية فيتفكك كليًّا ويطلق تراكيز عالية منها؛ ولذلك لا يُستعمل في التصوير بالأشعة السينية.', '["أيونات الكلوريد موجودة في الجسم أصلًا (في حمض المعدة وملح الطعام) وليست مصدر الخطر.","الخطر في سمية أيونات الباريوم، لا في قدرة المركب على امتصاص الأشعة.","","BaCl₂ عالي الذائبية فلا يترسب؛ وترسب المادة ليس هو مصدر السمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-06T22:20:31.246Z"}'::jsonb),
('mcq', 3, 3, 'BaSO₄(s) ⇌ Ba²⁺(aq) + SO₄²⁻(aq)، و[Ba²⁺] = [SO₄²⁻] = s، فـ Ksp = s² = 1.1 × 10⁻¹⁰، ومنه [Ba²⁺] = √(1.1 × 10⁻¹⁰) = 1.0 × 10⁻⁵ M.', '["هذه قيمة Ksp نفسها، وهي ناتج ضرب تركيزي الأيونين لا تركيز أحدهما.","قُسمت Ksp على 2 بدل أخذ الجذر التربيعي.","ضُرب الجذر في 2 ظنًّا أن لكل وحدة أيونين؛ وتركيز Ba²⁺ وحده يساوي s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-06T22:20:31.246Z"}'::jsonb),
('mcq', 4, 0, 'عدد مولات BaCl₂ = 37.5 g ÷ 208.23 g/mol = 0.180 mol، والحجم 100 mL = 0.100 L، فالتركيز = 0.180 ÷ 0.100 = 1.80 M؛ ولكل وحدة BaCl₂ أيون Ba²⁺ واحد، فـ [Ba²⁺] = 1.80 M (أكبر بنحو 10⁵ مرة من تركيزه في محلول BaSO₄ المشبع).', '["","هذا عدد المولات (0.180 mol) لا التركيز؛ لم يُقسم على الحجم 0.100 L.","ضُرب في 2 كأن لكل وحدة BaCl₂ أيوني Ba²⁺؛ والعدد 2 يخص أيونات Cl⁻.","قُسمت الكتلة على الحجم بالمليلتر (37.5 ÷ 100) دون التحويل إلى مولات ولترات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-06T22:20:31.246Z"}'::jsonb),
('mcq', 5, 2, 'يوفر Na₂SO₄ الذائب الأيون المشترك SO₄²⁻، فيزداد الجهد على الاتزان BaSO₄(s) ⇌ Ba²⁺(aq) + SO₄²⁻(aq)، فيُزاح نحو اليسار وفق مبدأ لوتشاتلييه لإنتاج مزيد من BaSO₄ الصلب، فيقل [Ba²⁺] كما يظهر في المنحنى.', '["أيونان موجبان لا يتحدان معًا؛ والأيون المؤثر هو SO₄²⁻.","Ksp ثابت عند درجة الحرارة نفسها؛ وانخفاض [Ba²⁺] سببه ازدياد [SO₄²⁻].","","يبين المنحنى انخفاض [Ba²⁺] من نحو 10⁻⁵ إلى نحو 10⁻⁹ mol/L، وهذا لا يفسره التخفيف بل تأثير الأيون المشترك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-06T22:20:31.247Z"}'::jsonb),
('mcq', 6, 1, 'الكأس (2) فيها مركب قليل الذوبان (BaSO₄): يبقى معظمه صلبًا ولا يوجد في المحلول إلا القليل من أيونات Ba²⁺، فهو آمن للمريض؛ أما الكأس (1) ففيها BaCl₂ الذي ذاب كله وأطلق تركيزًا كبيرًا من أيونات Ba²⁺ السامة.', '["ذوبان المركب كله يعني تركيزًا عاليًا من Ba²⁺ السام، وهذا سبب رفض BaCl₂.","","لا تمنع أيونات Cl⁻ امتصاص Ba²⁺؛ والكأس (1) خطرة لكثرة Ba²⁺ الذائب.","الصلب في الكأس (2) هو BaSO₄ المكون من أيونات Ba²⁺ وSO₄²⁻؛ وأمانه سببه قلة ما يذوب منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-06T22:20:31.247Z"}'::jsonb),
('mcq', 7, 0, 'في كل من المركبات الثلاثة [Ba²⁺] = [الأنيون] = s، فـ Ksp = s² و[Ba²⁺] = √Ksp؛ أي أن أصغر Ksp يعطي أقل [Ba²⁺]. أصغر القيم لـ BaSO₄ (1.1 × 10⁻¹⁰)، فـ [Ba²⁺] = √(1.1 × 10⁻¹⁰) = 1.0 × 10⁻⁵ M، وهي أقل من BaCrO₄ (1.1 × 10⁻⁵ M) ومن BaCO₃ (5.1 × 10⁻⁵ M)؛ وهذا يدعم اختيار BaSO₄ لتصوير الجهاز الهضمي بدلًا من مركبات الباريوم الأكثر ذائبية.', '["","العلاقة معكوسة: كلما كبرت Ksp كبرت تراكيز الأيونات في المحلول المشبع، فـ BaCO₃ هو الأكثر ذائبية بين الثلاثة.","المادة الصلبة لا تظهر في تعبير Ksp، والذائبية تُحسب من Ksp وحده (s = √Ksp للمركبات 1 : 1) دون الحاجة إلى كتلة الصلب.","تساوي نسبة الأيونات يجعل المقارنة بقيم Ksp مباشرة، لكنه لا يجعل التراكيز متساوية؛ فقيم Ksp مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-06T22:20:31.247Z"}'::jsonb),
('essay', 1, null::int, null, null, 'أيونات Ba²⁺ سامة، فالمركب الأفضل هو الذي يطلق أقل تركيز منها.
BaSO₄: Ksp = [Ba²⁺][SO₄²⁻] = s²، فـ [Ba²⁺] = √(1.1 × 10⁻¹⁰) = 1.0 × 10⁻⁵ M.
BaCl₂: n = 37.5 ÷ 208.23 = 0.180 mol في 0.100 L، فـ [Ba²⁺] = 1.80 M.
تركيز Ba²⁺ من BaCl₂ أكبر بنحو 1.7 × 10⁵ مرة؛ لذا يُستعمل BaSO₄ القليل الذوبان؛ إذ تذوب منه كمية قليلة لا تضر المريض، بينما يذوب BaCl₂ بكثرة فيكون سامًّا.', '["أيونات Ba²⁺ سامة","[Ba²⁺] من BaSO₄ = 1.0 × 10⁻⁵ M","[Ba²⁺] من BaCl₂ = 1.80 M","المقارنة بين التركيزين","الاستنتاج: BaSO₄ آمن لقلة ذائبيته"]'::jsonb, '["[Ba²⁺] (BaSO₄) = √(1.1 × 10⁻¹⁰) = 1.0 × 10⁻⁵ M","n(BaCl₂) = 37.5 g ÷ 208.23 g/mol = 0.180 mol","[Ba²⁺] (BaCl₂) = 0.180 mol ÷ 0.100 L = 1.80 M","1.80 ÷ (1.05 × 10⁻⁵) ≈ 1.7 × 10⁵"]'::jsonb, '[{"element":"ذكر سمية Ba²⁺","marks":1},{"element":"حساب [Ba²⁺] من BaSO₄","marks":1},{"element":"حساب [Ba²⁺] من BaCl₂","marks":2},{"element":"المقارنة والاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابان صحيحان مع مقارنة واستنتاج سليمين"},{"level":"3–4 درجات","description":"حساب واحد صحيح مع تعليل سليم"},{"level":"1–2 درجة","description":"تعليل نوعي صحيح دون حسابات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل 100 mL إلى 0.100 L","عدّ Ksp تركيزًا لأيون Ba²⁺","القول بأن BaSO₄ لا يحتوي على باريوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-06T22:20:31.247Z"}'::jsonb),
('essay', 2, null::int, null, null, 'BaSO₄(s) ⇌ Ba²⁺(aq) + SO₄²⁻(aq).
Na₂SO₄ مركب أيوني ذائب يوفر الأيون المشترك SO₄²⁻، فيزداد [SO₄²⁻] ويقع جهد على الاتزان، فيُزاح الاتزان نحو اليسار لإنتاج مزيد من BaSO₄ الصلب، فيقل عدد أيونات Ba²⁺ الضارة في المحلول، وهذا يزيد أمان المريض.', '["معادلة الاتزان موزونة بالحالات","Na₂SO₄ يوفر الأيون المشترك SO₄²⁻","إزاحة الاتزان نحو اليسار","نقص [Ba²⁺] الضارة"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة","marks":1},{"element":"تحديد الأيون المشترك","marks":1},{"element":"اتجاه الإزاحة ونتيجتها على [Ba²⁺]","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"المعادلة صحيحة والتفسير كامل"},{"level":"1–2 درجة","description":"المعادلة صحيحة مع تفسير ناقص، أو تفسير دون معادلة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول بأن الاتزان يُزاح نحو اليمين","الظن أن Na⁺ هو الأيون المؤثر","القول بأن Ksp يقل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-06T22:20:31.248Z"}'::jsonb),
('essay', 3, null::int, null, null, 'BaSO₄(s) ⇌ Ba²⁺(aq) + SO₄²⁻(aq)، وKsp = s²، فالذائبية المولارية s = √(1.1 × 10⁻¹⁰) = 1.05 × 10⁻⁵ mol/L.
عدد المولات الذائبة في 0.250 L = 1.05 × 10⁻⁵ × 0.250 = 2.62 × 10⁻⁶ mol.
الكتلة = 2.62 × 10⁻⁶ mol × 233.40 g/mol = 6.1 × 10⁻⁴ g.
أي أن أقل من مليغرام واحد فقط يذوب، فكمية أيونات Ba²⁺ المتاحة للامتصاص قليلة جدًّا ولا تضر المريض، بينما يبقى معظم BaSO₄ صلبًا ليظهر الجهاز الهضمي في صورة الأشعة.', '["s = 1.05 × 10⁻⁵ mol/L","عدد المولات في 0.250 L","الكتلة ≈ 6.1 × 10⁻⁴ g","الدلالة: الكمية الذائبة ضئيلة وآمنة"]'::jsonb, '["s = √Ksp = √(1.1 × 10⁻¹⁰) = 1.05 × 10⁻⁵ mol/L","n = 1.05 × 10⁻⁵ mol/L × 0.250 L = 2.62 × 10⁻⁶ mol","m = 2.62 × 10⁻⁶ mol × 233.40 g/mol = 6.1 × 10⁻⁴ g"]'::jsonb, '[{"element":"حساب الذائبية المولارية","marks":1},{"element":"حساب عدد المولات","marks":1},{"element":"حساب الكتلة","marks":1},{"element":"تفسير الدلالة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات صحيحة بالوحدات مع تفسير سليم"},{"level":"2–3 درجات","description":"خطأ في التحويل أو غياب التفسير"},{"level":"1 درجة","description":"حساب الذائبية المولارية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل 250 mL إلى 0.250 L","ضرب Ksp في الكتلة المولية مباشرة","عدّ s = Ksp"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-06T22:20:31.248Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
