('mcq', 2, 1, 'Ca(OH)₂(s) ⇌ Ca²⁺(aq) + 2OH⁻(aq). إذا كانت الذائبية x فإن [Ca²⁺] = x و[OH⁻] = 2x، فـ Ksp = (x)(2x)² = 4x³ = 5.0 × 10⁻⁶، ومنه x³ = 1.25 × 10⁻⁶ وx = 1.1 × 10⁻² mol/L.', '["استُعملت s = √Ksp كأن نسبة الأيونات 1 : 1؛ والنسبة هنا 1 : 2.","","كُتب Ksp = 2x³ بإهمال تربيع المعامل 2 لأيون OH⁻.","هذا تركيز OH⁻ (2x)، لا الذائبية المولارية للمركب (x)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-06T22:20:31.249Z"}'::jsonb),
('mcq', 3, 0, 'Fe(OH)₂(s) ⇌ Fe²⁺(aq) + 2OH⁻(aq). نفرض [Fe²⁺] = x و[OH⁻] = 2x، فـ Ksp = 4x³ = 4.9 × 10⁻¹⁷، ومنه x = ∛(1.225 × 10⁻¹⁷) = 2.3 × 10⁻⁶ M، و[OH⁻] = 2x = 4.6 × 10⁻⁶ M.', '["","هذا تركيز Fe²⁺ (x)؛ لم يُضرب في 2 للحصول على [OH⁻].","استُعمل الجذر التربيعي √Ksp كأن نسبة الأيونات 1 : 1.","أُخذ الجذر التكعيبي لـ Ksp مباشرة دون القسمة على 4."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-06T22:20:31.249Z"}'::jsonb),
('mcq', 4, 2, 'من الشكل: AgCl(s) ⇌ Ag⁺(aq) + Cl⁻(aq) وKsp = 1.8 × 10⁻¹⁰. بما أن [Ag⁺] = [Cl⁻] = s، فإن s² = 1.8 × 10⁻¹⁰ وs = 1.3 × 10⁻⁵ mol/L.', '["هذه قيمة Ksp نفسها، لا الذائبية.","قُسمت Ksp على 2 بدل أخذ الجذر التربيعي.","","استُعملت العلاقة Ksp = 4s³ الخاصة بالمركبات التي نسبتها 1 : 2، مع أن نسبة الأيونين في AgCl هي 1 : 1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-06T22:20:31.249Z"}'::jsonb),
('mcq', 5, 3, 's = √Ksp = √(7.4 × 10⁻¹⁴) = 2.72 × 10⁻⁷ mol/L، ثم الذائبية بـ g/L = 2.72 × 10⁻⁷ mol/L × 267.21 g/mol = 7.3 × 10⁻⁵ g/L.', '["هذه الذائبية المولارية بوحدة mol/L؛ لم تُضرب في الكتلة المولية.","قُسمت الذائبية المولارية على الكتلة المولية بدل الضرب فيها.","ضُربت Ksp في الكتلة المولية مباشرة دون حساب الذائبية أولًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-06T22:20:31.249Z"}'::jsonb),
('mcq', 6, 0, 'CaF₂(s) ⇌ Ca²⁺(aq) + 2F⁻(aq)، فـ [Ca²⁺] = s و[F⁻] = 2s، وKsp = [Ca²⁺][F⁻]² = (s)(2s)² = 4s³.', '["","العلاقة s² تخص المركبات التي نسبة أيوناتها 1 : 1 مثل AgCl.","أُهمل تربيع المعامل 2: (2s)² = 4s² لا 2s².","أُهمل تركيز Ca²⁺ وكُتب [F⁻] = 2s دون تربيعه أو ضربه في s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-06T22:20:31.249Z"}'::jsonb),
('mcq', 7, 1, 'من أي محاولة: Ksp = [Mn²⁺][CO₃²⁻] = (5.60 × 10⁻⁹)(4.00 × 10⁻³) = 2.24 × 10⁻¹¹ (وتعطي المحاولتان الأخريان القيمة نفسها). في الماء النقي [Mn²⁺] = [CO₃²⁻] = s، فـ s = √(2.24 × 10⁻¹¹) = 4.73 × 10⁻⁶ M.', '["هذا تركيز CO₃²⁻ في المحاولة 1، وهو ناتج عن مصدر إضافي للأيون، لا ذائبية المركب في الماء النقي.","","أُخذ الجذر التربيعي لـ [Mn²⁺] في المحاولة 1 بدل حساب Ksp أولًا.","هذه قيمة Ksp، والذائبية هي جذرها التربيعي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-06T22:20:31.249Z"}'::jsonb),
('essay', 1, null::int, null, null, 'PbF₂(s) ⇌ Pb²⁺(aq) + 2F⁻(aq)، وKsp = [Pb²⁺][F⁻]².
نفرض [Pb²⁺] = x، فإن [F⁻] = 2x، وKsp = (x)(2x)² = 4x³ = 3.3 × 10⁻⁸.
x³ = 8.25 × 10⁻⁹ ← x = 2.0 × 10⁻³ mol/L.
الذائبية المولارية = [Pb²⁺] = 2.0 × 10⁻³ mol/L، و[F⁻] = 2x = 4.0 × 10⁻³ mol/L.', '["المعادلة وتعبير Ksp","Ksp = 4x³","x = 2.0 × 10⁻³ mol/L","[Pb²⁺] = 2.0 × 10⁻³ M","[F⁻] = 4.0 × 10⁻³ M"]'::jsonb, '["PbF₂(s) ⇌ Pb²⁺(aq) + 2F⁻(aq)","Ksp = [Pb²⁺][F⁻]² = (x)(2x)² = 4x³","x³ = 3.3 × 10⁻⁸ ÷ 4 = 8.25 × 10⁻⁹","x = ∛(8.25 × 10⁻⁹) = 2.0 × 10⁻³ mol/L","[F⁻] = 2x = 4.0 × 10⁻³ mol/L"]'::jsonb, '[{"element":"المعادلة والتعبير","marks":1},{"element":"الوصول إلى 4x³","marks":1},{"element":"حساب الذائبية","marks":1},{"element":"تركيزا الأيونين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلة والتعبير والحسابات كلها صحيحة"},{"level":"2–3 درجات","description":"خطأ في 4x³ أو في تركيز F⁻"},{"level":"1 درجة","description":"كتابة المعادلة والتعبير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Ksp = (x)(2x) دون تربيع","استعمال الجذر التربيعي بدل التكعيبي","عدّ [F⁻] مساويًا للذائبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.250Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Ag₂SO₄(s) ⇌ 2Ag⁺(aq) + SO₄²⁻(aq)، وKsp = [Ag⁺]²[SO₄²⁻].
(أ) نفرض الذائبية x: [SO₄²⁻] = x و[Ag⁺] = 2x، فـ Ksp = (2x)²(x) = 4x³ = 1.2 × 10⁻⁵ ← x³ = 3.0 × 10⁻⁶ ← x = 1.4 × 10⁻² mol/L.
(ب) [Ag⁺] = 2x = 2.9 × 10⁻² M.
(ج) الذائبية = 1.44 × 10⁻² mol/L × 311.81 g/mol = 4.5 g/L.', '["Ksp = 4x³","x = 1.4 × 10⁻² mol/L","[Ag⁺] = 2.9 × 10⁻² M","الذائبية 4.5 g/L"]'::jsonb, '["Ksp = (2x)²(x) = 4x³","x³ = 1.2 × 10⁻⁵ ÷ 4 = 3.0 × 10⁻⁶","x = ∛(3.0 × 10⁻⁶) = 1.44 × 10⁻² mol/L","[Ag⁺] = 2 × 1.44 × 10⁻² = 2.9 × 10⁻² M","1.44 × 10⁻² mol/L × 311.81 g/mol = 4.5 g/L"]'::jsonb, '[{"element":"التعبير 4x³","marks":1},{"element":"الذائبية المولارية","marks":2},{"element":"[Ag⁺]","marks":1},{"element":"الذائبية بـ g/L","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأجزاء الثلاثة صحيحة بالوحدات"},{"level":"3–5 درجات","description":"جزءان صحيحان أو خطأ واحد في التعبير"},{"level":"1–2 درجة","description":"كتابة التعبير أو جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Ksp = (x)²(x) بإهمال المعامل 2 داخل التربيع","عدّ [Ag⁺] مساويًا للذائبية","قسمة الذائبية المولارية على الكتلة المولية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-06T22:20:31.250Z"}'::jsonb),
('essay', 3, null::int, null, null, 'CaCO₃(s) ⇌ Ca²⁺(aq) + CO₃²⁻(aq)، وKsp = [Ca²⁺][CO₃²⁻] = s².
s = √(3.4 × 10⁻⁹) = 5.8 × 10⁻⁵ mol/L.
التقويم: Ksp من رتبة 10⁻⁹ تقريبًا، فجذرها التربيعي متوقع أن يكون قريبًا من 10⁻⁵–10⁻⁴، والناتج 5.8 × 10⁻⁵ يقع في هذا المدى، فالإجابة معقولة.', '["المعادلة وتعبير Ksp","s = √Ksp","s = 5.8 × 10⁻⁵ mol/L","تقويم الرتبة العشرية"]'::jsonb, '["Ksp = [Ca²⁺][CO₃²⁻] = s²","s = √(3.4 × 10⁻⁹) = 5.8 × 10⁻⁵ mol/L"]'::jsonb, '[{"element":"المعادلة والتعبير","marks":1},{"element":"حساب s بالوحدة","marks":1},{"element":"التقويم","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعبير وحساب صحيحان مع تقويم سليم"},{"level":"1–2 درجة","description":"حساب صحيح دون تقويم، أو تعبير صحيح مع خطأ حسابي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء Ksp قيمةً للذائبية","الخطأ في الجذر التربيعي لقوة عشرية فردية (10⁻⁹)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-06T22:20:31.250Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
