from (values
('mcq', 1, 'إذا كانت قيمة الحاصل الأيوني Qsp لمحلول أيوني أقل من قيمة Ksp للمركب عند درجة الحرارة نفسها، فماذا تستنتج؟', null, null, '["المحلول مشبع ولا يحدث تغير","المحلول فوق مشبع ويتكون راسب","المحلول غير مشبع ولا يتكون راسب","المحلول غير مشبع ويتكون راسب"]'::jsonb, 'تذكر', 'حالات مقارنة Qsp بـ Ksp', 'سهل', 'الكتاب ص 104–105 — الحاصل الأيوني Qsp'),
('mcq', 2, 'اعتمادًا على الرسم الآتي، في أي الخلائط الثلاثة يكون المحلول مشبعًا دون أن يتكون راسب أو يحدث تغير؟', null, '[{"src":"qimg/chem22/c3-l3a-q-vs-ksp.svg","alt":"رسم بأعمدة عنوانه «قيم Qsp = [Ag⁺][Cl⁻] لحظة الخلط عند 298 K»، محوره الرأسي الحاصل الأيوني Qsp بتدريج لوغاريتمي من 10⁻¹³ إلى 10⁻⁷، ومحوره الأفقي ثلاثة خلائط. خط أفقي أحمر متقطع مكتوب عليه Ksp (AgCl) = 1.8 × 10⁻¹⁰. عمود الخليط (1) يصل إلى نحو 3.6 × 10⁻¹² أي تحت الخط، وعمود الخليط (2) يصل إلى الخط تمامًا (1.8 × 10⁻¹⁰)، وعمود الخليط (3) يصل إلى نحو 2.5 × 10⁻⁸ أي فوق الخط."}]'::jsonb, '["الخليط (1)","الخليط (3)","الخليطان (1) و(3)","الخليط (2)"]'::jsonb, 'فهم', 'تفسير رسم Qsp مقابل Ksp', 'سهل', 'الكتاب ص 104–105 — الحاصل الأيوني Qsp'),
('mcq', 3, 'ما الفرق بين ثابت حاصل الذائبية Ksp والحاصل الأيوني Qsp؟', null, null, '["Qsp وKsp متساويان دائمًا لأن لهما الصيغة الرياضية نفسها","Ksp قيمة ثابتة للمحلول المشبع عند الاتزان، وQsp قيمة تجريبية تُحسب من أي تراكيز","Qsp قيمة ثابتة عند درجة حرارة معينة، وKsp يتغير بتغير تراكيز الأيونات","Qsp يُحسب من تركيز المادة الصلبة، وKsp يُحسب من تراكيز الأيونات الذائبة"]'::jsonb, 'فهم', 'التمييز بين Qsp وKsp', 'متوسط', 'الكتاب ص 108 — السؤال 30'),
('mcq', 4, 'يمثل الرسم الآتي الحاصل الأيوني لثلاثة خلائط تحتوي على أيونات Ag⁺ وCl⁻ لحظة خلطها. إذا أُضيف ماء نقي إلى الخليط (2) عند درجة الحرارة نفسها، فكيف تتغير قيمتا Qsp وKsp، وما حالة المحلول بعد الإضافة؟', null, '[{"src":"qimg/chem22/c3-l3a-q-vs-ksp.svg","alt":"رسم بأعمدة عنوانه «قيم Qsp = [Ag⁺][Cl⁻] لحظة الخلط عند 298 K»، محوره الرأسي الحاصل الأيوني Qsp بتدريج لوغاريتمي من 10⁻¹³ إلى 10⁻⁷، ومحوره الأفقي ثلاثة خلائط. خط أفقي أحمر متقطع مكتوب عليه Ksp (AgCl) = 1.8 × 10⁻¹⁰. عمود الخليط (1) يصل إلى نحو 3.6 × 10⁻¹² أي تحت الخط، وعمود الخليط (2) يصل إلى الخط تمامًا (1.8 × 10⁻¹⁰)، وعمود الخليط (3) يصل إلى نحو 2.5 × 10⁻⁸ أي فوق الخط."}]'::jsonb, '["يقل Qsp وKsp معًا، فيبقى المحلول مشبعًا","يبقى Qsp ثابتًا ويقل Ksp، فيتكون راسب","يقل Qsp ويبقى Ksp ثابتًا، فيصبح المحلول غير مشبع","يزداد Qsp ويبقى Ksp ثابتًا، فيتكون راسب"]'::jsonb, 'تحليل', 'تحديد تكون الراسب من رسم', 'صعب', 'الكتاب ص 104–105 — الحاصل الأيوني Qsp'),
('mcq', 5, 'خُلط محلولان فكان الحاصل الأيوني Qsp لأحد المركبات القليلة الذوبان أكبر من Ksp له. ماذا يحدث حتى يصل النظام إلى الاتزان؟', null, null, '["يتكون راسب وتقل تراكيز الأيونات حتى يصبح Qsp = Ksp","يتكون راسب وتزداد قيمة Ksp حتى تساوي قيمة Qsp","يذوب مزيد من المادة الصلبة حتى يصبح Qsp = Ksp","يتكون راسب ويستمر الترسيب حتى تصبح تراكيز الأيونات صفرًا"]'::jsonb, 'فهم', 'ما يحدث عندما Qsp > Ksp', 'صعب', 'الكتاب ص 104–105 — الحاصل الأيوني Qsp'),
('mcq', 6, 'محلول يحتوي على [Ca²⁺] = 4.0 × 10⁻³ M و[SO₄²⁻] = 5.0 × 10⁻³ M عند 298 K، وKsp لكبريتات الكالسيوم CaSO₄ يساوي 4.9 × 10⁻⁵. ما قيمة Qsp، وما حالة المحلول؟', null, null, '["Qsp = 2.0 × 10⁻⁵؛ المحلول مشبع ولا يحدث تغير","Qsp = 9.0 × 10⁻³؛ يتكون راسب من CaSO₄","Qsp = 2.0 × 10⁻⁵؛ يتكون راسب من CaSO₄","Qsp = 2.0 × 10⁻⁵؛ المحلول غير مشبع ولا يتكون راسب"]'::jsonb, 'تطبيق', 'حساب Qsp ومقارنته', 'متوسط', 'الكتاب ص 104–105 — الحاصل الأيوني Qsp'),
('mcq', 7, 'محلول يحتوي على [Ag⁺] = 2.0 × 10⁻⁴ M و[CrO₄²⁻] = 5.0 × 10⁻⁵ M عند 298 K، وKsp لكرومات الفضة Ag₂CrO₄ يساوي 1.1 × 10⁻¹². ما قيمة Qsp، وما الذي تتوقعه؟', null, null, '["Qsp = 1.0 × 10⁻⁸؛ يتكون راسب","Qsp = 2.0 × 10⁻¹²؛ يتكون راسب","Qsp = 2.0 × 10⁻¹²؛ المحلول غير مشبع","Qsp = 8.0 × 10⁻¹²؛ يتكون راسب"]'::jsonb, 'تطبيق', 'حساب Qsp لمركب نسبته 2 : 1', 'صعب', 'الكتاب ص 104–105 — الحاصل الأيوني Qsp'),
('essay', 1, 'وضّح الحالات الثلاث التي يمكن أن تنتج عن مقارنة الحاصل الأيوني Qsp بثابت حاصل الذائبية Ksp لمحلول أيوني، مبيّنًا في كل حالة هل المحلول مشبع، وهل يتكون راسب.', null, null, null, 'فهم', 'مقارنة Qsp بـ Ksp', 'سهل', 'الكتاب ص 104–105 — الحاصل الأيوني Qsp'),
('essay', 2, '(أ) صف المحلول الناتج عن خلط محلولين إذا كان الحاصل الأيوني Qsp في الخليط مساويًا لـ Ksp. هل يتكون راسب؟
(ب) هل يُعد Qsp ثابت اتزان؟ فسّر إجابتك.', null, null, null, 'فهم', 'وصف المحلول وتمييز Qsp', 'متوسط', 'الكتاب ص 108 و113 — السؤالان 30 و62'),
('essay', 3, 'يبين الجدول الآتي تراكيز أيونات Pb²⁺ وI⁻ في ثلاثة محاليل عند 298 K. إذا علمت أن Ksp لـ PbI₂ يساوي 9.8 × 10⁻⁹، فاحسب Qsp لكل محلول، وحدّد هل هو غير مشبع أو مشبع أو يتكون فيه راسب.', '{"headers":["المحلول","[Pb²⁺] (M)","[I⁻] (M)"],"rows":[["1","1.0 × 10⁻³","2.0 × 10⁻³"],["2","2.5 × 10⁻³","2.0 × 10⁻³"],["3","9.8 × 10⁻⁵","1.0 × 10⁻²"]]}'::jsonb, null, null, 'تحليل', 'تصنيف محاليل بحساب Qsp', 'صعب', 'الكتاب ص 104–105 — الحاصل الأيوني Qsp')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
