from (values
('mcq', 1, 2, 'عند المقارنة: إذا كان Qsp < Ksp فإن المحلول غير مشبع ولا يتكون راسب؛ لأن ناتج ضرب تراكيز الأيونات لم يبلغ القيمة اللازمة للتشبع.', '["هذه حالة Qsp = Ksp.","هذه حالة Qsp > Ksp.","","المحلول غير المشبع لا يتكون فيه راسب؛ فالترسيب يحدث فقط عندما يتجاوز Qsp قيمة Ksp."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-06T22:20:31.251Z"}'::jsonb),
('mcq', 2, 3, 'عمود الخليط (2) يصل إلى خط Ksp تمامًا، أي Qsp = Ksp = 1.8 × 10⁻¹⁰، فالمحلول مشبع ولا يحدث تغير.', '["Qsp للخليط (1) أقل من Ksp، فهو غير مشبع.","Qsp للخليط (3) أكبر من Ksp، فيتكون فيه راسب.","الخليط (1) غير مشبع والخليط (3) يتكون فيه راسب؛ وكلاهما لا تتحقق فيه المساواة Qsp = Ksp.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-06T22:20:31.251Z"}'::jsonb),
('mcq', 3, 1, 'يُحسب Qsp بالتعويض بتراكيز الأيونات الموجودة فعلًا في تعبير Ksp، فهو قيمة تجريبية قد لا يكون المحلول عندها مشبعًا؛ أما Ksp فقيمة ثابتة عند درجة حرارة معينة تمثل ناتج الضرب في المحلول المشبع عند الاتزان. ولا يساوي Qsp قيمة Ksp إلا عند التشبع.', '["لهما الصيغة نفسها، لكن Qsp يتغير بتغير التراكيز ولا يساوي Ksp إلا في المحلول المشبع.","","العكس هو الصحيح: Ksp ثابت عند درجة حرارة معينة، وQsp يتغير بتغير التراكيز.","المادة الصلبة لا تدخل في أي من التعبيرين؛ كلاهما يُحسب من تراكيز الأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-06T22:20:31.251Z"}'::jsonb),
('mcq', 4, 2, 'في الخليط (2) كان Qsp = Ksp = 1.8 × 10⁻¹⁰ (محلول مشبع). إضافة الماء تزيد الحجم فيقل [Ag⁺] و[Cl⁻]، فيقل Qsp = [Ag⁺][Cl⁻]، أما Ksp فلا يتغير إلا بتغير درجة الحرارة. فيصبح Qsp < Ksp، أي أن المحلول غير مشبع ولا يتكون راسب.', '["Ksp ثابت عند درجة الحرارة نفسها ولا يتأثر بالتخفيف؛ والذي يقل هو Qsp فقط، فلا يبقى المحلول مشبعًا.","التخفيف يقلل تراكيز الأيونات فيقل Qsp، وKsp لا يتغير إلا بتغير درجة الحرارة.","","إضافة الماء تخفف المحلول فتقل تراكيز الأيونات ويقل Qsp لا يزداد، فلا يتكون راسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-06T22:20:31.251Z"}'::jsonb),
('mcq', 5, 0, 'إذا كان Qsp > Ksp يتكون راسب، وتقل تراكيز الأيونات في المحلول حتى يصبح ناتج ضرب تراكيز الأيونات في التعبير مساويًا للقيمة العددية لـ Ksp؛ فيكون النظام في حالة اتزان والمحلول مشبعًا.', '["","Ksp لا يتغير عند درجة الحرارة نفسها؛ الذي يتغير هو تراكيز الأيونات وبالتالي Qsp.","الذوبان يحدث عندما يكون Qsp < Ksp؛ أما هنا فالأيونات زائدة فتترسب.","الترسيب يتوقف عند الاتزان (Qsp = Ksp)، وتبقى في المحلول تراكيز صغيرة من الأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-06T22:20:31.251Z"}'::jsonb),
('mcq', 6, 3, 'Qsp = [Ca²⁺][SO₄²⁻] = (4.0 × 10⁻³)(5.0 × 10⁻³) = 2.0 × 10⁻⁵، وهي أقل من Ksp (4.9 × 10⁻⁵)، فالمحلول غير مشبع ولا يتكون راسب، ويمكن أن يذوب فيه مزيد من CaSO₄.', '["القيمة صحيحة لكن Qsp لا يساوي Ksp؛ إنه أقل منه، فالمحلول غير مشبع.","جُمع التركيزان بدل ضربهما: 4.0 × 10⁻³ + 5.0 × 10⁻³ = 9.0 × 10⁻³.","القيمة صحيحة لكن الاستنتاج معكوس؛ فالراسب يتكون فقط إذا كان Qsp > Ksp.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-06T22:20:31.252Z"}'::jsonb),
('mcq', 7, 1, 'Ag₂CrO₄(s) ⇌ 2Ag⁺(aq) + CrO₄²⁻(aq)، فـ Qsp = [Ag⁺]²[CrO₄²⁻] = (2.0 × 10⁻⁴)²(5.0 × 10⁻⁵) = 2.0 × 10⁻¹²، وهي أكبر من Ksp (1.1 × 10⁻¹²)، فيتكون راسب.', '["لم يُربَّع [Ag⁺]: (2.0 × 10⁻⁴)(5.0 × 10⁻⁵) = 1.0 × 10⁻⁸؛ والمعامل 2 يصبح أسًّا.","","القيمة صحيحة لكن 2.0 × 10⁻¹² أكبر من 1.1 × 10⁻¹² لا أصغر، فالمحلول ليس غير مشبع.","ضُوعف [Ag⁺] قبل تربيعه: (4.0 × 10⁻⁴)²(5.0 × 10⁻⁵)؛ والتركيز المعطى هو تركيز Ag⁺ الفعلي فلا يُضرب في 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-06T22:20:31.252Z"}'::jsonb),
('essay', 1, null::int, null, null, '1. Qsp < Ksp: المحلول غير مشبع، ولا يتكون راسب.
2. Qsp = Ksp: المحلول مشبع، ولا يحدث تغير.
3. Qsp > Ksp: يتكون راسب، وتقل تراكيز الأيونات حتى يصبح ناتج ضربها مساويًا لـ Ksp، فيصل النظام إلى الاتزان ويكون المحلول مشبعًا.', '["Qsp < Ksp: غير مشبع ولا راسب","Qsp = Ksp: مشبع ولا تغير","Qsp > Ksp: يتكون راسب حتى يصبح Qsp = Ksp"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة الأولى","marks":1},{"element":"الحالة الثانية","marks":1},{"element":"الحالة الثالثة مع ما يحدث بعد الترسيب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الحالات الثلاث صحيحة"},{"level":"1–2 درجة","description":"حالة أو حالتان صحيحتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين حالتي Qsp > Ksp وQsp < Ksp","القول بأن راسبًا يتكون عندما Qsp = Ksp"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.252Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) عندما Qsp = Ksp يكون المحلول مشبعًا تمامًا، ولا يتكون راسب ولا يحدث تغير؛ لأن ناتج ضرب تراكيز الأيونات يساوي القيمة اللازمة للتشبع بالضبط.
(ب) لا؛ Qsp قيمة تجريبية تُحسب بالتعويض بتراكيز الأيونات الموجودة في أي لحظة، فتتغير بتغير التراكيز، وقد لا يكون المحلول عندها في حالة اتزان. أما Ksp فقيمة ثابتة عند درجة حرارة معينة. ولا يساوي Qsp قيمة Ksp إلا عندما يكون المحلول مشبعًا في حالة اتزان.', '["المحلول مشبع","لا يتكون راسب","Qsp ليس ثابت اتزان","Qsp يتغير بتغير التراكيز ولا يساوي Ksp إلا عند الاتزان"]'::jsonb, '[]'::jsonb, '[{"element":"وصف المحلول وعدم تكون راسب","marks":2},{"element":"الحكم على Qsp","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الجزآن صحيحان مع تفسير كامل"},{"level":"2–3 درجات","description":"جزء صحيح كامل وجزء ناقص"},{"level":"1 درجة","description":"إجابة صحيحة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول بتكوّن راسب عند Qsp = Ksp","عدّ Qsp ثابتًا لأن صيغته تشبه صيغة Ksp"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-06T22:20:31.253Z"}'::jsonb),
('essay', 3, null::int, null, null, 'PbI₂(s) ⇌ Pb²⁺(aq) + 2I⁻(aq)، فـ Qsp = [Pb²⁺][I⁻]².
المحلول (1): Qsp = (1.0 × 10⁻³)(2.0 × 10⁻³)² = 4.0 × 10⁻⁹ < Ksp ← غير مشبع ولا يتكون راسب.
المحلول (2): Qsp = (2.5 × 10⁻³)(2.0 × 10⁻³)² = 1.0 × 10⁻⁸ > Ksp ← يتكون راسب من PbI₂.
المحلول (3): Qsp = (9.8 × 10⁻⁵)(1.0 × 10⁻²)² = 9.8 × 10⁻⁹ = Ksp ← مشبع ولا يحدث تغير.', '["Qsp = [Pb²⁺][I⁻]²","(1): 4.0 × 10⁻⁹ غير مشبع","(2): 1.0 × 10⁻⁸ يتكون راسب","(3): 9.8 × 10⁻⁹ مشبع"]'::jsonb, '["Qsp = [Pb²⁺][I⁻]²","(1) (1.0 × 10⁻³)(4.0 × 10⁻⁶) = 4.0 × 10⁻⁹","(2) (2.5 × 10⁻³)(4.0 × 10⁻⁶) = 1.0 × 10⁻⁸","(3) (9.8 × 10⁻⁵)(1.0 × 10⁻⁴) = 9.8 × 10⁻⁹","المقارنة بـ Ksp = 9.8 × 10⁻⁹"]'::jsonb, '[{"element":"تعبير Qsp بالأس الصحيح","marks":1},{"element":"المحلول (1) حسابًا وحكمًا","marks":1},{"element":"المحلول (2) حسابًا وحكمًا","marks":2},{"element":"المحلول (3) حسابًا وحكمًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التعبير والحسابات والأحكام الثلاثة صحيحة"},{"level":"3–4 درجات","description":"خطأ في محلول واحد"},{"level":"1–2 درجة","description":"التعبير صحيح مع حكم واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال تربيع [I⁻]","الحكم بالمقارنة بين الرتب العشرية فقط في المحلول (2) رغم تقارب القيمتين","عدّ المحلول (3) فوق مشبع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-06T22:20:31.253Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
