('mcq', 1, 'يبين الشكل الآتي خلط محلولين. ما قيمة Qsp لـ PbCl₂ في الخليط لحظة الخلط، وهل يتكون راسب؟', null, '[{"src":"qimg/chem22/c3-l3a-mix-pbcl2.svg","alt":"رسم لخلط محلولين: كأس على اليسار فيها 50.0 mL من محلول 0.0400 M Pb(NO₃)₂، وإشارة +، ثم كأس فيها 50.0 mL من محلول 0.0300 M NaCl، ثم سهم يشير إلى كأس الخليط وحجمه 100.0 mL، ومكتوب تحتها Ksp (PbCl₂) = 1.7 × 10⁻⁵."}]'::jsonb, '["Qsp = 3.6 × 10⁻⁵؛ يتكون راسب من PbCl₂","Qsp = 4.5 × 10⁻⁶؛ لا يتكون راسب","Qsp = 3.0 × 10⁻⁴؛ يتكون راسب من PbCl₂","Qsp = 4.5 × 10⁻⁶؛ يتكون راسب من PbCl₂"]'::jsonb, 'تطبيق', 'توقع الراسب عند خلط حجمين متساويين', 'متوسط', 'الكتاب ص 105 — المثال 3-7 توقع تكون راسب'),
('mcq', 2, 'خُلط حجم من محلول CaCl₂ تركيزه 0.10 M مع حجم مساوٍ من محلول آخر لا يحتوي على أيونات الكلوريد. ما تركيز أيونات Cl⁻ في الخليط؟', null, null, '["0.20 M","0.050 M","0.10 M","0.40 M"]'::jsonb, 'تطبيق', 'تركيز الأيون بعد الخلط', 'سهل', 'الكتاب ص 104 — توقع الرواسب وحساب تراكيز الأيونات'),
('mcq', 3, 'خُلطت أحجام متساوية من محلولي 0.10 M Pb(NO₃)₂ و0.030 M NaF. إذا علمت أن Ksp لـ PbF₂ يساوي 3.3 × 10⁻⁸، فما قيمة Qsp في الخليط، وما الذي تتوقعه؟', null, null, '["Qsp = 1.1 × 10⁻⁵؛ لا يتكون راسب","Qsp = 7.5 × 10⁻⁴؛ يتكون راسب","Qsp = 9.0 × 10⁻⁵؛ يتكون راسب","Qsp = 1.1 × 10⁻⁵؛ يتكون راسب"]'::jsonb, 'تطبيق', 'توقع الراسب لمركب نسبته 1 : 2', 'متوسط', 'الكتاب ص 106 — المسائل 25–26'),
('mcq', 4, 'خُلطت أحجام متساوية من محلولي 0.20 M K₂SO₄ و0.020 M AgNO₃. إذا علمت أن Ksp لـ Ag₂SO₄ يساوي 1.2 × 10⁻⁵، فما قيمة Qsp في الخليط، وما الذي تتوقعه؟', null, null, '["Qsp = 1.0 × 10⁻⁵؛ لا يتكون راسب","Qsp = 8.0 × 10⁻⁵؛ يتكون راسب","Qsp = 1.0 × 10⁻³؛ يتكون راسب","Qsp = 4.0 × 10⁻⁵؛ يتكون راسب"]'::jsonb, 'تطبيق', 'توقع الراسب مع تقارب Qsp وKsp', 'متوسط', 'الكتاب ص 106 — المسائل 25–26'),
('mcq', 5, 'أُضيف 100 mL من محلول 0.010 M MgCl₂ إلى 400 mL من محلول 1.0 × 10⁻⁴ M NaOH. ما قيمة Qsp لـ Mg(OH)₂ في الخليط لحظة الخلط؟', null, null, '["1.0 × 10⁻¹⁰","1.6 × 10⁻⁷","1.3 × 10⁻¹¹","5.1 × 10⁻¹¹"]'::jsonb, 'تطبيق', 'Qsp عند خلط حجمين مختلفين', 'صعب', 'الكتاب ص 106 — المسائل 25–26'),
('mcq', 6, 'عند خلط محلولين أيونيين، ما الشرط الذي يجب أن يتحقق ليتكون راسب من مركب قليل الذوبان؟', null, null, '["أن يكون Qsp للمركب في الخليط أقل من Ksp له","أن يكون Qsp للمركب في الخليط مساويًا لـ Ksp له","أن تكون قيمة Ksp للمركب أكبر من 1","أن يكون Qsp للمركب في الخليط أكبر من Ksp له"]'::jsonb, 'فهم', 'شرط تكون الراسب', 'سهل', 'الكتاب ص 108 — الخلاصة'),
('mcq', 7, 'يُراد خلط 100 mL من محلول Na₂CO₃ تركيزه 2.0 × 10⁻⁴ M مع 100 mL من محلول CaCl₂. إذا علمت أن Ksp لـ CaCO₃ يساوي 3.4 × 10⁻⁹، فما التركيز الذي يجب أن يتجاوزه تركيز محلول CaCl₂ قبل الخلط حتى يتكون راسب من CaCO₃؟', null, null, '["3.4 × 10⁻⁵ M","6.8 × 10⁻⁵ M","1.7 × 10⁻⁵ M","5.8 × 10⁻⁵ M"]'::jsonb, 'تحليل', 'أقل تركيز لازم لتكون راسب', 'صعب', 'الكتاب ص 116 — اختبار مقنن (السؤال 7)'),
('essay', 1, 'يبين الشكل الآتي خلط محلولين. توقع هل يتكون راسب من كلوريد الفضة AgCl، مبيّنًا خطوات الحل كاملة.', null, '[{"src":"qimg/chem22/c3-l3a-mix-agcl.svg","alt":"رسم لخلط محلولين: كأس على اليسار فيها 50.0 mL من محلول 1.0 × 10⁻⁴ M AgNO₃، وإشارة +، ثم كأس فيها 50.0 mL من محلول 1.0 × 10⁻⁴ M NaCl، ثم سهم يشير إلى كأس الخليط وحجمه 100.0 mL، ومكتوب تحتها Ksp (AgCl) = 1.8 × 10⁻¹⁰."}]'::jsonb, null, 'تطبيق', 'توقع تكون راسب بخطوات', 'متوسط', 'الكتاب ص 105 — المثال 3-7 توقع تكون راسب'),
('essay', 2, 'هل يتكون راسب من هيدروكسيد الكالسيوم Ca(OH)₂ عند خلط 60.0 mL من محلول CaCl₂ تركيزه 0.0300 M مع 40.0 mL من محلول NaOH تركيزه 0.0200 M؟ علمًا بأن Ksp لـ Ca(OH)₂ يساوي 5.0 × 10⁻⁶ عند 298 K. وضّح إجابتك بالحساب.', null, null, null, 'تطبيق', 'توقع الراسب عند خلط حجمين مختلفين', 'صعب', 'الكتاب ص 113 — السؤال 65'),
('essay', 3, 'لماذا يجب أن تحسب تراكيز الأيونات في الخليط أولًا قبل أن تتوقع تكون راسب عند خلط محلولين؟ ثم احسب تركيز أيونات Fe³⁺ وCl⁻ عند خلط حجمين متساويين من محلولي 0.10 M FeCl₃ و0.10 M K₄[Fe(CN)₆].', null, null, null, 'فهم', 'التخفيف عند الخلط', 'سهل', 'الكتاب ص 104 — توقع الرواسب وحساب تراكيز الأيونات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
