from (values
('mcq', 1, 1, 'الحجمان متساويان، فيقل تركيز كل أيون إلى النصف: [Pb²⁺] = 0.0400 ÷ 2 = 0.0200 M، و[Cl⁻] = 0.0300 ÷ 2 = 0.0150 M. Qsp = [Pb²⁺][Cl⁻]² = (0.0200)(0.0150)² = 4.5 × 10⁻⁶، وهي أقل من Ksp (1.7 × 10⁻⁵)، فلا يتكون راسب.', '["عُوِّض بالتركيزين قبل الخلط: (0.0400)(0.0300)² = 3.6 × 10⁻⁵؛ ونُسي أن الخلط يخفف كل تركيز إلى النصف.","","لم يُربَّع [Cl⁻]: (0.0200)(0.0150) = 3.0 × 10⁻⁴.","القيمة صحيحة لكن الاستنتاج معكوس؛ فـ Qsp أقل من Ksp."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-06T22:20:31.253Z"}'::jsonb),
('mcq', 2, 2, 'في محلول CaCl₂ الأصلي [Cl⁻] = 2 × 0.10 = 0.20 M، وعند الخلط بحجم مساوٍ يتضاعف الحجم فيقل التركيز إلى النصف: [Cl⁻] = 0.20 ÷ 2 = 0.10 M.', '["هذا تركيز Cl⁻ قبل الخلط؛ لم يُراعَ التخفيف إلى النصف.","قُسم تركيز CaCl₂ على 2 دون مراعاة أن لكل وحدة منه أيوني Cl⁻.","","ضُرب في 2 بدل القسمة على 2 عند الخلط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-06T22:20:31.254Z"}'::jsonb),
('mcq', 3, 3, 'بعد الخلط: [Pb²⁺] = 0.050 M و[F⁻] = 0.015 M. Qsp = [Pb²⁺][F⁻]² = (0.050)(0.015)² = 1.1 × 10⁻⁵، وهي أكبر بكثير من Ksp (3.3 × 10⁻⁸)، فيتكون راسب من PbF₂.', '["القيمة صحيحة لكن 1.1 × 10⁻⁵ أكبر من 3.3 × 10⁻⁸ لا أصغر؛ فالاستنتاج معكوس.","لم يُربَّع [F⁻]: (0.050)(0.015) = 7.5 × 10⁻⁴.","أُهمل التخفيف عند الخلط: (0.10)(0.030)² = 9.0 × 10⁻⁵.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-11-06T22:20:31.254Z"}'::jsonb),
('mcq', 4, 0, 'بعد الخلط: [Ag⁺] = 0.010 M و[SO₄²⁻] = 0.10 M. Qsp = [Ag⁺]²[SO₄²⁻] = (0.010)²(0.10) = 1.0 × 10⁻⁵، وهي أقل من Ksp (1.2 × 10⁻⁵)، فلا يتكون راسب.', '["","أُهمل التخفيف عند الخلط: (0.020)²(0.20) = 8.0 × 10⁻⁵.","لم يُربَّع [Ag⁺]: (0.010)(0.10) = 1.0 × 10⁻³.","خُفف [SO₄²⁻] وحده ونُسي تخفيف [Ag⁺]: (0.020)²(0.10) = 4.0 × 10⁻⁵."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-11-06T22:20:31.254Z"}'::jsonb),
('mcq', 5, 2, 'الحجم الكلي 500 mL. [Mg²⁺] = 0.010 × 100 ÷ 500 = 2.0 × 10⁻³ M، و[OH⁻] = 1.0 × 10⁻⁴ × 400 ÷ 500 = 8.0 × 10⁻⁵ M. Qsp = [Mg²⁺][OH⁻]² = (2.0 × 10⁻³)(8.0 × 10⁻⁵)² = 1.3 × 10⁻¹¹ (أكبر من Ksp = 5.6 × 10⁻¹²، فيتكون راسب).', '["عُوِّض بالتركيزين قبل الخلط: (0.010)(1.0 × 10⁻⁴)² = 1.0 × 10⁻¹⁰.","لم يُربَّع [OH⁻]: (2.0 × 10⁻³)(8.0 × 10⁻⁵) = 1.6 × 10⁻⁷.","","ضُوعف [OH⁻] قبل تربيعه كأنه 2x: (2.0 × 10⁻³)(1.6 × 10⁻⁴)²؛ والتركيز المحسوب هو تركيز OH⁻ الفعلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-06T22:20:31.254Z"}'::jsonb),
('mcq', 6, 3, 'يتكون راسب عند الخلط إذا كان الحاصل الأيوني Qsp (المحسوب من تراكيز الأيونات في الخليط) أكبر من Ksp.', '["عندما يكون Qsp < Ksp يكون المحلول غير مشبع ولا يتكون راسب.","عندما يكون Qsp = Ksp يكون المحلول مشبعًا ولا يحدث تغير.","قيم Ksp للمركبات القليلة الذوبان صغيرة جدًّا، والحكم يكون بمقارنة Qsp بـ Ksp لا بقيمة Ksp وحدها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-06T22:20:31.254Z"}'::jsonb),
('mcq', 7, 1, 'بعد الخلط [CO₃²⁻] = 2.0 × 10⁻⁴ ÷ 2 = 1.0 × 10⁻⁴ M. ليتكون راسب يجب أن يكون [Ca²⁺][CO₃²⁻] > 3.4 × 10⁻⁹، أي [Ca²⁺] في الخليط > 3.4 × 10⁻⁹ ÷ 1.0 × 10⁻⁴ = 3.4 × 10⁻⁵ M، وهذا بعد التخفيف إلى النصف، فتركيز CaCl₂ قبل الخلط > 2 × 3.4 × 10⁻⁵ = 6.8 × 10⁻⁵ M.', '["هذا التركيز اللازم في الخليط بعد التخفيف، لا تركيز المحلول الأصلي قبل الخلط.","","لم يُخفف [CO₃²⁻] عند الخلط (3.4 × 10⁻⁹ ÷ 2.0 × 10⁻⁴)، ولم يُضاعف الناتج للعودة إلى التركيز الأصلي.","هذه √Ksp، أي ذائبية CaCO₃ في الماء النقي، ولا علاقة لها بتركيز CO₃²⁻ في الخليط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-06T22:20:31.255Z"}'::jsonb),
('essay', 1, null::int, null, null, 'AgCl(s) ⇌ Ag⁺(aq) + Cl⁻(aq)، وQsp = [Ag⁺][Cl⁻].
الحجمان متساويان (50.0 mL لكل منهما)، فيقل تركيز كل أيون إلى النصف: [Ag⁺] = 1.0 × 10⁻⁴ ÷ 2 = 5.0 × 10⁻⁵ M، و[Cl⁻] = 5.0 × 10⁻⁵ M.
Qsp = (5.0 × 10⁻⁵)(5.0 × 10⁻⁵) = 2.5 × 10⁻⁹.
Qsp (2.5 × 10⁻⁹) > Ksp (1.8 × 10⁻¹⁰)، فيتكون راسب من AgCl.', '["معادلة الذوبان وتعبير Qsp","التخفيف إلى النصف","[Ag⁺] = [Cl⁻] = 5.0 × 10⁻⁵ M","Qsp = 2.5 × 10⁻⁹","المقارنة والاستنتاج: يتكون راسب"]'::jsonb, '["Qsp = [Ag⁺][Cl⁻]","[Ag⁺] = [Cl⁻] = 1.0 × 10⁻⁴ ÷ 2 = 5.0 × 10⁻⁵ M","Qsp = (5.0 × 10⁻⁵)² = 2.5 × 10⁻⁹","2.5 × 10⁻⁹ > 1.8 × 10⁻¹⁰ ← يتكون راسب"]'::jsonb, '[{"element":"تعبير Qsp","marks":1},{"element":"حساب التراكيز بعد الخلط","marks":1},{"element":"حساب Qsp","marks":1},{"element":"المقارنة والاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات كاملة صحيحة واستنتاج سليم"},{"level":"2–3 درجات","description":"إهمال التخفيف أو خطأ في المقارنة"},{"level":"1 درجة","description":"كتابة التعبير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال تخفيف التراكيز عند الخلط","مقارنة الرتب العشرية في الاتجاه الخطأ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-06T22:20:31.255Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Ca(OH)₂(s) ⇌ Ca²⁺(aq) + 2OH⁻(aq)، وQsp = [Ca²⁺][OH⁻]².
